#[derive(Clone)]
struct InternalEventSender {
    sender: tokio::sync::mpsc::Sender<InternalEventEnvelope>,
    wake: watch::Sender<u64>,
    payload_budget: Arc<InternalEventPayloadBudget>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum InternalEventTrySendError {
    Full,
    Closed,
    ByteBudget,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum InternalEventSendError {
    Closed,
    ByteBudget,
}

#[derive(Debug)]
struct InternalEventEnvelope {
    event: InternalAppEvent,
    _payload_permit: Option<InternalEventPayloadPermit>,
}

#[derive(Debug, Default)]
struct InternalEventPayloadBudget {
    queued_items: AtomicUsize,
    queued_bytes: AtomicUsize,
    rejected_events: AtomicU64,
}

#[derive(Debug)]
struct InternalEventPayloadPermit {
    budget: Arc<InternalEventPayloadBudget>,
    bytes: usize,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct InternalEventPayloadMetrics {
    pub queued_items: usize,
    pub queued_bytes: usize,
    pub rejected_events: u64,
}

impl InternalEventPayloadBudget {
    fn reserve(self: &Arc<Self>, bytes: usize) -> Option<InternalEventPayloadPermit> {
        if bytes == 0 {
            return None;
        }
        let reserved =
            self.queued_bytes
                .fetch_update(Ordering::AcqRel, Ordering::Acquire, |current| {
                    current
                        .checked_add(bytes)
                        .filter(|next| *next <= INTERNAL_OMENCHAT_EVENT_QUEUE_MAX_BYTES)
                });
        if reserved.is_err() {
            self.rejected_events.fetch_add(1, Ordering::Relaxed);
            return None;
        }
        self.queued_items.fetch_add(1, Ordering::Relaxed);
        Some(InternalEventPayloadPermit {
            budget: self.clone(),
            bytes,
        })
    }

    fn reject_reserved(&self, bytes: usize) {
        if bytes > 0 {
            self.rejected_events.fetch_add(1, Ordering::Relaxed);
        }
    }

    fn metrics(&self) -> InternalEventPayloadMetrics {
        InternalEventPayloadMetrics {
            queued_items: self.queued_items.load(Ordering::Acquire),
            queued_bytes: self.queued_bytes.load(Ordering::Acquire),
            rejected_events: self.rejected_events.load(Ordering::Relaxed),
        }
    }
}

impl Drop for InternalEventPayloadPermit {
    fn drop(&mut self) {
        self.budget.queued_items.fetch_sub(1, Ordering::Relaxed);
        self.budget
            .queued_bytes
            .fetch_sub(self.bytes, Ordering::Release);
    }
}

fn internal_omenchat_event_payload_bytes(event: &InternalAppEvent) -> usize {
    match event {
        InternalAppEvent::Runtime(RuntimeBusEvent::OmenChatLinkData(data)) => {
            data.frame_bytes.len()
        }
        InternalAppEvent::Runtime(RuntimeBusEvent::OmenChatResourceData(data)) => data
            .data
            .len()
            .saturating_add(data.metadata.as_ref().map_or(0, Vec::len)),
        InternalAppEvent::Runtime(RuntimeBusEvent::OmenChatLinkClosed(data)) => {
            data.reason.as_ref().map_or(0, String::len)
        }
        _ => 0,
    }
}

impl InternalEventSender {
    async fn send(&self, event: InternalAppEvent) -> Result<(), InternalEventSendError> {
        let bytes = internal_omenchat_event_payload_bytes(&event);
        let permit = self.payload_budget.reserve(bytes);
        if bytes > 0 && permit.is_none() {
            return Err(InternalEventSendError::ByteBudget);
        }
        let envelope = InternalEventEnvelope {
            event,
            _payload_permit: permit,
        };
        if self.sender.send(envelope).await.is_err() {
            self.payload_budget.reject_reserved(bytes);
            return Err(InternalEventSendError::Closed);
        }
        self.wake.send_modify(|generation| {
            *generation = generation.wrapping_add(1);
        });
        Ok(())
    }

    fn try_send(&self, event: InternalAppEvent) -> Result<(), InternalEventTrySendError> {
        let bytes = internal_omenchat_event_payload_bytes(&event);
        let permit = self.payload_budget.reserve(bytes);
        if bytes > 0 && permit.is_none() {
            return Err(InternalEventTrySendError::ByteBudget);
        }
        self.try_send_envelope(InternalEventEnvelope {
            event,
            _payload_permit: permit,
        })
    }

    fn try_send_envelope(
        &self,
        envelope: InternalEventEnvelope,
    ) -> Result<(), InternalEventTrySendError> {
        let has_payload_permit = envelope._payload_permit.is_some();
        self.sender.try_send(envelope).map_err(|error| {
            self.payload_budget
                .reject_reserved(usize::from(has_payload_permit));
            match error {
                tokio::sync::mpsc::error::TrySendError::Full(_) => InternalEventTrySendError::Full,
                tokio::sync::mpsc::error::TrySendError::Closed(_) => {
                    InternalEventTrySendError::Closed
                }
            }
        })?;
        self.wake.send_modify(|generation| {
            *generation = generation.wrapping_add(1);
        });
        Ok(())
    }
}

#[derive(Clone)]
pub(crate) struct InternalEventWake {
    id: u64,
    receiver: watch::Receiver<u64>,
}

impl InternalEventWake {
    pub(crate) fn receiver(&self) -> watch::Receiver<u64> {
        self.receiver.clone()
    }

    pub(crate) fn id(&self) -> u64 {
        self.id
    }
}

impl std::hash::Hash for InternalEventWake {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.id.hash(state);
    }
}

fn spawn_runtime_event_forwarder(
    event_tx: InternalEventSender,
    mut receiver: broadcast::Receiver<crate::runtime::RuntimeBusEvent>,
) -> bool {
    let Ok(handle) = tokio::runtime::Handle::try_current() else {
        return false;
    };
    handle.spawn(async move {
        loop {
            match receiver.recv().await {
                Ok(event) => match event_tx.send(InternalAppEvent::Runtime(event)).await {
                    Ok(()) | Err(InternalEventSendError::ByteBudget) => {}
                    Err(InternalEventSendError::Closed) => break,
                },
                Err(broadcast::error::RecvError::Closed) => break,
                Err(broadcast::error::RecvError::Lagged(_)) => continue,
            }
        }
    });
    true
}

async fn collect_live_interop_report(
    runtime: Arc<dyn NetworkRuntime>,
    input: LiveInteropReportInput,
) -> AppResult<serde_json::Value> {
    let destination_inspection = if let Some(destination) = input.parsed_destination.as_deref() {
        match runtime.inspect_destination(destination, true).await {
            Ok(inspection) => serde_json::json!({
                "ok": true,
                "inspection": inspection,
            }),
            Err(error) => serde_json::json!({
                "ok": false,
                "error": redact_sensitive_diagnostics_text(&error.to_string(), input.identity_path.as_ref()),
            }),
        }
    } else {
        serde_json::json!({
            "ok": false,
            "error": "active browser address is not a destination:path address",
        })
    };

    let native_issues = input
        .native_readiness
        .issues
        .iter()
        .map(|issue| redact_sensitive_diagnostics_text(issue, input.identity_path.as_ref()))
        .collect::<Vec<_>>();
    let trace_logs = input
        .recent_trace_logs
        .iter()
        .map(|entry| {
            serde_json::json!({
                "epoch_ms": entry.epoch_ms,
                "severity": format!("{:?}", entry.severity),
                "source": format!("{:?}", entry.source),
                "message": redact_log_message_for_diagnostics(&entry.message, input.identity_path.as_ref()),
            })
        })
        .collect::<Vec<_>>();

    Ok(serde_json::json!({
        "report": "live_nomadnet_interop",
        "app": {
            "name": env!("CARGO_PKG_NAME"),
            "version": env!("CARGO_PKG_VERSION"),
        },
        "active_browser": {
            "url": input.active_browser_url,
            "destination_hash": input.parsed_destination,
            "path": input.parsed_path,
        },
        "active_conversation": {
            "peer_hash": input.active_conversation_peer,
            "peer_label": input.active_conversation_label,
        },
        "runtime": {
            "backend": format!("{:?}", input.runtime_status.backend),
            "connected": input.runtime_status.connected,
            "message": redact_sensitive_diagnostics_text(&input.runtime_status.message, input.identity_path.as_ref()),
        },
        "native_reticulum_readiness": {
            "compiled": input.native_readiness.compiled,
            "configured": input.native_readiness.configured,
            "ready": input.native_readiness.ready,
            "summary": redact_sensitive_diagnostics_text(&input.native_readiness.summary, input.identity_path.as_ref()),
            "issues": native_issues,
        },
        "destination_inspection": destination_inspection,
        "latest_browser_probe_summary": input.probe_summary,
        "recent_page_load_trace_logs": trace_logs,
        "operator_checklist": [
            "Build with --features native-network",
            "Select native or auto runtime backend with a valid Reticulum config",
            "Open or enter a NomadNet destination:path address in Browser",
            "Open or select an LXMF peer conversation before running delivery diagnostics",
            "Use Diagnostics N for dry-run readiness and X for explicit live probe",
            "Check destination_inspection.has_path and known_identity before retrying page load",
        ],
    }))
}

async fn collect_native_network_smoke_test_report(
    runtime: Arc<dyn NetworkRuntime>,
    input: LiveInteropReportInput,
    execute_live_probe: bool,
    execute_live_fetch: bool,
    warmup: Option<SmokePathWarmup>,
    known_destinations_preload: Option<SmokeKnownDestinationsPreload>,
) -> AppResult<serde_json::Value> {
    let attempt_epoch_ms = current_epoch_ms();
    let active_url = input.active_browser_url.clone();
    let destination = input.parsed_destination.clone();
    let active_peer = input.active_conversation_peer.clone();
    let mut runtime_events = runtime.subscribe_events();
    let live_fetch_retry_wait_secs = warmup.map(|warmup| warmup.wait_secs).unwrap_or(5);
    let path_warmup =
        run_smoke_path_warmup(runtime.clone(), &active_url, destination.as_deref(), warmup).await;
    let interop = collect_live_interop_report(runtime.clone(), input).await?;
    let dry_run_probe_result = runtime.probe_page_fetch(&active_url, false).await;
    let dry_run_probe_report = dry_run_probe_result.as_ref().ok().cloned();
    let dry_run_probe = dry_run_probe_result
        .map(|report| {
            serde_json::json!({
                "ok": true,
                "report": report,
            })
        })
        .unwrap_or_else(|error| {
            serde_json::json!({
                "ok": false,
                "error": error.to_string(),
            })
        });
    let live_probe_result = if execute_live_probe {
        Some(runtime.probe_page_fetch(&active_url, true).await)
    } else {
        None
    };
    let live_probe_report = live_probe_result
        .as_ref()
        .and_then(|result| result.as_ref().ok().cloned());
    let live_probe = if let Some(result) = live_probe_result {
        result
            .map(|report| {
                serde_json::json!({
                    "ok": true,
                    "report": report,
                })
            })
            .unwrap_or_else(|error| {
                serde_json::json!({
                    "ok": false,
                    "error": error.to_string(),
                })
            })
    } else {
        serde_json::json!({
            "ok": false,
            "skipped": "live probe not requested",
        })
    };
    let pre_fetch_probe = live_probe_report.as_ref().or(dry_run_probe_report.as_ref());
    let (live_fetch_probe_after_retry, live_fetch_readiness_retry) = if execute_live_fetch {
        collect_page_fetch_readiness_retry(
            runtime.clone(),
            runtime_events.as_mut(),
            &active_url,
            pre_fetch_probe,
            live_fetch_retry_wait_secs,
        )
        .await?
    } else {
        (
            None,
            serde_json::json!({
                "attempted": false,
                "status": "skip",
                "detail": "live fetch not requested",
            }),
        )
    };
    let live_fetch_blocked_by_retry = live_fetch_readiness_retry
        .get("attempted")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
        && !live_fetch_probe_after_retry
            .as_ref()
            .is_some_and(|report| report.ready_to_request);
    let live_fetch = if execute_live_fetch {
        if !live_fetch_blocked_by_retry {
            runtime
                .fetch_page(&active_url, None, CancellationToken::new())
                .await
                .map(|page| {
                    serde_json::json!({
                        "ok": true,
                        "attempt_epoch_ms": current_epoch_ms(),
                        "stage_hint": "response_decode",
                        "url": page.url,
                        "title": page.title,
                        "source": format!("{:?}", page.source),
                        "metadata": page.metadata,
                        "request_data_present": page.request_data.is_some(),
                        "markup_bytes": page.markup.len(),
                        "markup_lines": page.markup.lines().count(),
                        "body_preview_lines": page
                            .markup
                            .lines()
                            .take(8)
                            .map(ToOwned::to_owned)
                            .collect::<Vec<_>>(),
                    })
                })
                .unwrap_or_else(|error| {
                    let error = error.to_string();
                    serde_json::json!({
                        "ok": false,
                        "attempt_epoch_ms": current_epoch_ms(),
                        "error": error,
                        "stage_hint": native_page_load_failure_stage(&error),
                    })
                })
        } else {
            serde_json::json!({
                "ok": false,
                "attempt_epoch_ms": current_epoch_ms(),
                "status": "blocked",
                "error": "live fetch preflight did not report ready_to_request",
                "stage_hint": live_fetch_probe_after_retry
                    .as_ref()
                    .or(pre_fetch_probe)
                    .and_then(first_failed_page_probe_stage)
                    .unwrap_or(PageFetchProbeStage::RuntimeSetup),
            })
        }
    } else {
        serde_json::json!({
            "ok": false,
            "attempt_epoch_ms": current_epoch_ms(),
            "skipped": "live fetch not requested",
        })
    };
    let lxmf_delivery_probe = if let Some(peer_hash) = active_peer.as_deref() {
        runtime
            .probe_lxmf_delivery(peer_hash, false)
            .await
            .map(|report| {
                serde_json::json!({
                    "ok": true,
                    "report": report,
                })
            })
            .unwrap_or_else(|error| {
                serde_json::json!({
                    "ok": false,
                    "error": error.to_string(),
                })
            })
    } else {
        serde_json::json!({
            "ok": false,
            "skipped": "no active conversation peer",
        })
    };
    let live_stage_subreport = live_smoke_stage_subreport(&live_probe, execute_live_probe);
    let verdicts = native_network_smoke_test_verdicts(
        &interop,
        &dry_run_probe,
        &live_probe,
        &lxmf_delivery_probe,
        execute_live_probe,
        &path_warmup,
    );
    let classification = native_network_smoke_test_classification(
        &verdicts,
        &live_fetch,
        &live_fetch_readiness_retry,
        execute_live_probe,
        execute_live_fetch,
    );

    Ok(serde_json::json!({
        "report": "native_network_smoke_test",
        "attempt": {
            "epoch_ms": attempt_epoch_ms,
            "live_page_probe_requested": execute_live_probe,
            "live_fetch_requested": execute_live_fetch,
            "lxmf_probe_requested": active_peer.is_some(),
        },
        "execute_live_probe": execute_live_probe,
        "execute_live_fetch": execute_live_fetch,
        "active_browser_url": active_url,
        "command_examples": live_interop_command_examples(&active_url, active_peer.as_deref()),
        "sequence": [
            "runtime_status",
            "native_readiness",
            "optional_known_destinations_preload",
            "optional_path_warmup",
            "destination_inspection",
            "dry_run_page_probe",
            "optional_live_page_probe",
            "optional_live_stage_subreport",
            "optional_live_fetch",
            "lxmf_delivery_probe",
        ],
        "verdicts": verdicts,
        "classification": classification,
        "live_fetch_readiness_retry": live_fetch_readiness_retry,
        "known_destinations_preload": known_destinations_preload
            .map(|preload| serde_json::json!({
                "requested": true,
                "source_hint": preload.source_hint,
                "loaded": preload.loaded,
            }))
            .unwrap_or_else(|| serde_json::json!({
                "requested": false,
                "status": "skip",
                "detail": "known destinations preload not requested",
            })),
        "path_warmup": path_warmup,
        "interop": interop,
        "dry_run_page_probe": dry_run_probe,
        "live_page_probe": live_probe,
        "live_stage_subreport": live_stage_subreport,
        "live_fetch": live_fetch,
        "lxmf_delivery_probe": lxmf_delivery_probe,
    }))
}

async fn collect_native_lxmf_smoke_send_report(
    runtime: Arc<dyn NetworkRuntime>,
    peer_hash: String,
    delivery_mode: DeliveryMode,
    propagation_node: Option<String>,
    include_ticket: bool,
) -> AppResult<serde_json::Value> {
    let attempt_epoch_ms = current_epoch_ms();
    if matches!(delivery_mode, DeliveryMode::Propagated) {
        runtime
            .set_outbound_propagation_node(propagation_node.clone())
            .await?;
    }
    let readiness = runtime.probe_lxmf_delivery(&peer_hash, false).await?;
    let send = if readiness.ready_to_send {
        let envelope = crate::messaging::MessageEnvelope {
            peer_hash: peer_hash.clone(),
            title: "OMENbrowser_rs LXMF smoke test".into(),
            body: "OMENbrowser_rs native LXMF smoke-send test. This message was explicitly requested by the local user.".into(),
            delivery_mode: delivery_mode.clone(),
            include_ticket,
            native_reply_ticket: None,
            attachments: Vec::new(),
        };
        runtime
            .send_message(envelope)
            .await
            .map(|message| {
                let packet_hash = message.message_id.clone();
                serde_json::json!({
                    "ok": true,
                    "attempt_epoch_ms": current_epoch_ms(),
                    "message_id": message.message_id,
                    "packet_hash": packet_hash,
                    "transport_method": message.transport_method,
                    "delivered": message.delivered,
                    "failed": message.failed,
                    "native_lxmf_state": message.fields.get("native_lxmf_state").cloned(),
                    "include_ticket": include_ticket,
                    "native_lxmf_include_ticket": message.fields.get("native_lxmf_include_ticket").cloned(),
                    "native_lxmf_reply_ticket_offered": message.fields.get("native_lxmf_reply_ticket_offered").cloned(),
                    "peer_hash": message.peer_hash,
                    "peer_label": message.peer_label,
                    "timestamp": message.timestamp,
                })
            })
            .unwrap_or_else(|error| {
                let error = error.to_string();
                serde_json::json!({
                    "ok": false,
                    "attempt_epoch_ms": current_epoch_ms(),
                    "error": error,
                    "stage_hint": lxmf_send_failure_stage(&error),
                })
            })
    } else {
        serde_json::json!({
            "ok": false,
            "attempt_epoch_ms": current_epoch_ms(),
            "skipped": "LXMF delivery probe did not report ready_to_send",
            "first_failed_stage": readiness
                .steps
                .iter()
                .find(|step| !step.ok)
                .and_then(|step| serde_json::to_value(&step.stage).ok()),
        })
    };

    Ok(serde_json::json!({
        "report": "native_lxmf_smoke_send",
        "attempt": {
            "epoch_ms": attempt_epoch_ms,
            "peer_visible": readiness.ready_to_send,
            "delivery_confirmation": "not_available_yet",
            "delivery_meaning": "success means submitted to the active native Reticulum transport; remote delivery receipt is not wired yet",
        },
        "warning": "This action sends a real, deliberately labeled LXMF smoke-test message when readiness passes.",
        "app_actions": {
            "setup": "Settings/Interfaces: create or attach identity, select native Reticulum, add an interface, then start native runtime",
            "peer": "Diagnostics: choose an LXMF Peer Candidate, or use Directory/Messages to open a peer conversation",
            "send": "Diagnostics: run LXMF Smoke Send from the active conversation",
            "retry": "If readiness is blocked, use Directory/path actions or wait for the peer announce before retrying",
        },
        "command_examples": live_interop_command_examples("00112233445566778899aabbccddeeff:/page/index.mu", Some(&peer_hash)),
        "peer_hash": peer_hash,
        "delivery_mode": delivery_mode,
        "propagation_node": propagation_node,
        "readiness_probe": readiness,
        "send": send,
    }))
}

async fn collect_native_lxmf_live_interop_report(
    runtime: Arc<dyn NetworkRuntime>,
    peer_hash: Option<String>,
    wait_secs: u64,
    delivery_mode: DeliveryMode,
    propagation_node: Option<String>,
    include_ticket: bool,
) -> AppResult<serde_json::Value> {
    let attempt_epoch_ms = current_epoch_ms();
    let mut receiver = runtime.subscribe_events();
    if matches!(delivery_mode, DeliveryMode::Propagated) {
        runtime
            .set_outbound_propagation_node(propagation_node.clone())
            .await?;
    }
    let status_before = runtime.status().await;
    let announce = runtime
        .announce_identity()
        .await
        .map(|announced| {
            serde_json::json!({
                "ok": true,
                "announced": announced,
            })
        })
        .unwrap_or_else(|error| {
            serde_json::json!({
                "ok": false,
                "error": error.to_string(),
            })
        });

    let (readiness, readiness_retry) = if let Some(peer) = peer_hash.as_deref() {
        let (readiness, retry) =
            collect_lxmf_delivery_readiness(runtime.clone(), receiver.as_mut(), peer, wait_secs)
                .await?;
        (Some(readiness), retry)
    } else {
        (
            None,
            serde_json::json!({
                "attempted": false,
                "status": "skip",
                "detail": "no peer hash was provided; receive-only interop does not need peer path readiness",
            }),
        )
    };
    let send = if let Some(peer) = peer_hash.as_deref() {
        if readiness
            .as_ref()
            .is_some_and(|report| report.ready_to_send)
        {
            let envelope = crate::messaging::MessageEnvelope {
                peer_hash: peer.to_string(),
                title: "OMENbrowser_rs LXMF interop test".into(),
                body: "OMENbrowser_rs native LXMF live interop test. This message was explicitly requested by the local user.".into(),
                delivery_mode: delivery_mode.clone(),
                include_ticket,
                native_reply_ticket: None,
                attachments: Vec::new(),
            };
            runtime
                .send_message(envelope)
                .await
                .map(|message| {
                    serde_json::json!({
                        "requested": true,
                        "ok": true,
                        "peer_hash": message.peer_hash,
                        "message_id": message.message_id,
                        "packet_hash": message.message_id,
                        "native_lxmf_state": message.fields.get("native_lxmf_state").cloned(),
                        "native_lxmf_propagation_node": message.fields.get("native_lxmf_propagation_node").cloned(),
                        "include_ticket": include_ticket,
                        "native_lxmf_include_ticket": message.fields.get("native_lxmf_include_ticket").cloned(),
                        "native_lxmf_reply_ticket_offered": message.fields.get("native_lxmf_reply_ticket_offered").cloned(),
                        "transport_method": message.transport_method,
                        "delivered": message.delivered,
                        "failed": message.failed,
                    })
                })
                .unwrap_or_else(|error| {
                    serde_json::json!({
                        "requested": true,
                        "ok": false,
                        "error": error.to_string(),
                        "stage_hint": lxmf_send_failure_stage(&error.to_string()),
                    })
                })
        } else {
            serde_json::json!({
                "requested": true,
                "ok": false,
                "skipped": "LXMF delivery probe did not report ready_to_send",
            })
        }
    } else {
        serde_json::json!({
            "requested": false,
            "status": "skip",
            "detail": "no peer hash was provided; no LXMF message was sent",
        })
    };

    let wait = wait_for_lxmf_interop_events(
        receiver.as_mut(),
        peer_hash.as_deref(),
        send.get("message_id")
            .and_then(serde_json::Value::as_str)
            .or_else(|| send.get("packet_hash").and_then(serde_json::Value::as_str)),
        wait_secs,
    )
    .await;
    let status_after = runtime.status().await;
    let local = lxmf_interop_local_status(&status_after);
    let failure_hints = lxmf_interop_failure_hints(&announce, readiness.as_ref(), &send, &wait);
    let classification = lxmf_interop_classification(
        &announce,
        readiness.as_ref(),
        &send,
        &wait,
        peer_hash.as_deref(),
    );
    let command_examples = lxmf_interop_command_examples(peer_hash.as_deref(), wait_secs);

    Ok(serde_json::json!({
        "report": "native_lxmf_live_interop",
        "attempt": {
            "epoch_ms": attempt_epoch_ms,
            "wait_secs": wait_secs,
            "peer_visible_send_requested": peer_hash.is_some(),
        },
        "warning": "This report announces local lxmf.delivery and only sends a peer-visible LXMF message when the active conversation has an LXMF peer hash selected.",
        "app_actions": {
            "setup": "Settings/Interfaces: create or attach identity, select native Reticulum, add an interface, then start native runtime",
            "peer": "Messages or Directory: open/select a conversation whose peer hash is an lxmf.delivery destination",
            "receive_only": "Diagnostics: run LXMF Interop without a selected peer to announce locally and observe inbound LXMF events",
            "send_and_wait": "Diagnostics: run LXMF Interop with an active peer conversation to send the labeled test and wait for proof/inbound evidence",
            "retry": "If readiness is blocked, request/warm the peer path from Directory/Diagnostics or wait for the peer announce before retrying",
        },
        "local": local,
        "runtime_status_before": status_before,
        "runtime_status_after": status_after,
        "local_announce": announce,
        "peer_hash": peer_hash,
        "delivery_mode": delivery_mode,
        "propagation_node": propagation_node,
        "readiness_probe": readiness,
        "readiness_retry": readiness_retry,
        "send": send,
        "wait": wait,
        "classification": classification,
        "command_examples": command_examples,
        "failure_hints": failure_hints,
    }))
}

async fn collect_native_lxmf_propagation_diagnostics_report(
    runtime: Arc<dyn NetworkRuntime>,
    selected_from_settings: Option<String>,
    sync_limit: Option<u32>,
) -> serde_json::Value {
    let mut receiver = runtime.subscribe_events();
    let before = runtime.propagation_status().await;
    let selected_from_runtime = before
        .as_ref()
        .ok()
        .and_then(|status| status.destination_hash.clone());
    let selected_node = selected_from_runtime
        .clone()
        .or_else(|| selected_from_settings.clone());
    let sync = runtime.sync_propagation_messages(sync_limit).await;
    let sync_events = drain_propagation_sync_events(receiver.as_mut());
    let after = runtime.propagation_status().await;
    let before_json = before
        .as_ref()
        .map(|status| serde_json::to_value(status).unwrap_or(serde_json::Value::Null))
        .unwrap_or_else(|error| serde_json::json!({ "error": error.to_string() }));
    let after_json = after
        .as_ref()
        .map(|status| serde_json::to_value(status).unwrap_or(serde_json::Value::Null))
        .unwrap_or_else(|error| serde_json::json!({ "error": error.to_string() }));
    let sync_error = sync.as_ref().err().map(ToString::to_string);
    let sync_ok = sync.is_ok();
    let transfer_state = after
        .as_ref()
        .ok()
        .map(|status| status.transfer_state.as_str())
        .unwrap_or("unknown");
    let has_path = after
        .as_ref()
        .ok()
        .map(|status| status.has_path)
        .unwrap_or(false);
    let known_app_data = after
        .as_ref()
        .ok()
        .map(|status| status.known_app_data)
        .unwrap_or(false);
    let blocker = if selected_node.is_none() {
        "no propagation node selected"
    } else if !sync_ok {
        "native propagation router/client sync is deferred or blocked"
    } else if transfer_state == "router_deferred" {
        "native propagation router/client sync is deferred"
    } else if !has_path {
        "propagation node path is not known yet"
    } else if !known_app_data {
        "propagation node app-data/signing key is not known yet"
    } else {
        "no propagation blocker reported"
    };
    let next_step = if selected_node.is_none() {
        "select a propagation node from Directory, then rerun propagation diagnostics"
    } else if !has_path {
        "wait for PathUpdated or request/warm the propagation node path, then rerun diagnostics"
    } else if !known_app_data {
        "wait for an lxmf.propagation announce or preload known_destinations, then rerun diagnostics"
    } else if sync_error.is_some() {
        "inspect the propagation sync events and runtime logs, then retry Sync Propagation"
    } else if transfer_state == "router_deferred" {
        "wait for native runtime path/app-data readiness, then retry Sync Propagation"
    } else {
        "try propagation sync again or inspect runtime logs"
    };

    serde_json::json!({
        "report": "native_lxmf_propagation_diagnostics",
        "selected_from_settings": selected_from_settings,
        "selected_from_runtime": selected_from_runtime,
        "selected_node": selected_node,
        "sync_limit": sync_limit,
        "sync": {
            "ok": sync_ok,
            "error": sync_error,
        },
        "sync_events": sync_events,
        "before": before_json,
        "after": after_json,
        "blocker": blocker,
        "next_step": next_step,
    })
}

fn drain_propagation_sync_events(
    receiver: Option<&mut broadcast::Receiver<RuntimeBusEvent>>,
) -> Vec<serde_json::Value> {
    let Some(receiver) = receiver else {
        return Vec::new();
    };
    let mut events = Vec::new();
    loop {
        match receiver.try_recv() {
            Ok(RuntimeBusEvent::PropagationStatus(status)) => {
                events.push(serde_json::json!({
                    "kind": "propagation_status",
                    "selected": status.selected,
                    "destination_hash": status.destination_hash,
                    "has_path": status.has_path,
                    "known_app_data": status.known_app_data,
                    "link_state": status.link_state,
                    "transfer_state": status.transfer_state,
                }));
            }
            Ok(RuntimeBusEvent::PropagationSync(event)) => {
                let mut value = serde_json::to_value(event).unwrap_or_else(|error| {
                    serde_json::json!({
                        "detail": format!("failed to encode propagation sync event: {error}")
                    })
                });
                if let Some(object) = value.as_object_mut() {
                    object.insert(
                        "kind".into(),
                        serde_json::Value::String("propagation_sync".into()),
                    );
                }
                events.push(value);
            }
            Ok(RuntimeBusEvent::Debug(line)) if line.contains("native LXMF propagation sync") => {
                events.push(serde_json::json!({
                    "kind": "debug",
                    "message": line,
                }));
            }
            Ok(RuntimeBusEvent::MessageReceived(message)) => {
                events.push(serde_json::json!({
                    "kind": "message_received",
                    "message": message,
                    "peer_hash": message.peer_hash,
                    "peer_label": message.peer_label,
                    "message_id": message.message_id,
                    "title_len": message.title.len(),
                    "content_len": message.content.len(),
                    "transport_method": message.transport_method,
                }));
            }
            Ok(RuntimeBusEvent::LxmfDeliveryEvidence(evidence)) => {
                events.push(serde_json::json!({
                    "kind": "lxmf_delivery_evidence",
                    "evidence": evidence,
                }));
            }
            Ok(_) => {}
            Err(broadcast::error::TryRecvError::Lagged(skipped)) => {
                events.push(serde_json::json!({
                    "kind": "warning",
                    "message": format!("runtime event receiver lagged by {skipped} events"),
                }));
            }
            Err(broadcast::error::TryRecvError::Empty)
            | Err(broadcast::error::TryRecvError::Closed) => break,
        }
    }
    events
}

fn messages_from_propagation_sync_report(report: &serde_json::Value) -> Vec<MessageSummary> {
    report
        .get("sync_events")
        .and_then(serde_json::Value::as_array)
        .map(|events| {
            events
                .iter()
                .filter_map(|event| {
                    (event.get("kind").and_then(serde_json::Value::as_str)
                        == Some("message_received"))
                    .then(|| {
                        event
                            .get("message")
                            .cloned()
                            .and_then(|value| serde_json::from_value::<MessageSummary>(value).ok())
                    })
                    .flatten()
                })
                .collect()
        })
        .unwrap_or_default()
}

fn lxmf_delivery_evidence_from_propagation_sync_report(
    report: &serde_json::Value,
) -> Vec<LxmfDeliveryEvidence> {
    report
        .get("sync_events")
        .and_then(serde_json::Value::as_array)
        .map(|events| {
            events
                .iter()
                .filter_map(|event| {
                    (event.get("kind").and_then(serde_json::Value::as_str)
                        == Some("lxmf_delivery_evidence"))
                    .then(|| {
                        event.get("evidence").cloned().and_then(|value| {
                            serde_json::from_value::<LxmfDeliveryEvidence>(value).ok()
                        })
                    })
                    .flatten()
                })
                .collect()
        })
        .unwrap_or_default()
}

async fn collect_lxmf_delivery_readiness(
    runtime: Arc<dyn NetworkRuntime>,
    receiver: Option<&mut broadcast::Receiver<RuntimeBusEvent>>,
    peer_hash: &str,
    wait_secs: u64,
) -> AppResult<(LxmfDeliveryProbeReport, serde_json::Value)> {
    let initial = runtime.probe_lxmf_delivery(peer_hash, false).await?;
    if initial.ready_to_send {
        return Ok((
            initial,
            serde_json::json!({
                "attempted": false,
                "status": "skip",
                "detail": "initial LXMF readiness probe is already ready_to_send",
            }),
        ));
    }

    if wait_secs == 0 {
        return Ok((
            initial,
            serde_json::json!({
                "attempted": false,
                "status": "skip",
                "detail": "readiness retry disabled because LXMF interop wait is 0",
            }),
        ));
    }

    if !lxmf_probe_queued_path_request(&initial) {
        let failed_stage = first_failed_lxmf_probe_stage(&initial);
        return Ok((
            initial,
            serde_json::json!({
                "attempted": false,
                "status": "skip",
                "detail": "initial LXMF readiness failure was not a queued path request",
                "first_failed_stage": failed_stage,
            }),
        ));
    }

    let path_wait_secs = wait_secs.min(5);
    let wait = wait_for_lxmf_path_readiness_event(receiver, peer_hash, path_wait_secs).await;
    let followup = runtime.probe_lxmf_delivery(peer_hash, false).await?;
    let retry = serde_json::json!({
        "attempted": true,
        "status": wait.get("status").and_then(serde_json::Value::as_str).unwrap_or("unknown"),
        "wait_secs": path_wait_secs,
        "initial_ready_to_send": initial.ready_to_send,
        "followup_ready_to_send": followup.ready_to_send,
        "initial_first_failed_stage": first_failed_lxmf_probe_stage(&initial),
        "followup_first_failed_stage": first_failed_lxmf_probe_stage(&followup),
        "wait": wait,
        "detail": "queued path request was given a short interop retry window before deciding whether to send",
    });
    Ok((followup, retry))
}

async fn wait_for_lxmf_path_readiness_event(
    receiver: Option<&mut broadcast::Receiver<RuntimeBusEvent>>,
    peer_hash: &str,
    wait_secs: u64,
) -> serde_json::Value {
    let Some(receiver) = receiver else {
        return serde_json::json!({
            "status": "skip",
            "detail": "runtime does not expose events",
            "events": [],
        });
    };
    if wait_secs == 0 {
        return serde_json::json!({
            "status": "skip",
            "detail": "path readiness wait disabled",
            "events": [],
        });
    }

    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(wait_secs);
    let mut events = Vec::new();
    loop {
        let now = tokio::time::Instant::now();
        if now >= deadline {
            break;
        }
        match tokio::time::timeout(deadline - now, receiver.recv()).await {
            Ok(Ok(RuntimeBusEvent::PathUpdated(path)))
                if path.destination_hash.eq_ignore_ascii_case(peer_hash) =>
            {
                events.push(serde_json::json!({
                    "event": "path_updated",
                    "destination_hash": path.destination_hash,
                    "known": path.known,
                    "hops": path.hops,
                }));
                if path.known {
                    return serde_json::json!({
                        "status": "observed",
                        "detail": "matching peer path update observed",
                        "events": events,
                    });
                }
            }
            Ok(Ok(RuntimeBusEvent::Announce(announce)))
                if announce.destination_hash.eq_ignore_ascii_case(peer_hash) =>
            {
                events.push(serde_json::json!({
                    "event": "announce",
                    "destination_hash": announce.destination_hash,
                    "kind": announce.kind,
                    "display_name": announce.display_name,
                }));
            }
            Ok(Ok(RuntimeBusEvent::Debug(message)))
                if message.contains(peer_hash) || message.to_lowercase().contains("path") =>
            {
                events.push(serde_json::json!({
                    "event": "debug",
                    "message": message,
                }));
            }
            Ok(Ok(_)) => {}
            Ok(Err(tokio::sync::broadcast::error::RecvError::Lagged(skipped))) => {
                events.push(serde_json::json!({
                    "event": "event_lagged",
                    "skipped": skipped,
                }));
            }
            Ok(Err(tokio::sync::broadcast::error::RecvError::Closed)) => {
                return serde_json::json!({
                    "status": "closed",
                    "detail": "runtime event stream closed while waiting for peer path readiness",
                    "events": events,
                });
            }
            Err(_) => break,
        }
    }

    serde_json::json!({
        "status": "timeout",
        "detail": "no matching peer path update arrived before retry timeout",
        "events": events,
    })
}

fn lxmf_probe_queued_path_request(report: &LxmfDeliveryProbeReport) -> bool {
    report.steps.iter().any(|step| {
        step.stage == LxmfDeliveryProbeStage::PathDiscovery
            && !step.ok
            && step
                .trace
                .get("request_path")
                .is_some_and(|value| value == "queued")
    })
}

fn first_failed_lxmf_probe_stage(report: &LxmfDeliveryProbeReport) -> Option<String> {
    report
        .steps
        .iter()
        .find(|step| !step.ok)
        .map(|step| format!("{:?}", step.stage))
}

async fn wait_for_lxmf_interop_events(
    receiver: Option<&mut tokio::sync::broadcast::Receiver<RuntimeBusEvent>>,
    peer_hash: Option<&str>,
    message_id: Option<&str>,
    wait_secs: u64,
) -> serde_json::Value {
    let Some(receiver) = receiver else {
        return serde_json::json!({
            "status": "skip",
            "detail": "runtime does not expose events",
            "proof_match_state": "no_sent_packet",
            "inbound_reply_match_state": if peer_hash.is_some() { "no_matching_peer_reply" } else { "no_peer_filter" },
            "events": [],
        });
    };
    if wait_secs == 0 {
        return serde_json::json!({
            "status": "skip",
            "detail": "LXMF interop wait disabled",
            "proof_match_state": match message_id {
                None => "no_sent_packet",
                Some(_) => "wait_disabled",
            },
            "inbound_reply_match_state": if peer_hash.is_some() { "wait_disabled" } else { "no_peer_filter" },
            "events": [],
        });
    }

    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(wait_secs);
    let mut events = Vec::new();
    let mut inbound_count = 0usize;
    let mut delivery_count = 0usize;
    let mut proof_count = 0usize;
    loop {
        let now = tokio::time::Instant::now();
        if now >= deadline {
            break;
        }
        match tokio::time::timeout(deadline - now, receiver.recv()).await {
            Ok(Ok(event)) => {
                if let Some(summary) = lxmf_interop_event_summary(event, peer_hash, message_id) {
                    if summary.get("event").and_then(serde_json::Value::as_str)
                        == Some("message_received")
                    {
                        inbound_count += 1;
                    }
                    if summary.get("event").and_then(serde_json::Value::as_str)
                        == Some("message_delivery_updated")
                    {
                        delivery_count += 1;
                        if summary.get("evidence").and_then(serde_json::Value::as_str)
                            == Some("rns_packet_proof")
                        {
                            proof_count += 1;
                        }
                    }
                    if summary.get("event").and_then(serde_json::Value::as_str)
                        == Some("lxmf_delivery_evidence")
                    {
                        match summary.get("kind").and_then(serde_json::Value::as_str) {
                            Some("packet_submitted" | "propagation_node_accepted") => {
                                delivery_count += 1;
                            }
                            Some("rns_packet_proof" | "lxmf_router_delivered") => {
                                delivery_count += 1;
                                proof_count += 1;
                            }
                            Some("inbound_peer_message") => {
                                inbound_count += 1;
                            }
                            _ => {}
                        }
                    }
                    events.push(summary);
                }
            }
            Ok(Err(tokio::sync::broadcast::error::RecvError::Lagged(skipped))) => {
                events.push(serde_json::json!({
                    "event": "event_lagged",
                    "skipped": skipped,
                }));
            }
            Ok(Err(tokio::sync::broadcast::error::RecvError::Closed)) => {
                return serde_json::json!({
                    "status": "closed",
                    "detail": "runtime event stream closed while waiting",
                    "proof_match_state": match message_id {
                        None => "no_sent_packet",
                        Some(_) if proof_count > 0 => "matched_packet_proof",
                        Some(_) => "no_matching_packet_proof",
                    },
                    "inbound_reply_match_state": match peer_hash {
                        None if inbound_count > 0 => "inbound_observed_without_peer_filter",
                        None => "no_peer_filter",
                        Some(_) if inbound_count > 0 => "matched_peer_reply",
                        Some(_) => "no_matching_peer_reply",
                    },
                    "events": events,
                    "inbound_messages": inbound_count,
                    "delivery_updates": delivery_count,
                    "packet_proofs": proof_count,
                });
            }
            Err(_) => break,
        }
    }

    let status = if inbound_count > 0 || proof_count > 0 {
        "observed"
    } else if delivery_count > 0 {
        "submitted_only"
    } else {
        "timeout"
    };

    serde_json::json!({
        "status": status,
        "proof_match_state": match message_id {
            None => "no_sent_packet",
            Some(_) if proof_count > 0 => "matched_packet_proof",
            Some(_) => "no_matching_packet_proof",
        },
        "inbound_reply_match_state": match peer_hash {
            None if inbound_count > 0 => "inbound_observed_without_peer_filter",
            None => "no_peer_filter",
            Some(_) if inbound_count > 0 => "matched_peer_reply",
            Some(_) => "no_matching_peer_reply",
        },
        "events": events,
        "inbound_messages": inbound_count,
        "delivery_updates": delivery_count,
        "packet_proofs": proof_count,
    })
}

fn lxmf_interop_local_status(status: &NetworkStatus) -> serde_json::Value {
    serde_json::json!({
        "identity_label": status
            .active_identity
            .as_ref()
            .map(|identity| identity.label.clone()),
        "identity_profile_hash": status
            .active_identity
            .as_ref()
            .map(|identity| identity.hash_hex.clone()),
        "local_lxmf_destination_hash": status_message_value(&status.message, "local_lxmf_destination"),
        "local_lxmf_registered": status_message_bool(&status.message, "local_lxmf_registered"),
        "proof_capable": status_message_bool(&status.message, "proof_capable"),
        "announced": status_message_bool(&status.message, "announced"),
    })
}

fn status_message_value(message: &str, key: &str) -> Option<String> {
    let prefix = format!("{key}=");
    message
        .split_whitespace()
        .find_map(|part| part.strip_prefix(&prefix))
        .map(|value| value.trim_end_matches(';').to_string())
        .filter(|value| value != "none")
}

fn status_message_bool(message: &str, key: &str) -> Option<bool> {
    match status_message_value(message, key)?.as_str() {
        "true" => Some(true),
        "false" => Some(false),
        _ => None,
    }
}

fn set_status_message_bool(message: &str, key: &str, value: bool) -> String {
    let replacement = format!("{key}={value}");
    let mut replaced = false;
    let mut parts = Vec::new();
    for part in message.split_whitespace() {
        if part
            .strip_prefix(key)
            .is_some_and(|suffix| suffix.starts_with('='))
        {
            parts.push(replacement.clone());
            replaced = true;
        } else {
            parts.push(part.to_string());
        }
    }
    if !replaced {
        parts.push(replacement);
    }
    parts.join(" ")
}

fn lxmf_interop_failure_hints(
    announce: &serde_json::Value,
    readiness: Option<&crate::runtime::network::LxmfDeliveryProbeReport>,
    send: &serde_json::Value,
    wait: &serde_json::Value,
) -> Vec<&'static str> {
    let mut hints = Vec::new();
    if !announce
        .get("ok")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        hints.push("local lxmf.delivery announce failed; verify native backend, identity path, and TCP interface");
    }
    if let Some(readiness) = readiness {
        if !readiness.ready_to_send {
            hints.push("peer is not ready for direct LXMF send; wait for lxmf.delivery announce, preload known_destinations, or request path");
        }
    }
    if send
        .get("requested")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
        && !send
            .get("ok")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
    {
        hints.push("LXMF send failed or was skipped; inspect send.stage_hint and readiness_probe first_failed_stage");
    }
    if wait
        .get("proof_match_state")
        .and_then(serde_json::Value::as_str)
        == Some("no_matching_packet_proof")
    {
        hints.push("no RNS packet proof arrived before timeout; verify the peer received the packet and supports proofs");
    }
    if wait
        .get("inbound_reply_match_state")
        .and_then(serde_json::Value::as_str)
        == Some("no_matching_peer_reply")
    {
        hints.push("no inbound LXMF reply from the target peer arrived before timeout");
    }
    if wait.get("status").and_then(serde_json::Value::as_str) == Some("timeout") {
        hints.push(
            "event wait timed out; keep the peer online and retry with a longer in-app wait when configurable",
        );
    }
    hints
}

fn lxmf_interop_classification(
    announce: &serde_json::Value,
    readiness: Option<&crate::runtime::network::LxmfDeliveryProbeReport>,
    send: &serde_json::Value,
    wait: &serde_json::Value,
    peer_hash: Option<&str>,
) -> serde_json::Value {
    let announce_ok = announce
        .get("ok")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let send_requested = send
        .get("requested")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let send_ok = send
        .get("ok")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let wait_status = wait
        .get("status")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("unknown");
    let proof_match_state = wait
        .get("proof_match_state")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("unknown");
    let inbound_reply_match_state = wait
        .get("inbound_reply_match_state")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("unknown");
    let send_native_state = send
        .get("native_lxmf_state")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("");
    let send_submitted_unconfirmed = matches!(
        send_native_state,
        "submitted_to_clean_reticulum"
            | "submitted_to_rns_net"
            | "submitted_to_runtime"
            | "submitted_unconfirmed"
    );

    let (outcome, reason, next_step) = if !announce_ok {
        (
            "blocked",
            "local lxmf.delivery announce did not succeed",
            "use Settings/Interfaces to select native Reticulum, create or attach an identity, add an interface, then run LXMF Interop again",
        )
    } else if let Some(readiness) = readiness {
        if !readiness.ready_to_send {
            (
                "blocked",
                "target peer is not ready for direct LXMF send",
                "wait for the peer lxmf.delivery announce, preload known_destinations, or request/warm the peer path before retrying",
            )
        } else if send_requested && !send_ok {
            (
                "fail",
                "explicit LXMF send failed after peer readiness passed",
                "inspect the send stage in Diagnostics, fix the runtime/interface/path issue, then retry from the same conversation",
            )
        } else if proof_match_state == "matched_packet_proof"
            || inbound_reply_match_state == "matched_peer_reply"
        {
            (
                "pass",
                "explicit send produced matching LXMF/RNS evidence",
                "repeat from this conversation or select another trusted peer to validate additional LXMF delivery paths",
            )
        } else if send_submitted_unconfirmed {
            (
                "submitted_unconfirmed",
                "explicit send was accepted by the native transport but no peer proof or reply arrived before timeout",
                "treat the outbound row as peer-unconfirmed; retry only if the peer does not receive it or use propagation for store-and-forward evidence",
            )
        } else if wait_status == "timeout" || wait_status == "submitted_only" {
            (
                "timeout",
                "explicit send completed but no matching proof or peer reply arrived before timeout",
                "keep the peer online, retry LXMF Interop, and confirm the remote peer returns packet proofs or replies",
            )
        } else {
            (
                "blocked",
                "explicit send path did not wait for matching network evidence",
                "run LXMF Interop again from the active conversation after readiness/path evidence improves",
            )
        }
    } else if inbound_reply_match_state == "inbound_observed_without_peer_filter" {
        (
            "pass",
            "receive-only interop observed inbound LXMF traffic",
            "open or create a conversation for that LXMF peer, then run LXMF Interop to validate explicit outbound delivery",
        )
    } else if wait_status == "timeout" {
        (
            "timeout",
            "local announce succeeded but no LXMF/proof events arrived before timeout",
            "keep the peer online, select its conversation, and retry LXMF Interop when announces/path state are visible",
        )
    } else {
        (
            "blocked",
            "receive-only interop did not wait for network evidence",
            "start native Reticulum from Settings/Interfaces and run LXMF Interop while connected to a real peer",
        )
    };

    serde_json::json!({
        "outcome": outcome,
        "reason": reason,
        "next_step": next_step,
        "peer_hash_provided": peer_hash.is_some(),
        "proof_match_state": proof_match_state,
        "inbound_reply_match_state": inbound_reply_match_state,
        "wait_status": wait_status,
    })
}

fn lxmf_interop_event_summary(
    event: crate::runtime::RuntimeBusEvent,
    peer_hash: Option<&str>,
    message_id: Option<&str>,
) -> Option<serde_json::Value> {
    match event {
        crate::runtime::RuntimeBusEvent::MessageReceived(message) => {
            if peer_hash.is_some_and(|peer| !message.peer_hash.eq_ignore_ascii_case(peer)) {
                return None;
            }
            Some(serde_json::json!({
                "event": "message_received",
                "peer_hash": message.peer_hash,
                "peer_label": message.peer_label,
                "message_id": message.message_id,
                "title_len": message.title.len(),
                "content_len": message.content.len(),
                "transport_method": message.transport_method,
            }))
        }
        crate::runtime::RuntimeBusEvent::MessageDeliveryUpdated(status) => {
            if peer_hash.is_some_and(|peer| !status.peer_hash.eq_ignore_ascii_case(peer)) {
                return None;
            }
            if let (Some(expected), Some(actual)) = (message_id, status.message_id.as_deref()) {
                if !actual.eq_ignore_ascii_case(expected) {
                    return None;
                }
            }
            Some(serde_json::json!({
                "event": "message_delivery_updated",
                "peer_hash": status.peer_hash,
                "message_id": status.message_id,
                "delivered": status.delivered,
                "failed": status.failed,
                "state": status.state,
                "evidence": status.evidence,
                "rtt": status.rtt,
            }))
        }
        crate::runtime::RuntimeBusEvent::LxmfDeliveryEvidence(evidence) => {
            if peer_hash.is_some_and(|peer| !evidence.peer_hash.eq_ignore_ascii_case(peer)) {
                return None;
            }
            if let (Some(expected), Some(actual)) = (message_id, evidence.message_id.as_deref()) {
                if !actual.eq_ignore_ascii_case(expected) {
                    return None;
                }
            }
            Some(serde_json::json!({
                "event": "lxmf_delivery_evidence",
                "peer_hash": evidence.peer_hash,
                "message_id": evidence.message_id,
                "kind": evidence.kind,
                "detail": evidence.detail,
                "rtt": evidence.rtt,
                "observed_at": evidence.observed_at,
            }))
        }
        crate::runtime::RuntimeBusEvent::Announce(announce) => Some(serde_json::json!({
            "event": "announce",
            "destination_hash": announce.destination_hash,
            "kind": announce.kind,
            "display_name": announce.display_name,
            "associated_hash": announce.associated_hash,
            "node_associated_hash": announce.node_associated_hash,
        })),
        crate::runtime::RuntimeBusEvent::Debug(message)
            if message.contains("lxmf")
                || message.contains("LXMF")
                || message.contains("proof")
                || message.contains("announce")
                || message.contains("app-data")
                || message.contains("stamp")
                || message.contains("submitted") =>
        {
            Some(serde_json::json!({
                "event": "debug",
                "message": message,
            }))
        }
        crate::runtime::RuntimeBusEvent::Error(message) => Some(serde_json::json!({
            "event": "error",
            "message": message,
        })),
        _ => None,
    }
}

fn lxmf_send_failure_stage(error: &str) -> &'static str {
    let lower = error.to_lowercase();
    if lower.contains("identity") {
        "source_identity"
    } else if lower.contains("peer") || lower.contains("destination") {
        "peer_identity"
    } else if lower.contains("path") {
        "path_discovery"
    } else if lower.contains("lxmf") || lower.contains("sign") || lower.contains("wire") {
        "packet_build"
    } else if lower.contains("send") || lower.contains("packet") {
        "send_packet"
    } else {
        "unknown"
    }
}

fn live_interop_command_examples(active_url: &str, peer_hash: Option<&str>) -> serde_json::Value {
    let base = format!(
        "cargo run --features native-network -- --native-smoke {active_url} --backend reticulum --identity <identity-file> --tcp-client <host:port> --stdout"
    );
    let live_fetch = format!("{base} --warm-path --path-wait 10 --live --fetch-page");
    let lxmf = peer_hash
        .map(|peer| format!("{base} --send-lxmf-smoke {peer}"))
        .unwrap_or_else(|| {
            format!("{base} --send-lxmf-smoke <lxmf-delivery-peer-destination-hash>")
        });

    serde_json::json!({
        "dry_run": base,
        "live_nomadnet_fetch": live_fetch,
        "explicit_lxmf_smoke_send": lxmf,
    })
}

fn lxmf_interop_command_examples(peer_hash: Option<&str>, wait_secs: u64) -> serde_json::Value {
    let wait_secs = wait_secs.max(10);
    let receive_only = "cargo run --features native-network -- --lxmf-interop --backend reticulum --identity <identity-file> --tcp-client <host:port> --stdout";
    let announce_and_wait = format!(
        "cargo run --features native-network -- --lxmf-wait {wait_secs} --backend reticulum --identity <identity-file> --tcp-client <host:port> --stdout"
    );
    let peer = peer_hash.unwrap_or("<lxmf-delivery-peer-destination-hash>");
    let explicit_send_and_wait = format!(
        "cargo run --features native-network -- --lxmf-interop --send-lxmf-smoke {peer} --backend reticulum --identity <identity-file> --tcp-client <host:port> --stdout"
    );
    let with_reticulum_config = format!(
        "cargo run --features native-network -- --lxmf-interop --send-lxmf-smoke {peer} --backend reticulum --identity <identity-file> --reticulum-config <reticulum-config-dir> --stdout"
    );

    serde_json::json!({
        "receive_only": receive_only,
        "announce_and_wait": announce_and_wait,
        "explicit_send_and_wait": explicit_send_and_wait,
        "with_reticulum_config": with_reticulum_config,
        "developer_only": true,
        "note": "CLI examples are for developer/live-lab reproduction only; normal users should use Settings, Interfaces, Directory, Messages, and Diagnostics inside the app.",
    })
}

fn live_smoke_stage_subreport(
    live_probe: &serde_json::Value,
    execute_live_probe: bool,
) -> serde_json::Value {
    if !execute_live_probe {
        return serde_json::json!({
            "requested": false,
            "status": "skip",
            "detail": "live stage subreport not requested",
        });
    }
    let Some(report) = live_probe.get("report") else {
        return serde_json::json!({
            "requested": true,
            "status": "fail",
            "detail": live_probe
                .get("error")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("live probe did not produce a report"),
        });
    };

    let stage_order = [
        PageFetchProbeStage::AddressParse,
        PageFetchProbeStage::RuntimeSetup,
        PageFetchProbeStage::DestinationIdentity,
        PageFetchProbeStage::PathDiscovery,
        PageFetchProbeStage::LinkSetup,
        PageFetchProbeStage::RequestSend,
        PageFetchProbeStage::ResponseWait,
        PageFetchProbeStage::ResponseDecode,
    ];
    let live_stages = [
        PageFetchProbeStage::PathDiscovery,
        PageFetchProbeStage::LinkSetup,
        PageFetchProbeStage::RequestSend,
        PageFetchProbeStage::ResponseWait,
        PageFetchProbeStage::ResponseDecode,
    ];
    let first_failed = stage_order
        .iter()
        .find(|stage| {
            probe_stage_step(report, (*stage).clone())
                .and_then(|step| step.get("ok"))
                .and_then(serde_json::Value::as_bool)
                .is_some_and(|ok| !ok)
        })
        .cloned();

    let destination_identity_known =
        probe_stage_ok(report, PageFetchProbeStage::DestinationIdentity);
    let path_known = probe_stage_ok(report, PageFetchProbeStage::PathDiscovery);
    let stages = live_stages
        .iter()
        .map(|stage| live_stage_summary(report, stage.clone(), first_failed.as_ref()))
        .collect::<Vec<_>>();
    let response_decoded = probe_stage_ok(report, PageFetchProbeStage::ResponseDecode);

    serde_json::json!({
        "requested": true,
        "status": if response_decoded { "pass" } else { "fail" },
        "preconditions": {
            "destination_identity_known": destination_identity_known,
            "path_known": path_known,
        },
        "first_blocking_stage": first_failed
            .as_ref()
            .and_then(|stage| serde_json::to_value(stage).ok()),
        "stages": stages,
        "detail": if response_decoded {
            "live rns-net page request reached response decode"
        } else {
            "live rns-net page request did not reach response decode"
        },
    })
}

fn live_stage_summary(
    report: &serde_json::Value,
    stage: PageFetchProbeStage,
    first_failed: Option<&PageFetchProbeStage>,
) -> serde_json::Value {
    let stage_name = serde_json::to_value(&stage).unwrap_or_else(|_| serde_json::json!("unknown"));
    if let Some(step) = probe_stage_step(report, stage.clone()) {
        let ok = step
            .get("ok")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        return serde_json::json!({
            "stage": stage_name,
            "status": if ok { "pass" } else { "fail" },
            "detail": step
                .get("detail")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("stage reported no detail"),
            "trace": step
                .get("trace")
                .cloned()
                .unwrap_or_else(|| serde_json::json!({})),
        });
    }

    let blocked =
        first_failed.is_some_and(|failed| stage_order_index(failed) < stage_order_index(&stage));
    serde_json::json!({
        "stage": stage_name,
        "status": if blocked { "blocked" } else { "skip" },
        "detail": if blocked {
            "stage was not reached because an earlier stage failed"
        } else {
            "stage was not reached"
        },
    })
}

fn stage_order_index(stage: &PageFetchProbeStage) -> usize {
    match stage {
        PageFetchProbeStage::AddressParse => 0,
        PageFetchProbeStage::RuntimeSetup => 1,
        PageFetchProbeStage::DestinationIdentity => 2,
        PageFetchProbeStage::PathDiscovery => 3,
        PageFetchProbeStage::LinkSetup => 4,
        PageFetchProbeStage::RequestSend => 5,
        PageFetchProbeStage::ResponseWait => 6,
        PageFetchProbeStage::ResponseDecode => 7,
    }
}

async fn collect_page_fetch_readiness_retry(
    runtime: Arc<dyn NetworkRuntime>,
    receiver: Option<&mut broadcast::Receiver<RuntimeBusEvent>>,
    active_url: &str,
    initial: Option<&PageFetchProbeReport>,
    wait_secs: u64,
) -> AppResult<(Option<PageFetchProbeReport>, serde_json::Value)> {
    let Some(initial) = initial else {
        return Ok((
            None,
            serde_json::json!({
                "attempted": false,
                "status": "skip",
                "detail": "no page fetch preflight probe was available",
            }),
        ));
    };
    if initial.ready_to_request {
        return Ok((
            None,
            serde_json::json!({
                "attempted": false,
                "status": "skip",
                "detail": "initial page fetch probe is already ready_to_request",
            }),
        ));
    }
    if wait_secs == 0 {
        return Ok((
            None,
            serde_json::json!({
                "attempted": false,
                "status": "skip",
                "detail": "page fetch readiness retry disabled because wait budget is 0",
                "initial_first_failed_stage": first_failed_page_probe_stage(initial),
            }),
        ));
    }
    if !page_probe_queued_path_request(initial) {
        return Ok((
            None,
            serde_json::json!({
                "attempted": false,
                "status": "skip",
                "detail": "initial page fetch preflight failure was not a queued path request",
                "initial_first_failed_stage": first_failed_page_probe_stage(initial),
            }),
        ));
    }

    let destination_hash = initial.destination_hash.as_deref();
    let path_wait_secs = wait_secs.min(5);
    let wait = wait_for_page_path_readiness_event(receiver, destination_hash, path_wait_secs).await;
    let followup = runtime.probe_page_fetch(active_url, false).await?;
    let retry = serde_json::json!({
        "attempted": true,
        "status": wait.get("status").and_then(serde_json::Value::as_str).unwrap_or("unknown"),
        "wait_secs": path_wait_secs,
        "destination_hash": destination_hash,
        "initial_ready_to_request": initial.ready_to_request,
        "followup_ready_to_request": followup.ready_to_request,
        "initial_first_failed_stage": first_failed_page_probe_stage(initial),
        "followup_first_failed_stage": first_failed_page_probe_stage(&followup),
        "wait": wait,
        "detail": "queued page path request was given a short smoke-test retry window before live fetch",
    });
    Ok((Some(followup), retry))
}

async fn wait_for_page_path_readiness_event(
    receiver: Option<&mut broadcast::Receiver<RuntimeBusEvent>>,
    destination_hash: Option<&str>,
    wait_secs: u64,
) -> serde_json::Value {
    let Some(receiver) = receiver else {
        return serde_json::json!({
            "status": "skip",
            "detail": "runtime does not expose events",
            "events": [],
        });
    };
    let Some(destination_hash) = destination_hash else {
        return serde_json::json!({
            "status": "skip",
            "detail": "page fetch probe did not expose a destination hash",
            "events": [],
        });
    };
    if wait_secs == 0 {
        return serde_json::json!({
            "status": "skip",
            "detail": "path readiness wait disabled",
            "events": [],
        });
    }

    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(wait_secs);
    let mut events = Vec::new();
    loop {
        let now = tokio::time::Instant::now();
        if now >= deadline {
            break;
        }
        match tokio::time::timeout(deadline - now, receiver.recv()).await {
            Ok(Ok(RuntimeBusEvent::PathUpdated(path)))
                if path.destination_hash.eq_ignore_ascii_case(destination_hash) =>
            {
                events.push(serde_json::json!({
                    "event": "path_updated",
                    "destination_hash": path.destination_hash,
                    "known": path.known,
                    "hops": path.hops,
                }));
                if path.known {
                    return serde_json::json!({
                        "status": "observed",
                        "detail": "matching page destination path update observed",
                        "events": events,
                    });
                }
            }
            Ok(Ok(RuntimeBusEvent::Announce(announce)))
                if announce
                    .destination_hash
                    .eq_ignore_ascii_case(destination_hash) =>
            {
                events.push(serde_json::json!({
                    "event": "announce",
                    "destination_hash": announce.destination_hash,
                    "kind": announce.kind,
                    "display_name": announce.display_name,
                }));
            }
            Ok(Ok(RuntimeBusEvent::Debug(message)))
                if message.contains(destination_hash)
                    || message.to_lowercase().contains("path") =>
            {
                events.push(serde_json::json!({
                    "event": "debug",
                    "message": message,
                }));
            }
            Ok(Ok(_)) => {}
            Ok(Err(tokio::sync::broadcast::error::RecvError::Lagged(skipped))) => {
                events.push(serde_json::json!({
                    "event": "event_lagged",
                    "skipped": skipped,
                }));
            }
            Ok(Err(tokio::sync::broadcast::error::RecvError::Closed)) => {
                return serde_json::json!({
                    "status": "closed",
                    "detail": "runtime event stream closed while waiting for page path readiness",
                    "events": events,
                });
            }
            Err(_) => break,
        }
    }

    serde_json::json!({
        "status": "timeout",
        "detail": "no matching page destination path update arrived before retry timeout",
        "events": events,
    })
}

fn page_probe_queued_path_request(report: &PageFetchProbeReport) -> bool {
    report.steps.iter().any(|step| {
        step.stage == PageFetchProbeStage::PathDiscovery
            && !step.ok
            && step
                .trace
                .get("request_path")
                .is_some_and(|value| value == "queued")
    })
}

fn first_failed_page_probe_stage(report: &PageFetchProbeReport) -> Option<PageFetchProbeStage> {
    report
        .steps
        .iter()
        .find(|step| !step.ok)
        .map(|step| step.stage.clone())
}

async fn run_smoke_path_warmup(
    runtime: Arc<dyn NetworkRuntime>,
    active_url: &str,
    destination: Option<&str>,
    warmup: Option<SmokePathWarmup>,
) -> serde_json::Value {
    run_smoke_path_warmup_with_cancel(runtime, active_url, destination, warmup, None).await
}

async fn run_smoke_path_warmup_with_cancel(
    runtime: Arc<dyn NetworkRuntime>,
    active_url: &str,
    destination: Option<&str>,
    warmup: Option<SmokePathWarmup>,
    cancel: Option<CancellationToken>,
) -> serde_json::Value {
    let Some(warmup) = warmup else {
        return serde_json::json!({
            "requested": false,
            "status": "skip",
            "detail": "path warmup not requested",
        });
    };
    let Some(destination) = destination else {
        return serde_json::json!({
            "requested": true,
            "status": "fail",
            "detail": "active browser address did not parse to a destination hash",
        });
    };
    if cancel.as_ref().is_some_and(CancellationToken::is_cancelled) {
        return serde_json::json!({
            "requested": true,
            "status": "cancelled",
            "destination_hash": destination,
            "detail": "path warmup cancelled before request_path",
        });
    }

    let mut receiver = runtime.subscribe_events();
    let request_result = runtime
        .request_path(destination, "non-TUI native smoke path warmup", false)
        .await;
    let request_json = match &request_result {
        Ok(queued) => serde_json::json!({
            "ok": true,
            "queued_or_known": queued,
        }),
        Err(error) => serde_json::json!({
            "ok": false,
            "error": error.to_string(),
        }),
    };
    if request_result.is_err() {
        return serde_json::json!({
            "requested": true,
            "status": "fail",
            "destination_hash": destination,
            "request_path": request_json,
            "detail": "request_path failed before wait",
        });
    }

    let wait = wait_for_smoke_path_discovery(
        runtime.clone(),
        receiver.as_mut(),
        active_url,
        destination,
        warmup.wait_secs,
        cancel.as_ref(),
    )
    .await;
    serde_json::json!({
        "requested": true,
        "status": wait.get("status").cloned().unwrap_or_else(|| serde_json::json!("unknown")),
        "destination_hash": destination,
        "wait_secs": warmup.wait_secs,
        "request_path": request_json,
        "wait": wait,
    })
}

async fn wait_for_smoke_path_discovery(
    runtime: Arc<dyn NetworkRuntime>,
    receiver: Option<&mut tokio::sync::broadcast::Receiver<crate::runtime::RuntimeBusEvent>>,
    active_url: &str,
    destination: &str,
    wait_secs: u64,
    cancel: Option<&CancellationToken>,
) -> serde_json::Value {
    let mut attempts = Vec::new();
    let first_attempt =
        smoke_path_discovery_attempt(runtime.clone(), active_url, destination).await;
    if first_attempt
        .get("has_path")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        return serde_json::json!({
            "status": "pass",
            "detail": "path was known before waiting",
            "attempts": [first_attempt],
        });
    }
    attempts.push(first_attempt);

    let Some(receiver) = receiver else {
        return serde_json::json!({
            "status": "skip",
            "detail": "runtime does not expose path/announce events",
            "attempts": attempts,
        });
    };
    if wait_secs == 0 {
        return serde_json::json!({
            "status": "skip",
            "detail": "path warmup wait disabled",
            "attempts": attempts,
        });
    }
    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(wait_secs);
    let poll_interval = std::time::Duration::from_secs(1);
    loop {
        if cancel.is_some_and(CancellationToken::is_cancelled) {
            return serde_json::json!({
                "status": "cancelled",
                "detail": "path warmup cancelled while waiting for discovery",
                "attempts": attempts,
            });
        }
        let now = tokio::time::Instant::now();
        if now >= deadline {
            return serde_json::json!({
                "status": "timeout",
                "detail": "no matching path or announce event received before timeout",
                "attempts": attempts,
            });
        }
        let remaining = deadline - now;
        let wait_for = remaining.min(poll_interval);
        let event = tokio::time::timeout(wait_for, receiver.recv()).await;
        let event_json = match event {
            Ok(Ok(crate::runtime::RuntimeBusEvent::PathUpdated(path)))
                if path.destination_hash.eq_ignore_ascii_case(destination) =>
            {
                Some(serde_json::json!({
                    "status": if path.known { "pass" } else { "fail" },
                    "event": "path_updated",
                    "known": path.known,
                    "hops": path.hops,
                }))
            }
            Ok(Ok(crate::runtime::RuntimeBusEvent::Announce(announce)))
                if announce.destination_hash.eq_ignore_ascii_case(destination)
                    || announce
                        .associated_hash
                        .as_deref()
                        .is_some_and(|hash| hash.eq_ignore_ascii_case(destination))
                    || announce
                        .node_associated_hash
                        .as_deref()
                        .is_some_and(|hash| hash.eq_ignore_ascii_case(destination)) =>
            {
                Some(serde_json::json!({
                    "status": "pass",
                    "event": "announce",
                    "kind": announce.kind,
                    "destination_hash": announce.destination_hash,
                    "display_name": announce.display_name,
                }))
            }
            Ok(Ok(_)) | Ok(Err(tokio::sync::broadcast::error::RecvError::Lagged(_))) => None,
            Ok(Err(tokio::sync::broadcast::error::RecvError::Closed)) => {
                return serde_json::json!({
                    "status": "fail",
                    "detail": "runtime event channel closed while waiting",
                    "attempts": attempts,
                });
            }
            Err(_) => None,
        };

        let attempt = smoke_path_discovery_attempt(runtime.clone(), active_url, destination).await;
        let has_path = attempt
            .get("has_path")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        attempts.push(attempt);
        if has_path {
            return serde_json::json!({
                "status": "pass",
                "detail": "path became known during warmup wait",
                "event": event_json,
                "attempts": attempts,
            });
        }
        if event_json
            .as_ref()
            .and_then(|event| event.get("status"))
            .and_then(serde_json::Value::as_str)
            == Some("fail")
        {
            return serde_json::json!({
                "status": "fail",
                "detail": "runtime reported a matching negative path update",
                "event": event_json,
                "attempts": attempts,
            });
        }
    }
}

async fn smoke_path_discovery_attempt(
    runtime: Arc<dyn NetworkRuntime>,
    active_url: &str,
    destination: &str,
) -> serde_json::Value {
    let inspection = runtime
        .inspect_destination(destination, false)
        .await
        .map(|inspection| {
            let has_path = inspection.has_path;
            serde_json::json!({
                "ok": true,
                "has_path": has_path,
                "known_identity": inspection.known_identity,
                "hops": inspection.hops,
                "inspection": inspection,
            })
        })
        .unwrap_or_else(|error| {
            serde_json::json!({
                "ok": false,
                "has_path": false,
                "error": error.to_string(),
            })
        });
    let dry_run_probe = runtime
        .probe_page_fetch(active_url, false)
        .await
        .map(|report| {
            serde_json::json!({
                "ok": true,
                "ready_to_request": report.ready_to_request,
                "path_stage_ok": report.steps.iter().any(|step| {
                    step.stage == PageFetchProbeStage::PathDiscovery && step.ok
                }),
                "first_failed_stage": report.steps.iter().find(|step| !step.ok).and_then(|step| {
                    serde_json::to_value(&step.stage).ok()
                }),
                "report": report,
            })
        })
        .unwrap_or_else(|error| {
            serde_json::json!({
                "ok": false,
                "ready_to_request": false,
                "error": error.to_string(),
            })
        });

    serde_json::json!({
        "has_path": inspection
            .get("has_path")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false),
        "inspection": inspection,
        "dry_run_page_probe": dry_run_probe,
    })
}

fn native_network_smoke_test_verdicts(
    interop: &serde_json::Value,
    dry_run_probe: &serde_json::Value,
    live_probe: &serde_json::Value,
    lxmf_delivery_probe: &serde_json::Value,
    execute_live_probe: bool,
    path_warmup: &serde_json::Value,
) -> serde_json::Value {
    let dry_report = dry_run_probe.get("report");
    let live_report = live_probe.get("report");
    let readiness = interop.get("native_reticulum_readiness");
    let inspection = interop
        .get("destination_inspection")
        .and_then(|value| value.get("inspection"));

    serde_json::json!({
        "overall": overall_smoke_test_verdict(dry_report, live_report, execute_live_probe),
        "config": verdict(
            readiness
                .and_then(|value| value.get("compiled"))
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
            "native feature support is compiled",
            "build with --features native-network"
        ),
        "runtime_startup": verdict(
            readiness
                .and_then(|value| value.get("ready"))
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
            "native runtime readiness check passed",
            "select native/auto backend and fix Reticulum config/interface blockers"
        ),
        "path_warmup": path_warmup_verdict(path_warmup),
        "address_parse": probe_stage_verdict(
            dry_report,
            PageFetchProbeStage::AddressParse,
            "enter a destination:path address such as <hash>:/page/index.mu"
        ),
        "destination_identity": probe_stage_verdict(
            dry_report,
            PageFetchProbeStage::DestinationIdentity,
            "wait for a node announce, preload known_destinations, or request/warm the destination path"
        ),
        "path_discovery": probe_stage_verdict(
            dry_report,
            PageFetchProbeStage::PathDiscovery,
            "wait for path discovery or use Directory/request-path/warm-path actions"
        ),
        "destination_inspection": verdict(
            inspection
                .and_then(|value| value.get("has_path"))
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
            "destination inspection reports a known path",
            "request the destination path and retry after announce/path update"
        ),
        "link_setup": live_or_skipped_stage_verdict(
            live_report,
            execute_live_probe,
            PageFetchProbeStage::LinkSetup,
            "run Diagnostics L or X to perform an explicit live probe; if it fails, inspect Reticulum 0.6 link setup"
        ),
        "request_send": live_or_skipped_stage_verdict(
            live_report,
            execute_live_probe,
            PageFetchProbeStage::RequestSend,
            "run Diagnostics L or X; if it fails, inspect request payload/path and clean Reticulum request send"
        ),
        "response_wait": live_or_skipped_stage_verdict(
            live_report,
            execute_live_probe,
            PageFetchProbeStage::ResponseWait,
            "run Diagnostics L or X; if it times out, verify remote node availability and path stability"
        ),
        "response_decode": live_or_skipped_stage_verdict(
            live_report,
            execute_live_probe,
            PageFetchProbeStage::ResponseDecode,
            "run Diagnostics L or X; if decode fails, inspect returned payload bytes/content type"
        ),
        "lxmf_source_identity": lxmf_probe_stage_verdict(
            lxmf_delivery_probe,
            LxmfDeliveryProbeStage::SourceIdentity,
            "attach an OMEN identity before attempting LXMF delivery"
        ),
        "lxmf_peer_identity": lxmf_probe_stage_verdict(
            lxmf_delivery_probe,
            LxmfDeliveryProbeStage::PeerIdentity,
            "wait for an lxmf.delivery announce, select a saved peer, or preload known_destinations"
        ),
        "lxmf_path_discovery": lxmf_probe_stage_verdict(
            lxmf_delivery_probe,
            LxmfDeliveryProbeStage::PathDiscovery,
            "request/warm the peer path and retry after Reticulum path discovery"
        ),
        "lxmf_packet_build": lxmf_probe_stage_verdict(
            lxmf_delivery_probe,
            LxmfDeliveryProbeStage::PacketBuild,
            "inspect LXMF codec/signing errors before sending"
        ),
    })
}

fn native_network_smoke_test_classification(
    verdicts: &serde_json::Value,
    live_fetch: &serde_json::Value,
    live_fetch_readiness_retry: &serde_json::Value,
    execute_live_probe: bool,
    execute_live_fetch: bool,
) -> serde_json::Value {
    if execute_live_fetch
        && live_fetch
            .get("ok")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
    {
        return serde_json::json!({
            "outcome": "pass",
            "stage": "live_fetch",
            "reason": "live fetch returned a decoded NomadNet page",
            "detail": "fetch_page returned markup and metadata",
            "next_step": "repeat against another known NomadNet node or compare rendered Micron output with Python OMENbrowser",
        });
    }

    let stage_order = [
        (
            "config",
            "blocked",
            "native feature support is not compiled or available",
            "build with --features native-network",
        ),
        (
            "runtime_startup",
            "blocked",
            "native runtime is not ready",
            "select native/auto backend and fix Reticulum config/interface blockers",
        ),
        (
            "address_parse",
            "blocked",
            "browser address is not a native NomadNet destination:path",
            "enter a destination:path address such as <hash>:/page/index.mu",
        ),
        (
            "destination_identity",
            "blocked",
            "destination identity is not known",
            "wait for a node announce, preload known_destinations, or request/warm the destination path",
        ),
        (
            "path_discovery",
            "blocked",
            "destination path is not known",
            "request the destination path, use --warm-path, and retry after Reticulum path discovery",
        ),
        (
            "destination_inspection",
            "blocked",
            "destination inspection does not report a known path",
            "request the destination path and retry after announce/path update",
        ),
        (
            "link_setup",
            "fail",
            "live link setup failed",
            "inspect Reticulum 0.6 link setup details in live_page_probe or run with --live --fetch-page --stdout",
        ),
        (
            "request_send",
            "fail",
            "live request send failed",
            "inspect request payload/path traces and clean Reticulum request send behavior",
        ),
        (
            "response_wait",
            "timeout",
            "live request did not receive a response in time",
            "verify remote node availability, path stability, and request timeout settings",
        ),
        (
            "response_decode",
            "fail",
            "live response decode failed",
            "inspect returned payload bytes/content type and Micron decode assumptions",
        ),
    ];

    for (key, outcome, reason, fallback_next_step) in stage_order {
        if let Some(stage) = verdicts.get(key) {
            match stage.get("status").and_then(serde_json::Value::as_str) {
                Some("fail") => {
                    return serde_json::json!({
                        "outcome": outcome,
                        "stage": key,
                        "reason": reason,
                        "detail": stage.get("detail").and_then(serde_json::Value::as_str).unwrap_or(reason),
                        "next_step": stage.get("next_action").and_then(serde_json::Value::as_str).unwrap_or(fallback_next_step),
                    });
                }
                Some("skip")
                    if matches!(
                        key,
                        "link_setup" | "request_send" | "response_wait" | "response_decode"
                    ) && (execute_live_probe || execute_live_fetch) =>
                {
                    return serde_json::json!({
                        "outcome": "blocked",
                        "stage": key,
                        "reason": "requested live validation did not reach this stage",
                        "detail": stage.get("detail").and_then(serde_json::Value::as_str).unwrap_or("stage was skipped"),
                        "next_step": stage.get("next_action").and_then(serde_json::Value::as_str).unwrap_or(fallback_next_step),
                    });
                }
                _ => {}
            }
        }
    }

    if execute_live_fetch {
        if live_fetch.get("status").and_then(serde_json::Value::as_str) == Some("blocked") {
            return serde_json::json!({
                "outcome": "blocked",
                "stage": "live_fetch_preflight",
                "reason": "live fetch preflight did not become ready",
                "detail": live_fetch.get("error").and_then(serde_json::Value::as_str).unwrap_or("preflight blocked live fetch"),
                "next_step": page_fetch_stage_next_step(
                    live_fetch
                        .get("stage_hint")
                        .and_then(|value| serde_json::from_value(value.clone()).ok())
                        .as_ref()
                ),
            });
        }
        let error = live_fetch
            .get("error")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("live fetch failed");
        let stage = live_fetch
            .get("stage_hint")
            .and_then(|value| serde_json::from_value::<PageFetchProbeStage>(value.clone()).ok())
            .unwrap_or_else(|| native_page_load_failure_stage(error));
        let outcome = if stage == PageFetchProbeStage::ResponseWait {
            "timeout"
        } else if matches!(
            stage,
            PageFetchProbeStage::DestinationIdentity | PageFetchProbeStage::PathDiscovery
        ) {
            "blocked"
        } else {
            "fail"
        };
        return serde_json::json!({
            "outcome": outcome,
            "stage": serde_json::to_value(&stage).unwrap_or_else(|_| serde_json::json!("unknown")),
            "reason": page_fetch_stage_reason(&stage),
            "detail": error,
            "next_step": page_fetch_stage_next_step(Some(&stage)),
            "readiness_retry_status": live_fetch_readiness_retry.get("status").and_then(serde_json::Value::as_str),
        });
    }

    if execute_live_probe {
        serde_json::json!({
            "outcome": "pass",
            "stage": "live_probe",
            "reason": "live probe reached response decode",
            "detail": "live_page_probe has response_decode pass",
            "next_step": "rerun with --fetch-page to exercise the normal browser fetch path",
        })
    } else {
        serde_json::json!({
            "outcome": "pass",
            "stage": "dry_run_page_probe",
            "reason": "dry-run probe reports ready for a live NomadNet request",
            "detail": "preconditions for live request are satisfied",
            "next_step": "rerun with --live --fetch-page to validate real page delivery",
        })
    }
}

fn page_fetch_stage_reason(stage: &PageFetchProbeStage) -> &'static str {
    match stage {
        PageFetchProbeStage::AddressParse => "browser address could not be parsed",
        PageFetchProbeStage::RuntimeSetup => "native runtime setup failed",
        PageFetchProbeStage::DestinationIdentity => "destination identity is not known",
        PageFetchProbeStage::PathDiscovery => "destination path is not known",
        PageFetchProbeStage::LinkSetup => "live link setup failed",
        PageFetchProbeStage::RequestSend => "live request send failed",
        PageFetchProbeStage::ResponseWait => "live request timed out waiting for response",
        PageFetchProbeStage::ResponseDecode => "live response decode failed",
    }
}

fn page_fetch_stage_next_step(stage: Option<&PageFetchProbeStage>) -> &'static str {
    match stage {
        Some(PageFetchProbeStage::AddressParse) => {
            "enter a destination:path address such as <hash>:/page/index.mu"
        }
        Some(PageFetchProbeStage::RuntimeSetup) => {
            "select native/auto backend and fix Reticulum config/interface blockers"
        }
        Some(PageFetchProbeStage::DestinationIdentity) => {
            "wait for a node announce, preload known_destinations, or request/warm the destination path"
        }
        Some(PageFetchProbeStage::PathDiscovery) => {
            "request the destination path, use --warm-path, and retry after Reticulum path discovery"
        }
        Some(PageFetchProbeStage::LinkSetup) => {
            "inspect Reticulum 0.6 link setup details in live_page_probe"
        }
        Some(PageFetchProbeStage::RequestSend) => {
            "inspect request payload/path traces and clean Reticulum request send behavior"
        }
        Some(PageFetchProbeStage::ResponseWait) => {
            "verify remote node availability, path stability, and request timeout settings"
        }
        Some(PageFetchProbeStage::ResponseDecode) => {
            "inspect returned payload bytes/content type and Micron decode assumptions"
        }
        None => "inspect verdicts and rerun with --stdout for the full JSON report",
    }
}

fn path_warmup_verdict(path_warmup: &serde_json::Value) -> serde_json::Value {
    if !path_warmup
        .get("requested")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        return skipped(
            "path warmup was not requested",
            "rerun smoke command with --warm-path before retrying a destination with unknown path",
        );
    }

    let request_ok = path_warmup
        .get("request_path")
        .and_then(|value| value.get("ok"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    if !request_ok {
        let detail = path_warmup
            .get("request_path")
            .and_then(|value| value.get("error"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or("request_path failed");
        return failed(
            detail,
            "verify native runtime startup, destination hash format, and Reticulum transport support",
        );
    }

    match path_warmup
        .get("wait")
        .and_then(|value| value.get("status"))
        .and_then(serde_json::Value::as_str)
    {
        Some("pass") => passed("matching path or announce event was observed"),
        Some("skip") if path_warmup_last_attempt_has_path(path_warmup) => {
            passed("path request was accepted and path is known")
        }
        Some("skip") => skipped(
            "path request was accepted but wait was disabled before path became known",
            "rerun with --path-wait greater than zero or retry after Reticulum path discovery",
        ),
        Some("timeout") => failed(
            "path request was accepted but no matching path/announce event arrived before timeout",
            "confirm interface connectivity and retry with a longer --path-wait",
        ),
        Some("fail") => failed(
            "runtime reported a negative path warmup event",
            "inspect runtime logs and Reticulum path discovery state",
        ),
        _ => skipped(
            "path warmup status was unavailable",
            "rerun with --warm-path and inspect path_warmup.wait in the JSON report",
        ),
    }
}

fn path_warmup_last_attempt_has_path(path_warmup: &serde_json::Value) -> bool {
    path_warmup
        .get("wait")
        .and_then(|value| value.get("attempts"))
        .and_then(serde_json::Value::as_array)
        .and_then(|attempts| attempts.last())
        .and_then(|attempt| attempt.get("has_path"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
}

async fn preload_known_destinations_and_recheck_path(
    runtime: Arc<dyn NetworkRuntime>,
    path: PathBuf,
    active_url: String,
    destination: Option<String>,
) -> AppResult<serde_json::Value> {
    if !path.is_file() {
        return Err(crate::error::AppError::Runtime(format!(
            "known destinations file does not exist: {}",
            path.display()
        )));
    }
    let loaded = runtime.preload_known_destinations(&path).await?;
    let source_hint = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("known_destinations")
        .to_string();
    let path_warmup = run_smoke_path_warmup(
        runtime,
        &active_url,
        destination.as_deref(),
        Some(SmokePathWarmup { wait_secs: 5 }),
    )
    .await;

    Ok(serde_json::json!({
        "report": "known_destinations_preload",
        "active_browser_url": active_url,
        "destination_hash": destination,
        "known_destinations_preload": {
            "source_hint": source_hint,
            "loaded": loaded,
        },
        "path_warmup": path_warmup,
    }))
}

fn overall_smoke_test_verdict(
    dry_report: Option<&serde_json::Value>,
    live_report: Option<&serde_json::Value>,
    execute_live_probe: bool,
) -> serde_json::Value {
    let dry_ready = dry_report
        .and_then(|report| report.get("ready_to_request"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let live_ready = live_report
        .map(|report| probe_stage_ok(report, PageFetchProbeStage::ResponseDecode))
        .unwrap_or(false);
    if execute_live_probe {
        verdict(
            live_ready,
            "live probe reached response decode",
            "inspect the first failed live verdict stage and retry after fixing it",
        )
    } else {
        verdict(
            dry_ready,
            "dry-run probe reports ready for live request",
            "fix the first failed dry-run verdict stage, or run L/X only when ready",
        )
    }
}

fn probe_stage_verdict(
    report: Option<&serde_json::Value>,
    stage: PageFetchProbeStage,
    next_action: &str,
) -> serde_json::Value {
    let Some(report) = report else {
        return skipped("probe report unavailable", next_action);
    };
    let Some(step) = probe_stage_step(report, stage.clone()) else {
        return skipped("stage was not reached", next_action);
    };
    let ok = step
        .get("ok")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let detail = step
        .get("detail")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("stage reported no detail");
    if ok {
        passed(detail)
    } else {
        failed(detail, next_action)
    }
}

fn live_or_skipped_stage_verdict(
    report: Option<&serde_json::Value>,
    executed: bool,
    stage: PageFetchProbeStage,
    next_action: &str,
) -> serde_json::Value {
    if !executed {
        return skipped("live probe was not requested", next_action);
    }
    probe_stage_verdict(report, stage, next_action)
}

fn lxmf_probe_stage_verdict(
    probe: &serde_json::Value,
    stage: LxmfDeliveryProbeStage,
    next_action: &str,
) -> serde_json::Value {
    if probe.get("report").is_none() {
        let detail = probe
            .get("error")
            .or_else(|| probe.get("skipped"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or("LXMF delivery probe report unavailable");
        return skipped(detail, next_action);
    }
    let Some(report) = probe.get("report") else {
        return skipped("LXMF delivery probe report unavailable", next_action);
    };
    let Some(step) = lxmf_probe_stage_step(report, stage) else {
        return skipped("LXMF delivery stage was not reached", next_action);
    };
    let ok = step
        .get("ok")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let detail = step
        .get("detail")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("stage reported no detail");
    if ok {
        passed(detail)
    } else {
        failed(detail, next_action)
    }
}

fn probe_stage_ok(report: &serde_json::Value, stage: PageFetchProbeStage) -> bool {
    probe_stage_step(report, stage)
        .and_then(|step| step.get("ok"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
}

fn probe_stage_step(
    report: &serde_json::Value,
    stage: PageFetchProbeStage,
) -> Option<&serde_json::Value> {
    let stage_name = serde_json::to_value(stage).ok()?;
    report
        .get("steps")
        .and_then(serde_json::Value::as_array)?
        .iter()
        .find(|step| step.get("stage") == Some(&stage_name))
}

fn lxmf_probe_stage_step(
    report: &serde_json::Value,
    stage: LxmfDeliveryProbeStage,
) -> Option<&serde_json::Value> {
    let stage_name = serde_json::to_value(stage).ok()?;
    report
        .get("steps")
        .and_then(serde_json::Value::as_array)?
        .iter()
        .find(|step| step.get("stage") == Some(&stage_name))
}

fn native_preflight_report_for_app(
    app: &App,
    destination: &str,
    lxmf_peer: Option<&str>,
) -> serde_json::Value {
    let readiness = app.native_reticulum_readiness();
    let parsed_address = BrowserAddress::parse(destination);
    let destination_hash_valid = parsed_address
        .as_ref()
        .is_some_and(|address| is_16_byte_hex_hash(&address.destination));
    let reticulum_config_path = app
        .settings
        .reticulum_config_path
        .as_ref()
        .unwrap_or(&app.paths.reticulum_config_dir);
    let known_destinations_path = reticulum_config_path
        .join("storage")
        .join("known_destinations");

    let mut stages = vec![
        native_preflight_stage(
            "backend",
            matches!(
                app.settings.runtime_backend,
                RuntimeBackendSetting::Reticulum | RuntimeBackendSetting::Auto
            ),
            true,
            format!("{:?}", app.settings.runtime_backend),
            "select Auto or Reticulum backend before native validation",
        ),
        native_preflight_stage(
            "native_reticulum_readiness",
            readiness.ready,
            readiness.configured,
            readiness.summary.clone(),
            "fix native readiness issues before NomadNet fetch or LXMF delivery",
        ),
        native_preflight_path_stage(
            "identity_path",
            app.settings.identity_path.as_ref(),
            true,
            "create or attach an identity before live native networking",
        ),
        native_preflight_path_stage(
            "reticulum_config_path",
            Some(reticulum_config_path),
            false,
            "provide an existing Reticulum config directory or use the managed config path",
        ),
        native_preflight_stage(
            "nomadnet_address",
            parsed_address.is_some(),
            false,
            parsed_address
                .as_ref()
                .map(|address| format!("destination={} path={}", address.destination, address.path))
                .unwrap_or_else(|| "destination could not be parsed".into()),
            "use a destination:path address such as 00112233445566778899aabbccddeeff:/page/index.mu",
        ),
        native_preflight_stage(
            "nomadnet_destination_hash",
            destination_hash_valid,
            false,
            if destination_hash_valid {
                String::from("32 hex character destination hash")
            } else {
                String::from("destination hash must be exactly 32 hexadecimal characters")
            },
            "copy the 16-byte NomadNet destination hash, not a full Reticulum address blob",
        ),
        native_preflight_stage(
            "known_destinations",
            known_destinations_path.is_file(),
            false,
            serde_json::json!({
                "path": known_destinations_path.display().to_string(),
                "exists": known_destinations_path.is_file(),
                "semantic_check": "not_run_from_desktop",
            })
            .to_string(),
            "preload an existing known_destinations file or wait for announces/path discovery",
        ),
    ];

    if let Some(peer) = lxmf_peer {
        stages.push(native_preflight_stage(
            "lxmf_peer_hash",
            is_16_byte_hex_hash(peer),
            false,
            if is_16_byte_hex_hash(peer) {
                String::from("32 hex character LXMF delivery hash")
            } else {
                String::from("LXMF peer hash must be exactly 32 hexadecimal characters")
            },
            "open/select a conversation using an lxmf.delivery destination hash",
        ));
    }

    let classification = native_preflight_classification(&stages);
    serde_json::json!({
        "schema_version": "omenbrowser_rs.native_preflight.v1",
        "report": "native_network_preflight",
        "destination": destination,
        "lxmf_peer": lxmf_peer,
        "classification": classification,
        "native_reticulum_readiness": {
            "compiled": readiness.compiled,
            "configured": readiness.configured,
            "ready": readiness.ready,
            "summary": readiness.summary,
            "issues": readiness.issues,
        },
        "interface_readiness": app.native_interface_readiness().into_iter().map(|detail| serde_json::json!({
            "profile_id": detail.profile_id,
            "name": detail.name,
            "kind": detail.kind,
            "enabled": detail.enabled,
            "supported": detail.supported,
            "blocks_native_startup": detail.blocks_native_startup,
            "reason": detail.reason,
            "warnings": detail.warnings,
        })).collect::<Vec<_>>(),
        "stages": stages,
    })
}

fn native_preflight_stage(
    stage: &str,
    passed: bool,
    blocked: bool,
    detail: impl Into<String>,
    next_step: &str,
) -> serde_json::Value {
    let outcome = if passed {
        "pass"
    } else if blocked {
        "blocked"
    } else {
        "fail"
    };
    serde_json::json!({
        "stage": stage,
        "outcome": outcome,
        "detail": detail.into(),
        "next_step": if passed { "continue" } else { next_step },
    })
}

fn native_preflight_path_stage(
    stage: &str,
    path: Option<&PathBuf>,
    must_be_file: bool,
    next_step: &str,
) -> serde_json::Value {
    let Some(path) = path else {
        return native_preflight_stage(stage, false, true, "path is not configured", next_step);
    };
    let exists = if must_be_file {
        path.is_file()
    } else {
        path.is_dir()
    };
    native_preflight_stage(
        stage,
        exists,
        !exists,
        serde_json::json!({
            "path": path.display().to_string(),
            "kind": if must_be_file { "file" } else { "directory" },
            "exists": exists,
        })
        .to_string(),
        next_step,
    )
}

fn native_preflight_classification(stages: &[serde_json::Value]) -> serde_json::Value {
    if let Some(stage) = stages
        .iter()
        .find(|stage| stage.get("outcome").and_then(serde_json::Value::as_str) == Some("fail"))
    {
        return native_preflight_classification_for_stage("fail", stage);
    }
    if let Some(stage) = stages
        .iter()
        .find(|stage| stage.get("outcome").and_then(serde_json::Value::as_str) == Some("blocked"))
    {
        return native_preflight_classification_for_stage("blocked", stage);
    }
    serde_json::json!({
        "outcome": "pass",
        "stage": "ready",
        "reason": "all preflight stages passed",
        "next_step": "run native smoke with live probe or LXMF interop",
    })
}

fn native_preflight_classification_for_stage(
    outcome: &str,
    stage: &serde_json::Value,
) -> serde_json::Value {
    serde_json::json!({
        "outcome": outcome,
        "stage": stage.get("stage").and_then(serde_json::Value::as_str).unwrap_or("unknown"),
        "reason": stage.get("detail").and_then(serde_json::Value::as_str).unwrap_or("preflight stage failed"),
        "next_step": stage.get("next_step").and_then(serde_json::Value::as_str).unwrap_or("inspect preflight stages"),
    })
}

fn is_16_byte_hex_hash(value: &str) -> bool {
    value.len() == 32 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn normalize_lxmf_peer_input(value: &str) -> String {
    value
        .trim()
        .strip_prefix("lxmf.delivery@")
        .or_else(|| value.trim().strip_prefix("lxmf@"))
        .unwrap_or_else(|| value.trim())
        .trim()
        .to_ascii_lowercase()
}

fn compact_hash(value: &str) -> String {
    let value = value.trim();
    if value.len() <= 16 {
        value.into()
    } else {
        format!("{}..{}", &value[..8], &value[value.len() - 6..])
    }
}

fn hex_lower(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn network_doctor_facade_events_from_runtime_bus_event(
    event: &RuntimeBusEvent,
) -> Vec<RuntimeFacadeEvent> {
    match event {
        RuntimeBusEvent::Announce(announce) => vec![RuntimeFacadeEvent::AnnounceObserved {
            destination_hash: announce.destination_hash.clone(),
            kind: format!("{:?}", announce.kind),
            display_name: announce.display_name.clone(),
            has_ratchet: announce.has_ratchet,
        }],
        RuntimeBusEvent::PathUpdated(path) => vec![RuntimeFacadeEvent::PathUpdated {
            destination_hash: path.destination_hash.clone(),
            known: path.known,
            hops: path.hops,
        }],
        RuntimeBusEvent::InterfaceStats(stats) => stats
            .samples
            .iter()
            .filter_map(|sample| {
                let interface_id = if sample.profile_id.is_empty() {
                    sample.name.clone()
                } else {
                    sample.profile_id.clone()
                };
                let detail = Some(format!(
                    "{} {}{}",
                    sample.kind,
                    sample.endpoint.as_deref().unwrap_or("endpoint unavailable"),
                    sample
                        .detail
                        .as_deref()
                        .map(|detail| format!(" | {detail}"))
                        .unwrap_or_default()
                ));
                if sample.attached
                    || sample.state == crate::runtime::network::InterfaceSampleState::Attached
                {
                    Some(RuntimeFacadeEvent::InterfaceUp {
                        interface_id,
                        detail,
                    })
                } else if sample.enabled && sample.supported {
                    Some(RuntimeFacadeEvent::InterfaceDown {
                        interface_id,
                        reason: detail,
                    })
                } else {
                    None
                }
            })
            .collect(),
        RuntimeBusEvent::MessageDeliveryUpdated(status) => {
            let state = if status.failed {
                "delivery_failed"
            } else if status.delivered {
                "delivery_delivered"
            } else {
                "delivery_updated"
            };
            let mut events = vec![RuntimeFacadeEvent::LxmfEvent {
                event: state.into(),
                detail: Some(format!(
                    "peer={} message={} state={:?} evidence={}",
                    compact_hash(&status.peer_hash),
                    status.message_id.as_deref().unwrap_or("none"),
                    status.state,
                    status.evidence.as_deref().unwrap_or("none")
                )),
            }];
            if let Some(progress) = lxmf_resource_progress_from_evidence(
                &status.peer_hash,
                status.message_id.as_deref(),
                status.evidence.as_deref(),
            ) {
                events.push(progress);
            }
            events
        }
        RuntimeBusEvent::LxmfDeliveryEvidence(evidence) => {
            let mut events = vec![RuntimeFacadeEvent::LxmfEvent {
                event: format!("{:?}", evidence.kind).to_ascii_lowercase(),
                detail: Some(format!(
                    "peer={} message={} detail={}",
                    compact_hash(&evidence.peer_hash),
                    evidence.message_id.as_deref().unwrap_or("none"),
                    evidence.detail.as_deref().unwrap_or("none")
                )),
            }];
            if let Some(progress) = lxmf_resource_progress_from_evidence(
                &evidence.peer_hash,
                evidence.message_id.as_deref(),
                evidence.detail.as_deref(),
            ) {
                events.push(progress);
            }
            events
        }
        RuntimeBusEvent::OmenChatLinkData(data) => vec![RuntimeFacadeEvent::LinkFrameReceived {
            link_id: hex_lower(&data.link_id),
            bytes: data.frame_bytes.len(),
        }],
        RuntimeBusEvent::OmenChatLinkClosed(data) => vec![RuntimeFacadeEvent::LinkClosed {
            link_id: hex_lower(&data.link_id),
            reason: data.reason.clone(),
        }],
        RuntimeBusEvent::OmenChatResourceData(data) => vec![RuntimeFacadeEvent::ResourceComplete {
            transfer_id: hex_lower(&data.link_id),
            bytes: data.data.len() as u64,
            source: Some("omenchat".into()),
            purpose: Some("omenchat-resource".into()),
            direction: Some("inbound".into()),
            peer: None,
        }],
        RuntimeBusEvent::ResourceProgress(progress) => vec![RuntimeFacadeEvent::ResourceProgress {
            transfer_id: progress.transfer_id.clone(),
            received: progress.received,
            total: progress.total,
            source: progress.source.clone(),
            purpose: progress.purpose.clone(),
            direction: progress.direction.clone(),
            peer: progress.peer.clone(),
        }],
        RuntimeBusEvent::ResourceLifecycle(lifecycle) => match lifecycle.state {
            crate::runtime::ResourceLifecycleState::Offered => {
                vec![RuntimeFacadeEvent::ResourceOffered {
                    link_id: lifecycle.peer.clone().unwrap_or_else(|| "unknown".into()),
                    transfer_id: lifecycle.transfer_id.clone(),
                    purpose: lifecycle
                        .purpose
                        .clone()
                        .unwrap_or_else(|| "resource".into()),
                    bytes: lifecycle.bytes,
                    source: lifecycle.source.clone(),
                    direction: lifecycle.direction.clone(),
                    peer: lifecycle.peer.clone(),
                }]
            }
            crate::runtime::ResourceLifecycleState::Complete => {
                vec![RuntimeFacadeEvent::ResourceComplete {
                    transfer_id: lifecycle.transfer_id.clone(),
                    bytes: lifecycle.bytes.unwrap_or(0),
                    source: lifecycle.source.clone(),
                    purpose: lifecycle.purpose.clone(),
                    direction: lifecycle.direction.clone(),
                    peer: lifecycle.peer.clone(),
                }]
            }
            crate::runtime::ResourceLifecycleState::Failed
            | crate::runtime::ResourceLifecycleState::Cancelled => {
                vec![RuntimeFacadeEvent::ResourceFailed {
                    transfer_id: lifecycle.transfer_id.clone(),
                    reason: lifecycle.reason.clone().unwrap_or_else(|| {
                        match lifecycle.state {
                            crate::runtime::ResourceLifecycleState::Cancelled => "cancelled",
                            _ => "failed",
                        }
                        .into()
                    }),
                    source: lifecycle.source.clone(),
                    purpose: lifecycle.purpose.clone(),
                    direction: lifecycle.direction.clone(),
                    peer: lifecycle.peer.clone(),
                }]
            }
        },
        _ => Vec::new(),
    }
}

fn directory_entry_path_candidates(entry: &DirectoryEntry) -> Vec<String> {
    let mut candidates = Vec::new();
    let mut seen = BTreeSet::new();
    for hash in [
        Some(entry.destination_hash.as_str()),
        entry.associated_hash.as_deref(),
        entry.node_associated_hash.as_deref(),
    ]
    .into_iter()
    .flatten()
    {
        let hash = hash.trim();
        if hash.is_empty() {
            continue;
        }
        let normalized = hash.to_ascii_lowercase();
        if seen.insert(normalized.clone()) {
            candidates.push(normalized);
        }
    }
    candidates
}

fn propagation_sync_stage_hint(report: &serde_json::Value) -> String {
    if let Some(stage) = report
        .get("sync_events")
        .and_then(serde_json::Value::as_array)
        .and_then(|events| {
            events.iter().rev().find_map(|event| {
                let kind = event.get("kind").and_then(serde_json::Value::as_str)?;
                (kind == "propagation_sync").then(|| {
                    event
                        .get("stage")
                        .and_then(serde_json::Value::as_str)
                        .map(ToOwned::to_owned)
                })?
            })
        })
    {
        return stage;
    }
    let error = report
        .get("sync")
        .and_then(|sync| sync.get("error"))
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .to_ascii_lowercase();
    let after = report.get("after");
    let has_path = after
        .and_then(|after| after.get("has_path"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let known_app_data = after
        .and_then(|after| after.get("known_app_data"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let transfer_state = after
        .and_then(|after| after.get("transfer_state"))
        .and_then(serde_json::Value::as_str)
        .unwrap_or("unknown");

    if report
        .get("selected_node")
        .is_none_or(serde_json::Value::is_null)
    {
        "no_propagation_node".into()
    } else if !has_path {
        "path_missing".into()
    } else if !known_app_data {
        "app_data_missing".into()
    } else if error.contains("timeout") && transfer_state.contains("list") {
        "list_request_timeout".into()
    } else if error.contains("timeout") && transfer_state.contains("receiving") {
        "get_request_timeout".into()
    } else if error.contains("decode") {
        "decode_failed".into()
    } else if !error.is_empty() {
        "sync_error".into()
    } else {
        transfer_state.into()
    }
}

fn relative_age_label(epoch_secs: f64) -> String {
    if epoch_secs <= 0.0 {
        return "never".into();
    }
    let now_secs = current_epoch_ms() as f64 / 1_000.0;
    let elapsed = (now_secs - epoch_secs).max(0.0) as u64;
    match elapsed {
        0..=59 => format!("{elapsed}s ago"),
        60..=3_599 => format!("{}m ago", elapsed / 60),
        3_600..=86_399 => format!("{}h ago", elapsed / 3_600),
        _ => format!("{}d ago", elapsed / 86_400),
    }
}

fn known_label(value: bool) -> &'static str {
    if value {
        "known"
    } else {
        "missing"
    }
}

fn extract_lxmf_evidence_value<'a>(evidence: &'a str, key: &str) -> Option<&'a str> {
    let prefix = format!("{key}:");
    evidence
        .split(';')
        .find_map(|part| part.strip_prefix(prefix.as_str()))
}

fn lxmf_resource_progress_from_evidence(
    peer_hash: &str,
    message_id: Option<&str>,
    evidence: Option<&str>,
) -> Option<RuntimeFacadeEvent> {
    let evidence = evidence?;
    let received = extract_lxmf_evidence_value(evidence, "resource_received")?
        .parse::<u64>()
        .ok()?;
    let total = extract_lxmf_evidence_value(evidence, "resource_total")
        .and_then(|value| value.parse::<u64>().ok());
    let transfer_id = extract_lxmf_evidence_value(evidence, "direct_link_id")
        .or_else(|| extract_lxmf_evidence_value(evidence, "propagation_link_id"))
        .or(message_id)
        .map(str::to_owned)
        .unwrap_or_else(|| compact_hash(peer_hash));
    Some(RuntimeFacadeEvent::ResourceProgress {
        transfer_id,
        received,
        total,
        source: Some("lxmf-evidence".into()),
        purpose: Some("lxmf".into()),
        direction: Some("outbound".into()),
        peer: Some(compact_hash(peer_hash)),
    })
}

fn lxmf_propagation_state_for_transfer(transfer_state: &str) -> &'static str {
    match transfer_state {
        "link_packet_sent" | "resource_advertised" | "resource_completed" => {
            "accepted_by_propagation_node"
        }
        "link_packet_failed"
        | "resource_failed"
        | "resource_advertise_failed"
        | "resource_timeout"
        | "router_timeout"
        | "link_timeout" => "failed",
        "resource_progress" => "in_progress",
        "router_deferred" => "deferred",
        _ => "queued",
    }
}

fn lxmf_state_for_propagation_transfer(transfer_state: &str) -> &'static str {
    match transfer_state {
        "link_packet_sent" | "resource_advertised" | "resource_completed" => {
            "propagation_transfer_completed"
        }
        "link_packet_failed"
        | "resource_failed"
        | "resource_advertise_failed"
        | "resource_timeout"
        | "router_timeout"
        | "link_timeout" => "failed",
        _ => "queued_for_propagation",
    }
}

fn lxmf_propagation_receipt_state_for_transfer(transfer_state: &str) -> &'static str {
    match transfer_state {
        "link_packet_sent" | "resource_advertised" | "resource_completed" => {
            "propagation_node_accepted_peer_unconfirmed"
        }
        "link_packet_failed"
        | "resource_failed"
        | "resource_advertise_failed"
        | "resource_timeout"
        | "router_timeout"
        | "link_timeout" => "propagation_resource_failed",
        "resource_progress" => "propagation_resource_in_progress",
        _ => "propagation_queued",
    }
}

fn lxmf_propagation_proof_state_for_transfer(transfer_state: &str) -> &'static str {
    match transfer_state {
        "link_packet_sent" | "resource_advertised" | "resource_completed" => {
            "peer_delivery_unconfirmed"
        }
        "link_packet_failed"
        | "resource_failed"
        | "resource_advertise_failed"
        | "resource_timeout"
        | "router_timeout"
        | "link_timeout" => "failed",
        "resource_progress" => "propagation_resource_in_progress",
        _ => "propagation_queued",
    }
}

fn lxmf_retry_guidance_for_propagation_transfer(transfer_state: &str) -> &'static str {
    match transfer_state {
        "link_packet_sent" => {
            "LXMF propagation envelope was sent to the propagation node; sync propagation or wait for peer delivery evidence"
        }
        "resource_completed" => {
            "LXMF wire payload transferred to propagation node; sync propagation or wait for peer delivery evidence"
        }
        "resource_advertised" => {
            "LXMF propagation resource was handed to the propagation node; sync propagation or wait for peer delivery evidence"
        }
        "link_packet_failed"
        | "resource_failed"
        | "resource_advertise_failed"
        | "resource_timeout"
        | "router_timeout"
        | "link_timeout" => {
            "propagation transfer failed; run Prop Diag and retry after the blocker is fixed"
        }
        "resource_progress" => {
            "propagation transfer is in progress; wait for resource completion or failure"
        }
        _ => "propagation message is queued; verify propagation node path/app-data if it does not progress",
    }
}

fn lxmf_state_for_direct_transfer(transfer_state: &str) -> &'static str {
    match transfer_state {
        "link_packet_sent" => "submitted_unconfirmed",
        "resource_completed" => "submitted_unconfirmed",
        "resource_failed" => "failed",
        "resource_timeout" => "submitted_unconfirmed",
        _ => "submitted_to_rns_net",
    }
}

fn lxmf_direct_receipt_state_for_transfer(transfer_state: &str) -> &'static str {
    match transfer_state {
        "link_packet_sent" => "direct_link_packet_sent_peer_unconfirmed",
        "resource_completed" => "direct_resource_completed_peer_unconfirmed",
        "resource_failed" => "lxmf_failed",
        "resource_timeout" => "direct_resource_timeout",
        "resource_progress" | "resource_advertised" => "direct_resource_in_progress",
        _ => "direct_resource_state_unknown",
    }
}

fn lxmf_direct_proof_state_for_transfer(transfer_state: &str) -> &'static str {
    match transfer_state {
        "link_packet_sent" => "link_packet_sent",
        "resource_completed" => "resource_completed",
        "resource_failed" => "failed",
        "resource_timeout" => "resource_timeout",
        "resource_progress" => "resource_progress",
        "resource_advertised" => "resource_advertised",
        _ => "direct_resource_state_unknown",
    }
}

fn lxmf_retry_guidance_for_direct_transfer(transfer_state: &str) -> &'static str {
    match transfer_state {
        "link_packet_sent" => "LXMF direct link packet was sent on an established encrypted link; wait for LXMF router evidence or peer activity before treating it as final",
        "resource_completed" => "LXMF direct resource transfer completed; wait for LXMF router evidence or peer activity before treating it as final",
        "resource_failed" => {
            "LXMF direct resource transfer failed; inspect peer/path and retry after the blocker is fixed"
        }
        "resource_timeout" => {
            "LXMF direct resource was accepted by the native transport but no sender-side completion proof arrived"
        }
        "resource_progress" | "resource_advertised" => {
            "LXMF direct resource is in progress; wait for completion, failure, or peer activity"
        }
        _ => "LXMF direct resource state is unknown; inspect peer/path before retrying",
    }
}

fn lxmf_delivery_evidence_fields(evidence: &LxmfDeliveryEvidence) -> BTreeMap<String, String> {
    let mut fields = BTreeMap::new();
    fields.insert(
        "native_lxmf_delivery_evidence_kind".into(),
        lxmf_delivery_evidence_kind_label(evidence.kind).into(),
    );
    if let Some(detail) = &evidence.detail {
        fields.insert(
            "native_lxmf_delivery_evidence_detail".into(),
            detail.clone(),
        );
        for (key, field) in [
            ("packet_hash", "native_lxmf_evidence_packet_hash"),
            ("direct_transfer_state", "native_lxmf_direct_transfer_state"),
            ("direct_link_id", "native_lxmf_direct_link_id"),
            (
                "propagation_transfer_state",
                "native_lxmf_propagation_transfer_state",
            ),
            ("propagation_link_id", "native_lxmf_propagation_link_id"),
            ("propagation_node", "native_lxmf_propagation_node"),
            ("receipt_state", "native_lxmf_receipt_state"),
            ("delivery_state", "native_lxmf_delivery_state"),
            ("proof_destination", "native_lxmf_proof_destination"),
            ("matched_pending", "native_lxmf_proof_matched_pending"),
            (
                "direct_timeout_age_secs",
                "native_lxmf_direct_timeout_age_secs",
            ),
            (
                "peer_activity_observed",
                "native_lxmf_peer_activity_observed",
            ),
            ("requested", "native_lxmf_propagation_sync_requested"),
            ("decoded", "native_lxmf_propagation_sync_decoded"),
            ("haves", "native_lxmf_propagation_sync_haves"),
            ("proof_state", "native_lxmf_evidence_proof_state"),
        ] {
            if let Some(value) = extract_lxmf_evidence_value(detail, key) {
                fields.insert(field.into(), value.into());
            }
        }
        if let Some(transfer_state) = extract_lxmf_evidence_value(detail, "direct_transfer_state") {
            fields.insert(
                "native_lxmf_receipt_state".into(),
                lxmf_direct_receipt_state_for_transfer(transfer_state).into(),
            );
            fields.insert(
                "native_lxmf_proof_state".into(),
                lxmf_direct_proof_state_for_transfer(transfer_state).into(),
            );
            fields.insert(
                "native_lxmf_state".into(),
                lxmf_state_for_direct_transfer(transfer_state).into(),
            );
            fields.insert(
                "native_lxmf_retry_guidance".into(),
                lxmf_retry_guidance_for_direct_transfer(transfer_state).into(),
            );
        }
    }
    if let Some(observed_at) = evidence.observed_at {
        fields.insert(
            "native_lxmf_delivery_evidence_observed_at".into(),
            format!("{observed_at:.3}"),
        );
    }
    if let Some(rtt) = evidence.rtt {
        fields.insert("native_lxmf_rtt".into(), format!("{rtt:.3}"));
    }
    if let Some(retry_after) = lxmf_retry_after_epoch_secs_for_evidence(evidence) {
        fields.insert(
            "native_lxmf_retry_after_epoch_secs".into(),
            format!("{retry_after:.3}"),
        );
    }
    match evidence.kind {
        LxmfDeliveryEvidenceKind::PacketSubmitted => {
            fields
                .entry("native_lxmf_receipt_state".into())
                .or_insert_with(|| "packet_submitted".into());
        }
        LxmfDeliveryEvidenceKind::RnsPacketProof => {
            fields.insert(
                "native_lxmf_proof_state".into(),
                "rns_packet_proof_peer_unconfirmed".into(),
            );
            fields.insert(
                "native_lxmf_receipt_state".into(),
                "rns_packet_proof_peer_delivery_unconfirmed".into(),
            );
            fields.insert(
                "native_lxmf_state".into(),
                "transport_proof_received".into(),
            );
            fields.insert(
                "native_lxmf_retry_guidance".into(),
                "RNS packet proof received, but native Rust has not observed LXMF router delivery or peer activity"
                    .into(),
            );
        }
        LxmfDeliveryEvidenceKind::PropagationNodeAccepted => {
            fields.insert(
                "native_lxmf_receipt_state".into(),
                "propagation_node_accepted_peer_unconfirmed".into(),
            );
            fields.insert(
                "native_lxmf_proof_state".into(),
                "peer_delivery_unconfirmed".into(),
            );
            fields.insert(
                "native_lxmf_state".into(),
                "propagation_node_accepted".into(),
            );
            fields.insert("native_lxmf_next_action".into(), "sync_propagation".into());
            fields.insert(
                "native_lxmf_retry_guidance".into(),
                "propagation node accepted the payload; sync propagation or wait for peer activity before resending"
                    .into(),
            );
        }
        LxmfDeliveryEvidenceKind::PropagationNodeFailed => {
            fields.insert(
                "native_lxmf_receipt_state".into(),
                "propagation_node_failed".into(),
            );
            fields.insert("native_lxmf_proof_state".into(), "failed".into());
            fields.insert("native_lxmf_state".into(), "failed".into());
            fields.insert(
                "native_lxmf_next_action".into(),
                "retry_propagated_send".into(),
            );
            fields.insert(
                "native_lxmf_retry_guidance".into(),
                "propagation node transfer failed; inspect propagation readiness, then retry after the backoff"
                    .into(),
            );
        }
        LxmfDeliveryEvidenceKind::PropagationSyncNoPayloads => {
            fields.insert(
                "native_lxmf_receipt_state".into(),
                "propagation_sync_no_peer_payload".into(),
            );
            fields.insert(
                "native_lxmf_proof_state".into(),
                "peer_delivery_unconfirmed".into(),
            );
            fields.insert(
                "native_lxmf_state".into(),
                "propagation_sync_no_payloads".into(),
            );
            fields.insert(
                "native_lxmf_retry_guidance".into(),
                "propagation sync completed but returned no peer payload; wait for the backoff, sync again, or watch for peer activity before resending"
                    .into(),
            );
            fields.insert(
                "native_lxmf_next_action".into(),
                "sync_propagation_again".into(),
            );
        }
        LxmfDeliveryEvidenceKind::LxmfRouterDelivered => {
            fields.insert("native_lxmf_receipt_state".into(), "lxmf_delivered".into());
            fields.insert(
                "native_lxmf_proof_state".into(),
                "lxmf_router_callback".into(),
            );
            fields.insert("native_lxmf_state".into(), "delivered".into());
            fields.insert(
                "native_lxmf_retry_guidance".into(),
                "LXMF router delivered callback received; no retry needed".into(),
            );
        }
        LxmfDeliveryEvidenceKind::LxmfRouterFailed => {
            fields.insert("native_lxmf_receipt_state".into(), "lxmf_failed".into());
            fields.insert("native_lxmf_proof_state".into(), "failed".into());
            fields.insert("native_lxmf_state".into(), "failed".into());
            fields.insert(
                "native_lxmf_retry_guidance".into(),
                "LXMF router failed callback received; inspect peer/path and retry after the blocker is fixed"
                    .into(),
            );
        }
        LxmfDeliveryEvidenceKind::InboundPeerMessage => {
            fields.insert(
                "native_lxmf_receipt_state".into(),
                "peer_activity_after_send".into(),
            );
            fields.insert("native_lxmf_peer_activity_observed".into(), "true".into());
            fields
                .entry("native_lxmf_proof_state".into())
                .or_insert_with(|| "peer_activity_observed".into());
        }
        LxmfDeliveryEvidenceKind::NoReceiptObserved => {
            let direct_transfer_state = evidence
                .detail
                .as_deref()
                .and_then(|detail| extract_lxmf_evidence_value(detail, "direct_transfer_state"));
            if direct_transfer_state.is_none() {
                fields.insert(
                    "native_lxmf_receipt_state".into(),
                    "lxmf_delivery_receipt_unavailable_native_wire".into(),
                );
                fields.insert(
                    "native_lxmf_proof_state".into(),
                    "proof_not_observed".into(),
                );
            }
            let fallback_ready = evidence
                .detail
                .as_deref()
                .and_then(|detail| extract_lxmf_evidence_value(detail, "fallback_ready"))
                == Some("true");
            if direct_transfer_state.is_none() || fallback_ready {
                fields.insert(
                    "native_lxmf_state".into(),
                    if fallback_ready {
                        "propagation_retry_ready"
                    } else {
                        "submitted_unconfirmed"
                    }
                    .into(),
                );
                fields.insert(
                    "native_lxmf_retry_guidance".into(),
                    if fallback_ready {
                        "direct LXMF transfer has no confirmed peer receipt; retry is prepared to use the selected propagation node"
                    } else {
                        "direct LXMF transfer has no confirmed peer receipt from the native wire path"
                    }
                    .into(),
                );
            }
            fields.insert(
                "native_lxmf_uncertain_reason".into(),
                if fallback_ready {
                    "native direct send did not receive confirmed peer delivery before timeout; explicit retry will use propagation when requested"
                } else {
                    "native direct send currently has transfer evidence but no confirmed peer-side receipt"
                }
                .into(),
            );
            if let Some(node) = evidence
                .detail
                .as_deref()
                .and_then(|detail| extract_lxmf_evidence_value(detail, "propagation_node"))
            {
                fields.insert(
                    "native_lxmf_propagation_fallback_available".into(),
                    "true".into(),
                );
                fields.insert("native_lxmf_propagation_node".into(), node.into());
            }
        }
    }
    fields
}

fn lxmf_retry_after_epoch_secs_for_evidence(evidence: &LxmfDeliveryEvidence) -> Option<f64> {
    let observed_at = evidence.observed_at?;
    match evidence.kind {
        LxmfDeliveryEvidenceKind::PropagationNodeFailed
        | LxmfDeliveryEvidenceKind::PropagationSyncNoPayloads => Some(observed_at + 30.0),
        _ => None,
    }
}

fn lxmf_delivery_evidence_kind_label(kind: LxmfDeliveryEvidenceKind) -> &'static str {
    match kind {
        LxmfDeliveryEvidenceKind::PacketSubmitted => "packet_submitted",
        LxmfDeliveryEvidenceKind::RnsPacketProof => "rns_packet_proof",
        LxmfDeliveryEvidenceKind::PropagationNodeAccepted => "propagation_node_accepted",
        LxmfDeliveryEvidenceKind::PropagationNodeFailed => "propagation_node_failed",
        LxmfDeliveryEvidenceKind::PropagationSyncNoPayloads => "propagation_sync_no_payloads",
        LxmfDeliveryEvidenceKind::LxmfRouterDelivered => "lxmf_router_delivered",
        LxmfDeliveryEvidenceKind::LxmfRouterFailed => "lxmf_router_failed",
        LxmfDeliveryEvidenceKind::InboundPeerMessage => "inbound_peer_message",
        LxmfDeliveryEvidenceKind::NoReceiptObserved => "no_receipt_observed",
    }
}

fn lxmf_delivery_evidence_is_failure(kind: LxmfDeliveryEvidenceKind) -> bool {
    matches!(
        kind,
        LxmfDeliveryEvidenceKind::PropagationNodeFailed
            | LxmfDeliveryEvidenceKind::LxmfRouterFailed
    )
}

