struct LatestLxmfOutboundState {
    state: String,
    evidence: Option<String>,
    delivery_evidence_kind: Option<String>,
    delivery_evidence_detail: Option<String>,
    receipt_state: Option<String>,
    proof_state: Option<String>,
    propagation_transfer_state: Option<String>,
    fallback: Option<String>,
    rtt: Option<String>,
    failure_reason: Option<String>,
    uncertain_reason: Option<String>,
    retry_guidance: Option<String>,
    delivered: bool,
    failed: bool,
}

fn latest_lxmf_outbound_state(conversation: &Conversation) -> Option<LatestLxmfOutboundState> {
    conversation
        .thread
        .messages
        .iter()
        .rev()
        .filter(|message| !message.incoming)
        .find_map(|message| {
            let state = message.fields.get("native_lxmf_state")?.clone();
            let evidence = message.fields.get("native_lxmf_evidence").cloned();
            let delivery_evidence_kind = message
                .fields
                .get("native_lxmf_delivery_evidence_kind")
                .cloned();
            let delivery_evidence_detail = message
                .fields
                .get("native_lxmf_delivery_evidence_detail")
                .cloned();
            let receipt_state = message.fields.get("native_lxmf_receipt_state").cloned();
            let proof_state = message.fields.get("native_lxmf_proof_state").cloned();
            let propagation_transfer_state = message
                .fields
                .get("native_lxmf_propagation_transfer_state")
                .cloned();
            let fallback = message.fields.get("native_lxmf_fallback").cloned();
            let rtt = message.fields.get("native_lxmf_rtt").cloned();
            let failure_reason = message.fields.get("native_lxmf_failure_reason").cloned();
            let uncertain_reason = message.fields.get("native_lxmf_uncertain_reason").cloned();
            let retry_guidance = message.fields.get("native_lxmf_retry_guidance").cloned();
            Some(LatestLxmfOutboundState {
                state,
                evidence,
                delivery_evidence_kind,
                delivery_evidence_detail,
                receipt_state,
                proof_state,
                propagation_transfer_state,
                fallback,
                rtt,
                failure_reason,
                uncertain_reason,
                retry_guidance,
                delivered: message.delivered,
                failed: message.failed,
            })
        })
}

fn lxmf_peer_candidate_order(left: &DirectoryEntry, right: &DirectoryEntry) -> std::cmp::Ordering {
    left.trusted
        .cmp(&right.trusted)
        .then_with(|| left.saved.cmp(&right.saved))
        .then_with(|| left.last_seen.total_cmp(&right.last_seen))
        .then_with(|| right.display_name.cmp(&left.display_name))
        .then_with(|| right.destination_hash.cmp(&left.destination_hash))
}

fn lxmf_peer_candidate_view_order(
    left: &LxmfPeerCandidate,
    right: &LxmfPeerCandidate,
) -> std::cmp::Ordering {
    right
        .active_conversation
        .cmp(&left.active_conversation)
        .then_with(|| right.selected.cmp(&left.selected))
        .then_with(|| right.trusted.cmp(&left.trusted))
        .then_with(|| right.saved.cmp(&left.saved))
        .then_with(|| right.last_seen.total_cmp(&left.last_seen))
        .then_with(|| left.display_name.cmp(&right.display_name))
        .then_with(|| left.destination_hash.cmp(&right.destination_hash))
}

fn verdict(ok: bool, detail: &str, next_action: &str) -> serde_json::Value {
    if ok {
        passed(detail)
    } else {
        failed(detail, next_action)
    }
}

fn passed(detail: &str) -> serde_json::Value {
    serde_json::json!({
        "status": "pass",
        "detail": detail,
    })
}

fn failed(detail: &str, next_action: &str) -> serde_json::Value {
    serde_json::json!({
        "status": "fail",
        "detail": detail,
        "next_action": next_action,
    })
}

fn skipped(detail: &str, next_action: &str) -> serde_json::Value {
    serde_json::json!({
        "status": "skip",
        "detail": detail,
        "next_action": next_action,
    })
}

#[derive(Clone, Debug)]
enum BrowserTaskKind {
    Open {
        target: String,
    },
    OpenLink {
        link: crate::micron::LinkAction,
        request_data: Option<BTreeMap<String, String>>,
    },
    Reload,
    Back,
    Forward,
    Download {
        target: String,
    },
    Partial {
        slot: String,
        target: String,
        fields: Vec<String>,
    },
}

fn browser_task_timeout(kind: &BrowserTaskKind) -> std::time::Duration {
    match kind {
        BrowserTaskKind::Partial { .. } => std::time::Duration::from_secs(20),
        BrowserTaskKind::Download { .. } => std::time::Duration::from_secs(60),
        BrowserTaskKind::Open { .. }
        | BrowserTaskKind::OpenLink { .. }
        | BrowserTaskKind::Reload
        | BrowserTaskKind::Back
        | BrowserTaskKind::Forward => std::time::Duration::from_secs(45),
    }
}

fn browser_task_label(kind: &BrowserTaskKind) -> &'static str {
    match kind {
        BrowserTaskKind::Open { .. } => "page request",
        BrowserTaskKind::OpenLink { .. } => "link request",
        BrowserTaskKind::Reload => "reload request",
        BrowserTaskKind::Back => "back request",
        BrowserTaskKind::Forward => "forward request",
        BrowserTaskKind::Download { .. } => "download request",
        BrowserTaskKind::Partial { .. } => "partial refresh",
    }
}

