    pub fn forget_current_page_form_state(&mut self) -> bool {
        self.settings_state.selected = settings_action_index(SettingsAction::ForgetPage);
        let Some(page_url) = self
            .active_browser_tab()
            .session
            .current_url()
            .map(str::to_string)
        else {
            self.status.task = "no active browser page form state to forget".into();
            return false;
        };
        match self.browser_form_state.remove_page(&page_url) {
            Ok(true) => {
                self.status.task = format!("forgot browser form state for {page_url}");
                true
            }
            Ok(false) => {
                self.status.task = format!("no saved browser form state for {page_url}");
                false
            }
            Err(error) => {
                self.logs
                    .lines
                    .push(format!("failed to forget browser form state: {error}"));
                self.status.task = format!("browser form forget failed: {error}");
                false
            }
        }
    }

    pub fn forget_current_node_form_state(&mut self) -> bool {
        self.settings_state.selected = settings_action_index(SettingsAction::ForgetNode);
        let Some(destination) = self.active_browser_tab().session.current_destination() else {
            self.status.task = "no active browser destination form state to forget".into();
            return false;
        };
        match self.browser_form_state.remove_pages_matching(|url| {
            BrowserAddress::parse(url).is_some_and(|address| address.destination == destination)
        }) {
            Ok(removed) if removed > 0 => {
                self.status.task =
                    format!("forgot {removed} browser form page(s) for {destination}");
                true
            }
            Ok(_) => {
                self.status.task = format!("no saved browser form state for {destination}");
                false
            }
            Err(error) => {
                self.logs
                    .lines
                    .push(format!("failed to forget node browser form state: {error}"));
                self.status.task = format!("browser form node forget failed: {error}");
                false
            }
        }
    }

    pub fn forget_all_browser_form_state(&mut self) -> bool {
        self.settings_state.selected = settings_action_index(SettingsAction::ForgetAll);
        match self.browser_form_state.clear() {
            Ok(removed) if removed > 0 => {
                self.status.task = format!("forgot {removed} browser form page(s)");
                true
            }
            Ok(_) => {
                self.status.task = "no saved browser form state to forget".into();
                false
            }
            Err(error) => {
                self.logs
                    .lines
                    .push(format!("failed to forget all browser form state: {error}"));
                self.status.task = format!("browser form forget-all failed: {error}");
                false
            }
        }
    }

    fn restore_browser_form_state(&mut self, index: usize) {
        if !self.settings.browser_form_state.enabled {
            return;
        }
        let Some(page_url) = self.workspace.browser_tabs[index]
            .session
            .current_url()
            .map(str::to_string)
        else {
            return;
        };
        let Some(fields) = self.browser_form_state.fields_for(&page_url).cloned() else {
            return;
        };
        let fields = self.filter_browser_form_fields_for_policy(index, &fields);
        self.workspace.browser_tabs[index]
            .session
            .apply_field_values(&fields);
    }

    fn persist_browser_form_state(&mut self, index: usize) {
        if !self.settings.browser_form_state.enabled {
            return;
        }
        let Some(page_url) = self.workspace.browser_tabs[index]
            .session
            .current_url()
            .map(str::to_string)
        else {
            return;
        };
        let fields = self.browser_form_fields_for_persistence(index);
        if let Err(error) = self.browser_form_state.set_fields(page_url, fields) {
            self.logs
                .lines
                .push(format!("failed to persist browser form state: {error}"));
            self.status.task = format!("browser form state save failed: {error}");
        }
    }

    fn browser_link_request_data(
        &self,
        index: usize,
        fields: &[String],
    ) -> BTreeMap<String, String> {
        let session = &self.workspace.browser_tabs[index].session;
        let mut request_data = session.build_request_data(fields);
        if !self.settings.browser_form_state.enabled {
            return request_data;
        }

        let Some(page_url) = session.current_url() else {
            return request_data;
        };
        let Some(saved_fields) = self.browser_form_state.fields_for(page_url) else {
            return request_data;
        };
        let saved_fields = self.filter_browser_form_fields_for_policy(index, saved_fields);
        let include_all = fields.iter().any(|field| field == "*");
        if include_all {
            for (name, value) in &saved_fields {
                let key = format!("field_{name}");
                if request_data
                    .get(&key)
                    .is_none_or(|current| current.is_empty())
                    && !value.is_empty()
                {
                    request_data.insert(key, value.clone());
                }
            }
        }
        for field in fields
            .iter()
            .filter(|field| field.as_str() != "*" && !field.contains('='))
        {
            let key = format!("field_{field}");
            if request_data
                .get(&key)
                .is_none_or(|current| current.is_empty())
            {
                if let Some(value) = saved_fields.get(field).filter(|value| !value.is_empty()) {
                    request_data.insert(key, value.clone());
                }
            }
        }
        request_data
    }

    fn browser_form_fields_for_persistence(&self, index: usize) -> BTreeMap<String, String> {
        self.filter_browser_form_fields_for_policy(
            index,
            &self.workspace.browser_tabs[index].session.field_values,
        )
    }

    fn filter_browser_form_fields_for_policy(
        &self,
        index: usize,
        values: &BTreeMap<String, String>,
    ) -> BTreeMap<String, String> {
        let sensitive_allowed = self.sensitive_form_persistence_allowed(index);
        self.workspace.browser_tabs[index]
            .session
            .interactive_controls()
            .into_iter()
            .filter_map(|control| {
                let value = values.get(&control.name)?;
                if control.masked && !sensitive_allowed {
                    return None;
                }
                Some((control.name, value.clone()))
            })
            .collect()
    }

    fn sensitive_form_persistence_allowed(&self, index: usize) -> bool {
        match self.settings.browser_form_state.sensitive_fields {
            SensitiveFormPersistence::Never => false,
            SensitiveFormPersistence::TrustedNodes => self
                .workspace
                .browser_tabs
                .get(index)
                .and_then(|tab| tab.session.current_url())
                .and_then(BrowserAddress::parse)
                .is_some_and(|address| {
                    self.directory_service
                        .trust_level(&address.destination, None)
                        == TrustLevel::Trusted
                }),
        }
    }

    fn sync_workspace_display_preferences_to_settings(&mut self) {
        self.settings.ui.show_help = self.workspace.show_help;
        self.settings.ui.browser_overlay_mode = self.workspace.browser_overlay_mode.into();
        self.settings.ui.active_workspace_section = self.workspace.active_section.into();
        self.settings.ui.active_browser_index = self.workspace.active_browser;
        self.settings.ui.active_conversation_index = self.workspace.active_conversation;
        self.settings.ui.sidebar_index = self.workspace.sidebar_index;
        self.settings.browser_tabs =
            self.workspace
                .browser_tabs
                .iter()
                .map(|tab| BrowserTabSettings {
                    title: tab.title.clone(),
                    address_input: tab.address_input.clone(),
                    current_url: tab
                        .session
                        .current_url()
                        .map(str::to_string)
                        .unwrap_or_else(|| tab.address_input.clone()),
                    history: tab.session.history.clone(),
                    history_index: tab.session.history_index,
                    scroll_offset: tab.scroll.offset,
                    micron_zoom_percent: tab.micron_zoom_percent,
                    focused_control: tab.focused_control.as_ref().map(|control| {
                        BrowserFocusedControlSettings {
                            name: control.name.clone(),
                            index: control.index,
                        }
                    }),
                    focused_link: tab.focused_link.as_ref().map(|link| {
                        BrowserFocusedLinkSettings {
                            target: link.target.clone(),
                            fields: link.fields.clone(),
                            region_index: link.region_index,
                        }
                    }),
                })
                .collect();
        self.settings.conversation_tabs = self
            .workspace
            .conversations
            .iter()
            .filter(|conversation| !Self::conversation_is_empty_placeholder(conversation))
            .map(|conversation| ConversationTabSettings {
                peer_hash: conversation.peer_hash.clone(),
                peer_label: conversation.peer_label.clone(),
                draft_title: conversation.draft_title.clone(),
                draft_body: conversation.draft_body.clone(),
                attachments: conversation.attachments.clone(),
                delivery_mode: conversation.delivery_mode.clone(),
                include_ticket: conversation.include_ticket,
            })
            .collect();
    }

    pub fn cycle_focus(&mut self) {
        self.workspace.focus = self.workspace.focus.next();
    }

    pub fn select_previous_sidebar_item(&mut self) {
        match self.workspace.active_section {
            WorkspaceSection::Directory => self.select_previous_directory_entry(),
            WorkspaceSection::Interfaces => self.select_previous_interface_profile(),
            WorkspaceSection::Plugins => self.select_previous_plugin(),
            WorkspaceSection::Settings => self.select_previous_settings_action(),
            _ => {
                self.workspace.sidebar_index = self.workspace.sidebar_index.saturating_sub(1);
                self.persist_ui_preferences("sidebar selection");
            }
        }
    }

    pub fn select_next_sidebar_item(&mut self) {
        match self.workspace.active_section {
            WorkspaceSection::Directory => self.select_next_directory_entry(),
            WorkspaceSection::Interfaces => self.select_next_interface_profile(),
            WorkspaceSection::Plugins => self.select_next_plugin(),
            WorkspaceSection::Settings => self.select_next_settings_action(),
            _ => {
                let max_index = self.sidebar_len().saturating_sub(1);
                self.workspace.sidebar_index = (self.workspace.sidebar_index + 1).min(max_index);
                self.persist_ui_preferences("sidebar selection");
            }
        }
    }

    pub fn activate_sidebar_selection(&mut self) {
        let index = self.workspace.sidebar_index;
        if index < WorkspaceSection::ALL.len() {
            self.switch_section(WorkspaceSection::ALL[index]);
            return;
        }
        let browser_start = WorkspaceSection::ALL.len() + 1;
        if index >= browser_start && index < browser_start + self.workspace.browser_tabs.len() {
            self.workspace.active_browser = index - browser_start;
            self.switch_section(WorkspaceSection::Browser);
            return;
        }
        let conversation_start = browser_start + self.workspace.browser_tabs.len();
        if index >= conversation_start
            && index < conversation_start + self.workspace.conversations.len()
        {
            self.workspace.active_conversation = index - conversation_start;
            self.switch_section(WorkspaceSection::Messages);
        }
    }

    pub fn switch_section(&mut self, section: WorkspaceSection) {
        self.workspace.active_section = section;
        if section == WorkspaceSection::Directory {
            self.refresh_panels_from_services();
        }
        if section == WorkspaceSection::Directory
            && self.directory_state.selected.is_none()
            && !self.directory_state.entries.is_empty()
        {
            self.restore_remembered_directory_selection();
            if self.directory_state.selected.is_none() {
                if let Some((index, kind)) = self
                    .directory_state
                    .entries
                    .iter()
                    .enumerate()
                    .find(|(_, entry)| {
                        directory_entry_matches_panel_view(
                            entry,
                            &entry.kind,
                            &self.directory_state.active_scope,
                            &self.directory_state.filter,
                        )
                    })
                    .map(|(index, entry)| (index, entry.kind.clone()))
                {
                    self.directory_state.active_kind = kind;
                    self.directory_state.selected = Some(index);
                    self.remember_selected_directory_entry();
                }
            }
        }
        if section == WorkspaceSection::Plugins
            && self.plugins_state.selected.is_none()
            && !self.plugins_state.manifests.is_empty()
        {
            self.plugins_state.selected = Some(0);
        }
        if section == WorkspaceSection::Interfaces
            && self.interfaces_state.selected.is_none()
            && !self.interfaces_state.profiles.is_empty()
        {
            self.interfaces_state.selected = Some(0);
        }
        if section == WorkspaceSection::Messages {
            let active = self.workspace.active_conversation;
            self.mark_conversation_read_by_index(active);
        }
        self.status.task = format!("section: {}", section.label());
        self.refresh_context_status();
        self.persist_ui_preferences("workspace section");
    }

    pub fn select_previous_directory_entry(&mut self) {
        let visible = self.visible_directory_entry_indices();
        if visible.is_empty() {
            self.directory_state.selected = None;
            return;
        }
        let current = self
            .directory_state
            .selected
            .and_then(|selected| visible.iter().position(|index| *index == selected))
            .unwrap_or(0);
        self.directory_state.selected = Some(visible[current.saturating_sub(1)]);
        self.remember_selected_directory_entry();
    }

    pub fn select_next_directory_entry(&mut self) {
        let visible = self.visible_directory_entry_indices();
        if visible.is_empty() {
            self.directory_state.selected = None;
            return;
        }
        let current = self
            .directory_state
            .selected
            .and_then(|selected| visible.iter().position(|index| *index == selected))
            .unwrap_or(0);
        self.directory_state.selected = Some(visible[(current + 1).min(visible.len() - 1)]);
        self.remember_selected_directory_entry();
    }

    pub fn switch_directory_kind(&mut self, kind: DirectoryKind) {
        self.remember_selected_directory_entry();
        self.directory_state.active_kind = kind;
        self.restore_remembered_directory_selection();
        self.switch_section(WorkspaceSection::Directory);
    }

    pub fn switch_directory_scope(&mut self, scope: DirectoryScope) {
        self.remember_selected_directory_entry();
        self.directory_state.active_scope = scope;
        self.restore_remembered_directory_selection();
        self.switch_section(WorkspaceSection::Directory);
    }

    pub fn set_directory_filter(&mut self, value: String) {
        self.directory_state.filter = value;
        self.restore_remembered_directory_selection();
    }

    fn remember_selected_directory_entry(&mut self) {
        let Some(index) = self.directory_state.selected else {
            return;
        };
        let Some(entry) = self.directory_state.entries.get(index) else {
            return;
        };
        self.directory_state
            .remembered_selection_by_kind
            .insert(entry.kind.clone(), entry.destination_hash.clone());
    }

    fn restore_remembered_directory_selection(&mut self) {
        let kind = self.directory_state.active_kind.clone();
        let selected_hash = self
            .directory_state
            .remembered_selection_by_kind
            .get(&kind)
            .cloned();
        self.directory_state.selected = selected_hash
            .as_deref()
            .and_then(|hash| {
                self.directory_state.entries.iter().position(|entry| {
                    entry.destination_hash == hash
                        && directory_entry_matches_panel_view(
                            entry,
                            &kind,
                            &self.directory_state.active_scope,
                            &self.directory_state.filter,
                        )
                })
            })
            .or_else(|| {
                self.directory_state.entries.iter().position(|entry| {
                    directory_entry_matches_panel_view(
                        entry,
                        &kind,
                        &self.directory_state.active_scope,
                        &self.directory_state.filter,
                    )
                })
            });
    }

    fn visible_directory_entry_indices(&self) -> Vec<usize> {
        self.directory_state
            .entries
            .iter()
            .enumerate()
            .filter_map(|(index, entry)| {
                directory_entry_matches_panel_view(
                    entry,
                    &self.directory_state.active_kind,
                    &self.directory_state.active_scope,
                    &self.directory_state.filter,
                )
                .then_some(index)
            })
            .collect()
    }

    pub fn select_previous_interface_profile(&mut self) {
        let len = self.interfaces_state.profiles.len();
        if len == 0 {
            self.interfaces_state.selected = None;
            return;
        }
        self.interfaces_state.selected = Some(
            self.interfaces_state
                .selected
                .unwrap_or(0)
                .saturating_sub(1),
        );
        self.status.task = "interface selection moved".into();
    }

    pub fn select_next_interface_profile(&mut self) {
        let len = self.interfaces_state.profiles.len();
        if len == 0 {
            self.interfaces_state.selected = None;
            return;
        }
        self.interfaces_state.selected = Some(
            self.interfaces_state
                .selected
                .map(|index| (index + 1).min(len - 1))
                .unwrap_or(0),
        );
        self.status.task = "interface selection moved".into();
    }

    pub fn select_interface_profile(&mut self, index: usize) -> bool {
        let Some(profile) = self.interfaces_state.profiles.get(index) else {
            self.status.task = "interface click was outside profiles".into();
            return false;
        };
        self.workspace.active_section = WorkspaceSection::Interfaces;
        self.interfaces_state.selected = Some(index);
        self.status.task = format!("selected interface: {}", profile.name);
        true
    }

    pub fn toggle_selected_interface_enabled(&mut self) -> bool {
        let Some(index) = self.interfaces_state.selected else {
            self.status.task = "no interface selected".into();
            return false;
        };
        let Some(profile) = self.interfaces_state.profiles.get(index) else {
            self.interfaces_state.selected = None;
            self.status.task = "selected interface is unavailable".into();
            return false;
        };
        let profile_id = profile.profile_id.clone();

        match self.interface_service.toggle_enabled(&profile_id) {
            Ok(Some(updated)) => match self.interface_service.apply() {
                Ok(_) => {
                    self.refresh_interface_state_preserving_selection(&profile_id);
                    self.status.task = format!(
                        "interface '{}' {} | {INTERFACE_RESTART_RECOMMENDED}",
                        updated.name,
                        if updated.enabled {
                            "enabled"
                        } else {
                            "disabled"
                        }
                    );
                    self.refresh_diagnostics_summary();
                    true
                }
                Err(error) => {
                    self.status.task = format!("failed to apply interface config: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Interface,
                        format!("failed to apply interface config after enabled toggle: {error}"),
                    );
                    false
                }
            },
            Ok(None) => {
                self.status.task = "selected interface no longer exists".into();
                false
            }
            Err(error) => {
                self.status.task = format!("failed to toggle interface: {error}");
                self.logs
                    .lines
                    .push(format!("failed to toggle interface enabled state: {error}"));
                false
            }
        }
    }

    fn refresh_interface_state_preserving_selection(&mut self, profile_id: &str) {
        let previous = self.interfaces_state.selected.unwrap_or(0);
        self.interfaces_state.profiles = self.interface_service.list_profiles().to_vec();
        if self.interfaces_state.profiles.is_empty() {
            self.interfaces_state.selected = None;
            return;
        }
        let new_index = self
            .interfaces_state
            .profiles
            .iter()
            .position(|profile| profile.profile_id == profile_id)
            .unwrap_or(previous.min(self.interfaces_state.profiles.len().saturating_sub(1)));
        self.interfaces_state.selected = Some(new_index);
    }

