    pub fn preview_managed_reticulum_config(&mut self) -> bool {
        let rendered = self.interface_service.render_config_for_apply();
        let line_count = rendered.lines().count();
        self.interfaces_state.config_preview = Some(rendered);
        self.workspace.active_section = WorkspaceSection::Interfaces;
        self.status.task = format!("previewed managed Reticulum config ({line_count} lines)");
        true
    }

    pub fn export_managed_reticulum_config(&mut self) -> bool {
        let rendered = self.interface_service.render_config_for_apply();
        let line_count = rendered.lines().count();
        if let Err(error) = std::fs::create_dir_all(&self.paths.diagnostics_dir) {
            self.status.task = format!("failed to prepare diagnostics export dir: {error}");
            self.logs.push_with_source(
                LogSeverity::Error,
                LogSource::Interface,
                format!(
                    "failed to prepare managed Reticulum config export dir {}: {error}",
                    self.paths.diagnostics_dir.display()
                ),
            );
            return false;
        }

        let epoch = current_epoch_ms();
        for suffix in 0..1000_u16 {
            let filename = if suffix == 0 {
                format!("managed-reticulum-config-{epoch}.conf")
            } else {
                format!("managed-reticulum-config-{epoch}-{suffix}.conf")
            };
            let path = self.paths.diagnostics_dir.join(filename);
            if path.exists() {
                continue;
            }
            match std::fs::write(&path, rendered.as_bytes()) {
                Ok(()) => {
                    self.interfaces_state.config_preview = Some(rendered);
                    self.interfaces_state.last_config_export_path = Some(path.clone());
                    self.workspace.active_section = WorkspaceSection::Interfaces;
                    self.status.task = format!(
                        "exported managed Reticulum config ({line_count} lines): {}",
                        path.display()
                    );
                    self.logs.push_with_source(
                        LogSeverity::Info,
                        LogSource::Interface,
                        format!("exported managed Reticulum config: {}", path.display()),
                    );
                    return true;
                }
                Err(error) => {
                    self.status.task =
                        format!("failed to export managed Reticulum config: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Interface,
                        format!(
                            "failed to export managed Reticulum config to {}: {error}",
                            path.display()
                        ),
                    );
                    return false;
                }
            }
        }

        self.status.task = "failed to export managed Reticulum config: no unique filename".into();
        self.logs.push_with_source(
            LogSeverity::Error,
            LogSource::Interface,
            format!(
                "failed to export managed Reticulum config under {}: no unique filename",
                self.paths.diagnostics_dir.display()
            ),
        );
        false
    }

    pub fn export_diagnostics_bundle(&mut self) -> bool {
        if self.diagnostics_export_pending.is_some() {
            self.status.task = "diagnostics bundle export already pending".into();
            return false;
        }

        let generation = self.next_diagnostics_generation;
        self.next_diagnostics_generation = self.next_diagnostics_generation.saturating_add(1);
        self.diagnostics_export_pending = Some(generation);
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.status.task = "collecting diagnostics snapshot".into();

        let service = DiagnosticsService::new(self.paths.clone(), self.runtime.clone());
        let message_store = self.message_store.clone();
        let directory_service = self.directory_service.clone();
        let cache = self.cache.clone();
        let interfaces = self.interface_service.list_profiles().to_vec();
        let plugins = self.plugins_state.manifests.clone();
        let browser_tabs = self.workspace.browser_tabs.len();
        let conversation_tabs = self.workspace.conversations.len();
        let event_tx = self.event_tx.clone();

        tokio::spawn(async move {
            let snapshot = service
                .snapshot(
                    Some(&message_store),
                    Some(&directory_service),
                    Some(cache.as_ref()),
                    &interfaces,
                    &plugins,
                    browser_tabs,
                    conversation_tabs,
                )
                .await
                .map(Box::new)
                .map_err(|error| error.to_string());
            let _ = event_tx
                .send(InternalAppEvent::DiagnosticsTask(
                    DiagnosticsTaskResult::ExportBundle {
                        generation,
                        snapshot,
                    },
                ))
                .await;
        });

        true
    }

    pub fn preview_diagnostics_bundle(&mut self) -> bool {
        let bundle = self.redacted_diagnostics_bundle();
        let content = match serde_json::to_string_pretty(&bundle) {
            Ok(content) => content,
            Err(error) => {
                self.status.task = format!("failed to render diagnostics preview: {error}");
                self.logs.push_with_source(
                    LogSeverity::Error,
                    LogSource::Diagnostics,
                    format!("failed to render diagnostics preview: {error}"),
                );
                return false;
            }
        };
        let lines = content.lines().map(ToOwned::to_owned).collect::<Vec<_>>();
        let line_count = lines.len();
        self.diagnostics_state.preview_lines = lines;
        self.diagnostics_state.preview_scroll = 0;
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.status.task = format!("previewed diagnostics bundle ({line_count} lines)");
        true
    }

    pub fn export_active_browser_render_fixture(&mut self) -> bool {
        let tab = self.active_browser_tab();
        let Some(page) = tab.session.current_page().or(tab.current_page.as_ref()) else {
            self.status.task = "failed to capture browser render: no page loaded".into();
            self.logs.push_with_source(
                LogSeverity::Warn,
                LogSource::Diagnostics,
                "failed to capture browser render: no page loaded",
            );
            return false;
        };
        let Some(document) = tab.session.current_document.as_ref() else {
            self.status.task = "failed to capture browser render: no parsed document".into();
            self.logs.push_with_source(
                LogSeverity::Warn,
                LogSource::Diagnostics,
                "failed to capture browser render: no parsed document",
            );
            return false;
        };

        if let Err(error) = std::fs::create_dir_all(&self.paths.diagnostics_dir) {
            self.status.task = format!("failed to prepare render capture dir: {error}");
            self.logs.push_with_source(
                LogSeverity::Error,
                LogSource::Diagnostics,
                format!(
                    "failed to prepare render capture dir {}: {error}",
                    self.paths.diagnostics_dir.display()
                ),
            );
            return false;
        }

        let epoch = current_epoch_ms();
        let slug = browser_capture_slug(&page.title, &page.url);
        for suffix in 0..1000_u16 {
            let dirname = if suffix == 0 {
                format!("browser-render-{epoch}-{slug}")
            } else {
                format!("browser-render-{epoch}-{slug}-{suffix}")
            };
            let dir = self.paths.diagnostics_dir.join(dirname);
            if dir.exists() {
                continue;
            }

            let markup_path = dir.join("page.mu");
            let summary_path = dir.join("render-summary.json");
            let result = (|| -> std::io::Result<serde_json::Value> {
                std::fs::create_dir_all(&dir)?;
                std::fs::write(&markup_path, page.markup.as_bytes())?;
                let summary = browser_render_capture_summary(page, document, 80);
                let summary_json =
                    serde_json::to_string_pretty(&summary).map_err(std::io::Error::other)?;
                std::fs::write(&summary_path, summary_json.as_bytes())?;
                Ok(summary)
            })();

            match result {
                Ok(summary) => {
                    let preview = serde_json::to_string_pretty(&summary).unwrap_or_else(|_| {
                        format!(
                            "{{\"report\":\"browser_render_capture\",\"path\":\"{}\"}}",
                            summary_path.display()
                        )
                    });
                    self.diagnostics_state.preview_lines =
                        preview.lines().map(ToOwned::to_owned).collect();
                    self.diagnostics_state.preview_scroll = 0;
                    self.diagnostics_state.last_export_path = Some(summary_path.clone());
                    self.diagnostics_state.last_export_summary = Some(format!(
                        "browser render capture: {}",
                        summary_path.display()
                    ));
                    self.workspace.active_section = WorkspaceSection::Diagnostics;
                    self.status.task = format!(
                        "captured browser render fixture: {}",
                        summary_path.display()
                    );
                    self.logs.push_with_source(
                        LogSeverity::Info,
                        LogSource::Diagnostics,
                        format!(
                            "captured browser render fixture markup={} summary={}",
                            markup_path.display(),
                            summary_path.display()
                        ),
                    );
                    return true;
                }
                Err(error) => {
                    self.status.task = format!("failed to capture browser render: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Diagnostics,
                        format!(
                            "failed to capture browser render fixture under {}: {error}",
                            dir.display()
                        ),
                    );
                    return false;
                }
            }
        }

        self.status.task = "failed to capture browser render: no unique filename".into();
        self.logs.push_with_source(
            LogSeverity::Error,
            LogSource::Diagnostics,
            format!(
                "failed to capture browser render under {}: no unique filename",
                self.paths.diagnostics_dir.display()
            ),
        );
        false
    }

