    pub fn run_native_network_smoke_test(&mut self, execute_live_probe: bool) -> bool {
        self.run_native_network_smoke_test_with_fetch_options(execute_live_probe, false, None)
    }

    pub fn run_native_network_live_fetch_validation(&mut self) -> bool {
        if !self.runtime_status.connected {
            self.pending_post_startup_action =
                Some(PendingPostStartupAction::NativeLiveFetchValidation);
            if self.runtime_startup_pending {
                self.status.task =
                    "native runtime startup pending; live fetch validation will run after startup"
                        .into();
                return true;
            }
            if self.start_configured_runtime_nonblocking() {
                self.status.task =
                    "starting native runtime; live fetch validation will run after startup".into();
                return true;
            }
            self.pending_post_startup_action = None;
            return false;
        }
        self.run_native_network_smoke_test_with_fetch_options(
            true,
            true,
            Some(SmokePathWarmup { wait_secs: 10 }),
        )
    }

    fn run_native_network_smoke_test_with_fetch_options(
        &mut self,
        execute_live_probe: bool,
        execute_live_fetch: bool,
        warmup: Option<SmokePathWarmup>,
    ) -> bool {
        let generation = self.next_diagnostics_generation;
        self.next_diagnostics_generation = self.next_diagnostics_generation.saturating_add(1);
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.note_outbound_diagnostic(estimated_browser_request_bytes(
            self.active_browser_tab().address_input.as_str(),
            0,
        ));
        self.status.task = if execute_live_fetch {
            "running native-network live fetch validation".into()
        } else if execute_live_probe {
            "running native-network smoke test with live probe".into()
        } else {
            "running native-network smoke test dry-run".into()
        };
        self.logs.push_with_source(
            LogSeverity::Info,
            LogSource::Diagnostics,
            format!(
                "native-network smoke test queued live_probe={execute_live_probe} live_fetch={execute_live_fetch} active_url={}",
                self.active_browser_tab().address_input
            ),
        );

        let runtime = self.runtime.clone();
        let event_tx = self.event_tx.clone();
        let report_input = self.live_interop_report_input();
        tokio::spawn(async move {
            let report = collect_native_network_smoke_test_report(
                runtime,
                report_input,
                execute_live_probe,
                execute_live_fetch,
                warmup,
                None,
            )
            .await
            .map_err(|error| error.to_string());
            let _ = event_tx
                .send(InternalAppEvent::DiagnosticsTask(
                    DiagnosticsTaskResult::NativeNetworkSmokeTest {
                        generation,
                        execute_live_probe,
                        execute_live_fetch,
                        report,
                    },
                ))
                .await;
        });

        true
    }

    pub fn run_native_preflight_report(&mut self) -> bool {
        let generation = self.next_diagnostics_generation;
        self.next_diagnostics_generation = self.next_diagnostics_generation.saturating_add(1);
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.note_outbound_diagnostic(96);
        self.status.task = "running native preflight report".into();

        let report = self.native_preflight_report_for_active_context();
        let event_tx = self.event_tx.clone();
        tokio::spawn(async move {
            let _ = event_tx
                .send(InternalAppEvent::DiagnosticsTask(
                    DiagnosticsTaskResult::NativePreflight {
                        generation,
                        report: Ok(report),
                    },
                ))
                .await;
        });
        true
    }

    pub fn native_preflight_report_for_active_context(&self) -> serde_json::Value {
        let destination = self.active_browser_tab().address_input.trim();
        let lxmf_peer = self.active_conversation().peer_hash.trim();
        let lxmf_peer = (!lxmf_peer.is_empty()).then_some(lxmf_peer);
        native_preflight_report_for_app(self, destination, lxmf_peer)
    }

    pub fn run_native_lxmf_smoke_send(&mut self) -> bool {
        let Some(peer_hash) = self.active_lxmf_peer_hash_for_interop() else {
            self.status.task =
                "no valid LXMF peer selected; open/select a Directory peer before smoke send"
                    .into();
            self.logs.push_with_source(
                LogSeverity::Warn,
                LogSource::Diagnostics,
                "LXMF smoke send blocked because no valid active or directory peer is available",
            );
            return false;
        };
        self.run_native_lxmf_smoke_send_for_peer(peer_hash)
    }

    pub fn run_native_lxmf_smoke_send_for_peer(&mut self, peer_hash: String) -> bool {
        if peer_hash.trim().is_empty() {
            self.status.task = "cannot run LXMF smoke send without a peer hash".into();
            return false;
        }
        let generation = self.next_diagnostics_generation;
        self.next_diagnostics_generation = self.next_diagnostics_generation.saturating_add(1);
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.note_outbound_diagnostic(estimated_lxmf_draft_bytes("smoke", "test"));
        self.status.task = format!("running explicit LXMF smoke send to {peer_hash}");
        self.logs.push_with_source(
            LogSeverity::Warn,
            LogSource::Diagnostics,
            format!("explicit peer-visible LXMF smoke send queued peer={peer_hash}"),
        );

        let runtime = self.runtime.clone();
        let event_tx = self.event_tx.clone();
        let task_peer = peer_hash.clone();
        tokio::spawn(async move {
            let report = collect_native_lxmf_smoke_send_report(
                runtime,
                task_peer.clone(),
                DeliveryMode::Direct,
                None,
                false,
            )
            .await
            .map_err(|error| error.to_string());
            let _ = event_tx
                .send(InternalAppEvent::DiagnosticsTask(
                    DiagnosticsTaskResult::NativeLxmfSmokeSend {
                        generation,
                        peer_hash: task_peer,
                        report,
                    },
                ))
                .await;
        });

        true
    }

    pub fn run_native_lxmf_live_interop(&mut self) -> bool {
        if !self.runtime_status.connected {
            self.pending_post_startup_action =
                Some(PendingPostStartupAction::NativeLxmfLiveInterop);
            if self.runtime_startup_pending {
                self.status.task =
                    "native runtime startup pending; LXMF interop will run after startup".into();
                return true;
            }
            if self.start_configured_runtime_nonblocking() {
                self.status.task =
                    "starting native runtime; LXMF interop will run after startup".into();
                return true;
            }
            self.pending_post_startup_action = None;
            return false;
        }
        let peer_hash = self.active_lxmf_peer_hash_for_interop();
        let wait_secs = 10;
        let generation = self.next_diagnostics_generation;
        self.next_diagnostics_generation = self.next_diagnostics_generation.saturating_add(1);
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.note_outbound_diagnostic(estimated_lxmf_draft_bytes("interop", "test"));
        self.status.task =
            "running native LXMF live interop: announce local delivery and wait".into();
        self.logs.push_with_source(
            LogSeverity::Info,
            LogSource::Diagnostics,
            format!(
                "native LXMF live interop queued generation {generation} wait={wait_secs}s send_peer={}",
                peer_hash.as_deref().unwrap_or("none")
            ),
        );

        let runtime = self.runtime.clone();
        let event_tx = self.event_tx.clone();
        let task_peer = peer_hash.clone();
        tokio::spawn(async move {
            let report = collect_native_lxmf_live_interop_report(
                runtime,
                task_peer.clone(),
                wait_secs,
                DeliveryMode::Direct,
                None,
                false,
            )
            .await
            .map_err(|error| error.to_string());
            let _ = event_tx
                .send(InternalAppEvent::DiagnosticsTask(
                    DiagnosticsTaskResult::NativeLxmfLiveInterop {
                        generation,
                        peer_hash: task_peer,
                        wait_secs,
                        report,
                    },
                ))
                .await;
        });

        true
    }

