    pub fn select_lxmf_peer_for_interop(&mut self) -> bool {
        let Some(entry) = self.best_lxmf_directory_peer() else {
            self.status.task =
                "no valid LXMF peer found; wait for an lxmf.delivery announce or save a peer"
                    .into();
            self.workspace.active_section = WorkspaceSection::Directory;
            return false;
        };
        let label = entry.display_name.clone();
        let hash = entry.destination_hash.clone();
        self.open_directory_peer_conversation(&hash);
        self.status.task = format!("selected LXMF peer for interop: {label} ({hash})");
        true
    }

    pub fn select_lxmf_peer_candidate(&mut self, candidate_index: usize) -> bool {
        let Some(candidate) = self.lxmf_peer_candidates().into_iter().nth(candidate_index) else {
            self.status.task = "LXMF peer candidate selection was outside the list".into();
            return false;
        };
        if let Some(directory_index) = candidate.directory_index {
            self.directory_state.selected = Some(directory_index);
        }
        self.open_directory_peer_conversation(&candidate.destination_hash);
        self.status.task = format!(
            "selected LXMF peer for interop: {} ({})",
            candidate.display_name, candidate.destination_hash
        );
        true
    }

    pub fn run_active_browser_path_discovery_diagnostics(&mut self) -> bool {
        let url = self.active_browser_tab().address_input.clone();
        self.set_diagnostics_target("browser", url.clone());
        let tab_id = self.active_browser_tab().id;
        let parsed = BrowserAddress::parse(&url);
        let destination = parsed.as_ref().map(|address| address.destination.clone());
        let path = parsed.as_ref().map(|address| address.path.clone());
        let generation = self.next_diagnostics_generation;
        self.next_diagnostics_generation = self.next_diagnostics_generation.saturating_add(1);
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.status.task = "requesting path discovery for active browser destination".into();
        self.monitoring_state.outbound_diagnostics =
            self.monitoring_state.outbound_diagnostics.saturating_add(1);
        self.monitoring_state
            .note_outbound(estimated_browser_request_bytes(&url, 0));

        let runtime = self.runtime.clone();
        let event_tx = self.event_tx.clone();
        tokio::spawn(async move {
            let path_warmup = run_smoke_path_warmup(
                runtime,
                &url,
                destination.as_deref(),
                Some(SmokePathWarmup { wait_secs: 5 }),
            )
            .await;
            let report = serde_json::json!({
                "report": "path_discovery_diagnostics",
                "active_browser_url": url,
                "destination_hash": destination,
                "path": path,
                "path_warmup": path_warmup,
            });
            let _ = event_tx
                .send(InternalAppEvent::DiagnosticsTask(
                    DiagnosticsTaskResult::PathDiscoveryDiagnostics {
                        tab_id,
                        generation,
                        report: Ok(report),
                    },
                ))
                .await;
        });

        true
    }

    pub fn set_diagnostics_target_for_browser_tab(&mut self, tab_id: TabId) -> bool {
        let Some(index) = self.browser_tab_index(tab_id) else {
            self.status.task = "browser tab no longer exists".into();
            return false;
        };
        let address = self.workspace.browser_tabs[index].address_input.clone();
        self.set_diagnostics_target("browser", address);
        true
    }

    pub fn set_diagnostics_target_for_conversation(&mut self, conversation_id: u64) -> bool {
        let Some(index) = self
            .workspace
            .conversations
            .iter()
            .position(|conversation| conversation.id == conversation_id)
        else {
            self.status.task = "conversation no longer exists".into();
            return false;
        };
        let peer = self.workspace.conversations[index].peer_hash.clone();
        let label = self.workspace.conversations[index].peer_label.clone();
        self.set_diagnostics_target("lxmf peer", peer.clone());
        self.status.task = format!("diagnostics target: {label} ({peer})");
        true
    }

    fn set_diagnostics_target(&mut self, kind: &str, address: String) {
        self.diagnostics_state.target_kind = Some(kind.into());
        self.diagnostics_state.target_address = Some(address.clone());
        self.settings.diagnostics_target_kind = Some(kind.into());
        self.settings.diagnostics_target_address = Some(address);
        let _ = self.save_settings_change("diagnostics target");
    }

    fn note_outbound_diagnostic(&mut self, estimated_bytes: u64) {
        self.monitoring_state.outbound_diagnostics =
            self.monitoring_state.outbound_diagnostics.saturating_add(1);
        self.monitoring_state.note_outbound(estimated_bytes);
    }

    pub fn begin_known_destinations_preload_flow(&mut self) -> bool {
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.note_outbound_diagnostic(64);
        self.workspace.focus = FocusArea::Command;
        self.persist_ui_preferences("workspace section");
        self.input.begin(
            InputTarget::DiagnosticsKnownDestinationsPath,
            self.default_known_destinations_path().display().to_string(),
        );
        self.status.task = "enter path to Reticulum storage/known_destinations file".into();
        true
    }

    fn default_known_destinations_path(&self) -> PathBuf {
        self.settings
            .reticulum_config_path
            .as_ref()
            .unwrap_or(&self.paths.reticulum_config_dir)
            .join("storage")
            .join("known_destinations")
    }

    fn submit_known_destinations_preload_path(&mut self, text: String) -> bool {
        let raw = text.trim();
        if raw.is_empty() {
            self.status.task = "known_destinations preload cancelled; path was empty".into();
            return false;
        }
        let preload_path = PathBuf::from(raw);
        if !preload_path.is_file() {
            self.status.task = format!(
                "known_destinations file must be an existing file: {}",
                preload_path.display()
            );
            return false;
        }

        let url = self.active_browser_tab().address_input.clone();
        let tab_id = self.active_browser_tab().id;
        let parsed = BrowserAddress::parse(&url);
        let destination = parsed.as_ref().map(|address| address.destination.clone());
        let generation = self.next_diagnostics_generation;
        self.next_diagnostics_generation = self.next_diagnostics_generation.saturating_add(1);
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.status.task =
            "preloading known_destinations and rechecking active browser path".into();

        let runtime = self.runtime.clone();
        let event_tx = self.event_tx.clone();
        tokio::spawn(async move {
            let report = preload_known_destinations_and_recheck_path(
                runtime,
                preload_path,
                url,
                destination,
            )
            .await
            .map_err(|error| error.to_string());
            let _ = event_tx
                .send(InternalAppEvent::DiagnosticsTask(
                    DiagnosticsTaskResult::KnownDestinationsPreload {
                        tab_id,
                        generation,
                        report,
                    },
                ))
                .await;
        });

        true
    }

    pub fn warm_active_browser_path(&mut self) -> bool {
        let active = self.workspace.active_browser;
        let url = self.active_browser_path_request_target(active);
        let parsed = BrowserAddress::parse(&url);
        let destination = parsed.as_ref().map(|address| address.destination.clone());
        if destination.is_none() {
            self.status.task =
                "cannot request path: active browser address is not destination:path".into();
            self.workspace.browser_tabs[active].probe_summary = Some(BrowserProbeSummary {
                url,
                mode: "path-discovery".into(),
                ready_to_request: false,
                status: "invalid address".into(),
                detail: "enter a destination:path address before requesting path discovery".into(),
            });
            return false;
        }

        if let Some(existing) = self.workspace.browser_tabs[active].path_warmup.take() {
            existing.cancel.cancel();
        }
        let tab_id = self.workspace.browser_tabs[active].id;
        let generation = self.next_diagnostics_generation;
        self.next_diagnostics_generation = self.next_diagnostics_generation.saturating_add(1);
        let cancel = CancellationToken::new();
        self.workspace.browser_tabs[active].path_warmup = Some(LoadState {
            generation,
            target: url.clone(),
            submitted_fields: false,
            cancel: cancel.clone(),
        });
        self.workspace.browser_tabs[active].probe_summary = Some(BrowserProbeSummary {
            url: url.clone(),
            mode: "path-discovery".into(),
            ready_to_request: false,
            status: "running".into(),
            detail: "requesting path and waiting up to 5 seconds".into(),
        });
        self.status.task = "requesting active browser path".into();

        let runtime = self.runtime.clone();
        let event_tx = self.event_tx.clone();
        tokio::spawn(async move {
            let path_warmup = run_smoke_path_warmup_with_cancel(
                runtime,
                &url,
                destination.as_deref(),
                Some(SmokePathWarmup { wait_secs: 5 }),
                Some(cancel),
            )
            .await;
            let report = serde_json::json!({
                "report": "browser_path_warmup",
                "active_browser_url": url,
                "destination_hash": destination,
                "path_warmup": path_warmup,
            });
            let _ = event_tx
                .send(InternalAppEvent::DiagnosticsTask(
                    DiagnosticsTaskResult::BrowserPathWarmup {
                        tab_id,
                        generation,
                        report: Ok(report),
                    },
                ))
                .await;
        });

        true
    }

    fn active_browser_path_request_target(&self, active: usize) -> String {
        let tab = &self.workspace.browser_tabs[active];
        if let Some(preview) = tab.request_preview.as_ref().filter(|preview| {
            matches!(
                preview.status,
                BrowserRequestStatus::Pending | BrowserRequestStatus::Failed
            )
        }) {
            if tab
                .retry_state
                .as_ref()
                .is_some_and(|retry| retry.target == preview.target)
            {
                return preview.target.clone();
            }
        }
        if let Some(retry) = tab.retry_state.as_ref() {
            if matches!(
                tab.request_preview.as_ref().map(|preview| &preview.status),
                Some(BrowserRequestStatus::Pending | BrowserRequestStatus::Failed)
            ) {
                return retry.target.clone();
            }
        }
        tab.address_input.clone()
    }

    pub async fn start_runtime_for_smoke_test(&mut self) -> AppResult<()> {
        self.start_runtime_for_smoke_test_with_interfaces(None)
            .await
    }

    pub fn start_configured_runtime_nonblocking(&mut self) -> bool {
        if self.runtime_startup_pending {
            self.status.task = "native runtime startup is already pending".into();
            return false;
        }
        if self.runtime_status.connected {
            self.status.task = "native runtime is already connected".into();
            return false;
        }
        if !matches!(self.runtime_status.backend, RuntimeBackendName::Reticulum) {
            self.status.task = format!(
                "native runtime startup blocked: active backend is {:?}; run Setup / Start Native first",
                self.runtime_status.backend
            );
            return false;
        }
        let Ok(handle) = tokio::runtime::Handle::try_current() else {
            self.status.task = "native runtime startup requires an active Tokio runtime".into();
            self.logs.push_with_source(
                LogSeverity::Warn,
                LogSource::Runtime,
                "native runtime startup requested without an active Tokio runtime",
            );
            return false;
        };
        if !self.ensure_managed_identity_for_native_startup() {
            return false;
        }
        let identity = match self.smoke_test_identity_profile() {
            Ok(identity) => identity,
            Err(error) => {
                self.status.task = format!("native runtime startup blocked: {error}");
                self.logs.push_with_source(
                    LogSeverity::Warn,
                    LogSource::Runtime,
                    format!("native runtime startup blocked: {error}"),
                );
                return false;
            }
        };
        let interfaces = self.interface_service.list_profiles().to_vec();
        let enabled_interfaces = interfaces.iter().filter(|profile| profile.enabled).count();
        let interface_summary = interfaces
            .iter()
            .filter(|profile| profile.enabled)
            .map(|profile| {
                format!(
                    "{}:{:?}:ifac={}",
                    profile.name,
                    profile.kind,
                    if profile.network_name.is_empty() && profile.passphrase.is_empty() {
                        "none".to_string()
                    } else if profile.network_name.is_empty() {
                        "passphrase-only".to_string()
                    } else if profile.passphrase.is_empty() {
                        format!("network-name-only({})", profile.network_name)
                    } else {
                        format!("network({})+passphrase", profile.network_name)
                    }
                )
            })
            .collect::<Vec<_>>()
            .join(", ");
        let runtime = self.runtime.clone();
        let tx = self.event_tx.clone();
        self.runtime_startup_pending = true;
        self.status.task = "starting native Reticulum runtime".into();
        self.logs.push_with_source(
            LogSeverity::Info,
            LogSource::Runtime,
            format!(
                "starting configured native Reticulum runtime identity={} hash={} enabled_interfaces={} [{}] managed_config={}",
                identity
                    .as_ref()
                    .map(|profile| profile.label.as_str())
                    .unwrap_or("none"),
                identity
                    .as_ref()
                    .map(|profile| profile.hash_hex.as_str())
                    .unwrap_or("none"),
                enabled_interfaces,
                if interface_summary.is_empty() {
                    "none".to_string()
                } else {
                    interface_summary
                },
                self.paths.reticulum_config_dir.display()
            ),
        );
        handle.spawn(async move {
            let started_at = Instant::now();
            let result = match runtime.start_runtime(identity, interfaces).await {
                Ok(()) => Ok(runtime.status().await),
                Err(error) => Err(error.to_string()),
            };
            let elapsed = started_at.elapsed();
            let _ = tx
                .send(InternalAppEvent::Runtime(RuntimeBusEvent::Debug(format!(
                    "native Reticulum startup task finished in {:.3}s",
                    elapsed.as_secs_f64()
                ))))
                .await;
            let _ = tx.send(InternalAppEvent::RuntimeStartup(result)).await;
        });
        true
    }

    pub async fn start_runtime_for_smoke_test_with_interfaces(
        &mut self,
        interface_override: Option<Vec<ReticulumInterfaceProfile>>,
    ) -> AppResult<()> {
        let identity = self.smoke_test_identity_profile()?;
        let interfaces = match interface_override {
            Some(interfaces) => {
                self.apply_smoke_test_interface_override(&interfaces)?;
                interfaces
            }
            None => self.interface_service.list_profiles().to_vec(),
        };
        self.runtime
            .start_runtime(identity.clone(), interfaces)
            .await?;
        self.runtime_status = self.runtime.status().await;
        self.status.backend = format!("backend: {:?}", self.runtime_status.backend).to_lowercase();
        self.status.task = "runtime startup completed for smoke test".into();
        Ok(())
    }

    fn apply_smoke_test_interface_override(
        &self,
        interfaces: &[ReticulumInterfaceProfile],
    ) -> AppResult<()> {
        std::fs::create_dir_all(&self.paths.reticulum_config_dir)?;
        std::fs::write(
            self.paths.reticulum_config_dir.join("config"),
            crate::interfaces::render_config(interfaces),
        )?;
        Ok(())
    }

    fn smoke_test_identity_profile(&self) -> AppResult<Option<crate::identity::IdentityProfile>> {
        let Some(identity_path) = self.settings.identity_path.clone() else {
            return Ok(None);
        };
        let manager = IdentityManager::new(
            self.paths.identities_dir.clone(),
            self.paths.identity_backups_dir.clone(),
        );
        manager
            .attach_existing(
                identity_path,
                self.settings.active_identity_label.as_deref(),
            )
            .map(Some)
    }

