    pub async fn native_network_smoke_test_report_for_url_with_fetch_options(
        &self,
        url: impl Into<String>,
        execute_live_probe: bool,
        execute_live_fetch: bool,
        warmup: Option<SmokePathWarmup>,
        known_destinations_preload: Option<SmokeKnownDestinationsPreload>,
    ) -> AppResult<serde_json::Value> {
        let url = url.into();
        let parsed = BrowserAddress::parse(&url);
        let input = LiveInteropReportInput {
            active_browser_url: url,
            parsed_destination: parsed.as_ref().map(|address| address.destination.clone()),
            parsed_path: parsed.as_ref().map(|address| address.path.clone()),
            active_conversation_peer: Some(self.active_conversation().peer_hash.clone()),
            active_conversation_label: Some(self.active_conversation().peer_label.clone()),
            runtime_status: self.runtime_status.clone(),
            native_readiness: self.native_reticulum_readiness(),
            probe_summary: None,
            recent_trace_logs: self.recent_page_load_trace_logs(25),
            identity_path: self.settings.identity_path.clone(),
        };
        collect_native_network_smoke_test_report(
            self.runtime.clone(),
            input,
            execute_live_probe,
            execute_live_fetch,
            warmup,
            known_destinations_preload,
        )
        .await
    }

