    pub async fn preload_known_destinations_for_smoke_test(
        &self,
        path: &Path,
    ) -> AppResult<SmokeKnownDestinationsPreload> {
        if !path.is_file() {
            return Err(crate::error::AppError::Runtime(format!(
                "known destinations file does not exist: {}",
                path.display()
            )));
        }
        let loaded = self.runtime.preload_known_destinations(path).await?;
        Ok(SmokeKnownDestinationsPreload {
            source_hint: path
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("known_destinations")
                .into(),
            loaded,
        })
    }

    fn start_live_interop_report(&mut self, export: bool) -> bool {
        let generation = self.next_diagnostics_generation;
        self.next_diagnostics_generation = self.next_diagnostics_generation.saturating_add(1);
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.status.task = if export {
            "collecting live interop report for export".into()
        } else {
            "collecting live interop report".into()
        };

        let runtime = self.runtime.clone();
        let event_tx = self.event_tx.clone();
        let report_input = self.live_interop_report_input();
        tokio::spawn(async move {
            let report = collect_live_interop_report(runtime, report_input)
                .await
                .map_err(|error| error.to_string());
            let _ = event_tx
                .send(InternalAppEvent::DiagnosticsTask(
                    DiagnosticsTaskResult::LiveInteropReport {
                        generation,
                        export,
                        report,
                    },
                ))
                .await;
        });

        true
    }

    fn live_interop_report_input(&self) -> LiveInteropReportInput {
        let tab = self.active_browser_tab();
        let parsed = BrowserAddress::parse(&tab.address_input);
        LiveInteropReportInput {
            active_browser_url: tab.address_input.clone(),
            parsed_destination: parsed.as_ref().map(|address| address.destination.clone()),
            parsed_path: parsed.as_ref().map(|address| address.path.clone()),
            active_conversation_peer: Some(self.active_conversation().peer_hash.clone()),
            active_conversation_label: Some(self.active_conversation().peer_label.clone()),
            runtime_status: self.runtime_status.clone(),
            native_readiness: self.native_reticulum_readiness(),
            probe_summary: tab.probe_summary.clone(),
            recent_trace_logs: self.recent_page_load_trace_logs(25),
            identity_path: self.settings.identity_path.clone(),
        }
    }

    fn recent_page_load_trace_logs(&self, limit: usize) -> Vec<LogEntry> {
        self.logs
            .entries
            .iter()
            .rev()
            .filter(|entry| {
                entry.message.contains("page probe step")
                    || entry.message.contains("browser-load page probe step")
            })
            .take(limit)
            .cloned()
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .collect()
    }

    pub fn browser_live_trace_lines(&self, limit: usize) -> Vec<String> {
        let tab = self.active_browser_tab();
        let parsed = BrowserAddress::parse(&tab.address_input);
        let readiness = self.native_reticulum_readiness();
        let source = tab
            .current_page
            .as_ref()
            .map(|page| browser_page_source_label(&page.source).to_string())
            .unwrap_or_else(|| "None".into());
        let request_backend = tab
            .current_page
            .as_ref()
            .and_then(page_native_request_backend)
            .unwrap_or("none");
        let loading = tab
            .loading
            .as_ref()
            .map(|loading| format!("{} gen={}", loading.target, loading.generation))
            .unwrap_or_else(|| "none".into());
        let path_warmup = tab
            .path_warmup
            .as_ref()
            .map(|warmup| format!("{} gen={}", warmup.target, warmup.generation))
            .unwrap_or_else(|| "none".into());
        let retry_state = tab
            .retry_state
            .as_ref()
            .map(browser_retry_state_line)
            .unwrap_or_else(|| "none".into());

        let mut lines = vec![
            format!("address: {}", tab.address_input),
            format!("page source: {source}"),
            format!("request backend: {request_backend}"),
            browser_live_page_evidence_line(
                tab.current_page.as_ref(),
                &self.runtime_status.backend,
            ),
            format!(
                "runtime: {:?} connected={} | {}",
                self.runtime_status.backend,
                self.runtime_status.connected,
                self.runtime_status.message
            ),
            format!(
                "native readiness: ready={} | {}",
                readiness.ready, readiness.summary
            ),
            format!("loading: {loading}"),
            format!("path request: {path_warmup}"),
            format!("retry: {retry_state}"),
        ];

        match parsed.as_ref() {
            Some(address) => {
                lines.push(format!("destination: {}", address.destination));
                lines.push(format!("path: {}", address.path));
            }
            None => lines.push("destination: invalid address; expected destination:/path".into()),
        }

        if readiness.issues.is_empty() {
            lines.push("readiness issues: none".into());
        } else {
            lines.extend(
                readiness
                    .issues
                    .iter()
                    .take(4)
                    .map(|issue| format!("readiness issue: {issue}")),
            );
        }

        if let Some(probe) = &tab.probe_summary {
            lines.push(format!(
                "probe: {} {} ready={} | {}",
                probe.mode, probe.status, probe.ready_to_request, probe.detail
            ));
            lines.push(format!(
                "probe evidence: {}",
                browser_probe_evidence_label(probe)
            ));
        } else {
            lines.push("probe: none".into());
            lines.push("probe evidence: none".into());
        }

        lines.push(format!(
            "next: {}",
            browser_live_trace_next_action(
                parsed.as_ref(),
                tab.loading.is_some(),
                tab.path_warmup.is_some(),
                tab.probe_summary.as_ref(),
                &self.runtime_status.backend,
                &readiness,
            )
        ));

        let trace_logs = self.recent_page_load_trace_logs(limit);
        if trace_logs.is_empty() {
            lines.push("trace: no page probe/load trace yet".into());
        } else {
            lines.extend(trace_logs.into_iter().map(|entry| {
                format!(
                    "trace {:?} {:?}: {}",
                    entry.severity, entry.source, entry.message
                )
            }));
        }

        lines
    }

    pub fn active_browser_live_warning(&self) -> Option<&BrowserLiveWarning> {
        self.active_browser_tab().live_warning.as_ref()
    }

    pub fn probe_active_browser_page_fetch(&mut self, execute_request: bool) -> bool {
        self.start_active_browser_page_fetch_probe(execute_request, true)
    }

    pub fn probe_active_browser_page_fetch_inline(&mut self) -> bool {
        self.start_active_browser_page_fetch_probe(false, false)
    }

    fn start_active_browser_page_fetch_probe(
        &mut self,
        execute_request: bool,
        show_diagnostics: bool,
    ) -> bool {
        let url = self.active_browser_tab().address_input.trim().to_string();
        if url.is_empty() {
            self.status.task = "cannot probe empty browser address".into();
            return false;
        }

        let tab_id = self.active_browser_tab().id;
        let generation = self.next_diagnostics_generation;
        self.next_diagnostics_generation = self.next_diagnostics_generation.saturating_add(1);
        if show_diagnostics {
            self.workspace.active_section = WorkspaceSection::Diagnostics;
        }
        self.active_browser_tab_mut().probe_summary = Some(BrowserProbeSummary {
            url: url.clone(),
            mode: if execute_request { "live" } else { "dry-run" }.into(),
            ready_to_request: false,
            status: "running".into(),
            detail: "probe task pending".into(),
        });
        self.status.task = if execute_request {
            format!("running live native page probe for {url}")
        } else {
            format!("running dry-run native page probe for {url}")
        };

        let runtime = self.runtime.clone();
        let event_tx = self.event_tx.clone();
        tokio::spawn(async move {
            let report = runtime
                .probe_page_fetch(&url, execute_request)
                .await
                .map_err(|error| error.to_string());
            let _ = event_tx
                .send(InternalAppEvent::DiagnosticsTask(
                    DiagnosticsTaskResult::PageFetchProbe {
                        tab_id,
                        generation,
                        execute_request,
                        show_diagnostics,
                        report,
                    },
                ))
                .await;
        });

        true
    }

    pub fn clear_diagnostics_preview(&mut self) -> bool {
        if self.diagnostics_state.preview_lines.is_empty()
            && self.diagnostics_state.last_export_path.is_none()
            && self.diagnostics_state.last_export_summary.is_none()
        {
            self.status.task = "no diagnostics preview/export state to clear".into();
            return false;
        }
        self.diagnostics_state.preview_lines.clear();
        self.diagnostics_state.preview_scroll = 0;
        self.diagnostics_state.last_export_path = None;
        self.diagnostics_state.last_export_summary = None;
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.status.task = "cleared diagnostics preview state".into();
        true
    }

    pub fn scroll_diagnostics_preview_lines(&mut self, delta: isize) -> usize {
        let max_offset = self.diagnostics_state.preview_lines.len().saturating_sub(1);
        let current = self.diagnostics_state.preview_scroll as isize;
        let next = current.saturating_add(delta).max(0) as usize;
        self.diagnostics_state.preview_scroll = next.min(max_offset);
        self.status.task = format!(
            "diagnostics preview scroll: {}",
            self.diagnostics_state.preview_scroll
        );
        self.diagnostics_state.preview_scroll
    }

    pub fn scroll_diagnostics_preview_page(
        &mut self,
        viewport_rows: usize,
        direction: isize,
    ) -> usize {
        let rows = viewport_rows.max(1) as isize;
        self.scroll_diagnostics_preview_lines(rows.saturating_mul(direction.signum()))
    }

    fn preview_live_interop_report_value(
        &mut self,
        generation: u64,
        report: &serde_json::Value,
    ) -> bool {
        let rendered = self.preview_json_diagnostics_value(report, |line_count| {
            format!("previewed live interop report generation {generation} ({line_count} lines)")
        });
        if rendered {
            self.logs.push_with_source(
                LogSeverity::Info,
                LogSource::Diagnostics,
                format!("previewed live interop report generation {generation}"),
            );
        }
        rendered
    }

    fn preview_json_diagnostics_value(
        &mut self,
        report: &serde_json::Value,
        status: impl FnOnce(usize) -> String,
    ) -> bool {
        let Some(line_count) = self.set_diagnostics_preview_value(report) else {
            self.status.task = "failed to render diagnostics JSON".into();
            return false;
        };
        self.workspace.active_section = WorkspaceSection::Diagnostics;
        self.status.task = status(line_count);
        true
    }

    fn set_diagnostics_preview_value(&mut self, report: &serde_json::Value) -> Option<usize> {
        let content = match serde_json::to_string_pretty(report) {
            Ok(content) => content,
            Err(error) => {
                self.status.task = format!("failed to render diagnostics JSON: {error}");
                return None;
            }
        };
        let lines = content.lines().map(ToOwned::to_owned).collect::<Vec<_>>();
        let line_count = lines.len();
        self.diagnostics_state.preview_lines = lines;
        self.diagnostics_state.preview_scroll = 0;
        Some(line_count)
    }

    fn write_live_interop_report_export(
        &mut self,
        generation: u64,
        report: &serde_json::Value,
    ) -> bool {
        let content = match serde_json::to_string_pretty(report) {
            Ok(content) => content,
            Err(error) => {
                self.status.task = format!("failed to render live interop report: {error}");
                return false;
            }
        };
        if let Err(error) = std::fs::create_dir_all(&self.paths.diagnostics_dir) {
            self.status.task = format!("failed to prepare diagnostics export dir: {error}");
            return false;
        }
        let epoch = current_epoch_ms();
        for suffix in 0..1000_u16 {
            let filename = if suffix == 0 {
                format!("live-interop-report-{epoch}.json")
            } else {
                format!("live-interop-report-{epoch}-{suffix}.json")
            };
            let path = self.paths.diagnostics_dir.join(filename);
            if path.exists() {
                continue;
            }
            match std::fs::write(&path, content.as_bytes()) {
                Ok(()) => {
                    self.diagnostics_state.last_export_path = Some(path.clone());
                    self.diagnostics_state.last_export_summary =
                        Some(format!("live interop report generation {generation}"));
                    self.workspace.active_section = WorkspaceSection::Diagnostics;
                    self.status.task = format!("exported live interop report: {}", path.display());
                    self.logs.push_with_source(
                        LogSeverity::Info,
                        LogSource::Diagnostics,
                        format!("exported live interop report: {}", path.display()),
                    );
                    return true;
                }
                Err(error) => {
                    self.status.task = format!("failed to export live interop report: {error}");
                    return false;
                }
            }
        }
        self.status.task = "failed to export live interop report: no unique filename".into();
        false
    }

    fn write_diagnostics_bundle_export(&mut self, snapshot: Option<&DiagnosticsSnapshot>) -> bool {
        if let Some(snapshot) = snapshot {
            self.diagnostics_state.last_lxmf_sdk_rpc_probe =
                Some(snapshot.native_lxmf_sdk_rpc_probe.clone());
        }
        let bundle = self.redacted_diagnostics_bundle_with_snapshot(snapshot);
        let content = match serde_json::to_string_pretty(&bundle) {
            Ok(content) => content,
            Err(error) => {
                self.status.task = format!("failed to render diagnostics bundle: {error}");
                self.logs.push_with_source(
                    LogSeverity::Error,
                    LogSource::Diagnostics,
                    format!("failed to render diagnostics bundle: {error}"),
                );
                return false;
            }
        };

        if let Err(error) = std::fs::create_dir_all(&self.paths.diagnostics_dir) {
            self.status.task = format!("failed to prepare diagnostics export dir: {error}");
            self.logs.push_with_source(
                LogSeverity::Error,
                LogSource::Diagnostics,
                format!(
                    "failed to prepare diagnostics bundle export dir {}: {error}",
                    self.paths.diagnostics_dir.display()
                ),
            );
            return false;
        }

        let epoch = current_epoch_ms();
        for suffix in 0..1000_u16 {
            let filename = if suffix == 0 {
                format!("diagnostics-bundle-{epoch}.json")
            } else {
                format!("diagnostics-bundle-{epoch}-{suffix}.json")
            };
            let path = self.paths.diagnostics_dir.join(filename);
            if path.exists() {
                continue;
            }

            match std::fs::write(&path, content.as_bytes()) {
                Ok(()) => {
                    let summary = format!(
                        "diagnostics bundle: interfaces={} browser_tabs={} conversation_tabs={} config_lines={}",
                        self.interface_service.list_profiles().len(),
                        self.workspace.browser_tabs.len(),
                        self.workspace.conversations.len(),
                        self.interface_service.render_config().lines().count()
                    );
                    self.diagnostics_state.last_export_path = Some(path.clone());
                    self.diagnostics_state.last_export_summary = Some(summary.clone());
                    self.diagnostics_state.last_snapshot = Some(summary);
                    self.workspace.active_section = WorkspaceSection::Diagnostics;
                    self.status.task = format!("exported diagnostics bundle: {}", path.display());
                    self.logs.push_with_source(
                        LogSeverity::Info,
                        LogSource::Diagnostics,
                        format!("exported diagnostics bundle: {}", path.display()),
                    );
                    return true;
                }
                Err(error) => {
                    self.status.task = format!("failed to export diagnostics bundle: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Diagnostics,
                        format!(
                            "failed to export diagnostics bundle to {}: {error}",
                            path.display()
                        ),
                    );
                    return false;
                }
            }
        }

        self.status.task = "failed to export diagnostics bundle: no unique filename".into();
        self.logs.push_with_source(
            LogSeverity::Error,
            LogSource::Diagnostics,
            format!(
                "failed to export diagnostics bundle under {}: no unique filename",
                self.paths.diagnostics_dir.display()
            ),
        );
        false
    }

    pub fn redacted_diagnostics_bundle(&self) -> serde_json::Value {
        self.redacted_diagnostics_bundle_with_snapshot(None)
    }

    pub fn redacted_diagnostics_bundle_with_snapshot(
        &self,
        snapshot: Option<&DiagnosticsSnapshot>,
    ) -> serde_json::Value {
        let native_readiness = self.native_reticulum_readiness();
        let identity_path = self.settings.identity_path.as_ref();
        let native_issues = native_readiness
            .issues
            .iter()
            .map(|issue| redact_sensitive_diagnostics_text(issue, identity_path))
            .collect::<Vec<_>>();
        let config = self.interface_service.render_config();

        let mut bundle = serde_json::json!({
            "app": {
                "name": env!("CARGO_PKG_NAME"),
                "version": env!("CARGO_PKG_VERSION"),
            },
            "runtime": {
                "backend": format!("{:?}", self.runtime_status.backend),
                "connected": self.runtime_status.connected,
                "message": self.runtime_status.message,
            },
            "native_reticulum_readiness": {
                "compiled": native_readiness.compiled,
                "configured": native_readiness.configured,
                "ready": native_readiness.ready,
                "summary": redact_sensitive_diagnostics_text(&native_readiness.summary, identity_path),
                "issues": native_issues,
            },
            "identity": self.runtime_status.active_identity.as_ref().map(|identity| {
                serde_json::json!({
                    "label": identity.label,
                    "hash_short": identity.hash_hex.chars().take(12).collect::<String>(),
                    "managed": identity.managed,
                    "path_hint": "<redacted>",
                })
            }),
            "paths": {
                "root": self.paths.root.display().to_string(),
                "settings_file": self.paths.settings_file.display().to_string(),
                "cache_dir": self.paths.cache_dir.display().to_string(),
                "downloads_dir": self.paths.downloads_dir.display().to_string(),
                "diagnostics_dir": self.paths.diagnostics_dir.display().to_string(),
                "reticulum_config_dir": self.paths.reticulum_config_dir.display().to_string(),
                "reticulum_storage_dir": self.paths.reticulum_storage_dir.display().to_string(),
            },
            "settings": {
                "runtime_backend": format!("{:?}", self.settings.runtime_backend),
                "reticulum_instance_mode": format!("{:?}", self.settings.reticulum_instance_mode),
                "announce_on_start": self.settings.announce_on_start,
                "periodic_lxmf_sync": self.settings.periodic_lxmf_sync,
                "auto_sync_after_propagation_accept": self.settings.auto_sync_after_propagation_accept,
                "lxmf_sync_interval": self.settings.lxmf_sync_interval,
                "lxmf_sync_limit": self.settings.lxmf_sync_limit,
                "theme_name": self.settings.ui.theme_name,
            },
            "counts": {
                "message_threads": self.message_store.list_threads().map(|threads| threads.len()).unwrap_or_default(),
                "directory_entries": self.directory_service.list_entries().len(),
                "live_directory_entries": self.directory_service.list_live_entries().len(),
                "interface_profiles": self.interface_service.list_profiles().len(),
                "browser_tabs": self.workspace.browser_tabs.len(),
                "conversation_tabs": self.workspace.conversations.len(),
                "plugins": self.plugins_state.manifests.len(),
                "recent_logs": self.logs.entries.len().min(50),
            },
            "recent_logs": redacted_recent_log_entries(&self.logs, identity_path, 50),
            "plugins": {
                "manifests": self.plugins_state.manifests,
                "warnings": self.plugins_state.warnings,
            },
            "interfaces": {
                "readiness": self.native_interface_readiness().into_iter().map(|detail| {
                    serde_json::json!({
                        "profile_id": detail.profile_id,
                        "name": detail.name,
                        "kind": detail.kind,
                        "enabled": detail.enabled,
                        "supported": detail.supported,
                        "blocks_native_startup": detail.blocks_native_startup,
                        "reason": detail.reason,
                        "warnings": detail.warnings,
                    })
                }).collect::<Vec<_>>(),
                "generated_reticulum_config": {
                    "line_count": config.lines().count(),
                    "content": config,
                },
            },
        });

        if let Some(snapshot) = snapshot {
            bundle["diagnostics_service_snapshot"] =
                serde_json::json!(DiagnosticsService::redacted_export(snapshot));
        }

        bundle
    }

    fn create_interface_profile(&mut self, kind: InterfaceKind, label: &str) -> bool {
        match self.interface_service.create(kind) {
            Ok(profile) => match self.interface_service.apply() {
                Ok(_) => {
                    self.refresh_interface_state_preserving_selection(&profile.profile_id);
                    self.workspace.active_section = WorkspaceSection::Interfaces;
                    self.status.task = format!(
                        "created {label} interface '{}' | {INTERFACE_RESTART_RECOMMENDED}",
                        profile.name
                    );
                    self.refresh_diagnostics_summary();
                    true
                }
                Err(error) => {
                    self.status.task = format!("failed to apply interface config: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Interface,
                        format!("failed to apply interface config after {label} create: {error}"),
                    );
                    false
                }
            },
            Err(error) => {
                self.status.task = format!("failed to create {label} interface: {error}");
                self.logs.push_with_source(
                    LogSeverity::Error,
                    LogSource::Interface,
                    format!("failed to create {label} interface: {error}"),
                );
                false
            }
        }
    }

    fn create_gateway_interface_profile_by_id(&mut self, gateway_id: &str, label: &str) -> bool {
        match self.interface_service.create_gateway_profile(gateway_id) {
            Ok(Some(outcome)) => match self.interface_service.apply() {
                Ok(_) => {
                    let profile = outcome.profile();
                    self.refresh_interface_state_preserving_selection(&profile.profile_id);
                    self.workspace.active_section = WorkspaceSection::Interfaces;
                    self.status.task = match outcome {
                        GatewayProfileCreateOutcome::Created(profile) => format!(
                            "created {label} gateway '{}:{}' | {INTERFACE_RESTART_RECOMMENDED}",
                            profile.target_host, profile.target_port
                        ),
                        GatewayProfileCreateOutcome::Enabled(profile) => format!(
                            "enabled {label} gateway '{}:{}' | {INTERFACE_RESTART_RECOMMENDED}",
                            profile.target_host, profile.target_port
                        ),
                        GatewayProfileCreateOutcome::AlreadyEnabled(profile) => format!(
                            "{label} gateway already enabled '{}:{}'",
                            profile.target_host, profile.target_port
                        ),
                    };
                    self.refresh_diagnostics_summary();
                    true
                }
                Err(error) => {
                    self.status.task = format!("failed to apply gateway interface config: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Interface,
                        format!("failed to apply interface config after {label} create: {error}"),
                    );
                    false
                }
            },
            Ok(None) => {
                self.status.task = format!("gateway preset not found: {gateway_id}");
                false
            }
            Err(error) => {
                self.status.task = format!("failed to create {label} interface: {error}");
                self.logs.push_with_source(
                    LogSeverity::Error,
                    LogSource::Interface,
                    format!("failed to create {label} interface: {error}"),
                );
                false
            }
        }
    }

    pub fn begin_selected_interface_delete_flow(&mut self) -> bool {
        if self.interfaces_state.profiles.len() <= 1 {
            self.status.task = "cannot delete the last interface profile".into();
            return false;
        }
        let Some(index) = self.interfaces_state.selected else {
            self.status.task = "no interface selected".into();
            return false;
        };
        let Some(profile) = self.interfaces_state.profiles.get(index) else {
            self.interfaces_state.selected = None;
            self.status.task = "selected interface is unavailable".into();
            return false;
        };
        self.workspace.active_section = WorkspaceSection::Interfaces;
        self.workspace.focus = FocusArea::Command;
        self.input.begin(
            InputTarget::InterfaceDeleteConfirm {
                profile_id: profile.profile_id.clone(),
            },
            String::new(),
        );
        self.status.task = format!("type DELETE to remove interface '{}'", profile.name);
        true
    }

    pub fn pending_interface_delete_profile(
        &self,
    ) -> Option<crate::interfaces::ReticulumInterfaceProfile> {
        let InputTarget::InterfaceDeleteConfirm { profile_id } =
            &self.input.active.as_ref()?.target
        else {
            return None;
        };
        self.interface_service.get(profile_id).cloned().or_else(|| {
            self.interfaces_state
                .profiles
                .iter()
                .find(|profile| profile.profile_id == *profile_id)
                .cloned()
        })
    }

    pub fn confirm_pending_interface_delete(&mut self) -> bool {
        let Some(InputTarget::InterfaceDeleteConfirm { profile_id }) = self
            .input
            .active
            .as_ref()
            .map(|active| active.target.clone())
        else {
            self.status.task = "no pending interface delete confirmation".into();
            return false;
        };
        self.input.cancel();
        self.workspace.focus = FocusArea::Workspace;
        self.submit_interface_delete_confirm(profile_id, "DELETE".into())
    }

    pub fn cancel_pending_interface_delete(&mut self) -> bool {
        let Some(InputTarget::InterfaceDeleteConfirm { .. }) = self
            .input
            .active
            .as_ref()
            .map(|active| active.target.clone())
        else {
            self.status.task = "no pending interface delete confirmation".into();
            return false;
        };
        self.input.cancel();
        self.workspace.focus = FocusArea::Workspace;
        self.status.task = "interface delete cancelled".into();
        true
    }

    pub fn toggle_selected_interface_connectable(&mut self) -> bool {
        let Some(index) = self.interfaces_state.selected else {
            self.status.task = "no interface selected".into();
            return false;
        };
        let Some(profile) = self.interfaces_state.profiles.get(index) else {
            self.interfaces_state.selected = None;
            self.status.task = "selected interface is unavailable".into();
            return false;
        };
        if profile.kind != InterfaceKind::I2p {
            self.status.task = "connectable toggle only applies to I2P profiles".into();
            return false;
        }
        let profile_id = profile.profile_id.clone();
        match self.interface_service.toggle_connectable(&profile_id) {
            Ok(Some(updated)) => match self.interface_service.apply() {
                Ok(_) => {
                    self.refresh_interface_state_preserving_selection(&profile_id);
                    self.refresh_diagnostics_summary();
                    self.status.task = format!(
                        "I2P interface '{}' connectable={}",
                        updated.name, updated.connectable
                    );
                    true
                }
                Err(error) => {
                    self.status.task = format!("failed to apply interface config: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Interface,
                        format!(
                        "failed to apply interface config after I2P connectable toggle: {error}"
                    ),
                    );
                    false
                }
            },
            Ok(None) => {
                self.status.task = "selected interface no longer exists".into();
                false
            }
            Err(error) => {
                self.status.task = format!("failed to toggle I2P connectable: {error}");
                self.logs
                    .lines
                    .push(format!("failed to toggle I2P connectable: {error}"));
                false
            }
        }
    }

