    fn begin_selected_interface_edit(&mut self, field: InterfaceEditField) -> bool {
        let Some(index) = self.interfaces_state.selected else {
            self.status.task = "no interface selected".into();
            return false;
        };
        let Some(profile) = self.interfaces_state.profiles.get(index) else {
            self.interfaces_state.selected = None;
            self.status.task = "selected interface is unavailable".into();
            return false;
        };
        match (&profile.kind, field) {
            (_, InterfaceEditField::ProfileName)
            | (InterfaceKind::TcpClient, InterfaceEditField::TcpHost)
            | (InterfaceKind::TcpClient, InterfaceEditField::TcpPort)
            | (InterfaceKind::TcpClient, InterfaceEditField::TcpIfacNetworkName)
            | (InterfaceKind::TcpClient, InterfaceEditField::TcpIfacPassphrase)
            | (InterfaceKind::TcpServer, InterfaceEditField::TcpHost)
            | (InterfaceKind::TcpServer, InterfaceEditField::TcpPort)
            | (InterfaceKind::TcpServer, InterfaceEditField::TcpIfacNetworkName)
            | (InterfaceKind::TcpServer, InterfaceEditField::TcpIfacPassphrase)
            | (InterfaceKind::I2p, InterfaceEditField::I2pPeers)
            | (InterfaceKind::RNode, InterfaceEditField::RNodeDevicePort)
            | (InterfaceKind::RNode, InterfaceEditField::RNodeFrequency)
            | (InterfaceKind::RNode, InterfaceEditField::RNodeBandwidth)
            | (InterfaceKind::RNode, InterfaceEditField::RNodeTxPower)
            | (InterfaceKind::RNode, InterfaceEditField::RNodeSpreadingFactor)
            | (InterfaceKind::RNode, InterfaceEditField::RNodeCodingRate) => {}
            (InterfaceKind::TcpClient, InterfaceEditField::I2pPeers) => {
                self.status.task = "TCP gateway profiles do not use I2P peers".into();
                return false;
            }
            (InterfaceKind::TcpClient, _) => {
                self.status.task = "TCP gateway profiles do not use RNode fields".into();
                return false;
            }
            (InterfaceKind::TcpServer, InterfaceEditField::I2pPeers) => {
                self.status.task = "TCP server profiles do not use I2P peers".into();
                return false;
            }
            (InterfaceKind::TcpServer, _) => {
                self.status.task = "TCP server profiles do not use RNode fields".into();
                return false;
            }
            (InterfaceKind::I2p, _) => {
                self.status.task = "I2P profiles only expose peer-list editing for now".into();
                return false;
            }
            (InterfaceKind::RNode, _) => {
                self.status.task = "RNode profiles only expose radio fields".into();
                return false;
            }
            _ => {
                self.status.task = "only TCP, I2P, and RNode fields are editable for now".into();
                return false;
            }
        }

        let value = match field {
            InterfaceEditField::ProfileName => profile.name.clone(),
            InterfaceEditField::TcpHost => profile.target_host.clone(),
            InterfaceEditField::TcpPort => profile.target_port.to_string(),
            InterfaceEditField::TcpIfacNetworkName => profile.network_name.clone(),
            InterfaceEditField::TcpIfacPassphrase => profile.passphrase.clone(),
            InterfaceEditField::I2pPeers => profile.peers.join(", "),
            InterfaceEditField::RNodeDevicePort => profile.device_port.clone(),
            InterfaceEditField::RNodeFrequency => profile.frequency.to_string(),
            InterfaceEditField::RNodeBandwidth => profile.bandwidth.to_string(),
            InterfaceEditField::RNodeTxPower => profile.tx_power.to_string(),
            InterfaceEditField::RNodeSpreadingFactor => profile.spreading_factor.to_string(),
            InterfaceEditField::RNodeCodingRate => profile.coding_rate.to_string(),
        };
        self.workspace.active_section = WorkspaceSection::Interfaces;
        self.workspace.focus = FocusArea::Command;
        self.input.begin(
            InputTarget::InterfaceField {
                profile_id: profile.profile_id.clone(),
                field,
            },
            value,
        );
        self.status.task = match field {
            InterfaceEditField::ProfileName => "editing interface name".into(),
            InterfaceEditField::TcpHost if profile.kind == InterfaceKind::TcpServer => {
                "editing TCP server listen IP".into()
            }
            InterfaceEditField::TcpHost => "editing TCP gateway host".into(),
            InterfaceEditField::TcpPort if profile.kind == InterfaceKind::TcpServer => {
                "editing TCP server listen port".into()
            }
            InterfaceEditField::TcpPort => "editing TCP gateway port".into(),
            InterfaceEditField::TcpIfacNetworkName => "editing TCP IFAC network name".into(),
            InterfaceEditField::TcpIfacPassphrase => "editing TCP IFAC passphrase".into(),
            InterfaceEditField::I2pPeers => "editing I2P peers".into(),
            InterfaceEditField::RNodeDevicePort => "editing RNode device port".into(),
            InterfaceEditField::RNodeFrequency => "editing RNode frequency".into(),
            InterfaceEditField::RNodeBandwidth => "editing RNode bandwidth".into(),
            InterfaceEditField::RNodeTxPower => "editing RNode TX power".into(),
            InterfaceEditField::RNodeSpreadingFactor => "editing RNode spreading factor".into(),
            InterfaceEditField::RNodeCodingRate => "editing RNode coding rate".into(),
        };
        true
    }

    pub fn select_previous_plugin(&mut self) {
        let len = self.plugins_state.manifests.len();
        if len == 0 {
            self.plugins_state.selected = None;
            return;
        }
        self.plugins_state.selected =
            Some(self.plugins_state.selected.unwrap_or(0).saturating_sub(1));
    }

    pub fn select_next_plugin(&mut self) {
        let len = self.plugins_state.manifests.len();
        if len == 0 {
            self.plugins_state.selected = None;
            return;
        }
        self.plugins_state.selected = Some(
            self.plugins_state
                .selected
                .map(|index| (index + 1).min(len - 1))
                .unwrap_or(0),
        );
    }

    pub fn select_previous_settings_action(&mut self) {
        self.settings_state.selected = self.settings_state.selected.saturating_sub(1);
        self.status.task = "settings selection moved".into();
    }

    pub fn select_next_settings_action(&mut self) {
        self.settings_state.selected =
            (self.settings_state.selected + 1).min(SettingsAction::ALL.len() - 1);
        self.status.task = "settings selection moved".into();
    }

    pub fn select_settings_action(&mut self, index: usize) -> bool {
        if index >= SettingsAction::ALL.len() {
            self.status.task = "settings click was outside actions".into();
            return false;
        }
        self.workspace.active_section = WorkspaceSection::Settings;
        self.settings_state.selected = index;
        self.status.task = format!("selected settings action: {:?}", SettingsAction::ALL[index]);
        true
    }

    pub fn new_browser_tab(&mut self) {
        let start_url = self.settings.default_start_page.clone();
        let id = self.next_tab_id;
        self.next_tab_id += 1;
        let mut session = BrowserSession::with_runtime(
            start_url.clone(),
            self.runtime.clone(),
            self.cache.clone(),
            self.paths.downloads_dir.clone(),
        );
        self.configure_browser_session(&mut session);
        let current_page = session.current_page().cloned();
        self.workspace.browser_tabs.push(BrowserTab {
            id,
            title: format!("Tab {id}"),
            session,
            address_input: start_url,
            current_page,
            render_cache: RenderCache::default(),
            loading: None,
            path_warmup: None,
            partials: PartialRefreshState::default(),
            scroll: ScrollState::default(),
            micron_zoom_percent: 100,
            viewport_width: self.browser_viewport_width.max(1),
            viewport_height: self.browser_viewport_height.max(1),
            focused_control: None,
            focused_link: None,
            request_preview: None,
            probe_summary: None,
            live_warning: None,
            retry_state: None,
            micronplus_widgets: MicronPlusWidgetStore::default(),
            micronplus_control_events: Vec::new(),
            micronplus_diagnostics_logged: Vec::new(),
        });
        self.workspace.active_browser = self.workspace.browser_tabs.len() - 1;
        self.switch_section(WorkspaceSection::Browser);
        self.status.task = format!("created browser tab {id}");
    }

    pub fn focus_address_bar(&mut self) {
        self.workspace.active_section = WorkspaceSection::Browser;
        self.workspace.focus = FocusArea::Command;
        self.persist_ui_preferences("workspace section");
        let tab = self.active_browser_tab();
        self.input.begin(
            InputTarget::BrowserAddress { tab_id: tab.id },
            tab.address_input.clone(),
        );
        self.status.task = "editing browser address".into();
    }

    pub fn edit_address_char(&mut self, ch: char) {
        let mut encoded = [0; 4];
        self.edit_address_text(ch.encode_utf8(&mut encoded));
    }

    pub fn edit_address_text(&mut self, text: &str) -> bool {
        if !self.input_accepts_text() {
            return false;
        }
        if let Some(candidate) = self.active_browser_field_candidate(text) {
            let Some((tab_id, name, value)) = candidate else {
                self.status.task = "page field limit reached; input was not changed".into();
                return false;
            };
            let admitted = self.browser_tab_index(tab_id).is_some_and(|index| {
                self.workspace.browser_tabs[index]
                    .session
                    .can_set_field_value(&name, &value)
            });
            if !admitted {
                self.status.task = "page field limit reached; input was not changed".into();
                return false;
            }
        }
        if !self.input.insert_text(text) {
            return false;
        }
        self.sync_active_input_to_target();
        true
    }

    pub fn address_backspace(&mut self) {
        if !self.input_accepts_text() || !self.input.backspace() {
            return;
        }
        self.sync_active_input_to_target();
    }

    pub fn input_delete(&mut self) {
        if !self.input_accepts_text() || !self.input.delete() {
            return;
        }
        self.sync_active_input_to_target();
    }

    pub fn input_move_left(&mut self) -> bool {
        self.input_accepts_text() && self.input.move_left()
    }

    pub fn input_move_right(&mut self) -> bool {
        self.input_accepts_text() && self.input.move_right()
    }

    pub fn input_move_home(&mut self) -> bool {
        self.input_accepts_text() && self.input.move_home()
    }

    pub fn input_move_end(&mut self) -> bool {
        self.input_accepts_text() && self.input.move_end()
    }

    fn input_accepts_text(&self) -> bool {
        self.workspace.focus == FocusArea::Command
            || matches!(
                self.input.active.as_ref().map(|active| &active.target),
                Some(InputTarget::BrowserField { .. })
            )
    }

    fn active_browser_field_candidate(
        &self,
        inserted: &str,
    ) -> Option<Option<(TabId, String, String)>> {
        let active = self.input.active.as_ref()?;
        let InputTarget::BrowserField { tab_id, name } = &active.target else {
            return None;
        };
        let Some(new_len) = active.buffer.as_str().len().checked_add(inserted.len()) else {
            return Some(None);
        };
        if new_len > crate::micron::parser::MICRON_CONTROL_VALUE_MAX_BYTES {
            return Some(None);
        }
        let mut value = active.buffer.as_str().to_string();
        value.insert_str(active.buffer.cursor(), inserted);
        Some(Some((*tab_id, name.clone(), value)))
    }

