    fn apply_browser_probe_summary(&mut self, tab_id: TabId, summary: BrowserProbeSummary) -> bool {
        let Some(index) = self.browser_tab_index(tab_id) else {
            return false;
        };
        self.workspace.browser_tabs[index].probe_summary = Some(summary);
        true
    }

    fn apply_browser_probe_report_retry_state(
        &mut self,
        tab_id: TabId,
        report: &PageFetchProbeReport,
    ) -> bool {
        let Some(index) = self.browser_tab_index(tab_id) else {
            return false;
        };
        if report.ready_to_request {
            self.mark_browser_retry_ready(index, "probe reports ready to request");
            return true;
        }
        let Some(step) = report
            .steps
            .iter()
            .find(|step| page_fetch_probe_step_queued_path_request(step))
        else {
            return false;
        };
        let Some(destination_hash) = report
            .destination_hash
            .clone()
            .or_else(|| BrowserAddress::parse(&report.url).map(|address| address.destination))
        else {
            return false;
        };
        let now = current_epoch_ms();
        self.workspace.browser_tabs[index].retry_state = Some(BrowserRetryState {
            target: report.url.clone(),
            destination_hash,
            reason: step.detail.clone(),
            requested_epoch_ms: now,
            retry_after_epoch_ms: now.saturating_add(5_000),
            ready_epoch_ms: None,
            attempts: self.workspace.browser_tabs[index]
                .retry_state
                .as_ref()
                .map(|state| state.attempts)
                .unwrap_or(0),
        });
        true
    }

    fn apply_browser_load_failure_retry_state(
        &mut self,
        index: usize,
        target: &str,
        step: &PageFetchProbeStep,
    ) {
        if !page_fetch_probe_step_queued_path_request(step) {
            return;
        }
        let Some(address) = BrowserAddress::parse(target) else {
            return;
        };
        let now = current_epoch_ms();
        self.workspace.browser_tabs[index].retry_state = Some(BrowserRetryState {
            target: target.into(),
            destination_hash: address.destination,
            reason: step.detail.clone(),
            requested_epoch_ms: now,
            retry_after_epoch_ms: now.saturating_add(5_000),
            ready_epoch_ms: None,
            attempts: self.workspace.browser_tabs[index]
                .retry_state
                .as_ref()
                .map(|state| state.attempts)
                .unwrap_or(0),
        });
    }

    fn apply_browser_manual_retry_state(
        &mut self,
        index: usize,
        target: &str,
        reason: impl Into<String>,
    ) -> bool {
        let Some(address) = BrowserAddress::parse(target) else {
            return false;
        };
        let now = current_epoch_ms();
        self.workspace.browser_tabs[index].retry_state = Some(BrowserRetryState {
            target: target.into(),
            destination_hash: address.destination.to_ascii_lowercase(),
            reason: reason.into(),
            requested_epoch_ms: now,
            retry_after_epoch_ms: now,
            ready_epoch_ms: Some(now),
            attempts: self.workspace.browser_tabs[index]
                .retry_state
                .as_ref()
                .filter(|state| state.target == target)
                .map(|state| state.attempts)
                .unwrap_or(0),
        });
        true
    }

    fn apply_browser_transient_load_retry_state(
        &mut self,
        index: usize,
        target: &str,
        step: &PageFetchProbeStep,
    ) -> bool {
        if !native_browser_load_failure_allows_one_auto_retry(&step.stage) {
            return false;
        }
        if !self.runtime_status.connected {
            return false;
        }
        let Some(address) = BrowserAddress::parse(target) else {
            return false;
        };
        let previous_attempts = self.workspace.browser_tabs[index]
            .retry_state
            .as_ref()
            .filter(|state| state.target == target)
            .map(|state| state.attempts)
            .unwrap_or(0);
        if previous_attempts >= 1 {
            return false;
        }
        let now = current_epoch_ms();
        self.workspace.browser_tabs[index].retry_state = Some(BrowserRetryState {
            target: target.into(),
            destination_hash: address.destination.to_ascii_lowercase(),
            reason: format!(
                "{}; one automatic retry before page load after stale link cleanup",
                page_fetch_probe_stage_label(&step.stage)
            ),
            requested_epoch_ms: now,
            retry_after_epoch_ms: now.saturating_add(1_500),
            ready_epoch_ms: Some(now),
            attempts: previous_attempts.saturating_add(1),
        });
        let tab_id = self.workspace.browser_tabs[index].id;
        self.schedule_browser_path_ready_event(
            address.destination,
            1_500,
            Some(target.to_string()),
            Some(now),
        );
        self.logs.push_with_source(
            LogSeverity::Info,
            LogSource::Runtime,
            format!(
                "queued one automatic browser retry after transient load failure tab_id={tab_id} target={target}"
            ),
        );
        true
    }

    fn schedule_browser_path_ready_event(
        &self,
        destination: String,
        delay_ms: u64,
        target: Option<String>,
        requested_epoch_ms: Option<u64>,
    ) -> bool {
        let Ok(handle) = tokio::runtime::Handle::try_current() else {
            return false;
        };
        let tx = self.event_tx.clone();
        let destination = destination.trim().to_ascii_lowercase();
        handle.spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
            let _ = tx
                .send(InternalAppEvent::StartupBrowserPathReady {
                    destination,
                    target,
                    requested_epoch_ms,
                })
                .await;
        });
        true
    }

    fn mark_browser_retry_ready(&mut self, index: usize, reason: impl Into<String>) -> bool {
        self.mark_browser_retry_ready_after(index, reason, 0)
    }

    fn mark_browser_retry_ready_after(
        &mut self,
        index: usize,
        reason: impl Into<String>,
        delay_ms: u64,
    ) -> bool {
        let Some(state) = &mut self.workspace.browser_tabs[index].retry_state else {
            return false;
        };
        let reason = reason.into();
        let target = state.target.clone();
        let now = current_epoch_ms();
        state.ready_epoch_ms = Some(now);
        state.retry_after_epoch_ms = now.saturating_add(delay_ms);
        state.reason = reason.clone();
        if let Some(preview) = self.workspace.browser_tabs[index].request_preview.as_mut() {
            if preview.target == target && matches!(preview.status, BrowserRequestStatus::Pending) {
                preview.detail = reason;
            }
        }
        true
    }

    fn apply_browser_path_request_timeout(
        &mut self,
        tab_id: TabId,
        destination: &str,
        target: &str,
        requested_epoch_ms: Option<u64>,
    ) -> bool {
        let Some(index) = self.browser_tab_index(tab_id) else {
            return false;
        };
        if self.workspace.browser_tabs[index].loading.is_some() {
            return false;
        }
        let pending_matches = self.workspace.browser_tabs[index]
            .retry_state
            .as_ref()
            .is_some_and(|state| {
                state.target == target
                    && state.destination_hash.eq_ignore_ascii_case(destination)
                    && state.ready_epoch_ms.is_none()
                    && requested_epoch_ms
                        .map(|requested| requested == state.requested_epoch_ms)
                        .unwrap_or(true)
            });
        if !pending_matches {
            return false;
        }
        let detail = "path request did not produce ready path evidence before timeout; request path again or wait for an announce, then retry";
        if let Some(preview) = self.workspace.browser_tabs[index].request_preview.as_mut() {
            if preview.target == target && matches!(preview.status, BrowserRequestStatus::Pending) {
                preview.status = BrowserRequestStatus::Failed;
                preview.detail = detail.into();
            }
        }
        self.status.task = format!("browser path request timed out for {target}");
        self.logs.push_with_source(
            LogSeverity::Warn,
            LogSource::Runtime,
            format!("browser path request timed out destination={destination} target={target}"),
        );
        true
    }

    fn apply_browser_path_discovery_summary(
        &mut self,
        tab_id: TabId,
        report: &serde_json::Value,
    ) -> bool {
        let Some(index) = self.browser_tab_index(tab_id) else {
            return false;
        };
        let summary = BrowserProbeSummary::from_path_discovery_report(report);
        if summary.ready_to_request {
            self.mark_browser_retry_ready(index, "path discovery reports a known route");
        }
        self.workspace.browser_tabs[index].probe_summary = Some(summary);
        true
    }

    fn refresh_browser_probe_summaries_from_announce(
        &mut self,
        announce: &crate::runtime::AnnouncePayload,
    ) {
        for tab in &mut self.workspace.browser_tabs {
            let Some(summary) = &mut tab.probe_summary else {
                continue;
            };
            if !browser_probe_summary_waits_for_network_evidence(summary)
                || !announce_matches_browser_probe(announce, &summary.url, &tab.address_input)
            {
                continue;
            }

            summary.status = announce_browser_probe_status(&announce.kind).into();
            summary.detail = format!(
                "{} announce received for {}; run N to re-check identity/path readiness",
                announce_kind_label(&announce.kind),
                announce.display_name
            );
        }
    }

    fn warm_paths_for_relevant_announce(&mut self, entry: &DirectoryEntry) -> bool {
        let candidates = directory_entry_path_candidates(entry);
        if candidates.is_empty() {
            return false;
        }

        let destination = entry.destination_hash.to_ascii_lowercase();
        let selected_hash = self
            .selected_directory_entry()
            .map(|entry| entry.destination_hash.to_ascii_lowercase());
        let preferred_hash = self
            .settings
            .preferred_propagation_node_hash
            .as_deref()
            .map(|hash| hash.trim().to_ascii_lowercase())
            .filter(|hash| !hash.is_empty());
        let active_peer_hash = Some(
            self.active_conversation()
                .peer_hash
                .trim()
                .to_ascii_lowercase(),
        )
        .filter(|hash| !hash.is_empty());
        let relevant_hashes = [selected_hash, preferred_hash, active_peer_hash]
            .into_iter()
            .flatten()
            .collect::<BTreeSet<_>>();
        let relevant = relevant_hashes.contains(&destination)
            || candidates.iter().any(|hash| relevant_hashes.contains(hash))
            || entry.saved
            || entry.trusted;

        if !relevant {
            return false;
        }

        let Ok(handle) = tokio::runtime::Handle::try_current() else {
            self.logs.push_with_source(
                LogSeverity::Debug,
                LogSource::Runtime,
                format!(
                    "announce path warm deferred destination={} reason=no active Tokio runtime",
                    entry.destination_hash
                ),
            );
            return false;
        };

        let runtime = self.runtime.clone();
        let tx = self.event_tx.clone();
        let destination_hash = entry.destination_hash.clone();
        let kind = announce_kind_label(&entry.kind).to_string();
        self.monitoring_state.outbound_path_warmups = self
            .monitoring_state
            .outbound_path_warmups
            .saturating_add(candidates.len() as u64);
        self.monitoring_state.note_outbound(
            candidates
                .iter()
                .map(|candidate| 96 + candidate.len() as u64)
                .sum(),
        );
        handle.spawn(async move {
            let candidates = candidates.into_iter().take(3).collect::<Vec<_>>();
            if let Err(error) = runtime.warm_paths(&candidates, 2, 15).await {
                let summary = format!(
                    "announce path warm failed destination={destination_hash} kind={kind}: {error}"
                );
                let _ = tx
                    .send(InternalAppEvent::LogWithSource {
                        severity: LogSeverity::Warn,
                        source: LogSource::Runtime,
                        line: summary,
                    })
                    .await;
            }
        });
        true
    }

    fn handle_runtime_bus_event(&mut self, event: crate::runtime::RuntimeBusEvent) -> bool {
        self.monitoring_state.note_runtime_event();
        for facade_event in network_doctor_facade_events_from_runtime_bus_event(&event) {
            self.network_doctor_state.record_facade_event(&facade_event);
        }
        match event {
            crate::runtime::RuntimeBusEvent::StatusChanged(status) => {
                self.runtime_status = status.clone();
                self.status.backend = format!("backend: {:?}", status.backend).to_lowercase();
                self.status.task = status.message.clone();
                self.logs.push_with_source(
                    LogSeverity::Info,
                    LogSource::Runtime,
                    format!(
                        "runtime status changed backend={:?} connected={} message={}",
                        status.backend, status.connected, status.message
                    ),
                );
                true
            }
            crate::runtime::RuntimeBusEvent::Announce(announce) => {
                self.monitoring_state.announces_received =
                    self.monitoring_state.announces_received.saturating_add(1);
                self.monitoring_state.estimated_inbound_bytes = self
                    .monitoring_state
                    .estimated_inbound_bytes
                    .saturating_add(estimated_announce_bytes(&announce));
                let announce_for_probe_summary = announce.clone();
                let entry = self.directory_service.ingest_announce_with_metadata(
                    announce.destination_hash,
                    announce.display_name,
                    announce.kind,
                    announce.associated_hash,
                    announce.node_associated_hash,
                    announce.lxmf_stamp_cost,
                );
                match entry {
                    Ok(entry) => {
                        if self.workspace.active_section == WorkspaceSection::Directory {
                            let selected_hash = self
                                .directory_state
                                .selected
                                .and_then(|index| self.directory_state.entries.get(index))
                                .map(|entry| entry.destination_hash.clone());
                            self.directory_state.entries = self.directory_service.list_entries();
                            if let Some(selected_hash) = selected_hash {
                                self.directory_state.selected =
                                    self.directory_state.entries.iter().position(|entry| {
                                        entry.destination_hash == selected_hash
                                            && directory_entry_matches_panel_view(
                                                entry,
                                                &self.directory_state.active_kind,
                                                &self.directory_state.active_scope,
                                                &self.directory_state.filter,
                                            )
                                    });
                                if self.directory_state.selected.is_some() {
                                    self.remember_selected_directory_entry();
                                }
                            }
                        }
                        self.refresh_browser_probe_summaries_from_announce(
                            &announce_for_probe_summary,
                        );
                        self.warm_paths_for_relevant_announce(&entry);
                        if self
                            .runtime_announce_matches_active_lxmf_peer(&announce_for_probe_summary)
                            && self.inspect_active_lxmf_peer_quiet()
                        {
                            self.logs.push_with_source(
                                LogSeverity::Debug,
                                LogSource::Runtime,
                                format!(
                                    "queued LXMF peer inspection after {:?} announce for {}",
                                    announce_for_probe_summary.kind,
                                    announce_for_probe_summary.destination_hash
                                ),
                            );
                        }
                        true
                    }
                    Err(error) => {
                        self.status.task = error.to_string();
                        false
                    }
                }
            }
            crate::runtime::RuntimeBusEvent::MessageReceived(message) => {
                self.monitoring_state.inbound_messages =
                    self.monitoring_state.inbound_messages.saturating_add(1);
                self.monitoring_state.estimated_inbound_bytes = self
                    .monitoring_state
                    .estimated_inbound_bytes
                    .saturating_add(estimated_message_bytes(&message));
                match self.messaging_service.ingest_runtime_message(message) {
                    Ok(stored) => {
                        self.merge_message_into_conversation(stored);
                        true
                    }
                    Err(error) => {
                        self.status.task = format!("message ingest failed: {error}");
                        false
                    }
                }
            }
            crate::runtime::RuntimeBusEvent::MessageDeliveryUpdated(status) => {
                self.monitoring_state.outbound_status_updates = self
                    .monitoring_state
                    .outbound_status_updates
                    .saturating_add(1);
                let stored = self
                    .messaging_service
                    .update_outbound_status(&status)
                    .unwrap_or(false);
                let visible = self.apply_outbound_status_to_visible_conversations(&status);
                if stored || visible {
                    if status.failed {
                        self.logs.push_with_source(
                            LogSeverity::Warn,
                            LogSource::Runtime,
                            format!(
                                "outbound message status failed peer={} message_id={} state={:?} evidence={}",
                                status.peer_hash,
                                status.message_id.as_deref().unwrap_or("none"),
                                status.state,
                                status.evidence.as_deref().unwrap_or("none")
                            ),
                        );
                    }
                    return true;
                }
                self.defer_outbound_status(status)
            }
            crate::runtime::RuntimeBusEvent::LxmfDeliveryEvidence(evidence) => {
                self.monitoring_state.lxmf_evidence_updates = self
                    .monitoring_state
                    .lxmf_evidence_updates
                    .saturating_add(1);
                let stored = self
                    .messaging_service
                    .apply_lxmf_delivery_evidence(&evidence)
                    .unwrap_or(false);
                let visible = self.apply_lxmf_delivery_evidence_to_visible_conversations(&evidence);
                if stored || visible {
                    self.maybe_auto_sync_after_propagation_acceptance(&evidence);
                    if lxmf_delivery_evidence_is_failure(evidence.kind) {
                        self.logs.push_with_source(
                            LogSeverity::Warn,
                            LogSource::Runtime,
                            format!(
                                "LXMF delivery evidence failed peer={} message_id={} kind={:?} detail={}",
                                evidence.peer_hash,
                                evidence.message_id.as_deref().unwrap_or("none"),
                                evidence.kind,
                                evidence.detail.as_deref().unwrap_or("none")
                            ),
                        );
                    }
                    return true;
                }
                self.defer_lxmf_delivery_evidence(evidence)
            }
            crate::runtime::RuntimeBusEvent::PropagationStatus(status) => {
                self.status.propagation = if status.selected {
                    let destination = status
                        .destination_hash
                        .as_deref()
                        .map(compact_hash)
                        .unwrap_or_else(|| "selected".into());
                    format!(
                        "propagation: {destination} {}:{}",
                        status.link_state, status.transfer_state
                    )
                } else {
                    "propagation: none".into()
                };
                true
            }
            crate::runtime::RuntimeBusEvent::PropagationSync(event) => {
                self.monitoring_state.propagation_sync_events = self
                    .monitoring_state
                    .propagation_sync_events
                    .saturating_add(1);
                if self.propagation_sync_pending.is_some() {
                    self.status.task = format!(
                        "propagation sync {:?}/{:?}: {}",
                        event.stage, event.status, event.detail
                    );
                }
                self.logs.push_with_source(
                    LogSeverity::Debug,
                    LogSource::Messaging,
                    format!(
                        "propagation sync stage={:?} status={:?} detail={} counts={:?}",
                        event.stage, event.status, event.detail, event.counts
                    ),
                );
                true
            }
            crate::runtime::RuntimeBusEvent::InterfaceStats(stats) => {
                self.monitoring_state.last_interface_stats = Some(stats.clone());
                self.status.task = if stats.available {
                    format!("interfaces: {}", stats.interfaces.len())
                } else {
                    stats
                        .reason
                        .unwrap_or_else(|| "interfaces unavailable".into())
                };
                true
            }
            crate::runtime::RuntimeBusEvent::PathUpdated(path) => {
                self.monitoring_state.path_updates_received = self
                    .monitoring_state
                    .path_updates_received
                    .saturating_add(1);
                self.status.destination = format!(
                    "destination: {} {}",
                    path.destination_hash,
                    if path.known { "known" } else { "unknown" }
                );
                for tab in &mut self.workspace.browser_tabs {
                    let Some(summary) = &mut tab.probe_summary else {
                        continue;
                    };
                    if summary.ready_to_request || !summary.url.contains(&path.destination_hash) {
                        continue;
                    }
                    summary.status = if path.known {
                        "path known".into()
                    } else {
                        "path unknown".into()
                    };
                    summary.detail = match path.hops {
                        Some(hops) if path.known => {
                            format!("path update received ({hops} hops); press Retry/Open now or run N to re-check identity/path readiness")
                        }
                        _ if path.known => {
                            "path update received; press Retry/Open now or run N to re-check identity/path readiness".into()
                        }
                        _ => "path update reported destination unknown".into(),
                    };
                }
                let mut path_ready_events = Vec::new();
                if path.known {
                    for index in 0..self.workspace.browser_tabs.len() {
                        let matches_destination = self.workspace.browser_tabs[index]
                            .retry_state
                            .as_ref()
                            .is_some_and(|state| {
                                state
                                    .destination_hash
                                    .eq_ignore_ascii_case(&path.destination_hash)
                            });
                        if matches_destination {
                            let Some((retry_target, retry_requested_epoch_ms)) =
                                self.workspace.browser_tabs[index]
                                    .retry_state
                                    .as_ref()
                                    .map(|state| (state.target.clone(), state.requested_epoch_ms))
                            else {
                                continue;
                            };
                            let startup_retry = self.workspace.browser_tabs[index]
                                .retry_state
                                .as_ref()
                                .is_some_and(|state| state.reason.contains("startup path request"));
                            let auto_load_retry = self.workspace.browser_tabs[index]
                                .retry_state
                                .as_ref()
                                .is_some_and(|state| {
                                    state.reason.contains("auto-load when path is known")
                                });
                            if startup_retry {
                                let reason = match path.hops {
                                    Some(hops) => {
                                        format!("startup path request passed ({hops} hops); waiting briefly before restored page load")
                                    }
                                    None => {
                                        "startup path request passed; waiting briefly before restored page load"
                                            .into()
                                    }
                                };
                                self.mark_browser_retry_ready_after(index, reason, 2_000);
                                path_ready_events.push((
                                    path.destination_hash.to_ascii_lowercase(),
                                    2_000,
                                    retry_target,
                                    retry_requested_epoch_ms,
                                ));
                            } else if auto_load_retry {
                                let reason = match path.hops {
                                    Some(hops) => {
                                        format!("browser path request passed ({hops} hops); waiting briefly before page load")
                                    }
                                    None => {
                                        "browser path request passed; waiting briefly before page load"
                                            .into()
                                    }
                                };
                                self.mark_browser_retry_ready_after(index, reason, 2_000);
                                path_ready_events.push((
                                    path.destination_hash.to_ascii_lowercase(),
                                    2_000,
                                    retry_target,
                                    retry_requested_epoch_ms,
                                ));
                            } else {
                                let reason = match path.hops {
                                    Some(hops) => {
                                        format!("path discovery reports a known route ({hops} hops); retry now")
                                    }
                                    None => {
                                        "path discovery reports a known route; retry now".into()
                                    }
                                };
                                self.mark_browser_retry_ready(index, reason);
                            }
                        }
                    }
                }
                if !path_ready_events.is_empty() {
                    for (destination, delay_ms, target, requested_epoch_ms) in path_ready_events {
                        self.schedule_browser_path_ready_event(
                            destination,
                            delay_ms,
                            Some(target),
                            Some(requested_epoch_ms),
                        );
                    }
                }
                if self.runtime_path_matches_active_lxmf_peer(&path)
                    && self.inspect_active_lxmf_peer_quiet()
                {
                    self.logs.push_with_source(
                        LogSeverity::Debug,
                        LogSource::Runtime,
                        format!(
                            "queued LXMF peer inspection after path update for {}",
                            path.destination_hash
                        ),
                    );
                }
                true
            }
            crate::runtime::RuntimeBusEvent::PageFetchProbe(report) => {
                self.monitoring_state.page_fetch_probes =
                    self.monitoring_state.page_fetch_probes.saturating_add(1);
                let successful_probe = report.steps.iter().all(|step| step.ok);
                if !successful_probe {
                    self.status.task = format!(
                        "page probe: {} step(s), ready={}",
                        report.steps.len(),
                        report.ready_to_request
                    );
                    self.logs.push_with_source(
                        LogSeverity::Warn,
                        LogSource::Runtime,
                        format!("page fetch probe for {}: {:?}", report.url, report.steps),
                    );
                }
                for (index, step) in report.steps.iter().enumerate() {
                    if successful_probe && step.ok {
                        continue;
                    }
                    self.logs.push_with_source(
                        if step.ok {
                            LogSeverity::Debug
                        } else {
                            LogSeverity::Warn
                        },
                        LogSource::Runtime,
                        format_page_probe_trace_log_line("runtime", index, step),
                    );
                }
                true
            }
            crate::runtime::RuntimeBusEvent::OmenChatLinkData(data) => {
                let link_id = data.link_id;
                let frame_bytes = data.frame_bytes.len();
                self.monitoring_state.estimated_inbound_bytes = self
                    .monitoring_state
                    .estimated_inbound_bytes
                    .saturating_add(frame_bytes as u64);
                #[cfg(any(feature = "chat-client-rns", feature = "chat-client-rns-clean"))]
                if self.pending_omenchat_link_data.len() >= OMENCHAT_STAGED_FRAME_MAX_ITEMS
                    || self
                        .pending_omenchat_link_data_bytes
                        .saturating_add(frame_bytes)
                        > OMENCHAT_STAGED_FRAME_MAX_BYTES
                {
                    self.rejected_omenchat_staged_frames =
                        self.rejected_omenchat_staged_frames.saturating_add(1);
                    self.logs.push_with_source(
                        LogSeverity::Warn,
                        LogSource::Runtime,
                        format!(
                            "OMENchat link frame staging budget exceeded link_id={} bytes={frame_bytes}",
                            hex_lower(&link_id)
                        ),
                    );
                    return true;
                } else {
                    self.pending_omenchat_link_data_bytes = self
                        .pending_omenchat_link_data_bytes
                        .saturating_add(frame_bytes);
                    self.pending_omenchat_link_data.push(data);
                }
                self.logs.push_with_source(
                    LogSeverity::Debug,
                    LogSource::Runtime,
                    format!(
                        "OMENchat link frame received link_id={} bytes={}",
                        hex_lower(&link_id),
                        frame_bytes
                    ),
                );
                true
            }
            crate::runtime::RuntimeBusEvent::OmenChatLinkClosed(data) => {
                let link_id = data.link_id;
                #[cfg(any(feature = "chat-client-rns", feature = "chat-client-rns-clean"))]
                let reason_bytes = data.reason.as_ref().map_or(0, String::len);
                let reason = data.reason.clone();
                #[cfg(any(feature = "chat-client-rns", feature = "chat-client-rns-clean"))]
                if self.pending_omenchat_link_closed.len() >= OMENCHAT_STAGED_CLOSE_MAX_ITEMS
                    || self
                        .pending_omenchat_link_closed_bytes
                        .saturating_add(reason_bytes)
                        > OMENCHAT_STAGED_CLOSE_MAX_BYTES
                {
                    self.rejected_omenchat_staged_closes =
                        self.rejected_omenchat_staged_closes.saturating_add(1);
                    self.logs.push_with_source(
                        LogSeverity::Warn,
                        LogSource::Runtime,
                        format!(
                            "OMENchat link-close staging item budget exceeded link_id={}",
                            hex_lower(&link_id)
                        ),
                    );
                    return true;
                } else {
                    self.pending_omenchat_link_closed_bytes = self
                        .pending_omenchat_link_closed_bytes
                        .saturating_add(reason_bytes);
                    self.pending_omenchat_link_closed.push(data);
                }
                let benign_close = reason.as_deref().is_some_and(|reason| {
                    let reason = reason.trim();
                    reason.eq_ignore_ascii_case("timeout")
                        || reason.eq_ignore_ascii_case("destinationclosed")
                        || reason.eq_ignore_ascii_case("initiatorclosed")
                });
                self.logs.push_with_source(
                    if benign_close {
                        LogSeverity::Debug
                    } else {
                        LogSeverity::Info
                    },
                    LogSource::Runtime,
                    format!(
                        "OMENchat link closed link_id={} reason={}",
                        hex_lower(&link_id),
                        reason.as_deref().unwrap_or("unknown")
                    ),
                );
                true
            }
            crate::runtime::RuntimeBusEvent::OmenChatResourceData(data) => {
                let link_id = data.link_id;
                let data_bytes = data.data.len();
                let metadata_bytes = data.metadata.as_ref().map_or(0, Vec::len);
                #[cfg(any(feature = "chat-client-rns", feature = "chat-client-rns-clean"))]
                let retained_bytes = data_bytes.saturating_add(metadata_bytes);
                self.monitoring_state.estimated_inbound_bytes = self
                    .monitoring_state
                    .estimated_inbound_bytes
                    .saturating_add(data_bytes as u64);
                #[cfg(any(feature = "chat-client-rns", feature = "chat-client-rns-clean"))]
                if self.pending_omenchat_resource_data.len() >= OMENCHAT_STAGED_RESOURCE_MAX_ITEMS
                    || self
                        .pending_omenchat_resource_data_bytes
                        .saturating_add(retained_bytes)
                        > OMENCHAT_STAGED_RESOURCE_MAX_BYTES
                {
                    self.rejected_omenchat_staged_resources =
                        self.rejected_omenchat_staged_resources.saturating_add(1);
                    self.logs.push_with_source(
                        LogSeverity::Warn,
                        LogSource::Runtime,
                        format!(
                            "OMENchat resource staging budget exceeded link_id={} bytes={data_bytes} metadata={metadata_bytes}",
                            hex_lower(&link_id)
                        ),
                    );
                    return true;
                } else {
                    self.pending_omenchat_resource_data_bytes = self
                        .pending_omenchat_resource_data_bytes
                        .saturating_add(retained_bytes);
                    self.pending_omenchat_resource_data.push(data);
                }
                self.logs.push_with_source(
                    LogSeverity::Debug,
                    LogSource::Runtime,
                    format!(
                        "OMENchat resource received link_id={} bytes={} metadata={}",
                        hex_lower(&link_id),
                        data_bytes,
                        metadata_bytes
                    ),
                );
                true
            }
            crate::runtime::RuntimeBusEvent::ResourceProgress(progress) => {
                self.status.task = match progress.total {
                    Some(total) => format!(
                        "resource {} {}/{} bytes",
                        progress.transfer_id, progress.received, total
                    ),
                    None => format!(
                        "resource {} {} bytes",
                        progress.transfer_id, progress.received
                    ),
                };
                self.logs.push_with_source(
                    LogSeverity::Debug,
                    LogSource::Runtime,
                    self.status.task.clone(),
                );
                true
            }
            crate::runtime::RuntimeBusEvent::ResourceLifecycle(lifecycle) => {
                let source = lifecycle.source.as_deref().unwrap_or("resource");
                let reason = lifecycle.reason.as_deref().unwrap_or("no detail");
                self.status.task = match lifecycle.state {
                    crate::runtime::ResourceLifecycleState::Offered => format!(
                        "{source} offered {} size={}",
                        lifecycle.transfer_id,
                        lifecycle
                            .bytes
                            .map(|bytes| format!("{bytes} bytes"))
                            .unwrap_or_else(|| "unknown".into())
                    ),
                    crate::runtime::ResourceLifecycleState::Complete => format!(
                        "{source} complete {} size={}",
                        lifecycle.transfer_id,
                        lifecycle
                            .bytes
                            .map(|bytes| format!("{bytes} bytes"))
                            .unwrap_or_else(|| "unknown".into())
                    ),
                    crate::runtime::ResourceLifecycleState::Failed => {
                        self.monitoring_state.runtime_errors =
                            self.monitoring_state.runtime_errors.saturating_add(1);
                        format!("{source} failed {}: {reason}", lifecycle.transfer_id)
                    }
                    crate::runtime::ResourceLifecycleState::Cancelled => {
                        format!("{source} cancelled {}: {reason}", lifecycle.transfer_id)
                    }
                };
                self.logs.push_with_source(
                    match lifecycle.state {
                        crate::runtime::ResourceLifecycleState::Failed => LogSeverity::Warn,
                        _ => LogSeverity::Debug,
                    },
                    LogSource::Runtime,
                    self.status.task.clone(),
                );
                true
            }
            crate::runtime::RuntimeBusEvent::Debug(message) => {
                self.monitoring_state.runtime_debug_events =
                    self.monitoring_state.runtime_debug_events.saturating_add(1);
                if !is_noisy_runtime_debug_message(&message) {
                    self.logs
                        .push_with_source(LogSeverity::Debug, LogSource::Runtime, message);
                }
                true
            }
            crate::runtime::RuntimeBusEvent::Error(message) => {
                self.monitoring_state.runtime_errors =
                    self.monitoring_state.runtime_errors.saturating_add(1);
                self.status.task = message.clone();
                self.logs
                    .push_with_source(LogSeverity::Error, LogSource::Runtime, message);
                true
            }
        }
    }

    pub fn apply_diagnostics_task_result(&mut self, result: DiagnosticsTaskResult) -> bool {
        match result {
            DiagnosticsTaskResult::ExportBundle {
                generation,
                snapshot,
            } => {
                if self.diagnostics_export_pending != Some(generation) {
                    return false;
                }
                self.diagnostics_export_pending = None;
                match snapshot {
                    Ok(snapshot) => self.write_diagnostics_bundle_export(Some(&snapshot)),
                    Err(error) => {
                        self.status.task =
                            format!("failed to collect diagnostics snapshot: {error}");
                        self.logs
                            .lines
                            .push(format!("failed to collect diagnostics snapshot: {error}"));
                        false
                    }
                }
            }
            DiagnosticsTaskResult::LiveInteropReport {
                generation,
                export,
                report,
            } => match report {
                Ok(report) => {
                    if export {
                        self.write_live_interop_report_export(generation, &report)
                    } else {
                        self.preview_live_interop_report_value(generation, &report)
                    }
                }
                Err(error) => {
                    self.status.task = format!("failed to collect live interop report: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Diagnostics,
                        format!("failed to collect live interop report generation {generation}: {error}"),
                    );
                    false
                }
            },
            DiagnosticsTaskResult::NativeNetworkSmokeTest {
                generation,
                execute_live_probe,
                execute_live_fetch,
                report,
            } => match report {
                Ok(report) => {
                    let rendered = self.preview_json_diagnostics_value(&report, |line_count| {
                        format!(
                            "native-network smoke test generation {generation} complete ({line_count} lines, live={execute_live_probe}, fetch={execute_live_fetch})"
                        )
                    });
                    if rendered {
                        self.logs.push_with_source(
                            LogSeverity::Info,
                            LogSource::Diagnostics,
                            format!(
                                "native-network smoke test generation {generation} complete live={execute_live_probe} fetch={execute_live_fetch}"
                            ),
                        );
                    }
                    rendered
                }
                Err(error) => {
                    self.status.task = format!("failed to run native-network smoke test: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Diagnostics,
                        format!(
                            "failed to run native-network smoke test generation {generation}: {error}"
                        ),
                    );
                    false
                }
            },
            DiagnosticsTaskResult::NativePreflight { generation, report } => match report {
                Ok(report) => {
                    let rendered = self.preview_json_diagnostics_value(&report, |line_count| {
                        format!(
                            "native preflight generation {generation} complete ({line_count} lines)"
                        )
                    });
                    if rendered {
                        self.logs.push_with_source(
                            LogSeverity::Info,
                            LogSource::Diagnostics,
                            format!("native preflight generation {generation} complete"),
                        );
                    }
                    rendered
                }
                Err(error) => {
                    self.status.task = format!("failed to run native preflight: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Diagnostics,
                        format!("failed to run native preflight generation {generation}: {error}"),
                    );
                    false
                }
            },
            DiagnosticsTaskResult::NativeLxmfSmokeSend {
                generation,
                peer_hash,
                report,
            } => match report {
                Ok(report) => {
                    let rendered = self.preview_json_diagnostics_value(&report, |line_count| {
                        format!(
                            "native LXMF smoke send generation {generation} complete ({line_count} lines, peer={peer_hash})"
                        )
                    });
                    if rendered {
                        self.logs.push_with_source(
                            LogSeverity::Info,
                            LogSource::Diagnostics,
                            format!(
                                "native LXMF smoke send generation {generation} complete peer={peer_hash}"
                            ),
                        );
                    }
                    rendered
                }
                Err(error) => {
                    self.status.task = format!("failed to run native LXMF smoke send: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Diagnostics,
                        format!(
                            "failed to run native LXMF smoke send generation {generation} peer={peer_hash}: {error}"
                        ),
                    );
                    false
                }
            },
            DiagnosticsTaskResult::NativeLxmfLiveInterop {
                generation,
                peer_hash,
                wait_secs,
                report,
            } => match report {
                Ok(report) => {
                    let rendered = self.preview_json_diagnostics_value(&report, |line_count| {
                        format!(
                            "native LXMF live interop generation {generation} complete ({line_count} lines, wait={wait_secs}s)"
                        )
                    });
                    if rendered {
                        self.logs.push_with_source(
                            LogSeverity::Info,
                            LogSource::Diagnostics,
                            format!(
                                "native LXMF live interop generation {generation} complete peer={}",
                                peer_hash.as_deref().unwrap_or("none")
                            ),
                        );
                    }
                    rendered
                }
                Err(error) => {
                    self.status.task = format!("failed to run native LXMF live interop: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Diagnostics,
                        format!(
                            "failed to run native LXMF live interop generation {generation} peer={}: {error}",
                            peer_hash.as_deref().unwrap_or("none")
                        ),
                    );
                    false
                }
            },
            DiagnosticsTaskResult::NativeLxmfPropagationDiagnostics { generation, report } => {
                match report {
                    Ok(report) => {
                        let blocker = report
                            .get("blocker")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or("unknown");
                        let rendered =
                            self.preview_json_diagnostics_value(&report, |line_count| {
                                format!(
                                    "native LXMF propagation diagnostics generation {generation} complete ({line_count} lines)"
                                )
                            });
                        if rendered {
                            self.logs.push_with_source(
                                LogSeverity::Info,
                                LogSource::Diagnostics,
                                format!(
                                    "native LXMF propagation diagnostics generation {generation} complete blocker={blocker}"
                                ),
                            );
                        }
                        rendered
                    }
                    Err(error) => {
                        self.status.task =
                            format!("failed to run native LXMF propagation diagnostics: {error}");
                        self.logs.push_with_source(
                            LogSeverity::Error,
                            LogSource::Diagnostics,
                            format!(
                                "failed to run native LXMF propagation diagnostics generation {generation}: {error}"
                            ),
                        );
                        false
                    }
                }
            }
            DiagnosticsTaskResult::PathDiscoveryDiagnostics {
                tab_id,
                generation,
                report,
            } => match report {
                Ok(report) => {
                    self.apply_browser_path_discovery_summary(tab_id, &report);
                    let rendered = self.preview_json_diagnostics_value(&report, |line_count| {
                        format!(
                            "path discovery diagnostics generation {generation} complete ({line_count} lines)"
                        )
                    });
                    if rendered {
                        self.logs.push_with_source(
                            LogSeverity::Info,
                            LogSource::Diagnostics,
                            format!("path discovery diagnostics generation {generation} complete"),
                        );
                    }
                    rendered
                }
                Err(error) => {
                    self.status.task = format!("failed to run path discovery diagnostics: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Diagnostics,
                        format!(
                            "failed to run path discovery diagnostics generation {generation}: {error}"
                        ),
                    );
                    false
                }
            },
            DiagnosticsTaskResult::BrowserPathWarmup {
                tab_id,
                generation,
                report,
            } => {
                let Some(index) = self.browser_tab_index(tab_id) else {
                    return false;
                };
                if self.workspace.browser_tabs[index]
                    .path_warmup
                    .as_ref()
                    .map(|warmup| warmup.generation)
                    != Some(generation)
                {
                    return false;
                }
                self.workspace.browser_tabs[index].path_warmup = None;
                match report {
                    Ok(report) => {
                        self.apply_browser_path_discovery_summary(tab_id, &report);
                        let status = report
                            .get("path_warmup")
                            .and_then(|value| value.get("status"))
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or("unknown");
                        self.status.task =
                            format!("browser path request complete: status={status}");
                        self.logs.push_with_source(
                            LogSeverity::Info,
                            LogSource::Diagnostics,
                            format!(
                                "browser path request generation {generation} complete status={status}"
                            ),
                        );
                        true
                    }
                    Err(error) => {
                        self.status.task = format!("browser path request failed: {error}");
                        self.logs.push_with_source(
                            LogSeverity::Error,
                            LogSource::Diagnostics,
                            format!("browser path request generation {generation} failed: {error}"),
                        );
                        false
                    }
                }
            }
            DiagnosticsTaskResult::KnownDestinationsPreload {
                tab_id,
                generation,
                report,
            } => match report {
                Ok(report) => {
                    self.apply_browser_path_discovery_summary(tab_id, &report);
                    let rendered = self.preview_json_diagnostics_value(&report, |line_count| {
                        format!(
                            "known_destinations preload generation {generation} complete ({line_count} lines)"
                        )
                    });
                    if rendered {
                        let loaded = report
                            .get("known_destinations_preload")
                            .and_then(|value| value.get("loaded"))
                            .and_then(serde_json::Value::as_u64)
                            .unwrap_or(0);
                        self.logs.push_with_source(
                            LogSeverity::Info,
                            LogSource::Diagnostics,
                            format!(
                                "known_destinations preload generation {generation} complete loaded={loaded}"
                            ),
                        );
                    }
                    rendered
                }
                Err(error) => {
                    self.status.task = format!("known_destinations preload failed: {error}");
                    self.logs.push_with_source(
                        LogSeverity::Error,
                        LogSource::Diagnostics,
                        format!(
                            "known_destinations preload generation {generation} failed: {error}"
                        ),
                    );
                    false
                }
            },
            DiagnosticsTaskResult::PageFetchProbe {
                tab_id,
                generation,
                execute_request,
                show_diagnostics,
                report,
            } => {
                let mode = if execute_request { "live" } else { "dry-run" };
                match report {
                    Ok(report) => match serde_json::to_string_pretty(&report) {
                        Ok(content) => {
                            let line_count = content.lines().count();
                            self.apply_browser_probe_summary(
                                tab_id,
                                BrowserProbeSummary::from_report(&report, mode),
                            );
                            self.apply_browser_probe_report_retry_state(tab_id, &report);
                            self.diagnostics_state.preview_lines =
                                content.lines().map(ToOwned::to_owned).collect();
                            self.diagnostics_state.preview_scroll = 0;
                            if show_diagnostics {
                                self.workspace.active_section = WorkspaceSection::Diagnostics;
                            }
                            self.status.task = format!(
                                "{mode} page probe complete: {} step(s), ready={}",
                                report.steps.len(),
                                report.ready_to_request
                            );
                            self.logs.push_with_source(
                                LogSeverity::Info,
                                LogSource::Diagnostics,
                                format!(
                                    "{mode} page probe generation {generation} rendered ({line_count} lines)"
                                ),
                            );
                            for (index, step) in report.steps.iter().enumerate() {
                                self.logs.push_with_source(
                                    if step.ok {
                                        LogSeverity::Debug
                                    } else {
                                        LogSeverity::Warn
                                    },
                                    LogSource::Diagnostics,
                                    format_page_probe_trace_log_line(mode, index, step),
                                );
                            }
                            true
                        }
                        Err(error) => {
                            self.status.task =
                                format!("failed to render {mode} page probe: {error}");
                            self.logs.push_with_source(
                                LogSeverity::Error,
                                LogSource::Diagnostics,
                                format!("failed to render {mode} page probe: {error}"),
                            );
                            false
                        }
                    },
                    Err(error) => {
                        self.apply_browser_probe_summary(
                            tab_id,
                            BrowserProbeSummary {
                                url: self
                                    .browser_tab_index(tab_id)
                                    .map(|index| {
                                        self.workspace.browser_tabs[index].address_input.clone()
                                    })
                                    .unwrap_or_default(),
                                mode: mode.into(),
                                ready_to_request: false,
                                status: "failed".into(),
                                detail: error.clone(),
                            },
                        );
                        self.status.task = format!("{mode} page probe failed: {error}");
                        self.logs.push_with_source(
                            LogSeverity::Error,
                            LogSource::Diagnostics,
                            format!("{mode} page probe failed: {error}"),
                        );
                        false
                    }
                }
            }
        }
    }

    pub fn apply_message_task_result(&mut self, result: MessageTaskResult) -> bool {
        match result {
            MessageTaskResult::Sent {
                conversation_id,
                generation,
                message,
            } => {
                let Some(index) = self.conversation_index(conversation_id) else {
                    return false;
                };
                if !self.message_result_matches_pending(index, generation) {
                    return false;
                }
                let conversation = &mut self.workspace.conversations[index];
                conversation.pending_send = None;
                remove_pending_send_placeholder(conversation, generation);
                let propagation_state = message.fields.get("native_lxmf_state").map(String::as_str);
                let propagation_transfer = message
                    .fields
                    .get("native_lxmf_propagation_transfer_state")
                    .map(String::as_str);
                let queued_for_propagation =
                    propagation_state.is_some_and(|state| state == "queued_for_propagation");
                let accepted_by_propagation_node = matches!(
                    propagation_state,
                    Some("propagation_transfer_completed" | "propagation_node_accepted")
                ) || matches!(
                    propagation_transfer,
                    Some("link_packet_sent" | "resource_advertised" | "resource_completed")
                );
                let propagation_in_progress =
                    matches!(propagation_transfer, Some("resource_progress"));
                let propagation_failed = matches!(
                    propagation_transfer,
                    Some(
                        "link_packet_failed"
                            | "resource_failed"
                            | "resource_advertise_failed"
                            | "resource_timeout"
                            | "router_timeout"
                            | "link_timeout"
                    )
                ) || propagation_state
                    .is_some_and(|state| state == "failed");
                let propagated_send = queued_for_propagation
                    || accepted_by_propagation_node
                    || propagation_in_progress
                    || propagation_failed;
                let transfer_state = propagation_transfer.unwrap_or("router_deferred");
                let state = propagation_state.unwrap_or_default();
                let native_submitted =
                    message
                        .fields
                        .get("native_lxmf_state")
                        .is_some_and(|state| {
                            state == "submitted_to_rns_net" || state == "submitted_unconfirmed"
                        });
                conversation.push_message(message.clone());
                self.status.task = if message.delivered {
                    if message.fields.contains_key("native_lxmf_state") {
                        "LXMF router delivered callback received; no retry needed".into()
                    } else {
                        "message delivered".into()
                    }
                } else if message.failed {
                    "message failed".into()
                } else if propagated_send {
                    match transfer_state {
                        "link_packet_sent" => {
                            "message accepted by propagation node; peer delivery unconfirmed"
                        }
                        "resource_completed" => {
                            "message transferred to propagation node; peer delivery unconfirmed"
                        }
                        "resource_advertised" => {
                            "message accepted by propagation node; peer delivery unconfirmed"
                        }
                        "resource_progress" => {
                            "message queued for propagation; resource transfer in progress"
                        }
                        "link_timeout" => {
                            "message queued for propagation; propagation link timed out"
                        }
                        "resource_advertise_failed" => {
                            "message queued for propagation; resource advertisement failed"
                        }
                        "resource_failed" | "resource_timeout" | "router_timeout"
                        | "link_packet_failed" => {
                            "message propagation transfer failed; retry after the blocker is fixed"
                        }
                        _ if state == "propagation_node_accepted"
                            || state == "propagation_transfer_completed" =>
                        {
                            "message accepted by propagation node; peer delivery unconfirmed"
                        }
                        _ => "message queued for propagation; native router transfer is deferred",
                    }
                    .into()
                } else if native_submitted {
                    "message submitted to RNS; waiting for LXMF delivery evidence".into()
                } else {
                    "message queued".into()
                };
                self.refresh_context_status();
                self.apply_deferred_lxmf_updates_for_message(&message);
                self.persist_ui_preferences("conversation draft");
                true
            }
            MessageTaskResult::Synced {
                generation,
                messages,
            } => {
                if self.message_sync_pending != Some(generation) {
                    return false;
                }
                self.message_sync_pending = None;
                let count = messages.len();
                for message in messages {
                    self.merge_message_into_conversation(message);
                }
                self.status.task = format!("synced {count} messages");
                self.refresh_context_status();
                self.persist_ui_preferences("conversation tabs");
                true
            }
            MessageTaskResult::PropagationSynced {
                generation,
                report,
                messages,
            } => {
                if self.propagation_sync_pending != Some(generation) {
                    return false;
                }
                self.propagation_sync_pending = None;
                let mut messages = messages;
                messages.extend(messages_from_propagation_sync_report(&report));
                deduplicate_message_summaries(&mut messages);
                let message_count = messages.len();
                for message in messages {
                    match self.messaging_service.ingest_runtime_message(message) {
                        Ok(stored) => self.merge_message_into_conversation(stored),
                        Err(error) => {
                            self.logs.push_with_source(
                                LogSeverity::Warn,
                                LogSource::Messaging,
                                format!(
                                    "failed to persist propagation sync message before display: {error}"
                                ),
                            );
                        }
                    }
                }
                let sync_evidence = lxmf_delivery_evidence_from_propagation_sync_report(&report);
                let sync_evidence_count = sync_evidence.len();
                for evidence in sync_evidence {
                    let stored = self
                        .messaging_service
                        .apply_lxmf_delivery_evidence(&evidence)
                        .unwrap_or(false);
                    let visible =
                        self.apply_lxmf_delivery_evidence_to_visible_conversations(&evidence);
                    if !(stored || visible) {
                        self.defer_lxmf_delivery_evidence(evidence);
                    }
                }
                let sync_ok = report
                    .get("sync")
                    .and_then(|sync| sync.get("ok"))
                    .and_then(serde_json::Value::as_bool)
                    .unwrap_or(false);
                let blocker = report
                    .get("blocker")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("unknown");
                let after_state = report
                    .get("after")
                    .and_then(|after| after.get("transfer_state"))
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("unknown");
                let event_count = report
                    .get("sync_events")
                    .and_then(serde_json::Value::as_array)
                    .map(Vec::len)
                    .unwrap_or(0);
                let stage_hint = propagation_sync_stage_hint(&report);
                let _ = self.set_diagnostics_preview_value(&report);
                let blocked = blocker != "no propagation blocker reported";
                self.status.task = if sync_ok && !blocked {
                    format!(
                        "propagation sync complete: state={after_state} messages={message_count} delivery_updates={sync_evidence_count} events={event_count}"
                    )
                } else {
                    format!("propagation sync blocked: {stage_hint}; {blocker}")
                };
                self.logs.push_with_source(
                    if sync_ok && !blocked {
                        LogSeverity::Info
                    } else {
                        LogSeverity::Warn
                    },
                    LogSource::Messaging,
                    format!(
                        "LXMF propagation sync result ok={sync_ok} state={after_state} stage={stage_hint} messages={message_count} delivery_updates={sync_evidence_count} events={event_count} blocker={blocker}"
                    ),
                );
                true
            }
            MessageTaskResult::PeerInspection {
                conversation_id,
                generation,
                peer_hash,
                update_status,
                result,
            } => self.apply_lxmf_peer_inspection_result(
                conversation_id,
                generation,
                peer_hash,
                update_status,
                result,
            ),
            MessageTaskResult::PeerPathRequest {
                conversation_id,
                generation,
                peer_hash,
                result,
            } => self.apply_lxmf_peer_path_request_result(
                conversation_id,
                generation,
                peer_hash,
                result,
            ),
            MessageTaskResult::Error {
                conversation_id,
                generation,
                message,
            } => {
                if let Some(conversation_id) = conversation_id {
                    let Some(index) = self.conversation_index(conversation_id) else {
                        return false;
                    };
                    if !self.message_result_matches_pending(index, generation) {
                        return false;
                    }
                    let failed =
                        self.failed_outbound_message_from_conversation(index, generation, &message);
                    self.workspace.conversations[index].pending_send = None;
                    remove_pending_send_placeholder(
                        &mut self.workspace.conversations[index],
                        generation,
                    );
                    match self.message_store.append(failed.clone()) {
                        Ok(stored) => {
                            if !message_already_present(
                                &self.workspace.conversations[index],
                                &stored,
                            ) {
                                self.workspace.conversations[index].push_message(stored);
                            }
                        }
                        Err(error) => {
                            self.logs.push_with_source(
                                LogSeverity::Error,
                                LogSource::Messaging,
                                format!("failed to store outbound send failure: {error}"),
                            );
                            if !message_already_present(
                                &self.workspace.conversations[index],
                                &failed,
                            ) {
                                self.workspace.conversations[index].push_message(failed);
                            }
                        }
                    }
                    self.logs.push_with_source(
                        LogSeverity::Warn,
                        LogSource::Messaging,
                        format!(
                            "LXMF send failed for {}: {message}",
                            self.workspace.conversations[index].peer_hash
                        ),
                    );
                } else {
                    if self.message_sync_pending != Some(generation) {
                        return false;
                    }
                    self.message_sync_pending = None;
                }
                self.status.task = format!("message send failed: {message}");
                self.persist_ui_preferences("message state");
                true
            }
        }
    }

    fn failed_outbound_message_from_conversation(
        &self,
        index: usize,
        generation: u64,
        reason: &str,
    ) -> MessageSummary {
        let conversation = &self.workspace.conversations[index];
        let transport_method = match conversation.delivery_mode {
            DeliveryMode::Direct => TransportMethod::Direct,
            DeliveryMode::Propagated => TransportMethod::Propagated,
        };
        let pending_id = pending_send_message_id(generation);
        let pending_message = conversation
            .thread
            .messages
            .iter()
            .find(|message| message.message_id.as_deref() == Some(pending_id.as_str()));
        let title = if conversation.draft_title.is_empty() {
            pending_message
                .map(|message| message.title.clone())
                .unwrap_or_default()
        } else {
            conversation.draft_title.clone()
        };
        let content = if conversation.draft_body.is_empty() {
            pending_message
                .map(|message| message.content.clone())
                .unwrap_or_default()
        } else {
            conversation.draft_body.clone()
        };
        let attachments = if conversation.attachments.is_empty() {
            pending_message
                .map(|message| message.attachments.clone())
                .unwrap_or_default()
        } else {
            conversation
                .attachments
                .iter()
                .filter_map(|path| {
                    let metadata = std::fs::metadata(path).ok()?;
                    if !metadata.is_file() {
                        return None;
                    }
                    Some(crate::messaging::AttachmentSummary {
                        name: path
                            .file_name()
                            .and_then(|name| name.to_str())
                            .unwrap_or("attachment")
                            .to_string(),
                        size: metadata.len(),
                        path: Some(path.clone()),
                    })
                })
                .collect()
        };
        MessageSummary {
            peer_hash: conversation.peer_hash.clone(),
            peer_label: conversation.peer_label.clone(),
            title,
            content,
            timestamp: current_epoch_ms() as f64 / 1_000.0,
            transport_method,
            delivered: false,
            failed: true,
            incoming: false,
            unread: false,
            message_id: Some(format!("failed-send-{generation}")),
            fields: BTreeMap::from([
                ("native_lxmf_state".into(), "failed".into()),
                ("native_lxmf_proof_state".into(), "failed".into()),
                ("native_lxmf_failure_reason".into(), reason.into()),
                (
                    "native_lxmf_retry_guidance".into(),
                    "send failed before delivery was queued; fix the blocker and retry".into(),
                ),
            ]),
            attachments,
        }
    }

    fn apply_lxmf_peer_inspection_result(
        &mut self,
        conversation_id: u64,
        generation: u64,
        peer_hash: String,
        update_status: bool,
        result: Result<DestinationInspection, String>,
    ) -> bool {
        let Some(state) = self.lxmf_peer_inspection.as_ref() else {
            return false;
        };
        if state.conversation_id != conversation_id
            || state.generation != generation
            || state.peer_hash != peer_hash
        {
            return false;
        }

        let mut next_state = state.clone();
        next_state.pending = false;
        match result {
            Ok(inspection) => {
                let status = if inspection.known_identity && inspection.has_path {
                    "ready"
                } else if inspection.known_identity {
                    "path missing"
                } else {
                    "peer key missing"
                };
                if update_status {
                    self.status.task = format!("LXMF peer inspection: {status}");
                }
                next_state.inspection = Some(inspection);
                next_state.error = None;
            }
            Err(error) => {
                if update_status {
                    self.status.task = format!("LXMF peer inspection failed: {error}");
                }
                next_state.inspection = None;
                next_state.error = Some(error);
            }
        }
        self.lxmf_peer_inspection = Some(next_state);
        true
    }

    fn apply_lxmf_peer_path_request_result(
        &mut self,
        conversation_id: u64,
        generation: u64,
        peer_hash: String,
        result: Result<bool, String>,
    ) -> bool {
        let Some(index) = self.conversation_index(conversation_id) else {
            return false;
        };
        if self.workspace.conversations[index].peer_hash.trim() != peer_hash {
            return false;
        }

        match result {
            Ok(true) => {
                self.status.task =
                    format!("LXMF peer path request queued or already known: {peer_hash}");
                self.logs.push_with_source(
                    LogSeverity::Debug,
                    LogSource::Messaging,
                    format!(
                        "LXMF peer path request generation {generation} queued or already known for {peer_hash}"
                    ),
                );
            }
            Ok(false) => {
                self.status.task = format!("LXMF peer path request not queued: {peer_hash}");
                self.logs.push_with_source(
                    LogSeverity::Warn,
                    LogSource::Messaging,
                    format!(
                        "LXMF peer path request generation {generation} not queued for {peer_hash}"
                    ),
                );
            }
            Err(error) => {
                self.status.task = format!("LXMF peer path request failed: {error}");
                self.logs.push_with_source(
                    LogSeverity::Warn,
                    LogSource::Messaging,
                    format!(
                        "LXMF peer path request generation {generation} failed for {peer_hash}: {error}"
                    ),
                );
            }
        }
        let _ = self.inspect_active_lxmf_peer_quiet();
        true
    }

    fn runtime_path_matches_active_lxmf_peer(&self, path: &crate::runtime::PathEvent) -> bool {
        let peer_hash = self.active_conversation().peer_hash.trim();
        is_16_byte_hex_hash(peer_hash) && peer_hash.eq_ignore_ascii_case(&path.destination_hash)
    }

    fn runtime_announce_matches_active_lxmf_peer(
        &self,
        announce: &crate::runtime::AnnouncePayload,
    ) -> bool {
        let peer_hash = self.active_conversation().peer_hash.trim();
        if !is_16_byte_hex_hash(peer_hash) {
            return false;
        }
        announce.kind == DirectoryKind::Peer
            && (peer_hash.eq_ignore_ascii_case(&announce.destination_hash)
                || announce
                    .associated_hash
                    .as_deref()
                    .is_some_and(|hash| peer_hash.eq_ignore_ascii_case(hash))
                || announce
                    .node_associated_hash
                    .as_deref()
                    .is_some_and(|hash| peer_hash.eq_ignore_ascii_case(hash)))
    }

    fn spawn_browser_task(
        &self,
        tab_id: TabId,
        generation: u64,
        mut session: BrowserSession,
        kind: BrowserTaskKind,
        cancel: CancellationToken,
    ) {
        let tx = self.event_tx.clone();
        tokio::spawn(async move {
            let timeout = browser_task_timeout(&kind);
            let timeout_label = browser_task_label(&kind);
            let timeout_cancel = cancel.clone();
            let task = async move {
                match kind {
                    BrowserTaskKind::Open { target } => {
                        match session.open(&target, None, true, true, cancel).await {
                            Ok(page) => BrowserTaskResult::Page {
                                tab_id,
                                generation,
                                session: Box::new(session),
                                page,
                            },
                            Err(error) => BrowserTaskResult::Error {
                                tab_id,
                                generation,
                                message: error.to_string(),
                            },
                        }
                    }
                    BrowserTaskKind::OpenLink { link, request_data } => {
                        let use_cache = request_data.is_none();
                        match session
                            .open(&link.target, request_data, true, use_cache, cancel)
                            .await
                        {
                            Ok(page) => BrowserTaskResult::Page {
                                tab_id,
                                generation,
                                session: Box::new(session),
                                page,
                            },
                            Err(error) => BrowserTaskResult::Error {
                                tab_id,
                                generation,
                                message: error.to_string(),
                            },
                        }
                    }
                    BrowserTaskKind::Reload => match session.reload(cancel).await {
                        Ok(Some(page)) => BrowserTaskResult::Page {
                            tab_id,
                            generation,
                            session: Box::new(session),
                            page,
                        },
                        Ok(None) => BrowserTaskResult::Error {
                            tab_id,
                            generation,
                            message: "nothing to reload".into(),
                        },
                        Err(error) => BrowserTaskResult::Error {
                            tab_id,
                            generation,
                            message: error.to_string(),
                        },
                    },
                    BrowserTaskKind::Back => match session.back(cancel).await {
                        Ok(Some(page)) => BrowserTaskResult::Page {
                            tab_id,
                            generation,
                            session: Box::new(session),
                            page,
                        },
                        Ok(None) => BrowserTaskResult::Error {
                            tab_id,
                            generation,
                            message: "no back history".into(),
                        },
                        Err(error) => BrowserTaskResult::Error {
                            tab_id,
                            generation,
                            message: error.to_string(),
                        },
                    },
                    BrowserTaskKind::Forward => match session.forward(cancel).await {
                        Ok(Some(page)) => BrowserTaskResult::Page {
                            tab_id,
                            generation,
                            session: Box::new(session),
                            page,
                        },
                        Ok(None) => BrowserTaskResult::Error {
                            tab_id,
                            generation,
                            message: "no forward history".into(),
                        },
                        Err(error) => BrowserTaskResult::Error {
                            tab_id,
                            generation,
                            message: error.to_string(),
                        },
                    },
                    BrowserTaskKind::Download { target } => {
                        match session.download(&target, cancel).await {
                            Ok(file) => BrowserTaskResult::Download {
                                tab_id,
                                generation,
                                file,
                            },
                            Err(error) => BrowserTaskResult::Error {
                                tab_id,
                                generation,
                                message: error.to_string(),
                            },
                        }
                    }
                    BrowserTaskKind::Partial {
                        slot,
                        target,
                        fields,
                    } => {
                        let request_data =
                            (!fields.is_empty()).then(|| session.build_request_data(&fields));
                        match session.fetch_fragment(&target, request_data, cancel).await {
                            Ok(page) => BrowserTaskResult::Partial {
                                tab_id,
                                generation,
                                slot,
                                content: page.markup,
                            },
                            Err(error) => BrowserTaskResult::PartialError {
                                tab_id,
                                generation,
                                slot,
                                message: error.to_string(),
                            },
                        }
                    }
                }
            };
            let result = match tokio::time::timeout(timeout, task).await {
                Ok(result) => result,
                Err(_) => {
                    timeout_cancel.cancel();
                    BrowserTaskResult::Error {
                        tab_id,
                        generation,
                        message: format!(
                            "{timeout_label} timed out after {}s; request cancelled, retry when path/link is ready",
                            timeout.as_secs()
                        ),
                    }
                }
            };
            let _ = tx.send(InternalAppEvent::BrowserTask(result)).await;
        });
    }

    pub fn apply_browser_task_result(&mut self, result: BrowserTaskResult) -> bool {
        match result {
            BrowserTaskResult::Page {
                tab_id,
                generation,
                session,
                page,
            } => {
                let Some(index) = self
                    .workspace
                    .browser_tabs
                    .iter()
                    .position(|tab| tab.id == tab_id)
                else {
                    return false;
                };
                if !self.browser_result_matches_loading(index, generation) {
                    return false;
                }
                self.monitoring_state.inbound_page_responses = self
                    .monitoring_state
                    .inbound_page_responses
                    .saturating_add(1);
                self.monitoring_state
                    .note_inbound(estimated_browser_page_bytes(&page));
                self.workspace.browser_tabs[index].session = *session;
                self.sync_browser_tab_from_session(index, Some(page));
                self.workspace.browser_tabs[index].scroll.offset = 0;
                self.workspace.browser_tabs[index].focused_control = None;
                self.workspace.browser_tabs[index].focused_link = None;
                self.workspace.browser_tabs[index].loading = None;
                self.workspace.browser_tabs[index].live_warning = None;
                self.workspace.browser_tabs[index].retry_state = None;
                let page = self.workspace.browser_tabs[index]
                    .current_page
                    .as_ref()
                    .expect("browser tab was just synced with page")
                    .clone();
                if let Some(preview) = self.workspace.browser_tabs[index].request_preview.as_mut() {
                    preview.status = BrowserRequestStatus::Completed;
                    preview.detail = format!("loaded {}", page.url);
                }
                self.status.task = browser_page_loaded_status(&page, &self.runtime_status.backend);
                self.log_micronplus_diagnostics_for_tab(index, "page");
                self.refresh_context_status();
                true
            }
            BrowserTaskResult::Download {
                tab_id,
                generation,
                file,
            } => {
                let Some(index) = self
                    .workspace
                    .browser_tabs
                    .iter()
                    .position(|tab| tab.id == tab_id)
                else {
                    return false;
                };
                if !self.browser_result_matches_loading(index, generation) {
                    return false;
                }
                self.monitoring_state.inbound_downloads =
                    self.monitoring_state.inbound_downloads.saturating_add(1);
                if let Ok(metadata) = std::fs::metadata(&file.path) {
                    self.monitoring_state.note_inbound(metadata.len());
                }
                self.workspace.browser_tabs[index].loading = None;
                self.status.task = format!("downloaded {}", file.path.display());
                true
            }
            BrowserTaskResult::Partial {
                tab_id,
                generation,
                slot,
                content,
            } => {
                let Some(index) = self
                    .workspace
                    .browser_tabs
                    .iter()
                    .position(|tab| tab.id == tab_id)
                else {
                    return false;
                };
                if !self.workspace.browser_tabs[index]
                    .session
                    .is_current_generation(generation)
                {
                    return false;
                }
                let should_extract_widget_events = self.workspace.browser_tabs[index]
                    .current_page
                    .as_ref()
                    .is_some_and(|page| {
                        page.metadata.contains_key("micronplus_tree")
                            || page.metadata.contains_key("micronplus_layout")
                    });
                let (content, widget_events) = if should_extract_widget_events {
                    extract_micronplus_widget_events(&content)
                } else {
                    (content, Vec::new())
                };
                let layout_slot = self.workspace.browser_tabs[index]
                    .partials
                    .specs
                    .iter()
                    .find(|spec| spec.slot == slot)
                    .and_then(|spec| spec.slot.split(':').next())
                    .filter(|id| !id.is_empty() && *id != "partial")
                    .map(str::to_string)
                    .unwrap_or_else(|| slot.clone());
                match self.workspace.browser_tabs[index]
                    .session
                    .apply_partial_content(&slot, &content)
                {
                    Ok(page) => {
                        self.sync_browser_tab_partial_page(index, page);
                        self.log_micronplus_diagnostics_for_tab(index, "partial");
                        if should_extract_widget_events {
                            let mut candidate_page =
                                self.workspace.browser_tabs[index].current_page.clone();
                            if let Some(tree_value) = candidate_page
                                .as_mut()
                                .and_then(|page| page.metadata.get_mut("micronplus_tree"))
                            {
                                if let Ok(mut tree) = serde_json::from_value::<MicronPlusWidgetTree>(
                                    tree_value.clone(),
                                ) {
                                    if apply_micronplus_tree_partial(
                                        &mut tree,
                                        &layout_slot,
                                        &content,
                                    ) {
                                        *tree_value = serde_json::to_value(tree)
                                            .expect("MicronPlus tree serializes");
                                    }
                                }
                            }
                            if let Some(layout_value) = candidate_page
                                .as_mut()
                                .and_then(|page| page.metadata.get_mut("micronplus_layout"))
                            {
                                if let Ok(mut layout) =
                                    serde_json::from_value::<MicronPlusLayout>(layout_value.clone())
                                {
                                    if apply_micronplus_layout_partial(
                                        &mut layout,
                                        &layout_slot,
                                        &content,
                                    ) {
                                        *layout_value = serde_json::to_value(layout)
                                            .expect("MicronPlus layout serializes");
                                    }
                                }
                            }
                            if candidate_page
                                .as_ref()
                                .is_some_and(|page| page.validate_retained().is_ok())
                            {
                                self.workspace.browser_tabs[index].current_page = candidate_page;
                            }
                        }
                        self.workspace.browser_tabs[index].session.current_page =
                            self.workspace.browser_tabs[index].current_page.clone();
                        self.workspace.browser_tabs[index].partials.pending =
                            self.workspace.browser_tabs[index]
                                .partials
                                .pending
                                .saturating_sub(1);
                        self.workspace.browser_tabs[index]
                            .partials
                            .pending_slots
                            .remove(&slot);
                        if let Some(spec) = self.workspace.browser_tabs[index]
                            .partials
                            .specs
                            .iter_mut()
                            .find(|spec| spec.slot == slot)
                        {
                            spec.failures = 0;
                        }
                        for event in widget_events {
                            self.handle_internal_event(InternalAppEvent::MicronPlusWidget {
                                tab_id,
                                event,
                            });
                        }
                        true
                    }
                    Err(error) => {
                        self.workspace.browser_tabs[index].partials.pending =
                            self.workspace.browser_tabs[index]
                                .partials
                                .pending
                                .saturating_sub(1);
                        self.workspace.browser_tabs[index]
                            .partials
                            .pending_slots
                            .remove(&slot);
                        if let Some(spec) = self.workspace.browser_tabs[index]
                            .partials
                            .specs
                            .iter_mut()
                            .find(|spec| spec.slot == slot)
                        {
                            spec.failures = spec.failures.saturating_add(1);
                        }
                        self.status.task = error.to_string();
                        false
                    }
                }
            }
            BrowserTaskResult::PartialError {
                tab_id,
                generation,
                slot,
                message,
            } => {
                let Some(index) = self
                    .workspace
                    .browser_tabs
                    .iter()
                    .position(|tab| tab.id == tab_id)
                else {
                    return false;
                };
                if !self.workspace.browser_tabs[index]
                    .session
                    .is_current_generation(generation)
                {
                    return false;
                }
                self.workspace.browser_tabs[index].partials.pending = self.workspace.browser_tabs
                    [index]
                    .partials
                    .pending
                    .saturating_sub(1);
                self.workspace.browser_tabs[index]
                    .partials
                    .pending_slots
                    .remove(&slot);
                if let Some(spec) = self.workspace.browser_tabs[index]
                    .partials
                    .specs
                    .iter_mut()
                    .find(|spec| spec.slot == slot)
                {
                    spec.failures = spec.failures.saturating_add(1);
                    let backoff_ms = 5_000u64.saturating_mul(spec.failures.min(6) as u64);
                    spec.next_refresh_epoch_ms =
                        Some(current_epoch_ms().saturating_add(backoff_ms));
                }
                self.status.task = format!("partial refresh failed: {slot}");
                self.logs.push_with_source(
                    LogSeverity::Warn,
                    LogSource::Runtime,
                    format!("partial refresh failed slot={slot}: {message}"),
                );
                false
            }
            BrowserTaskResult::Error {
                tab_id,
                generation,
                message,
            } => {
                let Some(index) = self
                    .workspace
                    .browser_tabs
                    .iter()
                    .position(|tab| tab.id == tab_id)
                else {
                    return false;
                };
                if !self.browser_result_matches_loading(index, generation) {
                    return false;
                }
                let loading_snapshot = self.workspace.browser_tabs[index].loading.clone();
                let target = loading_snapshot
                    .as_ref()
                    .map(|loading| loading.target.clone())
                    .unwrap_or_else(|| self.workspace.browser_tabs[index].address_input.clone());
                let submitted_fields = loading_snapshot
                    .as_ref()
                    .is_some_and(|loading| loading.submitted_fields);
                self.workspace.browser_tabs[index].loading = None;
                if let Some(preview) = self.workspace.browser_tabs[index].request_preview.as_mut() {
                    preview.status = BrowserRequestStatus::Failed;
                    preview.detail = message.clone();
                }
                if let Some(step) = native_browser_load_failure_step(&target, &message) {
                    let next_action = native_browser_load_failure_status_action(&step.stage);
                    let app_level_timeout =
                        browser_load_failure_is_app_timeout(&message.to_ascii_lowercase());
                    let auto_retry = !app_level_timeout
                        && !submitted_fields
                        && self.apply_browser_transient_load_retry_state(index, &target, &step);
                    self.workspace.browser_tabs[index].live_warning = Some(BrowserLiveWarning {
                        target: target.clone(),
                        visible_page: self.workspace.browser_tabs[index]
                            .current_page
                            .as_ref()
                            .map(|page| {
                                format!(
                                    "{} ({})",
                                    page.url,
                                    browser_page_source_label(&page.source)
                                )
                            }),
                        message: message.clone(),
                        next_action: next_action.into(),
                    });
                    self.workspace.browser_tabs[index].probe_summary = Some(
                        BrowserProbeSummary::from_native_browser_load_failure(&target, &step),
                    );
                    if app_level_timeout {
                        self.apply_browser_manual_retry_state(
                            index,
                            &target,
                            "browser request timed out and was cancelled; press Retry to rebuild the page link",
                        );
                        self.request_browser_target_path_quiet_with_current_destination(
                            index,
                            &target,
                            "browser timeout recovery",
                            true,
                        );
                    } else if submitted_fields {
                        self.apply_browser_manual_retry_state(
                            index,
                            &target,
                            "browser form submit failed; press Retry to resubmit the captured request",
                        );
                    } else {
                        self.apply_browser_load_failure_retry_state(index, &target, &step);
                    }
                    self.logs.push_with_source(
                        LogSeverity::Warn,
                        LogSource::Diagnostics,
                        format_page_probe_trace_log_line("browser-load", 0, &step),
                    );
                    self.status.task = if auto_retry {
                        format!("{message} | retrying once after stale link cleanup")
                    } else if app_level_timeout {
                        compact_app_timeout_status(&message)
                    } else {
                        format!("{message} | {next_action}")
                    };
                } else {
                    self.workspace.browser_tabs[index].live_warning = None;
                    self.status.task = message;
                }
                true
            }
        }
    }

    fn browser_result_matches_loading(&self, index: usize, generation: u64) -> bool {
        self.workspace.browser_tabs[index]
            .loading
            .as_ref()
            .is_some_and(|loading| loading.generation == generation)
    }

    fn message_result_matches_pending(&self, index: usize, generation: u64) -> bool {
        self.workspace.conversations[index]
            .pending_send
            .as_ref()
            .is_some_and(|pending| pending.generation == generation)
    }

    pub fn close_active_browser_tab(&mut self) {
        if self.workspace.browser_tabs.len() <= 1 {
            self.status.task = "kept last browser tab open".into();
            return;
        }
        self.workspace
            .browser_tabs
            .remove(self.workspace.active_browser);
        self.workspace.active_browser = self
            .workspace
            .active_browser
            .min(self.workspace.browser_tabs.len() - 1);
        self.status.task = "closed browser tab".into();
        self.persist_ui_preferences("browser tabs");
    }

    pub fn next_browser_tab(&mut self) {
        if self.workspace.browser_tabs.is_empty() {
            return;
        }
        self.workspace.active_browser =
            (self.workspace.active_browser + 1) % self.workspace.browser_tabs.len();
        self.switch_section(WorkspaceSection::Browser);
    }

    pub fn select_browser_tab(&mut self, index: usize) {
        if index >= self.workspace.browser_tabs.len() {
            return;
        }
        self.workspace.active_browser = index;
        self.switch_section(WorkspaceSection::Browser);
    }

    pub fn previous_browser_tab(&mut self) {
        if self.workspace.browser_tabs.is_empty() {
            return;
        }
        self.workspace.active_browser = if self.workspace.active_browser == 0 {
            self.workspace.browser_tabs.len() - 1
        } else {
            self.workspace.active_browser - 1
        };
        self.switch_section(WorkspaceSection::Browser);
    }

    pub fn new_conversation(&mut self) {
        let id = self.next_conversation_id;
        self.next_conversation_id += 1;
        self.workspace
            .conversations
            .push(Conversation::new(id, "", "New Conversation"));
        self.workspace.active_conversation = self.workspace.conversations.len() - 1;
        self.switch_section(WorkspaceSection::Messages);
        self.status.task = "created blank conversation".into();
    }

    pub fn close_active_conversation_tab(&mut self) {
        if self.workspace.conversations.len() <= 1 {
            self.status.task = "kept last conversation open".into();
            return;
        }
        self.workspace
            .conversations
            .remove(self.workspace.active_conversation);
        self.workspace.active_conversation = self
            .workspace
            .active_conversation
            .min(self.workspace.conversations.len() - 1);
        self.status.task = "closed conversation tab".into();
        self.persist_ui_preferences("conversation tabs");
    }

    pub fn delete_active_conversation(&mut self) {
        let active = self.workspace.active_conversation;
        let peer_hash = self.workspace.conversations[active].peer_hash.clone();
        let peer_label = self.workspace.conversations[active].peer_label.clone();
        let deleted = self.delete_persisted_conversation_history(&peer_hash);
        match deleted {
            Ok(deleted_thread) => {
                let before = self.workspace.conversations.len();
                if peer_hash.trim().is_empty() {
                    self.workspace.conversations.remove(active);
                } else {
                    self.workspace.conversations.retain(|conversation| {
                        !conversation
                            .peer_hash
                            .trim()
                            .eq_ignore_ascii_case(peer_hash.trim())
                    });
                }
                let removed_tabs = before.saturating_sub(self.workspace.conversations.len());
                if self.workspace.conversations.is_empty() {
                    let id = self.next_conversation_id;
                    self.next_conversation_id += 1;
                    self.workspace.conversations.push(Conversation::new(
                        id,
                        "",
                        "New Conversation",
                    ));
                    self.workspace.active_conversation = 0;
                } else {
                    self.workspace.active_conversation =
                        active.min(self.workspace.conversations.len() - 1);
                }
                self.status.task = if deleted_thread {
                    format!("deleted conversation history for {peer_label}; removed {removed_tabs} tab(s)")
                } else {
                    "removed blank conversation".into()
                };
                self.mark_conversation_deleted(&peer_hash);
                self.purge_deleted_conversation_restore_metadata(&peer_hash);
                self.persist_ui_preferences("conversation tabs");
                self.flush_pending_ui_preferences();
            }
            Err(error) => {
                self.status.task = format!("failed to delete conversation: {error}");
                self.logs.push_with_source(
                    LogSeverity::Warn,
                    LogSource::Messaging,
                    format!("failed to delete conversation {peer_label}: {error}"),
                );
            }
        }
    }

    fn delete_persisted_conversation_history(&self, peer_hash: &str) -> AppResult<bool> {
        let peer_hash = peer_hash.trim();
        if peer_hash.is_empty() {
            return Ok(false);
        }

        let mut deleted = self.messaging_service.delete_conversation(peer_hash)?;

        let legacy_messages_dir = self.paths.root.join("messages");
        if legacy_messages_dir.is_dir() && legacy_messages_dir != self.message_store.root() {
            let legacy_store = MessageStore::new(legacy_messages_dir)?;
            deleted |= legacy_store.delete_thread(peer_hash)?;
        }

        Ok(deleted)
    }

    fn mark_conversation_deleted(&mut self, peer_hash: &str) {
        let peer_hash = peer_hash.trim();
        if peer_hash.is_empty() {
            return;
        }
        let deleted_at = current_epoch_ms() as f64 / 1_000.0;
        self.settings
            .deleted_conversations
            .retain(|deleted| !deleted.peer_hash.trim().eq_ignore_ascii_case(peer_hash));
        self.settings
            .deleted_conversations
            .push(DeletedConversationSettings {
                peer_hash: peer_hash.to_string(),
                deleted_at,
            });
    }

    fn clear_deleted_conversation_marker(&mut self, peer_hash: &str) {
        let peer_hash = peer_hash.trim();
        if peer_hash.is_empty() {
            return;
        }
        self.settings
            .deleted_conversations
            .retain(|deleted| !deleted.peer_hash.trim().eq_ignore_ascii_case(peer_hash));
    }

    fn purge_deleted_conversation_restore_metadata(&mut self, peer_hash: &str) {
        let peer_hash = peer_hash.trim();
        if peer_hash.is_empty() {
            return;
        }
        let removed_indices = self
            .settings
            .conversation_tabs
            .iter()
            .enumerate()
            .filter_map(|(index, tab)| {
                tab.peer_hash
                    .trim()
                    .eq_ignore_ascii_case(peer_hash)
                    .then_some(index)
            })
            .collect::<std::collections::BTreeSet<_>>();
        self.settings
            .conversation_tabs
            .retain(|tab| !tab.peer_hash.trim().eq_ignore_ascii_case(peer_hash));
        if removed_indices.is_empty() {
            return;
        }
        self.settings.ui.desktop_workspace_panes.retain(|pane| {
            pane.kind != crate::storage::settings::DesktopWorkspacePaneKind::Conversation
                || !removed_indices.contains(&pane.index)
        });
        self.settings.ui.desktop_workspace_layout = self
            .settings
            .ui
            .desktop_workspace_layout
            .take()
            .and_then(|node| prune_deleted_conversation_layout_node(node, &removed_indices));
        self.settings.ui.active_desktop_workspace_pane = self
            .settings
            .ui
            .active_desktop_workspace_pane
            .filter(|index| *index < self.settings.ui.desktop_workspace_panes.len());
    }

    pub fn set_active_conversation_peer_hash(&mut self, value: String) {
        let index = self.workspace.active_conversation;
        let normalized = normalize_lxmf_peer_input(&value);
        self.clear_deleted_conversation_marker(&normalized);
        let label = self
            .directory_service
            .find(&normalized)
            .map(|entry| entry.display_name.clone())
            .unwrap_or_else(|| {
                if normalized.trim().is_empty() {
                    "New Conversation".into()
                } else {
                    normalized.chars().take(8).collect()
                }
            });
        let conversation = &mut self.workspace.conversations[index];
        conversation.peer_hash = normalized.clone();
        conversation.peer_label = label.clone();
        conversation.thread.peer_hash = normalized;
        conversation.thread.peer_label = label;
        self.persist_ui_preferences("conversation peer");
    }

    pub fn select_conversation_tab(&mut self, index: usize) {
        if index >= self.workspace.conversations.len() {
            return;
        }
        self.workspace.active_conversation = index;
        self.mark_conversation_read_by_index(index);
        self.switch_section(WorkspaceSection::Messages);
    }

    pub fn set_active_conversation_draft_title(&mut self, value: String) {
        let index = self.workspace.active_conversation;
        self.workspace.conversations[index].draft_title = value;
        self.workspace.active_section = WorkspaceSection::Messages;
        self.status.task = "message draft updated".into();
        self.mark_ui_preferences_dirty("conversation draft");
    }

    pub fn set_active_conversation_draft_body(&mut self, value: String) {
        let index = self.workspace.active_conversation;
        self.workspace.conversations[index].draft_body = value;
        self.workspace.active_section = WorkspaceSection::Messages;
        self.status.task = "message draft updated".into();
        self.mark_ui_preferences_dirty("conversation draft");
    }

    pub fn add_active_conversation_attachment(&mut self, path: PathBuf) -> bool {
        let index = self.workspace.active_conversation;
        if !path.is_file() {
            self.status.task = "attachment path is not a file".into();
            return false;
        }
        let conversation = &mut self.workspace.conversations[index];
        if conversation
            .attachments
            .iter()
            .any(|existing| existing == &path)
        {
            self.status.task = "attachment already added".into();
            return false;
        }
        conversation.attachments.push(path);
        self.workspace.active_section = WorkspaceSection::Messages;
        self.status.task = "attachment added".into();
        self.mark_ui_preferences_dirty("conversation attachments");
        true
    }

    pub fn remove_active_conversation_attachment(&mut self, attachment_index: usize) -> bool {
        let index = self.workspace.active_conversation;
        let conversation = &mut self.workspace.conversations[index];
        if attachment_index >= conversation.attachments.len() {
            self.status.task = "attachment was already removed".into();
            return false;
        }
        conversation.attachments.remove(attachment_index);
        self.workspace.active_section = WorkspaceSection::Messages;
        self.status.task = "attachment removed".into();
        self.mark_ui_preferences_dirty("conversation attachments");
        true
    }

    pub fn open_directory_node_in_browser(&mut self, destination_hash: &str) {
        let url = format!("{destination_hash}:{}", crate::browser::page::DEFAULT_PATH);
        if let Some(index) = self
            .workspace
            .browser_tabs
            .iter()
            .position(|tab| browser_tab_matches_destination(tab, destination_hash))
        {
            self.workspace.active_browser = index;
            self.switch_section(WorkspaceSection::Browser);
            self.workspace.browser_tabs[index].address_input = url.clone();
            self.status.task = format!(
                "reusing browser tab for {}",
                directory_node_tab_label(
                    self.directory_service.find(destination_hash).as_ref(),
                    destination_hash
                )
            );
            self.open_browser_target_at_index(index, url);
            return;
        }

        let id = self.next_tab_id;
        self.next_tab_id += 1;
        let mut session = BrowserSession::with_runtime(
            url.clone(),
            self.runtime.clone(),
            self.cache.clone(),
            self.paths.downloads_dir.clone(),
        );
        self.configure_browser_session(&mut session);
        self.workspace.browser_tabs.push(BrowserTab {
            id,
            title: directory_node_tab_label(
                self.directory_service.find(destination_hash).as_ref(),
                destination_hash,
            ),
            current_page: session.current_page().cloned(),
            session,
            address_input: url.clone(),
            render_cache: RenderCache::default(),
            loading: None,
            path_warmup: None,
            partials: PartialRefreshState::default(),
            scroll: ScrollState::default(),
            micron_zoom_percent: 100,
            viewport_width: self.browser_viewport_width.max(1),
            viewport_height: self.browser_viewport_height.max(1),
            focused_control: None,
            focused_link: None,
            request_preview: None,
            probe_summary: None,
            live_warning: None,
            retry_state: None,
            micronplus_widgets: MicronPlusWidgetStore::default(),
            micronplus_control_events: Vec::new(),
            micronplus_diagnostics_logged: Vec::new(),
        });
        self.workspace.active_browser = self.workspace.browser_tabs.len() - 1;
        self.switch_section(WorkspaceSection::Browser);
        let active = self.workspace.active_browser;
        self.open_browser_target_at_index(active, url);
    }

    pub fn open_directory_peer_conversation(&mut self, peer_hash: &str) {
        self.clear_deleted_conversation_marker(peer_hash);
        if let Some(index) = self
            .workspace
            .conversations
            .iter()
            .position(|conversation| conversation.peer_hash == peer_hash)
        {
            self.workspace.active_conversation = index;
            self.switch_section(WorkspaceSection::Messages);
            return;
        }
        let label = self
            .directory_service
            .find(peer_hash)
            .map(|entry| entry.display_name)
            .unwrap_or_else(|| peer_hash.chars().take(8).collect());
        let id = self.next_conversation_id;
        self.next_conversation_id += 1;
        self.workspace
            .conversations
            .push(Conversation::new(id, peer_hash, label));
        self.workspace.active_conversation = self.workspace.conversations.len() - 1;
        self.switch_section(WorkspaceSection::Messages);
    }

    pub fn open_lxmf_peer_link(&mut self, target: &str) -> bool {
        let trimmed = target.trim();
        if !(trimmed.starts_with("lxmf@") || trimmed.starts_with("lxmf.delivery@")) {
            return false;
        }
        let peer_hash = normalize_lxmf_peer_input(target);
        if !is_16_byte_hex_hash(&peer_hash) {
            return false;
        }
        self.open_directory_peer_conversation(&peer_hash);
        self.status.task = format!("opened LXMF conversation {}", compact_hash(&peer_hash));
        true
    }

    pub fn request_selected_directory_path(&mut self) -> bool {
        let Some(entry) = self.selected_directory_entry() else {
            self.status.task = "no directory entry selected".into();
            return false;
        };
        self.request_directory_entry_paths(&entry, "directory path request")
    }

    fn request_directory_entry_paths(&mut self, entry: &DirectoryEntry, reason: &str) -> bool {
        let destination = entry.destination_hash.clone();
        let associated = entry.associated_hash.clone();
        let node_associated = entry.node_associated_hash.clone();
        let display_name = entry.display_name.clone();
        let candidates = directory_entry_path_candidates(entry);
        let kind = match entry.kind {
            DirectoryKind::Node => "node",
            DirectoryKind::Peer => "peer",
            DirectoryKind::Propagation => "propagation",
            DirectoryKind::OmenChat => "omenchat",
            DirectoryKind::Unknown => "unknown",
        };
        let reason = reason.to_string();
        let Ok(handle) = tokio::runtime::Handle::try_current() else {
            self.status.task = "path request queued only when the desktop runtime is active".into();
            self.logs.push_with_source(
                LogSeverity::Warn,
                LogSource::Directory,
                format!("cannot request path for {display_name}; no active Tokio runtime"),
            );
            return false;
        };

        self.status.task = format!("requesting path for {display_name}");
        self.monitoring_state.outbound_path_requests = self
            .monitoring_state
            .outbound_path_requests
            .saturating_add(candidates.len() as u64);
        self.monitoring_state.outbound_path_warmups = self
            .monitoring_state
            .outbound_path_warmups
            .saturating_add(candidates.len() as u64);
        self.monitoring_state.note_outbound(
            candidates
                .iter()
                .map(|candidate| 128 + candidate.len() as u64)
                .sum(),
        );
        self.logs.push_with_source(
            LogSeverity::Info,
            LogSource::Directory,
            format!(
                "requesting {kind} paths for {display_name} candidates={}",
                candidates.join(",")
            ),
        );
        let runtime = self.runtime.clone();
        let tx = self.event_tx.clone();
        handle.spawn(async move {
            let mut lines = Vec::new();
            let mut failed = false;
            for (hash, label) in [
                (Some(destination.as_str()), kind),
                (
                    associated.as_deref(),
                    match kind {
                        "node" => "peer associate",
                        "peer" => "node associate",
                        "propagation" => "peer associate",
                        _ => "associate",
                    },
                ),
                (node_associated.as_deref(), "node associate"),
            ]
            .into_iter()
            .filter_map(|(hash, label)| hash.map(|hash| (hash.trim().to_ascii_lowercase(), label)))
            {
                if hash.is_empty() {
                    continue;
                }
                match runtime
                    .request_path(&hash, &format!("{reason} {label}"), true)
                    .await
                {
                    Ok(true) => lines.push(format!("queued {label} path {hash}")),
                    Ok(false) => lines.push(format!("{label} path already known or not queued {hash}")),
                    Err(error) => {
                        failed = true;
                        lines.push(format!("{label} path request failed {hash}: {error}"));
                    }
                }
            }

            match runtime.warm_paths(&candidates, 3, 0).await {
                Ok(requested) => {
                    lines.push(format!("warm_paths immediate requested={requested} candidates={}", candidates.len()))
                }
                Err(error) => {
                    failed = true;
                    lines.push(format!("warm_paths immediate failed: {error}"));
                }
            }

            let immediate_summary = format!(
                "directory path request {display_name} [{destination}]: {}",
                lines.join("; ")
            );
            let _ = tx
                .send(InternalAppEvent::LogWithSource {
                    severity: if failed {
                        LogSeverity::Warn
                    } else {
                        LogSeverity::Debug
                    },
                    source: LogSource::Runtime,
                    line: immediate_summary,
                })
                .await;

            if !candidates.is_empty() {
                tokio::time::sleep(std::time::Duration::from_millis(1_200)).await;
                match runtime.warm_paths(&candidates, 3, 0).await {
                    Ok(requested) => {
                        let _ = tx
                            .send(InternalAppEvent::LogWithSource {
                                severity: LogSeverity::Debug,
                                source: LogSource::Runtime,
                                line: format!(
                                    "directory path retry {display_name} [{destination}]: warm_paths requested={requested} candidates={}",
                                    candidates.len()
                                ),
                            })
                            .await;
                    }
                    Err(error) => {
                        let _ = tx
                            .send(InternalAppEvent::LogWithSource {
                                severity: LogSeverity::Warn,
                                source: LogSource::Runtime,
                                line: format!(
                                    "directory path retry {display_name} [{destination}] failed: {error}"
                                ),
                            })
                            .await;
                    }
                }
            };
        });
        true
    }

    fn active_lxmf_peer_hash_for_interop(&mut self) -> Option<String> {
        let active_peer = self.active_conversation().peer_hash.trim();
        if is_16_byte_hex_hash(active_peer) {
            return Some(active_peer.to_string());
        }

        if let Some(entry) = self.best_lxmf_directory_peer() {
            let hash = entry.destination_hash.clone();
            let label = entry.display_name.clone();
            self.open_directory_peer_conversation(&hash);
            self.logs.push_with_source(
                LogSeverity::Info,
                LogSource::Diagnostics,
                format!("auto-selected LXMF peer for interop: {label} ({hash})"),
            );
            return Some(hash);
        }

        None
    }

    fn best_lxmf_directory_peer(&self) -> Option<DirectoryEntry> {
        if let Some(entry) = self
            .selected_directory_entry()
            .filter(|entry| entry.kind == DirectoryKind::Peer)
            .filter(|entry| is_16_byte_hex_hash(&entry.destination_hash))
        {
            return Some(entry);
        }

        self.directory_service
            .list_entries()
            .into_iter()
            .filter(|entry| entry.kind == DirectoryKind::Peer)
            .filter(|entry| is_16_byte_hex_hash(&entry.destination_hash))
            .max_by(lxmf_peer_candidate_order)
    }

    pub fn apply_network_status(&mut self, status: NetworkStatus) {
        self.status.backend = runtime_backend_status_label(&status.backend);
        self.status.identity = status
            .active_identity
            .as_ref()
            .map(|identity| format!("identity: {}", identity.label))
            .unwrap_or_else(|| "identity: none".into());
        self.status.task = status.message.clone();
        self.runtime_status = status;
        self.refresh_context_status();
    }

    pub fn active_browser_tab(&self) -> &BrowserTab {
        &self.workspace.browser_tabs[self.workspace.active_browser]
    }

    pub fn active_browser_tab_mut(&mut self) -> &mut BrowserTab {
        let index = self.workspace.active_browser;
        &mut self.workspace.browser_tabs[index]
    }

    pub fn active_browser_field_editor(&self) -> Option<BrowserFieldEditor> {
        let active = self.input.active.as_ref()?;
        let InputTarget::BrowserField { tab_id, name } = &active.target else {
            return None;
        };
        if *tab_id != self.active_browser_tab().id {
            return None;
        }
        Some(BrowserFieldEditor {
            name: name.clone(),
            value: active.buffer.as_str().to_string(),
            cursor_byte: active.buffer.cursor(),
        })
    }

    pub fn finish_active_browser_field_edit_preserving_value(&mut self) -> bool {
        let Some(active) = self.input.active.as_ref() else {
            return false;
        };
        let InputTarget::BrowserField { tab_id, name } = active.target.clone() else {
            return false;
        };
        let text = active.buffer.as_str().to_string();
        self.input.active = None;
        self.apply_input_text(&InputTarget::BrowserField { tab_id, name }, text);
        self.workspace.focus = FocusArea::Workspace;
        self.status.task = "page field edit ended".into();
        true
    }

    pub fn set_active_browser_field_draft(&mut self, value: String) -> bool {
        let Some(active) = self.input.active.as_ref() else {
            return false;
        };
        let InputTarget::BrowserField { tab_id, name } = &active.target else {
            return false;
        };
        let admitted = value.len() <= crate::micron::parser::MICRON_CONTROL_VALUE_MAX_BYTES
            && self.browser_tab_index(*tab_id).is_some_and(|index| {
                self.workspace.browser_tabs[index]
                    .session
                    .can_set_field_value(name, &value)
            });
        if !admitted {
            self.status.task = "page field limit reached; input was not changed".into();
            return false;
        }

        let active = self.input.active.as_mut().expect("active input checked");
        active.buffer.set_text(value);
        self.sync_active_input_to_target();
        self.status.task = "editing page field".into();
        true
    }

    pub fn active_conversation(&self) -> &Conversation {
        &self.workspace.conversations[self.workspace.active_conversation]
    }

    pub fn lxmf_unread_status_line(&self) -> String {
        let (trusted, untrusted) = self.workspace.conversations.iter().fold(
            (0u32, 0u32),
            |(trusted, untrusted), conversation| {
                let unread = conversation.thread.unread_count;
                if unread == 0 {
                    return (trusted, untrusted);
                }
                if self.lxmf_peer_is_trusted(&conversation.peer_hash) {
                    (trusted.saturating_add(unread), untrusted)
                } else {
                    (trusted, untrusted.saturating_add(unread))
                }
            },
        );
        format!("unread: {} trusted / {} untrusted", trusted, untrusted)
    }

    fn mark_conversation_read_by_index(&mut self, index: usize) -> bool {
        let Some(conversation) = self.workspace.conversations.get_mut(index) else {
            return false;
        };
        if conversation.thread.unread_count == 0 {
            return false;
        }
        let peer_hash = conversation.peer_hash.clone();
        conversation.thread.unread_count = 0;
        conversation.unread_at_open = 0;
        for message in &mut conversation.thread.messages {
            if message.incoming {
                message.unread = false;
            }
        }
        if !peer_hash.trim().is_empty() {
            if let Err(error) = self.messaging_service.mark_read(&peer_hash) {
                self.logs.push_with_source(
                    LogSeverity::Warn,
                    LogSource::Messaging,
                    format!("failed to persist read state for {peer_hash}: {error}"),
                );
            }
        }
        true
    }

