    #[test]
    fn micronplus_transform_diagnostics_route_to_plugin_logs_once() {
        let mut app = App::new(test_config("browser-micronplus-diagnostics-log"));
        app.workspace.browser_tabs[0]
            .session
            .set_micronplus_policy(true, Some(BTreeSet::from(["mock.node".into()])));
        let page = BrowserPage {
            url: "mock.node:/page/bad-micronplus.mu".into(),
            title: "Bad MicronPlus".into(),
            markup: r#"[window title="Bad" strange="x"]
[status text="Ready" unknown="y"]
body
[/window]"#
                .into(),
            source: crate::browser::PageSource::Network,
            metadata: BTreeMap::new(),
            request_data: None,
        };

        app.workspace.browser_tabs[0].session.apply_page(page, true);
        app.sync_browser_tab_from_session(0, None);
        app.log_micronplus_diagnostics_for_tab(0, "page");
        app.log_micronplus_diagnostics_for_tab(0, "page");

        let plugin_warnings = app
            .logs
            .entries
            .iter()
            .filter(|entry| {
                entry.source == LogSource::Plugin && entry.severity == LogSeverity::Warn
            })
            .collect::<Vec<_>>();
        assert_eq!(plugin_warnings.len(), 2);
        assert!(plugin_warnings.iter().any(|entry| entry
            .message
            .contains("[window] ignores unsupported attrs: strange")));
        assert!(plugin_warnings.iter().any(|entry| entry
            .message
            .contains("[status] ignores unsupported attrs: unknown")));
        let page = app
            .active_browser_tab()
            .current_page
            .as_ref()
            .expect("page");
        assert!(page.metadata.contains_key("micronplus_diagnostics"));
        assert!(!page.markup.contains("unsupported attrs"));
    }

