    #[test]
    fn micronplus_partial_response_routes_widget_events_without_code_spill() {
        let mut app = App::new(test_config("browser-partial-widget-events"));
        app.workspace.browser_tabs[0]
            .session
            .set_micronplus_policy(true, Some(BTreeSet::from(["mock.node".into()])));
        let page = BrowserPage {
            url: "mock.node:/page/micronplus-live-widgets.mu".into(),
            title: "MicronPlus Live Widgets".into(),
            markup: r#"[window title="Widgets"]
[columns]
[column title="Feed" width=28]
[live id="feed" src="mock.node:/page/live-feed.mu" refresh=2]
[status id="state" text="Initial" style="error"]
[/column]
[column title="Log" weight=1]
[log id="events" height=2 max=2]
old
[/log]
[/column]
[/columns]
[/window]"#
                .into(),
            source: crate::browser::PageSource::Network,
            metadata: BTreeMap::new(),
            request_data: None,
        };
        app.workspace.browser_tabs[0].session.apply_page(page, true);
        app.sync_browser_tab_from_session(0, None);

        let tab_id = app.active_browser_tab().id;
        let generation = app.active_browser_tab().session.generation;
        let slot = app.active_browser_tab().partials.specs[0].slot.clone();

        assert!(app.apply_browser_task_result(BrowserTaskResult::Partial {
            tab_id,
            generation,
            slot,
            content: r#"[event name="status.update.state" text="Ready" style="success"]
[event name="log.append.events" text="Widget event"]
Loaded body"#
                .into(),
        }));

        let markup = app
            .active_browser_tab()
            .current_page
            .as_ref()
            .map(|page| page.markup.as_str())
            .expect("partial page");
        assert!(markup.contains("Loaded body"));
        assert!(!markup.contains("status.update.state"));
        assert!(!markup.contains("log.append.events"));

        let text = app
            .browser_rendered_rows_for_tab_width(app.active_browser_tab(), 80)
            .expect("column rows")
            .into_iter()
            .map(|row| row.text())
            .collect::<Vec<_>>()
            .join("\n");
        assert!(text.contains("Ready"));
        assert!(text.contains("Widget event"));
        assert!(text.contains("Loaded body"));
    }

