    #[test]
    fn flat_micronplus_live_partial_columns_do_not_replace_parent_page() {
        let mut app = App::new(test_config("flat-live-partial-columns"));
        app.workspace.browser_tabs[0]
            .session
            .set_micronplus_policy(true, Some(BTreeSet::from(["mock.node".into()])));
        let page = BrowserPage {
            url: "mock.node:/page/sample.mu".into(),
            title: "Sample".into(),
            markup: r#"SAMPLE PORTAL
[live id="sample_badge" src=":/page/status-card.mu" refresh=1 loop=7 fields="started_at=1|seed=1"]
SAMPLE NAVIGATION
`[Home`:/page/index.mu]`_`"#
                .into(),
            source: crate::browser::PageSource::Network,
            metadata: BTreeMap::new(),
            request_data: None,
        };
        app.workspace.browser_tabs[0].session.apply_page(page, true);
        app.sync_browser_tab_from_session(0, None);
        assert!(app
            .active_browser_tab()
            .current_page
            .as_ref()
            .is_some_and(|page| !page.metadata.contains_key("micronplus_layout")));

        let tab_id = app.active_browser_tab().id;
        let generation = app.active_browser_tab().session.generation;
        let slot = app.active_browser_tab().partials.specs[0].slot.clone();
        assert!(app.apply_browser_task_result(BrowserTaskResult::Partial {
            tab_id,
            generation,
            slot,
            content: r#"[columns]
[column weight=1]
[/column]
[column width=14]
`F8ff`!SAMPLE/READY`!`f
[/column]
[column weight=1]
[/column]
[/columns]"#
                .into(),
        }));

        let page = app
            .active_browser_tab()
            .current_page
            .as_ref()
            .expect("page");
        assert_eq!(page.url, "mock.node:/page/sample.mu");
        assert!(!page.metadata.contains_key("micronplus_layout"));
        assert!(page.markup.contains("SAMPLE PORTAL"));
        assert!(page.markup.contains("SAMPLE/READY"));
        assert!(page.markup.contains("SAMPLE NAVIGATION"));

        let rows = app
            .browser_rendered_rows_for_tab_width(app.active_browser_tab(), 88)
            .expect("structured rows");
        let text = rows
            .into_iter()
            .map(|row| row.text())
            .collect::<Vec<_>>()
            .join("\n");
        assert!(text.contains("SAMPLE PORTAL"));
        assert!(text.contains("SAMPLE/READY"));
        assert!(text.contains("SAMPLE NAVIGATION"));
        assert!(text.contains("Home"));
    }

