    #[test]
    fn sidebar_activation_switches_sections_and_nested_items() {
        let mut app = App::new(test_config("sidebar"));
        app.new_browser_tab();
        app.new_conversation();

        app.workspace.sidebar_index = 2;
        app.activate_sidebar_selection();
        assert_eq!(app.workspace.active_section, WorkspaceSection::Directory);

        app.workspace.sidebar_index = WorkspaceSection::ALL.len() + 1;
        app.activate_sidebar_selection();
        assert_eq!(app.workspace.active_section, WorkspaceSection::Browser);
        assert_eq!(app.workspace.active_browser, 0);

        app.workspace.sidebar_index =
            WorkspaceSection::ALL.len() + 1 + app.workspace.browser_tabs.len();
        app.activate_sidebar_selection();
        assert_eq!(app.workspace.active_section, WorkspaceSection::Messages);
        assert_eq!(app.workspace.active_conversation, 0);
    }

    #[tokio::test]
    async fn opening_directory_node_and_peer_updates_workspaces() {
        let mut app = App::new(test_config("directory-actions"));
        app.directory_service
            .ingest_announce("node.hash", "Node", DirectoryKind::Node, None, None)
            .expect("node announce");
        app.directory_service
            .ingest_announce("peer.hash", "Peer", DirectoryKind::Peer, None, None)
            .expect("peer announce");
        app.refresh_panels_from_services();

        app.open_directory_node_in_browser("node.hash");
        assert_eq!(app.workspace.active_section, WorkspaceSection::Browser);
        assert_eq!(
            app.active_browser_tab().address_input,
            "node.hash:/page/index.mu"
        );
        assert_eq!(app.active_browser_tab().title, "Node");
        assert!(app.active_browser_tab().loading.is_some());
        let tab_count = app.workspace.browser_tabs.len();
        let active_tab_id = app.active_browser_tab().id;

        app.open_directory_node_in_browser("node.hash");
        assert_eq!(app.workspace.browser_tabs.len(), tab_count);
        assert_eq!(app.active_browser_tab().id, active_tab_id);
        assert_eq!(
            app.active_browser_tab().address_input,
            "node.hash:/page/index.mu"
        );

        app.open_directory_peer_conversation("peer.hash");
        assert_eq!(app.workspace.active_section, WorkspaceSection::Messages);
        assert_eq!(app.active_conversation().peer_label, "Peer");
    }

    #[tokio::test]
    async fn directory_propagation_selection_persists_and_notifies_runtime() {
        let mut app = App::new(test_config("directory-propagation-select"));
        app.directory_service
            .ingest_announce(
                FIXTURE_NODE_HASH,
                "Relay",
                DirectoryKind::Propagation,
                None,
                Some("node.hash".into()),
            )
            .expect("propagation announce");
        app.refresh_panels_from_services();
        let index = app
            .directory_state
            .entries
            .iter()
            .position(|entry| entry.destination_hash == FIXTURE_NODE_HASH)
            .expect("propagation entry");

        assert!(app.select_directory_entry(index));
        assert!(app.use_selected_directory_propagation_node());
        tokio::task::yield_now().await;

        assert_eq!(
            app.settings.preferred_propagation_node_hash.as_deref(),
            Some(FIXTURE_NODE_HASH)
        );
        assert_eq!(
            app.runtime
                .get_outbound_propagation_node()
                .await
                .expect("mock propagation node")
                .as_deref(),
            Some(FIXTURE_NODE_HASH)
        );
        let saved = app
            .directory_service
            .find(FIXTURE_NODE_HASH)
            .expect("saved propagation entry");
        assert!(saved.saved);

        assert!(app.clear_preferred_propagation_node());
        tokio::task::yield_now().await;
        assert_eq!(app.settings.preferred_propagation_node_hash, None);
        assert_eq!(
            app.runtime
                .get_outbound_propagation_node()
                .await
                .expect("mock propagation node cleared"),
            None
        );
    }

