    #[tokio::test]
    async fn directory_path_request_queues_through_runtime_boundary() {
        let mut app = App::new(test_config("directory-path-request"));
        app.directory_service
            .ingest_announce(
                FIXTURE_NODE_HASH,
                "Live Node",
                DirectoryKind::Node,
                Some(FIXTURE_PEER_HASH.into()),
                Some(FIXTURE_ASSOCIATED_HASH.into()),
            )
            .expect("node announce");
        app.refresh_panels_from_services();
        app.directory_state.selected = app
            .directory_state
            .entries
            .iter()
            .position(|entry| entry.destination_hash == FIXTURE_NODE_HASH);

        assert!(app.request_selected_directory_path());
        tokio::task::yield_now().await;
        app.drain_internal_events();

        assert!(app.logs.entries.iter().any(|entry| entry
            .message
            .contains("directory path request")
            && entry.message.contains(FIXTURE_NODE_HASH)
            && entry.message.contains(FIXTURE_PEER_HASH)
            && entry.message.contains(FIXTURE_ASSOCIATED_HASH)
            && entry.message.contains("warm_paths immediate")));
    }

