    #[test]
    fn lxmf_peer_candidates_mark_selected_and_active_peers() {
        let mut app = App::new(test_config("lxmf-peer-candidates"));
        app.directory_service
            .ingest_announce(FIXTURE_NODE_HASH, "Peer A", DirectoryKind::Peer, None, None)
            .expect("peer a announce");
        app.directory_service
            .ingest_announce(FIXTURE_PEER_HASH, "Peer B", DirectoryKind::Peer, None, None)
            .expect("peer b announce");
        app.refresh_panels_from_services();
        app.open_directory_peer_conversation(FIXTURE_PEER_HASH);
        app.directory_state.selected = app
            .directory_state
            .entries
            .iter()
            .position(|entry| entry.destination_hash == FIXTURE_NODE_HASH);

        let candidates = app.lxmf_peer_candidates();
        assert_eq!(candidates.len(), 2);
        assert!(candidates.iter().any(|candidate| {
            candidate.destination_hash == FIXTURE_NODE_HASH && candidate.selected
        }));
        assert_eq!(
            candidates
                .first()
                .map(|candidate| candidate.destination_hash.as_str()),
            Some(FIXTURE_PEER_HASH)
        );
        assert!(candidates
            .first()
            .is_some_and(|candidate| candidate.active_conversation));
    }

