    #[test]
    fn lxmf_messaging_diagnostics_reports_packet_submission_and_proof() {
        let mut app = App::new(test_config("lxmf-diag-submitted"));
        let peer = FIXTURE_NODE_HASH;
        app.active_conversation_mut_for_test().peer_hash = peer.into();
        app.active_conversation_mut_for_test()
            .push_message(MessageSummary {
                peer_hash: peer.into(),
                peer_label: "Peer".into(),
                title: "Subject".into(),
                content: "Body".into(),
                timestamp: 1.0,
                transport_method: TransportMethod::Direct,
                delivered: false,
                failed: false,
                incoming: false,
                unread: false,
                message_id: Some("packet-a".into()),
                fields: BTreeMap::from([(
                    "native_lxmf_state".into(),
                    "submitted_to_rns_net".into(),
                )]),
                attachments: Vec::new(),
            });

        let submitted = app.active_lxmf_messaging_diagnostics();
        assert!(submitted
            .lines
            .iter()
            .any(|line| line.contains("submitted; waiting for proof or peer activity")));

        let message = app
            .active_conversation_mut_for_test()
            .thread
            .messages
            .last_mut()
            .expect("message");
        message
            .fields
            .insert("native_lxmf_state".into(), "delivered".into());
        message
            .fields
            .insert("native_lxmf_evidence".into(), "rns_packet_proof".into());
        message.delivered = true;

        let delivered = app.active_lxmf_messaging_diagnostics();
        assert!(delivered
            .lines
            .iter()
            .any(|line| line.contains("LXMF router delivered")));
    }

