    #[cfg(feature = "native-reticulum")]
    fn make_native_send_ready_app(name: &str) -> App {
        let mut config = test_config(name);
        config.settings.runtime_backend = RuntimeBackendSetting::Reticulum;
        let mut app = App::new(config);
        app.runtime_status.backend = RuntimeBackendName::Reticulum;
        app.runtime_status.connected = true;
        app.runtime_status.message = format!(
            "local_lxmf_registered=true proof_capable=true announced=true local_lxmf_destination={FIXTURE_NODE_HASH}"
        );
        app.runtime_status.active_identity = Some(crate::identity::IdentityProfile {
            label: "test".into(),
            path: app.paths.identities_dir.join("default_identity"),
            hash_hex: "00".repeat(16),
            managed: true,
        });
        app.active_conversation_mut_for_test().peer_hash = FIXTURE_NODE_HASH.into();
        app.active_conversation_mut_for_test().draft_title = "Subject".into();
        app.active_conversation_mut_for_test().draft_body = "Body".into();
        app
    }

