    #[test]
    fn conversation_attachment_draft_management_deduplicates_and_removes() {
        let mut app = App::new(test_config("conversation-attachment-draft"));
        let attachment = app.paths.root.join("draft-attachment.txt");
        std::fs::write(&attachment, b"attached").expect("write attachment fixture");

        assert!(app.add_active_conversation_attachment(attachment.clone()));
        assert!(!app.add_active_conversation_attachment(attachment.clone()));
        assert_eq!(app.active_conversation().attachments, vec![attachment]);

        assert!(app.remove_active_conversation_attachment(0));
        assert!(app.active_conversation().attachments.is_empty());
        assert!(!app.remove_active_conversation_attachment(0));
    }

