    async fn native_lxmf_send_waits_for_local_announce_before_inspection_when_needed() {
        let mut app = make_native_send_ready_app("native-send-auto-announce");
        app.runtime_status.message = format!(
            "local_lxmf_registered=true proof_capable=true announced=false local_lxmf_destination={FIXTURE_NODE_HASH}"
        );

        app.send_active_conversation_draft();

        assert_eq!(
            app.pending_local_lxmf_announce_action,
            Some(PendingLocalLxmfAnnounceAction::Send {
                conversation_id: app.active_conversation().id,
            })
        );
        assert!(app.active_conversation().pending_send.is_none());
        assert!(app
            .logs
            .lines
            .iter()
            .any(|line| line.contains("announcing local LXMF identity before LXMF send")));

        assert!(app.apply_local_lxmf_announce_result(Ok(true)));

        assert_eq!(
            status_message_bool(&app.runtime_status.message, "announced"),
            Some(true)
        );
        assert!(app
            .lxmf_peer_inspection
            .as_ref()
            .is_some_and(|state| state.pending));
    }

