    #[test]
    fn app_restores_browser_and_conversation_session_descriptors_from_settings() {
        let mut config = test_config("session-descriptor-restore");
        config.settings.browser_tabs = vec![
            BrowserTabSettings {
                title: "One".into(),
                address_input: "mock.node:/one.mu".into(),
                current_url: "mock.node:/one.mu".into(),
                history: vec!["mock.node:/one.mu".into()],
                history_index: 0,
                ..BrowserTabSettings::default()
            },
            BrowserTabSettings {
                title: "Two".into(),
                address_input: "mock.node:/two.mu".into(),
                current_url: "mock.node:/two.mu".into(),
                history: vec!["mock.node:/one.mu".into(), "mock.node:/two.mu".into()],
                history_index: 1,
                scroll_offset: 4,
                focused_link: Some(BrowserFocusedLinkSettings {
                    target: "mock.node:/later.mu".into(),
                    fields: vec!["name".into()],
                    region_index: 2,
                }),
                ..BrowserTabSettings::default()
            },
        ];
        config.settings.conversation_tabs = vec![ConversationTabSettings {
            peer_hash: "lxmf@abc".into(),
            peer_label: "Peer ABC".into(),
            draft_title: "draft".into(),
            draft_body: "body".into(),
            attachments: vec![config.paths.root.join("draft.bin")],
            delivery_mode: DeliveryMode::Propagated,
            include_ticket: true,
        }];
        config.settings.ui.active_browser_index = 1;
        config.settings.ui.active_conversation_index = 0;

        let app = App::new(config);

        assert_eq!(app.workspace.browser_tabs.len(), 2);
        assert_eq!(app.workspace.active_browser, 1);
        assert_eq!(app.active_browser_tab().title, "Two");
        assert_eq!(
            app.active_browser_tab().session.history,
            vec![
                "mock.node:/one.mu".to_string(),
                "mock.node:/two.mu".to_string()
            ]
        );
        assert_eq!(app.active_browser_tab().session.history_index, 1);
        assert_eq!(app.active_browser_tab().scroll.offset, 4);
        assert_eq!(
            app.active_browser_tab()
                .focused_link
                .as_ref()
                .map(|link| link.target.as_str()),
            Some("mock.node:/later.mu")
        );
        assert_eq!(app.workspace.conversations.len(), 1);
        assert_eq!(app.active_conversation().peer_hash, "lxmf@abc");
        assert_eq!(app.active_conversation().draft_title, "draft");
        assert_eq!(app.active_conversation().draft_body, "body");
        assert_eq!(
            app.active_conversation().delivery_mode,
            DeliveryMode::Propagated
        );
        assert!(app.active_conversation().include_ticket);
        assert!(app.active_conversation().pending_send.is_none());
    }

