    #[test]
    fn masked_browser_fields_persist_only_for_trusted_nodes_when_policy_allows_it() {
        let mut config = test_config("form-state-sensitive-trusted");
        config.settings.browser_form_state.sensitive_fields =
            SensitiveFormPersistence::TrustedNodes;
        let mut app = App::new(config);
        app.directory_service
            .ingest_announce("mock.node", "Mock Node", DirectoryKind::Node, None, None)
            .expect("announce");
        app.directory_service
            .set_trust_level("mock.node", TrustLevel::Trusted)
            .expect("trust");
        let page = BrowserPage {
            url: "mock.node:/login.mu".into(),
            title: "Login".into(),
            markup: "`<!|password`seed> `<12|nickname`anon>".into(),
            source: crate::browser::PageSource::Network,
            metadata: BTreeMap::new(),
            request_data: None,
        };
        app.active_browser_tab_mut().session.apply_page(page, true);
        app.sync_browser_tab_from_session(app.workspace.active_browser, None);
        app.active_browser_tab_mut().focused_control = Some(FocusedControl {
            name: "password".into(),
            index: 0,
        });

        assert!(app.activate_focused_browser_control());
        app.edit_address_char('x');
        let form_state =
            BrowserFormStateStore::load_or_default(app.paths.browser_form_state_file.clone())
                .expect("load form state");

        assert_eq!(
            form_state
                .fields_for("mock.node:/login.mu")
                .and_then(|fields| fields.get("password"))
                .map(String::as_str),
            Some("seedx")
        );
        assert_eq!(
            form_state
                .fields_for("mock.node:/login.mu")
                .and_then(|fields| fields.get("nickname"))
                .map(String::as_str),
            Some("anon")
        );
    }

