    #[test]
    fn settings_edit_inputs_commit_theme_home_and_form_max_age() {
        let mut app = App::new(test_config("settings-edit-inputs"));
        app.browser_form_state
            .set_fields_at(
                "mock.node:/old.mu",
                BTreeMap::from([("name".into(), "old".into())]),
                1_000,
            )
            .expect("save old form state");

        app.edit_settings_theme_name();
        assert_eq!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(&InputTarget::SettingsThemeName)
        );
        app.input
            .active
            .as_mut()
            .expect("active input")
            .buffer
            .set_text("amber");
        app.submit_active_input();

        app.edit_settings_default_start_page();
        app.input
            .active
            .as_mut()
            .expect("active input")
            .buffer
            .set_text("mock.node:/custom.mu");
        app.submit_active_input();

        app.edit_settings_browser_form_max_age();
        app.input
            .active
            .as_mut()
            .expect("active input")
            .buffer
            .set_text("1");
        app.submit_active_input();

        let saved = AppSettings::load_or_default(&app.paths.settings_file).expect("load settings");
        assert_eq!(saved.ui.theme_name, "amber");
        assert_eq!(saved.default_start_page, "mock.node:/custom.mu");
        assert_eq!(saved.browser_form_state.max_age_secs, 1);
        assert!(app
            .browser_form_state
            .fields_for("mock.node:/old.mu")
            .is_none());
    }

