    #[test]
    fn settings_runtime_and_sync_actions_persist_safely() {
        let mut app = App::new(test_config("settings-runtime-sync"));

        assert!(app.cycle_runtime_backend_setting());
        #[cfg(feature = "native-reticulum")]
        assert_eq!(
            app.settings.runtime_backend,
            RuntimeBackendSetting::Reticulum
        );
        #[cfg(not(feature = "native-reticulum"))]
        assert_eq!(app.settings.runtime_backend, RuntimeBackendSetting::Auto);
        assert!(app.settings.restart_required);
        assert!(app.cycle_reticulum_instance_mode());
        assert_eq!(
            app.settings.reticulum_instance_mode,
            ReticulumInstanceMode::External
        );
        assert!(app.toggle_announce_on_start());
        assert!(!app.settings.announce_on_start);
        assert!(app.toggle_periodic_lxmf_sync());
        assert!(!app.settings.periodic_lxmf_sync);
        assert!(app.toggle_auto_sync_after_propagation_accept());
        assert!(app.settings.auto_sync_after_propagation_accept);

        app.edit_settings_lxmf_sync_interval();
        assert_eq!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(&InputTarget::SettingsLxmfSyncIntervalSecs)
        );
        app.input
            .active
            .as_mut()
            .expect("active input")
            .buffer
            .set_text("120");
        app.submit_active_input();

        app.edit_settings_lxmf_sync_limit();
        app.input
            .active
            .as_mut()
            .expect("active input")
            .buffer
            .set_text("3");
        app.submit_active_input();

        let saved = AppSettings::load_or_default(&app.paths.settings_file).expect("load settings");
        #[cfg(feature = "native-reticulum")]
        assert_eq!(saved.runtime_backend, RuntimeBackendSetting::Reticulum);
        #[cfg(not(feature = "native-reticulum"))]
        assert_eq!(saved.runtime_backend, RuntimeBackendSetting::Auto);
        assert_eq!(
            saved.reticulum_instance_mode,
            ReticulumInstanceMode::External
        );
        assert!(!saved.announce_on_start);
        assert!(!saved.periodic_lxmf_sync);
        assert!(saved.auto_sync_after_propagation_accept);
        assert_eq!(saved.lxmf_sync_interval, 120);
        assert_eq!(saved.lxmf_sync_limit, 3);
        assert!(saved.restart_required);
    }

