    #[test]
    fn native_reticulum_readiness_reports_compiled_configured_and_issue_state() {
        let mut app = App::new(test_config("native-readiness"));
        let readiness = app.native_reticulum_readiness();

        assert_eq!(readiness.compiled, cfg!(feature = "native-reticulum"));
        assert_eq!(readiness.ready, cfg!(feature = "native-reticulum"));
        if cfg!(feature = "native-reticulum") {
            assert!(readiness.configured);
            assert!(readiness.summary.contains("compiled and configured"));
        } else {
            assert!(readiness
                .issues
                .iter()
                .any(|issue| issue.contains("native-reticulum feature is not compiled")));
        }

        app.settings.identity_path = Some(app.paths.root.join("missing-identity"));
        let readiness = app.native_reticulum_readiness();
        assert!(!readiness.configured);
        assert!(!readiness.ready);
        assert!(readiness
            .issues
            .iter()
            .any(|issue| issue.contains("identity path is not an existing file")));
    }

