    #[test]
    fn native_interface_readiness_identifies_blocking_profiles() {
        let mut app = App::new(test_config("native-interface-readiness"));
        let mut disabled_rnode = app
            .interface_service
            .create(InterfaceKind::RNode)
            .expect("create rnode");
        disabled_rnode.enabled = false;
        app.interface_service
            .update(disabled_rnode)
            .expect("disable rnode");
        let enabled_i2p = app
            .interface_service
            .create(InterfaceKind::I2p)
            .expect("create i2p");

        let readiness = app.native_interface_readiness();

        assert!(readiness
            .iter()
            .any(|detail| detail.kind == "auto" && detail.supported));
        assert!(readiness.iter().any(|detail| {
            detail.profile_id == enabled_i2p.profile_id
                && !detail.supported
                && detail.blocks_native_startup
                && detail.reason.contains("not wired")
        }));
        assert!(readiness.iter().any(|detail| {
            detail.name == "RNode" && !detail.enabled && !detail.blocks_native_startup
        }));
    }

