    #[test]
    fn interface_toggle_enabled_updates_readiness_and_state() {
        let mut app = App::new(test_config("interface-toggle-enabled"));
        let i2p = app
            .interface_service
            .create(InterfaceKind::I2p)
            .expect("create i2p");
        app.refresh_panels_from_services();
        let index = app
            .interfaces_state
            .profiles
            .iter()
            .position(|profile| profile.profile_id == i2p.profile_id)
            .expect("i2p visible");
        app.select_interface_profile(index);

        assert!(app
            .native_interface_readiness()
            .iter()
            .any(|detail| detail.profile_id == i2p.profile_id && detail.blocks_native_startup));

        assert!(app.toggle_selected_interface_enabled());
        let updated = app
            .interfaces_state
            .profiles
            .iter()
            .find(|profile| profile.profile_id == i2p.profile_id)
            .expect("updated profile");
        assert!(!updated.enabled);
        assert!(app.status.task.contains("disabled"));
        assert!(app.native_interface_readiness().iter().any(|detail| {
            detail.profile_id == i2p.profile_id && !detail.blocks_native_startup
        }));
        let rendered = std::fs::read_to_string(app.interface_service.config_path())
            .expect("applied disabled interface config");
        assert!(rendered.contains("enabled = No"));

        assert!(app.toggle_selected_interface_enabled());
        let updated = app
            .interfaces_state
            .profiles
            .iter()
            .find(|profile| profile.profile_id == i2p.profile_id)
            .expect("updated profile");
        assert!(updated.enabled);
        let rendered = std::fs::read_to_string(app.interface_service.config_path())
            .expect("applied enabled interface config");
        assert!(rendered.contains("enabled = Yes"));
    }

    #[test]
    fn interface_tcp_client_endpoint_edits_validate_persist_and_apply_config() {
        let mut app = App::new(test_config("interface-tcp-edits"));
        let mut tcp = app
            .interface_service
            .create(InterfaceKind::TcpClient)
            .expect("create tcp");
        tcp.target_host = "old.example".into();
        app.interface_service.update(tcp.clone()).expect("seed tcp");
        app.refresh_panels_from_services();
        let index = app
            .interfaces_state
            .profiles
            .iter()
            .position(|profile| profile.profile_id == tcp.profile_id)
            .expect("tcp visible");
        app.select_interface_profile(index);

        assert!(app.edit_selected_interface_tcp_host());
        assert_eq!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(&InputTarget::InterfaceField {
                profile_id: tcp.profile_id.clone(),
                field: InterfaceEditField::TcpHost,
            })
        );
        app.input
            .active
            .as_mut()
            .expect("active host input")
            .buffer
            .set_text("new.example");
        app.submit_active_input();

        let updated = app
            .interface_service
            .get(&tcp.profile_id)
            .expect("updated tcp");
        assert_eq!(updated.target_host, "new.example");
        assert!(app.status.task.contains("updated TCP gateway host"));

        assert!(app.edit_selected_interface_tcp_port());
        app.input
            .active
            .as_mut()
            .expect("active port input")
            .buffer
            .set_text("0");
        app.submit_active_input();
        assert_eq!(
            app.interface_service
                .get(&tcp.profile_id)
                .expect("tcp after invalid port")
                .target_port,
            4242
        );
        assert!(app.status.task.contains("1-65535"));

        assert!(app.edit_selected_interface_tcp_port());
        app.input
            .active
            .as_mut()
            .expect("active port input")
            .buffer
            .set_text("4243");
        app.submit_active_input();
        let updated = app
            .interface_service
            .get(&tcp.profile_id)
            .expect("updated tcp port");
        assert_eq!(updated.target_port, 4243);
        let rendered = std::fs::read_to_string(app.paths.reticulum_config_dir.join("config"))
            .expect("managed config");
        assert!(rendered.contains("target_host = new.example"));
        assert!(rendered.contains("target_port = 4243"));
    }

