    #[test]
    fn interface_create_and_delete_are_persisted_guarded_and_applied() {
        let mut app = App::new(test_config("interface-create-delete"));
        app.refresh_panels_from_services();
        let starting_len = app.interfaces_state.profiles.len();

        assert!(app.create_tcp_client_interface_profile());
        assert_eq!(app.interfaces_state.profiles.len(), starting_len + 1);
        assert_eq!(app.interfaces_state.selected, Some(0));
        let created = app.interfaces_state.profiles[0].clone();
        assert_eq!(created.kind, InterfaceKind::TcpClient);
        let rendered = std::fs::read_to_string(app.paths.reticulum_config_dir.join("config"))
            .expect("managed config after create");
        assert!(rendered.contains("type = TCPClientInterface"));

        assert!(app.begin_selected_interface_delete_flow());
        assert_eq!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(&InputTarget::InterfaceDeleteConfirm {
                profile_id: created.profile_id.clone(),
            })
        );
        app.input
            .active
            .as_mut()
            .expect("active delete input")
            .buffer
            .set_text("no");
        app.submit_active_input();
        assert!(app.interface_service.get(&created.profile_id).is_some());
        assert!(app.status.task.contains("cancelled"));

        assert!(app.begin_selected_interface_delete_flow());
        assert_eq!(
            app.pending_interface_delete_profile()
                .as_ref()
                .map(|profile| profile.profile_id.as_str()),
            Some(created.profile_id.as_str())
        );
        assert!(app.cancel_pending_interface_delete());
        assert!(app.input.active.is_none());
        assert!(app.interface_service.get(&created.profile_id).is_some());
        assert!(app.status.task.contains("cancelled"));

        assert!(app.begin_selected_interface_delete_flow());
        assert!(app.confirm_pending_interface_delete());
        assert!(app.interface_service.get(&created.profile_id).is_none());
        assert!(app.input.active.is_none());
        assert_eq!(app.interfaces_state.profiles.len(), starting_len);
        assert!(app.status.task.contains("deleted interface"));

        assert!(!app.begin_selected_interface_delete_flow());
        assert!(app.status.task.contains("last interface"));
    }

    #[test]
    fn gateway_presets_create_native_tcp_client_profiles_in_browser() {
        let mut app = App::new(test_config("gateway-preset-create"));
        app.refresh_panels_from_services();
        let starting_len = app.interfaces_state.profiles.len();

        assert!(app.create_rmap_gateway_interface_profile());
        assert_eq!(app.interfaces_state.profiles.len(), starting_len + 1);
        let rmap = app.interfaces_state.profiles[0].clone();
        assert_eq!(rmap.kind, InterfaceKind::TcpClient);
        assert_eq!(rmap.name, "RMAP");
        assert_eq!(rmap.target_host, "rmap.world");
        assert_eq!(rmap.target_port, 4242);
        assert!(app.status.task.contains("created RMAP gateway"));

        assert!(app.create_wns_gateway_interface_profile());
        let wns = app.interfaces_state.profiles[0].clone();
        assert_eq!(wns.kind, InterfaceKind::TcpClient);
        assert_eq!(wns.name, "WNS");
        assert_eq!(wns.target_host, "107.175.67.46");
        assert_eq!(wns.target_port, 4242);

        let rendered = std::fs::read_to_string(app.paths.reticulum_config_dir.join("config"))
            .expect("managed config after gateway create");
        assert!(rendered.contains("[[RMAP]]"));
        assert!(rendered.contains("target_host = rmap.world"));
        assert!(rendered.contains("[[WNS]]"));
        assert!(rendered.contains("target_host = 107.175.67.46"));

        let len_after_presets = app.interfaces_state.profiles.len();
        assert!(app.toggle_selected_interface_enabled());
        assert!(!app.interfaces_state.profiles[0].enabled);
        assert!(app.status.task.contains("restart recommended"));

        assert!(app.create_wns_gateway_interface_profile());
        assert_eq!(app.interfaces_state.profiles.len(), len_after_presets);
        assert!(app.interfaces_state.profiles[0].enabled);
        assert!(app.status.task.contains("enabled WNS gateway"));

        assert!(app.create_wns_gateway_interface_profile());
        assert_eq!(app.interfaces_state.profiles.len(), len_after_presets);
        assert!(app.status.task.contains("already enabled"));
    }

