    #[tokio::test]
    async fn launch_bootstrap_creates_and_attaches_managed_identity() {
        let mut app = App::new(test_config("launch-bootstrap-identity"));

        assert!(app.settings.identity_path.is_none());
        assert!(app.bootstrap_runtime_on_launch());

        let identity_path = app
            .settings
            .identity_path
            .as_ref()
            .expect("identity path configured");
        assert!(identity_path.is_file());
        assert_eq!(
            app.settings.active_identity_label.as_deref(),
            Some("OMEN Identity")
        );
        assert!(app.status.identity.contains("OMEN Identity"));

        for _ in 0..10 {
            if app.drain_internal_events() > 0 {
                break;
            }
            tokio::task::yield_now().await;
        }
        assert!(app.runtime_status.active_identity.is_some());
        assert!(app.logs.entries.iter().any(|entry| {
            entry.source == LogSource::Runtime
                && entry.message.contains("launch bootstrap starting")
        }));
        assert!(app.logs.entries.iter().any(|entry| {
            entry.source == LogSource::Runtime
                && entry
                    .message
                    .contains("launch bootstrap using mock runtime")
        }));
        assert!(app.logs.entries.iter().any(|entry| {
            entry.source == LogSource::Runtime
                && entry.message.contains("attaching launch identity")
        }));
    }

