    #[test]
    fn duplicate_interface_names_surface_warning_without_blocking_save() {
        let mut app = App::new(test_config("interface-duplicate-names"));
        app.create_tcp_client_interface_profile();
        let first_id = app.interfaces_state.profiles[0].profile_id.clone();
        app.create_tcp_client_interface_profile();
        let second_id = app.interfaces_state.profiles[0].profile_id.clone();

        assert!(app.edit_selected_interface_name());
        app.input
            .active
            .as_mut()
            .expect("active rename input")
            .buffer
            .set_text("Shared Name");
        app.submit_active_input();

        let first_index = app
            .interfaces_state
            .profiles
            .iter()
            .position(|profile| profile.profile_id == first_id)
            .expect("first profile visible");
        app.select_interface_profile(first_index);
        assert!(app.edit_selected_interface_name());
        app.input
            .active
            .as_mut()
            .expect("active rename input")
            .buffer
            .set_text("Shared Name");
        app.submit_active_input();

        let readiness = app.native_interface_readiness();
        let duplicate_warnings = readiness
            .iter()
            .filter(|detail| {
                (detail.profile_id == first_id || detail.profile_id == second_id)
                    && detail
                        .warnings
                        .iter()
                        .any(|warning| warning.contains("duplicate interface name"))
            })
            .count();

        assert_eq!(duplicate_warnings, 2);
        assert!(readiness
            .iter()
            .filter(|detail| detail.profile_id == first_id || detail.profile_id == second_id)
            .all(|detail| !detail.blocks_native_startup));
        app.refresh_diagnostics_summary();
        assert!(app
            .diagnostics_state
            .last_snapshot
            .as_deref()
            .expect("diagnostics summary")
            .contains("duplicate_interface_names=2"));
    }

    #[test]
    fn managed_reticulum_config_preview_and_export_use_generated_config() {
        let mut app = App::new(test_config("interface-config-preview-export"));
        assert!(app.create_tcp_client_interface_profile());
        let profile_id = app.interfaces_state.profiles[0].profile_id.clone();

        let profile = app
            .interface_service
            .get(&profile_id)
            .expect("created tcp profile");
        let mut profile = profile.clone();
        profile.name = "Preview TCP".into();
        profile.target_host = "node.example".into();
        profile.target_port = 4243;
        app.interface_service
            .update(profile)
            .expect("profile update");
        app.refresh_panels_from_services();

        assert!(app.preview_managed_reticulum_config());
        let preview = app
            .interfaces_state
            .config_preview
            .as_ref()
            .expect("previewed config");
        assert!(preview.contains("[[Preview TCP]]"));
        assert!(preview.contains("target_host = node.example"));
        assert!(preview.contains("target_port = 4243"));
        assert!(!preview.to_lowercase().contains("identity"));
        assert!(app
            .status
            .task
            .contains("previewed managed Reticulum config"));

        assert!(app.export_managed_reticulum_config());
        let path = app
            .interfaces_state
            .last_config_export_path
            .clone()
            .expect("export path");
        assert!(path.starts_with(&app.paths.diagnostics_dir));
        assert!(path
            .file_name()
            .and_then(|name| name.to_str())
            .is_some_and(
                |name| name.starts_with("managed-reticulum-config-") && name.ends_with(".conf")
            ));
        let exported = std::fs::read_to_string(path).expect("exported config");
        assert_eq!(exported, app.interface_service.render_config_for_apply());
        assert!(!exported.to_lowercase().contains("identity"));
        assert!(app
            .status
            .task
            .contains("exported managed Reticulum config"));
    }

