    #[tokio::test]
    async fn diagnostics_bundle_export_includes_redacted_snapshot_readiness_and_generated_config() {
        let mut config = test_config("diagnostics-bundle-export");
        let identity_path = config.paths.root.join("secret-identity-file");
        config.settings.identity_path = Some(identity_path.clone());
        let mut app = App::new(config);
        assert!(app.create_tcp_client_interface_profile());
        let profile_id = app.interfaces_state.profiles[0].profile_id.clone();

        let profile = app
            .interface_service
            .get(&profile_id)
            .expect("created tcp profile");
        let mut profile = profile.clone();
        profile.name = "Diagnostics TCP".into();
        app.interface_service
            .update(profile)
            .expect("profile update");
        app.refresh_panels_from_services();
        app.logs.push(
            LogSeverity::Warn,
            format!("identity path warning: {}", identity_path.display()),
        );
        app.logs
            .push(LogSeverity::Info, "message body: secret message text");

        let bundle = app.redacted_diagnostics_bundle();
        let bundle_text = serde_json::to_string(&bundle).expect("bundle serializes");
        assert!(bundle_text.contains("Diagnostics TCP"));
        assert!(bundle_text.contains("generated_reticulum_config"));
        assert!(bundle_text.contains("recent_logs"));
        assert!(bundle_text.contains("<identity-path>"));
        assert!(bundle_text.contains("<redacted message body log>"));
        assert!(!bundle_text.contains(&identity_path.display().to_string()));
        assert!(!bundle_text.contains("secret message text"));
        assert_eq!(
            bundle["interfaces"]["generated_reticulum_config"]["content"],
            app.interface_service.render_config()
        );
        assert!(app
            .native_lxmf_sdk_rpc_probe_line()
            .contains("not collected"));

        assert!(app.export_diagnostics_bundle());
        assert!(app.diagnostics_export_pending());
        assert!(!app.export_diagnostics_bundle());
        assert!(app.status.task.contains("already pending"));
        assert!(app.wait_for_diagnostics_task_result().await);
        assert!(!app.diagnostics_export_pending());
        let path = app
            .diagnostics_state
            .last_export_path
            .clone()
            .expect("diagnostics export path");
        assert!(path.starts_with(&app.paths.diagnostics_dir));
        assert!(
            path.file_name()
                .and_then(|name| name.to_str())
                .is_some_and(
                    |name| name.starts_with("diagnostics-bundle-") && name.ends_with(".json")
                )
        );
        let exported = std::fs::read_to_string(path).expect("exported diagnostics bundle");
        assert!(exported.contains("Diagnostics TCP"));
        assert!(exported.contains("<identity-path>"));
        assert!(exported.contains("recent_logs"));
        assert!(exported.contains("Warn"));
        assert!(exported.contains("<redacted message body log>"));
        assert!(exported.contains("diagnostics_service_snapshot"));
        assert!(exported.contains("interface_stats"));
        assert!(exported.contains("propagation_status"));
        assert!(exported.contains("native_lxmf_sdk_rpc_probe"));
        assert!(exported.contains("cache_files"));
        assert!(!exported.contains(&identity_path.display().to_string()));
        assert!(!exported.contains("secret message text"));
        assert!(app
            .diagnostics_state
            .last_lxmf_sdk_rpc_probe
            .as_ref()
            .is_some_and(|probe| probe.state == "disabled"));
        assert!(app
            .native_lxmf_sdk_rpc_probe_line()
            .contains("state=disabled"));
        assert!(app
            .diagnostics_state
            .last_export_summary
            .as_deref()
            .expect("export summary")
            .contains("config_lines="));
        assert_eq!(app.workspace.active_section, WorkspaceSection::Diagnostics);
        assert!(app.status.task.contains("exported diagnostics bundle"));
    }

    #[test]
    fn diagnostics_preview_renders_scrolls_and_clears_redacted_bundle() {
        let mut config = test_config("diagnostics-preview");
        let identity_path = config.paths.root.join("secret-preview-identity");
        config.settings.identity_path = Some(identity_path.clone());
        let mut app = App::new(config);
        assert!(app.create_tcp_client_interface_profile());
        app.logs.push(
            LogSeverity::Error,
            format!("preview identity path: {}", identity_path.display()),
        );
        app.logs
            .push(LogSeverity::Info, "draft body: should not export");

        assert!(app.preview_diagnostics_bundle());
        assert_eq!(app.workspace.active_section, WorkspaceSection::Diagnostics);
        assert_eq!(app.diagnostics_state.preview_scroll, 0);
        assert!(!app.diagnostics_state.preview_lines.is_empty());
        let preview = app.diagnostics_state.preview_lines.join("\n");
        assert!(preview.contains("generated_reticulum_config"));
        assert!(preview.contains("recent_logs"));
        assert!(preview.contains("<identity-path>"));
        assert!(preview.contains("<redacted message body log>"));
        assert!(!preview.contains(&identity_path.display().to_string()));
        assert!(!preview.contains("should not export"));
        assert!(app.status.task.contains("previewed diagnostics bundle"));

        assert_eq!(app.scroll_diagnostics_preview_lines(3), 3);
        assert_eq!(app.scroll_diagnostics_preview_lines(-1), 2);
        assert_eq!(
            app.scroll_diagnostics_preview_page(1000, 1),
            app.diagnostics_state.preview_lines.len().saturating_sub(1)
        );
        assert_eq!(app.scroll_diagnostics_preview_page(1000, -1), 0);

        assert!(app.clear_diagnostics_preview());
        assert!(app.diagnostics_state.preview_lines.is_empty());
        assert_eq!(app.diagnostics_state.preview_scroll, 0);
        assert!(app.status.task.contains("cleared diagnostics preview"));
        assert!(!app.clear_diagnostics_preview());
    }

