    #[tokio::test]
    async fn known_destinations_preload_flow_validates_path_and_rechecks_active_destination() {
        let mut app = App::new(test_config("known-destinations-preload-flow"));
        app.active_browser_tab_mut().address_input = "0123456789abcdef:/".into();

        assert!(app.begin_known_destinations_preload_flow());
        assert_eq!(app.workspace.active_section, WorkspaceSection::Diagnostics);
        assert!(matches!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(InputTarget::DiagnosticsKnownDestinationsPath)
        ));

        app.input
            .active
            .as_mut()
            .expect("active input")
            .buffer
            .set_text(app.paths.root.join("missing-known").display().to_string());
        app.submit_active_input();
        assert!(app.status.task.contains("must be an existing file"));

        let known_path = app.paths.root.join("known_destinations");
        std::fs::write(&known_path, b"not a real cache").expect("known file");
        assert!(app.begin_known_destinations_preload_flow());
        app.input
            .active
            .as_mut()
            .expect("active input")
            .buffer
            .set_text(known_path.display().to_string());
        app.submit_active_input();
        assert!(app.status.task.contains("preloading known_destinations"));
        assert!(app.wait_for_diagnostics_task_result().await);
        assert!(app.status.task.contains("known_destinations preload"));
        assert!(app
            .diagnostics_state
            .preview_lines
            .join("\n")
            .contains("\"known_destinations_preload\""));
        assert_eq!(
            app.active_browser_tab()
                .probe_summary
                .as_ref()
                .expect("probe summary")
                .status,
            "path known"
        );
        assert!(app
            .logs
            .entries
            .iter()
            .any(|entry| entry.message.contains("preload generation")));
    }

