    #[test]
    fn auto_sync_after_propagation_acceptance_is_disabled_by_default() {
        let mut app = App::new(test_config("auto-prop-sync-disabled"));
        let evidence = LxmfDeliveryEvidence {
            peer_hash: "peer".into(),
            message_id: Some("prop-a".into()),
            kind: LxmfDeliveryEvidenceKind::PropagationNodeAccepted,
            detail: Some("propagation_node:fedcba98765432100123456789abcdef".into()),
            rtt: None,
            observed_at: Some(1.0),
        };

        assert!(!app.maybe_auto_sync_after_propagation_acceptance_at(&evidence, 1_000));
        assert!(app.propagation_sync_pending.is_none());
        assert_eq!(app.next_lxmf_auto_propagation_sync_epoch_ms, 0);
    }

    #[tokio::test]
    async fn auto_sync_after_propagation_acceptance_queues_throttled_sync_when_enabled() {
        let mut config = test_config("auto-prop-sync-enabled");
        config.settings.auto_sync_after_propagation_accept = true;
        config.settings.lxmf_sync_interval = 45;
        let mut app = App::new(config);
        let evidence = LxmfDeliveryEvidence {
            peer_hash: "peer".into(),
            message_id: Some("prop-a".into()),
            kind: LxmfDeliveryEvidenceKind::PropagationNodeAccepted,
            detail: Some("propagation_node:fedcba98765432100123456789abcdef".into()),
            rtt: None,
            observed_at: Some(1.0),
        };

        assert!(app.maybe_auto_sync_after_propagation_acceptance_at(&evidence, 1_000));
        assert!(app.propagation_sync_pending.is_some());
        assert_eq!(app.next_lxmf_auto_propagation_sync_epoch_ms, 46_000);
        assert!(!app.maybe_auto_sync_after_propagation_acceptance_at(&evidence, 2_000));
    }

