    #[test]
    fn runtime_outbound_status_before_sent_row_is_deferred_and_reconciled() {
        let mut app = App::new(test_config("deferred-outbound-status"));
        let conversation_id = app.active_conversation().id;
        app.active_conversation_mut_for_test().peer_hash = "peer".into();
        app.active_conversation_mut_for_test().peer_label = "Peer".into();
        app.active_conversation_mut_for_test().pending_send =
            Some(MessageSendState { generation: 9 });

        assert!(app.handle_runtime_bus_event(
            crate::runtime::RuntimeBusEvent::MessageDeliveryUpdated(OutboundStatus {
                peer_hash: "peer".into(),
                message_id: Some("packet-early".into()),
                delivered: true,
                failed: false,
                state: OutboundDeliveryState::Delivered,
                evidence: Some("rns_packet_proof".into()),
                rtt: Some(0.333),
            })
        ));
        assert!(!app
            .logs
            .lines
            .iter()
            .any(|line| line.contains("deferred outbound message status")));

        let sent = MessageSummary {
            peer_hash: "peer".into(),
            peer_label: "Peer".into(),
            title: "Subject".into(),
            content: "Body".into(),
            timestamp: 1.0,
            transport_method: TransportMethod::Direct,
            delivered: false,
            failed: false,
            incoming: false,
            unread: false,
            message_id: Some("packet-early".into()),
            fields: BTreeMap::from([("native_lxmf_state".into(), "submitted_to_rns_net".into())]),
            attachments: Vec::new(),
        };
        app.message_store
            .append(sent.clone())
            .expect("store sent row");

        assert!(app.apply_message_task_result(MessageTaskResult::Sent {
            conversation_id,
            generation: 9,
            message: sent,
        }));

        let visible = app.active_conversation();
        assert!(visible.thread.messages[0].delivered);
        assert_eq!(
            visible.thread.messages[0]
                .fields
                .get("native_lxmf_state")
                .map(String::as_str),
            Some("delivered")
        );
        assert_eq!(
            visible.thread.messages[0]
                .fields
                .get("native_lxmf_rtt")
                .map(String::as_str),
            Some("0.333")
        );
        let stored = app.message_store.get_thread("peer").expect("stored thread");
        assert!(stored.messages[0].delivered);
    }

