    #[test]
    fn live_smoke_stage_subreport_reports_full_live_success() {
        let live_probe = serde_json::json!({
            "ok": true,
            "report": PageFetchProbeReport {
                backend: RuntimeBackendName::Reticulum,
                url: fixture_node_url(),
                destination_hash: Some(FIXTURE_NODE_HASH.into()),
                path: Some("/".into()),
                execute_request: true,
                ready_to_request: true,
                steps: vec![
                    PageFetchProbeStep::ok(PageFetchProbeStage::AddressParse, "parsed"),
                    PageFetchProbeStep::ok(PageFetchProbeStage::RuntimeSetup, "running"),
                    PageFetchProbeStep::ok(PageFetchProbeStage::DestinationIdentity, "known"),
                    PageFetchProbeStep::ok(PageFetchProbeStage::PathDiscovery, "path known"),
                    PageFetchProbeStep::ok(PageFetchProbeStage::LinkSetup, "link created"),
                    PageFetchProbeStep::ok(PageFetchProbeStage::RequestSend, "request sent"),
                    PageFetchProbeStep::ok(PageFetchProbeStage::ResponseWait, "response received"),
                    PageFetchProbeStep::ok(PageFetchProbeStage::ResponseDecode, "decoded"),
                ],
            },
        });

        let report = live_smoke_stage_subreport(&live_probe, true);

        assert_eq!(
            report.get("status").and_then(serde_json::Value::as_str),
            Some("pass")
        );
        assert_eq!(
            report
                .get("preconditions")
                .and_then(|value| value.get("destination_identity_known"))
                .and_then(serde_json::Value::as_bool),
            Some(true)
        );
        assert!(report
            .get("stages")
            .and_then(serde_json::Value::as_array)
            .expect("stages")
            .iter()
            .all(|stage| stage.get("status").and_then(serde_json::Value::as_str) == Some("pass")));
    }

