    #[test]
    fn native_browser_load_failure_updates_path_discovery_summary() {
        let mut app = App::new(test_config("native-load-probe-hint"));
        app.switch_section(WorkspaceSection::Browser);
        let tab_id = app.active_browser_tab().id;
        app.active_browser_tab_mut().loading = Some(LoadState {
            generation: 7,
            target: fixture_node_url(),
            submitted_fields: false,
            cancel: CancellationToken::new(),
        });

        assert!(app.apply_browser_task_result(BrowserTaskResult::Error {
            tab_id,
            generation: 7,
            message: format!("native Reticulum page fetch failed for {FIXTURE_NODE_HASH} during destination identity: destination signing public key is not known"),
        }));

        assert!(app.status.task.contains("Diagnostics D"));
        let summary = app
            .active_browser_tab()
            .probe_summary
            .as_ref()
            .expect("probe hint summary");
        assert_eq!(summary.mode, "path-discovery");
        assert_eq!(summary.status, "identity unknown");
        assert_eq!(summary.url, fixture_node_url());
        assert!(summary.detail.contains("identity"));
        assert!(summary.detail.contains("Diagnostics D"));
        let warning = app
            .active_browser_live_warning()
            .expect("stale page live warning");
        assert_eq!(warning.target, fixture_node_url());
        assert!(warning
            .visible_page
            .as_deref()
            .is_some_and(|page| page.contains("mock")));
        assert!(warning
            .message
            .contains("native Reticulum page fetch failed"));
        assert!(warning.next_action.contains("Diagnostics D"));
        let overlay = app.browser_status_overlay();
        assert!(overlay
            .lines
            .iter()
            .any(|line| line.contains("page probe: path-discovery identity unknown")));
        assert!(app.logs.lines.iter().any(|line| {
            line.contains("browser-load page probe step")
                && line.contains(&format!("destination={FIXTURE_NODE_HASH}"))
                && line.contains("suggested_action=run Diagnostics D for path state")
        }));
    }

    #[test]
    fn native_browser_load_failure_reports_exact_link_request_response_stage() {
        let cases = [
            (
                format!("native Reticulum page fetch failed for {FIXTURE_NODE_HASH} during link setup: Reticulum 0.6 failed to create page request link"),
                PageFetchProbeStage::LinkSetup,
                "native-load",
                "link setup failed",
                "link/request/response report",
            ),
            (
                format!("native Reticulum page fetch failed for {FIXTURE_NODE_HASH} during request send: clean Reticulum request send failed"),
                PageFetchProbeStage::RequestSend,
                "native-load",
                "request send failed",
                "link/request/response report",
            ),
            (
                format!("native Reticulum page fetch failed for {FIXTURE_NODE_HASH} during response wait: timed out waiting for clean Reticulum page response"),
                PageFetchProbeStage::ResponseWait,
                "native-load",
                "response wait failed",
                "link/request/response report",
            ),
            (
                format!("native Reticulum page fetch failed for {FIXTURE_NODE_HASH} during response decode: page body was not UTF-8"),
                PageFetchProbeStage::ResponseDecode,
                "native-load",
                "response decode failed",
                "link/request/response report",
            ),
        ];

        for (message, stage, mode, status, status_action) in cases {
            let mut app = App::new(test_config(&format!("native-load-stage-{status}")));
            app.switch_section(WorkspaceSection::Browser);
            app.runtime_status.connected = false;
            let tab_id = app.active_browser_tab().id;
            app.active_browser_tab_mut().loading = Some(LoadState {
                generation: 9,
                target: fixture_node_url(),
                submitted_fields: false,
                cancel: CancellationToken::new(),
            });

            assert!(app.apply_browser_task_result(BrowserTaskResult::Error {
                tab_id,
                generation: 9,
                message,
            }));

            let summary = app
                .active_browser_tab()
                .probe_summary
                .as_ref()
                .expect("probe summary");
            assert_eq!(summary.mode, mode);
            assert_eq!(summary.status, status);
            assert!(summary
                .detail
                .contains(page_fetch_probe_stage_label(&stage)));
            assert!(app.status.task.contains(status_action));
            assert!(app.logs.lines.iter().any(|line| {
                line.contains("browser-load page probe step")
                    && line.contains(page_fetch_probe_stage_label(&stage))
                    && line.contains("suggested_action=run Diagnostics X or L")
            }));
        }
    }

    #[tokio::test]
    async fn transient_native_browser_timeout_schedules_one_auto_retry() {
        let mut app = App::new(test_config("native-load-transient-auto-retry"));
        app.switch_section(WorkspaceSection::Browser);
        app.runtime_status.connected = true;
        let tab_id = app.active_browser_tab().id;
        let target = fixture_node_url();
        app.active_browser_tab_mut().loading = Some(LoadState {
            generation: 12,
            target: target.clone(),
            submitted_fields: false,
            cancel: CancellationToken::new(),
        });

        assert!(app.apply_browser_task_result(BrowserTaskResult::Error {
            tab_id,
            generation: 12,
            message: format!("native Reticulum page fetch failed for {FIXTURE_NODE_HASH} during response wait: timed out waiting for clean Reticulum page response"),
        }));

        let retry = app
            .active_browser_tab()
            .retry_state
            .as_ref()
            .expect("retry state");
        assert_eq!(retry.target, target);
        assert_eq!(retry.attempts, 1);
        assert!(retry.ready_epoch_ms.is_some());
        assert!(retry.reason.contains("automatic retry"));
        assert!(app.status.task.contains("retrying once"));

        let mut event =
            tokio::time::timeout(std::time::Duration::from_secs(3), app.event_rx.recv())
                .await
                .expect("scheduled event")
                .expect("event")
                .event;
        while !matches!(
            &event,
            InternalAppEvent::StartupBrowserPathReady { destination, .. }
                if destination == FIXTURE_NODE_HASH
        ) {
            event = tokio::time::timeout(std::time::Duration::from_secs(3), app.event_rx.recv())
                .await
                .expect("scheduled retry event")
                .expect("event")
                .event;
        }
        assert!(matches!(
            &event,
            InternalAppEvent::StartupBrowserPathReady { destination, .. }
                if destination == FIXTURE_NODE_HASH
        ));
        assert!(app.handle_internal_event(event));
        assert_eq!(
            app.active_browser_tab()
                .loading
                .as_ref()
                .map(|loading| loading.target.as_str()),
            Some(target.as_str())
        );
    }

