    #[tokio::test]
    async fn browser_open_preflight_autoloads_when_path_is_already_known() {
        let mut app = App::new(test_config("browser-open-known-path-preflight"));
        app.runtime_status.connected = true;
        let destination = FIXTURE_KNOWN_PATH_HASH;
        let target = format!("{destination}:/page/index.mu");

        app.open_browser_target_at_index(0, target.clone());

        assert!(app.active_browser_tab().loading.is_none());
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let mut saw_path_update = false;
        while std::time::Instant::now() < deadline {
            let Ok(Some(event)) =
                tokio::time::timeout(std::time::Duration::from_millis(250), app.event_rx.recv())
                    .await
            else {
                continue;
            };
            let event = event.event;
            if matches!(
                &event,
                InternalAppEvent::Runtime(crate::runtime::RuntimeBusEvent::PathUpdated(path))
                    if path.destination_hash == destination && path.known
            ) {
                assert!(app.handle_internal_event(event));
                saw_path_update = true;
                break;
            }
            app.handle_internal_event(event);
        }
        assert!(saw_path_update);
        app.active_browser_tab_mut()
            .retry_state
            .as_mut()
            .expect("retry")
            .retry_after_epoch_ms = current_epoch_ms();
        assert!(
            app.handle_internal_event(InternalAppEvent::StartupBrowserPathReady {
                destination: destination.into(),
                target: None,
                requested_epoch_ms: None,
            })
        );

        let loading = app.active_browser_tab().loading.as_ref().expect("loading");
        assert_eq!(loading.target, target);
    }

