    #[test]
    fn browser_path_update_waits_before_clicked_link_autoload() {
        let mut app = App::new(test_config("browser-link-autoload-delay"));
        let destination = FIXTURE_PEER_HASH;
        let target = format!("{destination}:/page/index.mu");
        app.active_browser_tab_mut().retry_state = Some(BrowserRetryState {
            target: target.clone(),
            destination_hash: destination.into(),
            reason: "browser link path request queued; auto-load when path is known".into(),
            requested_epoch_ms: current_epoch_ms(),
            retry_after_epoch_ms: current_epoch_ms().saturating_add(5_000),
            ready_epoch_ms: None,
            attempts: 0,
        });
        app.active_browser_tab_mut().request_preview = Some(BrowserRequestPreview {
            target: target.clone(),
            fields: Vec::new(),
            request_data: BTreeMap::new(),
            status: BrowserRequestStatus::Pending,
            detail: "requesting path before link request".into(),
        });

        let before = current_epoch_ms();
        assert!(
            app.handle_runtime_bus_event(crate::runtime::RuntimeBusEvent::PathUpdated(
                crate::runtime::PathEvent {
                    destination_hash: destination.into(),
                    known: true,
                    hops: Some(1),
                },
            ))
        );

        let retry = app
            .active_browser_tab()
            .retry_state
            .as_ref()
            .expect("retry");
        assert!(retry.ready_epoch_ms.is_some());
        assert!(retry.retry_after_epoch_ms >= before.saturating_add(1_500));
        assert!(retry.retry_after_epoch_ms <= before.saturating_add(2_500));
        assert!(retry.reason.contains("waiting briefly before page load"));
        let preview = app
            .active_browser_tab()
            .request_preview
            .as_ref()
            .expect("request preview");
        assert_eq!(preview.status, BrowserRequestStatus::Pending);
        assert!(preview.detail.contains("waiting briefly before page load"));
    }

