    #[tokio::test]
    async fn startup_path_inspection_autoloads_when_path_is_already_known() {
        let mut app = App::new(test_config("startup-path-known-inspection"));
        let destination = FIXTURE_KNOWN_PATH_HASH;
        let target = format!("{destination}:/page/index.mu");
        app.active_browser_tab_mut().address_input = target.clone();

        assert!(app.queue_startup_path_requests_nonblocking());

        let mut saw_path_update = false;
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(8);
        while std::time::Instant::now() < deadline {
            if let Ok(event) =
                tokio::time::timeout(std::time::Duration::from_millis(500), app.event_rx.recv())
                    .await
            {
                match event.expect("internal event").event {
                    InternalAppEvent::Runtime(crate::runtime::RuntimeBusEvent::PathUpdated(
                        path,
                    )) if path.destination_hash == destination && path.known => {
                        saw_path_update = true;
                        assert!(app.handle_runtime_bus_event(
                            crate::runtime::RuntimeBusEvent::PathUpdated(path)
                        ));
                    }
                    InternalAppEvent::StartupBrowserPathReady {
                        destination,
                        target,
                        requested_epoch_ms,
                    } => {
                        assert!(app.handle_internal_event(
                            InternalAppEvent::StartupBrowserPathReady {
                                destination,
                                target,
                                requested_epoch_ms,
                            }
                        ));
                        break;
                    }
                    InternalAppEvent::StartupPathRequestsComplete { destinations } => {
                        let _ = app.handle_internal_event(
                            InternalAppEvent::StartupPathRequestsComplete { destinations },
                        );
                    }
                    InternalAppEvent::Log(line) => {
                        app.logs
                            .push_with_source(LogSeverity::Info, LogSource::App, line);
                    }
                    other => {
                        let _ = app.handle_internal_event(other);
                    }
                }
            }
        }

        assert!(saw_path_update);
        let loading = app.active_browser_tab().loading.as_ref().expect("loading");
        assert_eq!(loading.target, target);
    }

    #[tokio::test]
    async fn startup_path_completion_autoloads_restored_browser_when_path_event_is_absent() {
        let mut app = App::new(test_config("startup-path-complete-autoload"));
        let destination = FIXTURE_NODE_HASH;
        let target = fixture_node_url();
        let now = current_epoch_ms();
        app.active_browser_tab_mut().address_input = target.clone();
        app.active_browser_tab_mut().retry_state = Some(BrowserRetryState {
            target: target.clone(),
            destination_hash: destination.into(),
            reason: "startup path request queued; auto-load when path is known".into(),
            requested_epoch_ms: now,
            retry_after_epoch_ms: now.saturating_add(5_000),
            ready_epoch_ms: None,
            attempts: 0,
        });

        assert!(
            !app.handle_internal_event(InternalAppEvent::StartupPathRequestsComplete {
                destinations: vec![destination.into()],
            })
        );

        app.active_browser_tab_mut()
            .retry_state
            .as_mut()
            .expect("retry")
            .ready_epoch_ms = Some(current_epoch_ms());
        app.active_browser_tab_mut()
            .retry_state
            .as_mut()
            .expect("retry")
            .retry_after_epoch_ms = current_epoch_ms();
        assert!(
            app.handle_internal_event(InternalAppEvent::StartupPathRequestsComplete {
                destinations: vec![destination.into()],
            })
        );

        let loading = app.active_browser_tab().loading.as_ref().expect("loading");
        assert_eq!(loading.target, target);
        assert!(app
            .active_browser_tab()
            .retry_state
            .as_ref()
            .is_some_and(|state| state.ready_epoch_ms.is_some()));
    }

