    #[test]
    fn structured_logs_persist_rotate_and_filter_by_severity_and_source() {
        let mut app = App::new(test_config("structured-logs"));
        let log_file = app.paths.logs_dir.join("omenbrowser_rs.jsonl");
        assert!(app.flush_structured_logs(Duration::from_secs(2)));
        assert!(log_file.is_file());

        app.logs
            .push_with_source(LogSeverity::Warn, LogSource::Runtime, "runtime warn");
        app.logs
            .push_with_source(LogSeverity::Error, LogSource::Plugin, "plugin error");
        assert!(app.flush_structured_logs(Duration::from_secs(2)));
        let persisted = std::fs::read_to_string(&log_file).expect("structured log file");
        assert!(persisted.contains("\"severity\":\"Warn\""));
        assert!(persisted.contains("\"source\":\"Runtime\""));
        assert!(persisted.contains("plugin error"));

        assert!(app.cycle_log_severity_filter());
        assert_eq!(app.logs.severity_filter, Some(LogSeverity::Debug));
        assert!(app.cycle_log_severity_filter());
        assert_eq!(app.logs.severity_filter, Some(LogSeverity::Info));
        assert!(app.cycle_log_source_filter());
        assert_eq!(app.logs.source_filter, Some(LogSource::App));
        assert!(app.cycle_log_source_filter());
        assert_eq!(app.logs.source_filter, Some(LogSource::Runtime));
        app.logs.severity_filter = Some(LogSeverity::Warn);
        assert!(app
            .logs
            .filtered_entries()
            .iter()
            .any(|entry| entry.message == "runtime warn"));

        app.logs.severity_filter = Some(LogSeverity::Error);
        app.logs.source_filter = Some(LogSource::Plugin);
        assert!(app
            .logs
            .filtered_entries()
            .iter()
            .any(|entry| entry.message == "plugin error"));

        std::fs::write(
            &log_file,
            "x".repeat((STRUCTURED_LOG_DEFAULT_MAX_BYTES + 1) as usize),
        )
        .expect("inflate log file");
        app.logs
            .push_with_source(LogSeverity::Info, LogSource::App, "after rotate");
        assert!(app.flush_structured_logs(Duration::from_secs(2)));
        let rotated = std::fs::read_dir(&app.paths.logs_dir)
            .expect("logs dir")
            .filter_map(Result::ok)
            .filter(|entry| {
                entry.file_name().to_str().is_some_and(|name| {
                    name.starts_with("omenbrowser_rs-") && name.ends_with(".jsonl")
                })
            })
            .count();
        assert!(rotated >= 1);
        let current = std::fs::read_to_string(&log_file).expect("current log after rotate");
        assert!(current.contains("after rotate"));
    }

