    #[cfg(feature = "native-reticulum")]
    #[test]
    fn native_reticulum_selection_requires_confirmation_when_not_ready() {
        let mut app = App::new(test_config("native-reticulum-confirm"));
        app.interface_service
            .create(InterfaceKind::RNode)
            .expect("create unsupported enabled interface");

        assert!(!app.set_runtime_backend_setting(RuntimeBackendSetting::Reticulum));
        assert_eq!(app.settings.runtime_backend, RuntimeBackendSetting::Mock);
        assert_eq!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(&InputTarget::RuntimeBackendConfirm {
                backend: RuntimeBackendSetting::Reticulum
            })
        );
        assert!(app.status.task.contains("submit Reticulum"));

        app.input
            .active
            .as_mut()
            .expect("active confirmation")
            .buffer
            .set_text("no");
        app.submit_active_input();
        assert_eq!(app.settings.runtime_backend, RuntimeBackendSetting::Mock);
        assert!(app.status.task.contains("cancelled"));

        assert!(!app.set_runtime_backend_setting(RuntimeBackendSetting::Reticulum));
        app.input
            .active
            .as_mut()
            .expect("active confirmation")
            .buffer
            .set_text("Reticulum");
        app.submit_active_input();

        assert_eq!(
            app.settings.runtime_backend,
            RuntimeBackendSetting::Reticulum
        );
        assert!(app.settings.restart_required);
    }

