    #[test]
    fn settings_restart_apply_flow_exits_without_hot_swapping_runtime() {
        let mut app = App::new(test_config("settings-restart-apply"));
        let original_backend = app.runtime_status.backend.clone();

        assert!(!app.restart_to_apply_settings());
        assert!(!app.should_quit());
        assert!(app.status.task.contains("no restart-required"));

        assert!(app.cycle_runtime_backend_setting());
        assert_eq!(app.runtime_status.backend, original_backend);
        assert!(app.settings.restart_required);
        assert!(app
            .restart_pending_summary()
            .iter()
            .any(|line| line.contains("runtime backend")));

        assert!(app.restart_to_apply_settings());
        assert!(app.should_quit());
        assert!(app
            .logs
            .lines
            .iter()
            .any(|line| line.contains("exiting to apply settings")));

        let saved = AppSettings::load_or_default(&app.paths.settings_file).expect("load settings");
        assert!(saved.restart_required);
    }

    #[test]
    fn restart_required_flag_clears_after_relaunch_initializes_with_saved_settings() {
        let mut config = test_config("settings-restart-clear-on-start");
        config.settings.runtime_backend = RuntimeBackendSetting::Mock;
        config.settings.restart_required = true;
        config
            .settings
            .save(&config.paths.settings_file)
            .expect("save settings");

        let app = App::new(config);

        assert!(!app.settings.restart_required);
        assert_eq!(app.runtime_status.backend, RuntimeBackendName::Mock);
        assert!(app
            .logs
            .lines
            .iter()
            .any(|line| line.contains("restart-required settings applied")));
        let saved = AppSettings::load_or_default(&app.paths.settings_file).expect("load settings");
        assert!(!saved.restart_required);
    }

