    #[test]
    fn settings_propagation_remote_content_and_paths_persist_safely() {
        let mut app = App::new(test_config("settings-propagation-paths"));
        let identity_path = app.paths.root.join("external_identity");
        std::fs::write(&identity_path, b"identity-material").expect("write identity");
        let config_dir = app.paths.root.join("external-reticulum");
        std::fs::create_dir_all(&config_dir).expect("create config dir");

        app.edit_settings_preferred_propagation();
        assert_eq!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(&InputTarget::SettingsPreferredPropagationNode)
        );
        app.input
            .active
            .as_mut()
            .expect("active input")
            .buffer
            .set_text("prop.hash");
        app.submit_active_input();

        assert!(app.toggle_plugin_remote_content());

        app.edit_settings_identity_path();
        app.input
            .active
            .as_mut()
            .expect("active input")
            .buffer
            .set_text(identity_path.display().to_string());
        app.submit_active_input();

        app.edit_settings_reticulum_config_path();
        app.input
            .active
            .as_mut()
            .expect("active input")
            .buffer
            .set_text(config_dir.display().to_string());
        app.submit_active_input();

        let saved = AppSettings::load_or_default(&app.paths.settings_file).expect("load settings");
        assert_eq!(
            saved.preferred_propagation_node_hash.as_deref(),
            Some("prop.hash")
        );
        assert!(saved.plugins.remote_content_enabled);
        assert_eq!(saved.identity_path.as_ref(), Some(&identity_path));
        assert_eq!(saved.reticulum_config_path.as_ref(), Some(&config_dir));
        assert!(saved.restart_required);
        assert_eq!(
            saved.active_identity_label.as_deref(),
            Some("external_identity")
        );
    }

