    #[test]
    fn settings_selection_moves_and_enter_activates_selected_action() {
        let mut app = App::new(test_config("settings-selection"));
        app.switch_section(WorkspaceSection::Settings);

        assert_eq!(app.settings_state.selected, 0);
        for _ in 0..settings_action_index(SettingsAction::EditFormMaxAge) {
            app.select_next_sidebar_item();
        }
        assert_eq!(
            app.settings_state.selected,
            settings_action_index(SettingsAction::EditFormMaxAge)
        );
        app.activate_workspace_selection();
        assert_eq!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(&InputTarget::SettingsBrowserFormMaxAgeSecs)
        );
        assert_eq!(app.workspace.focus, FocusArea::Command);

        assert!(app.cancel_active_input());
        app.select_previous_sidebar_item();
        assert_eq!(
            app.settings_state.selected,
            settings_action_index(SettingsAction::EditReticulumConfigPath)
        );
        while app.settings_state.selected > 0 {
            app.select_previous_sidebar_item();
        }
        assert_eq!(app.settings_state.selected, 0);
    }

