    #[test]
    fn app_discovers_installed_plugin_manifests_without_enabling_execution() {
        let config = test_config("plugin-discovery");
        let plugin_dir = config.paths.plugins_dir.join("example");
        std::fs::create_dir_all(&plugin_dir).expect("plugin dir");
        std::fs::write(
            plugin_dir.join("plugin.json"),
            r#"{
                "id": "example-plugin",
                "name": "Example Plugin",
                "version": "0.1.0",
                "author": "OMENbrowser",
                "description": "Example",
                "entrypoint": "plugin.py",
                "permissions": ["transform_content"]
            }"#,
        )
        .expect("manifest");

        let app = App::new(config);

        assert!(app
            .plugins_state
            .manifests
            .iter()
            .any(|manifest| manifest.plugin_id == BUILTIN_MICRONPLUS_PLUGIN_ID));
        assert!(app
            .plugins_state
            .manifests
            .iter()
            .any(|manifest| manifest.plugin_id == "example-plugin"));
        assert!(app
            .selected_plugin_detail_lines()
            .iter()
            .any(|line| line.contains("entrypoint: builtin (not executed)")));
    }

    #[test]
    fn plugin_command_flow_installs_refreshes_and_removes_manifest_only() {
        let config = test_config("plugin-command-flow");
        let source = config.paths.root.join("source-plugin");
        std::fs::create_dir_all(&source).expect("source dir");
        std::fs::write(
            source.join("plugin.json"),
            r#"{
                "id": "command-plugin",
                "name": "Command Plugin",
                "version": "0.1.0",
                "author": "OMENbrowser",
                "description": "Command flow",
                "entrypoint": "plugin.py",
                "permissions": ["transform_content"]
            }"#,
        )
        .expect("manifest");
        std::fs::write(
            source.join("plugin.py"),
            "raise RuntimeError('must not run')\n",
        )
        .expect("entrypoint");
        let mut app = App::new(config);

        app.begin_plugin_install_flow();
        assert!(matches!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(InputTarget::PluginInstallPath)
        ));
        app.install_plugin_from_command(format!("trust {}", source.display()));
        assert!(app
            .plugins_state
            .manifests
            .iter()
            .any(|manifest| manifest.plugin_id == "command-plugin"));
        assert!(app
            .settings
            .plugins
            .enabled_plugin_ids
            .contains(&"command-plugin".into()));
        assert!(app
            .paths
            .plugins_dir
            .join("command-plugin")
            .join("plugin.py")
            .exists());

        app.plugins_state.selected = app
            .plugins_state
            .manifests
            .iter()
            .position(|manifest| manifest.plugin_id == "command-plugin");
        assert!(app.begin_selected_plugin_remove_flow());
        assert!(matches!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(InputTarget::PluginRemoveConfirm { plugin_id }) if plugin_id == "command-plugin"
        ));
        assert!(app.remove_plugin_from_command("command-plugin", "command-plugin".into()));
        assert!(!app
            .plugins_state
            .manifests
            .iter()
            .any(|manifest| manifest.plugin_id == "command-plugin"));
        assert!(!app
            .settings
            .plugins
            .enabled_plugin_ids
            .contains(&"command-plugin".into()));
    }

