    #[test]
    fn directory_entries_report_micronplus_trust_state() {
        let mut app = App::new(test_config("directory-micronplus-status"));
        app.directory_service
            .ingest_announce("node.hash", "Node", DirectoryKind::Node, None, None)
            .expect("node announce");
        app.directory_service
            .ingest_announce("peer.hash", "Peer", DirectoryKind::Peer, None, None)
            .expect("peer announce");
        app.refresh_panels_from_services();

        let node = app
            .directory_state
            .entries
            .iter()
            .find(|entry| entry.destination_hash == "node.hash")
            .expect("node entry");
        assert_eq!(
            app.micronplus_status_for_directory_entry(node),
            "MicronPlus: trust required"
        );
        let peer = app
            .directory_state
            .entries
            .iter()
            .find(|entry| entry.destination_hash == "peer.hash")
            .expect("peer entry");
        assert_eq!(
            app.micronplus_status_for_directory_entry(peer),
            "MicronPlus: n/a"
        );

        app.directory_service
            .set_trust_level("node.hash", TrustLevel::Trusted)
            .expect("set trust");
        app.refresh_panels_from_services();
        let node = app
            .directory_state
            .entries
            .iter()
            .find(|entry| entry.destination_hash == "node.hash")
            .expect("node entry");
        assert_eq!(
            app.micronplus_status_for_directory_entry(node),
            "MicronPlus: allowed"
        );
    }

