    #[tokio::test]
    async fn runtime_event_forwarder_routes_announces_into_app_bus() {
        let mut app = App::new(test_config("runtime-forwarder-announce"));
        let (runtime_tx, runtime_rx) = tokio::sync::broadcast::channel(8);
        assert!(spawn_runtime_event_forwarder(
            app.event_tx.clone(),
            runtime_rx
        ));

        runtime_tx
            .send(crate::runtime::RuntimeBusEvent::Announce(
                crate::runtime::AnnouncePayload {
                    destination_hash: "node.forwarded".into(),
                    display_name: "Forwarded Node".into(),
                    kind: DirectoryKind::Node,
                    associated_hash: None,
                    node_associated_hash: None,
                    has_ratchet: false,
                    lxmf_stamp_cost: None,
                },
            ))
            .expect("send runtime event");

        for _ in 0..10 {
            if app.drain_internal_events() > 0 {
                break;
            }
            tokio::task::yield_now().await;
        }

        app.refresh_panels_from_services();
        assert!(app
            .directory_state
            .entries
            .iter()
            .any(|entry| entry.destination_hash == "node.forwarded"));
    }

    #[tokio::test]
    async fn relevant_announces_warm_selected_associated_paths() {
        let mut app = App::new(test_config("announce-warm-selected-associated"));
        app.directory_service
            .ingest_announce(
                "mock.node",
                "Selected Node",
                DirectoryKind::Node,
                None,
                None,
            )
            .expect("selected node");
        app.refresh_panels_from_services();
        app.directory_state.selected = app
            .directory_state
            .entries
            .iter()
            .position(|entry| entry.destination_hash == "mock.node");

        assert!(
            app.enqueue_runtime_event(crate::runtime::RuntimeBusEvent::Announce(
                crate::runtime::AnnouncePayload {
                    destination_hash: "peer.hash".into(),
                    display_name: "Associated Peer".into(),
                    kind: DirectoryKind::Peer,
                    associated_hash: Some("mock.node".into()),
                    node_associated_hash: None,
                    has_ratchet: false,
                    lxmf_stamp_cost: None,
                },
            ))
        );
        assert_eq!(app.drain_internal_events(), 1);
        tokio::task::yield_now().await;
        app.drain_internal_events();

        app.refresh_panels_from_services();
        assert!(app
            .directory_state
            .entries
            .iter()
            .any(|entry| entry.destination_hash == "peer.hash"
                && entry.associated_hash.as_deref() == Some("mock.node")));
        assert!(!app.logs.entries.iter().any(|entry| {
            entry.message.contains("announce path warm")
                && !entry.message.contains("failed")
                && !entry.message.contains("deferred")
        }));
    }

