    #[test]
    fn internal_event_bus_deduplicates_inbound_runtime_messages() {
        let mut app = App::new(test_config("event-message"));
        let message = MessageSummary {
            peer_hash: "peer.hash".into(),
            peer_label: "Peer".into(),
            title: "Hello".into(),
            content: "Body".into(),
            timestamp: 1.0,
            transport_method: TransportMethod::Direct,
            delivered: true,
            failed: false,
            incoming: true,
            unread: true,
            message_id: Some("m1".into()),
            fields: BTreeMap::new(),
            attachments: Vec::new(),
        };

        assert!(
            app.enqueue_runtime_event(crate::runtime::RuntimeBusEvent::MessageReceived(
                message.clone()
            ))
        );
        assert!(
            app.enqueue_runtime_event(crate::runtime::RuntimeBusEvent::MessageReceived(message))
        );
        assert_eq!(app.drain_internal_events(), 2);

        let conversation = app
            .workspace
            .conversations
            .iter()
            .find(|conversation| conversation.peer_hash == "peer.hash")
            .expect("conversation created");
        assert_eq!(conversation.thread.messages.len(), 1);
        assert_eq!(
            app.messaging_service
                .conversation("peer.hash")
                .expect("stored thread")
                .messages
                .len(),
            1
        );
    }

    #[test]
    fn propagation_sync_result_merges_inbound_messages_into_threads() {
        let mut app = App::new(test_config("propagation-sync-merge"));
        app.propagation_sync_pending = Some(7);
        let message = MessageSummary {
            peer_hash: FIXTURE_PROPAGATION_PEER.into(),
            peer_label: "Prop Peer".into(),
            title: "Propagated".into(),
            content: "Hello over propagation".into(),
            timestamp: 2.0,
            transport_method: TransportMethod::Propagated,
            delivered: true,
            failed: false,
            incoming: true,
            unread: true,
            message_id: Some("prop-msg-1".into()),
            fields: BTreeMap::new(),
            attachments: Vec::new(),
        };

        assert!(app.apply_message_task_result(MessageTaskResult::PropagationSynced {
            generation: 7,
            report: serde_json::json!({
                "report": "native_lxmf_propagation_diagnostics",
                "selected_node": FIXTURE_NODE_HASH,
                "sync": {"ok": true, "error": null},
                "after": {
                    "has_path": true,
                    "known_app_data": true,
                    "transfer_state": "complete"
                },
                "sync_events": [
                    {"kind": "message_received", "peer_hash": FIXTURE_PROPAGATION_PEER, "message_id": "prop-msg-1"}
                ],
                "blocker": "no propagation blocker reported"
            }),
            messages: vec![message],
        }));

        let conversation = app
            .workspace
            .conversations
            .iter()
            .find(|conversation| conversation.peer_hash == FIXTURE_PROPAGATION_PEER)
            .expect("propagation conversation");
        assert_eq!(conversation.thread.messages.len(), 1);
        assert!(app
            .status
            .task
            .contains("propagation sync complete: state=complete messages=1"));
        assert!(app.propagation_sync_pending.is_none());
    }

