    #[test]
    fn propagation_sync_result_applies_lxmf_delivery_evidence_to_pending_outbound() {
        let mut app = App::new(test_config("propagation-sync-evidence"));
        app.propagation_sync_pending = Some(8);
        let pending = MessageSummary {
            peer_hash: FIXTURE_PROPAGATION_PEER.into(),
            peer_label: "Prop Peer".into(),
            title: "Pending".into(),
            content: "Waiting for peer activity".into(),
            timestamp: 1.0,
            transport_method: TransportMethod::Propagated,
            delivered: false,
            failed: false,
            incoming: false,
            unread: false,
            message_id: Some("prop-out-1".into()),
            fields: BTreeMap::from([
                (
                    "native_lxmf_state".into(),
                    "propagation_node_accepted".into(),
                ),
                (
                    "native_lxmf_proof_state".into(),
                    "peer_delivery_unconfirmed".into(),
                ),
                (
                    "native_lxmf_receipt_state".into(),
                    "propagation_node_accepted_peer_unconfirmed".into(),
                ),
            ]),
            attachments: Vec::new(),
        };
        app.merge_message_into_conversation(pending.clone());
        app.messaging_service
            .store()
            .append(pending)
            .expect("store pending message");

        assert!(app.apply_message_task_result(MessageTaskResult::PropagationSynced {
            generation: 8,
            report: serde_json::json!({
                "report": "native_lxmf_propagation_diagnostics",
                "selected_node": FIXTURE_NODE_HASH,
                "sync": {"ok": true, "error": null},
                "after": {
                    "has_path": true,
                    "known_app_data": true,
                    "transfer_state": "complete"
                },
                "sync_events": [
                    {
                        "kind": "lxmf_delivery_evidence",
                        "evidence": {
                            "peer_hash": FIXTURE_PROPAGATION_PEER,
                            "message_id": "prop-out-1",
                            "kind": "inbound_peer_message",
                            "detail": "packet_hash:prop-out-1;peer_activity_observed:true;proof_state:peer_activity_observed",
                            "observed_at": 12.0
                        }
                    }
                ],
                "blocker": "no propagation blocker reported"
            }),
            messages: Vec::new(),
        }));

        let visible = app
            .workspace
            .conversations
            .iter()
            .find(|conversation| conversation.peer_hash == FIXTURE_PROPAGATION_PEER)
            .expect("visible conversation");
        let fields = &visible.thread.messages[0].fields;
        assert_eq!(
            fields
                .get("native_lxmf_delivery_evidence_kind")
                .map(String::as_str),
            Some("inbound_peer_message")
        );
        assert_eq!(
            fields
                .get("native_lxmf_peer_activity_observed")
                .map(String::as_str),
            Some("true")
        );
        assert_eq!(
            fields.get("native_lxmf_proof_state").map(String::as_str),
            Some("peer_activity_observed")
        );
        assert!(app.status.task.contains("delivery_updates=1"));
    }

    #[test]
    fn propagation_sync_no_payload_evidence_keeps_outbound_peer_unconfirmed() {
        let mut app = App::new(test_config("propagation-sync-no-payload"));
        app.propagation_sync_pending = Some(9);
        let pending = MessageSummary {
            peer_hash: FIXTURE_PROPAGATION_PEER.into(),
            peer_label: "Prop Peer".into(),
            title: "Pending".into(),
            content: "Waiting for payload".into(),
            timestamp: 1.0,
            transport_method: TransportMethod::Propagated,
            delivered: false,
            failed: false,
            incoming: false,
            unread: false,
            message_id: Some("prop-out-2".into()),
            fields: BTreeMap::from([
                (
                    "native_lxmf_state".into(),
                    "propagation_node_accepted".into(),
                ),
                (
                    "native_lxmf_proof_state".into(),
                    "peer_delivery_unconfirmed".into(),
                ),
                (
                    "native_lxmf_receipt_state".into(),
                    "propagation_node_accepted_peer_unconfirmed".into(),
                ),
            ]),
            attachments: Vec::new(),
        };
        app.merge_message_into_conversation(pending.clone());
        app.messaging_service
            .store()
            .append(pending)
            .expect("store pending message");

        assert!(app.apply_message_task_result(MessageTaskResult::PropagationSynced {
            generation: 9,
            report: serde_json::json!({
                "report": "native_lxmf_propagation_diagnostics",
                "selected_node": FIXTURE_NODE_HASH,
                "sync": {"ok": true, "error": null},
                "after": {
                    "has_path": true,
                    "known_app_data": true,
                    "transfer_state": "complete"
                },
                "sync_events": [
                    {
                        "kind": "lxmf_delivery_evidence",
                        "evidence": {
                            "peer_hash": FIXTURE_PROPAGATION_PEER,
                            "message_id": "prop-out-2",
                            "kind": "propagation_sync_no_payloads",
                            "detail": format!("propagation_transfer_state:resource_completed;propagation_node:{FIXTURE_NODE_HASH};requested:0;decoded:0;haves:2;receipt_state:propagation_sync_no_peer_payload;delivery_state:peer_delivery_unconfirmed"),
                            "observed_at": 12.0
                        }
                    }
                ],
                "blocker": "no propagation blocker reported"
            }),
            messages: Vec::new(),
        }));

        let visible = app
            .workspace
            .conversations
            .iter()
            .find(|conversation| conversation.peer_hash == FIXTURE_PROPAGATION_PEER)
            .expect("visible conversation");
        let message = &visible.thread.messages[0];
        assert!(!message.delivered);
        assert!(!message.failed);
        assert_eq!(
            message
                .fields
                .get("native_lxmf_propagation_sync_evidence_kind")
                .map(String::as_str),
            Some("propagation_sync_no_payloads")
        );
        assert!(!message
            .fields
            .contains_key("native_lxmf_delivery_evidence_kind"));
        assert_eq!(
            message
                .fields
                .get("native_lxmf_receipt_state")
                .map(String::as_str),
            Some("propagation_node_accepted_peer_unconfirmed")
        );
        assert_eq!(
            message.fields.get("native_lxmf_state").map(String::as_str),
            Some("propagation_node_accepted")
        );
        assert_eq!(
            message
                .fields
                .get("native_lxmf_propagation_sync_receipt_state")
                .map(String::as_str),
            Some("propagation_sync_no_peer_payload")
        );
        assert_eq!(
            message
                .fields
                .get("native_lxmf_propagation_sync_state")
                .map(String::as_str),
            Some("propagation_sync_no_payloads")
        );
        assert_eq!(
            message
                .fields
                .get("native_lxmf_proof_state")
                .map(String::as_str),
            Some("peer_delivery_unconfirmed")
        );
        assert_eq!(
            message
                .fields
                .get("native_lxmf_propagation_sync_haves")
                .map(String::as_str),
            Some("2")
        );
        assert_eq!(
            message
                .fields
                .get("native_lxmf_next_action")
                .map(String::as_str),
            Some("sync_propagation_again")
        );
        let stored = app
            .message_store
            .get_thread(FIXTURE_PROPAGATION_PEER)
            .expect("stored thread");
        assert_eq!(
            stored.messages[0]
                .fields
                .get("native_lxmf_receipt_state")
                .map(String::as_str),
            Some("propagation_node_accepted_peer_unconfirmed")
        );
        assert_eq!(
            message
                .fields
                .get("native_lxmf_retry_after_epoch_secs")
                .map(String::as_str),
            Some("42.000")
        );
    }

