    #[test]
    fn message_composer_uses_shared_input_submit_and_cancel() {
        let mut app = App::new(test_config("composer-input"));

        app.focus_message_title();
        for ch in "Subject".chars() {
            app.edit_address_char(ch);
        }
        app.submit_active_input();
        assert_eq!(app.active_conversation().draft_title, "Subject");
        assert!(matches!(
            app.input.active.as_ref().map(|active| &active.target),
            Some(InputTarget::MessageBody { .. })
        ));

        for ch in "Body".chars() {
            app.edit_address_char(ch);
        }
        app.cancel_active_input();
        assert_eq!(app.active_conversation().draft_title, "Subject");
        assert_eq!(app.active_conversation().draft_body, "");

        app.focus_message_body();
        for ch in "Body".chars() {
            app.edit_address_char(ch);
        }
        app.submit_active_input();
        assert_eq!(app.active_conversation().draft_body, "Body");
        assert_eq!(app.status.task, "message draft updated");
    }

