    #[test]
    fn failed_send_result_creates_visible_and_stored_failed_message() {
        let mut app = App::new(test_config("failed-send-visible"));
        let conversation_id = app.active_conversation().id;
        app.active_conversation_mut_for_test().peer_hash = FIXTURE_NODE_HASH.into();
        app.active_conversation_mut_for_test().peer_label = "Peer".into();
        app.active_conversation_mut_for_test().draft_title = "Subject".into();
        app.active_conversation_mut_for_test().draft_body = "Body".into();
        app.active_conversation_mut_for_test().pending_send =
            Some(MessageSendState { generation: 7 });
        let pending = pending_outbound_message_from_conversation(app.active_conversation(), 7);
        app.active_conversation_mut_for_test().push_message(pending);
        app.active_conversation_mut_for_test().draft_title.clear();
        app.active_conversation_mut_for_test().draft_body.clear();

        assert!(app.apply_message_task_result(MessageTaskResult::Error {
            conversation_id: Some(conversation_id),
            generation: 7,
            message: "native LXMF send failed during link setup".into(),
        }));

        let conversation = app.active_conversation();
        assert!(conversation.pending_send.is_none());
        assert_eq!(conversation.thread.messages.len(), 1);
        let failed = &conversation.thread.messages[0];
        assert_eq!(failed.title, "Subject");
        assert_eq!(failed.content, "Body");
        assert!(failed.failed);
        assert!(!failed.delivered);
        assert_eq!(
            failed.fields.get("native_lxmf_state").map(String::as_str),
            Some("failed")
        );
        assert!(failed
            .fields
            .get("native_lxmf_failure_reason")
            .is_some_and(|reason| reason.contains("link setup")));
        let stored = app
            .message_store
            .get_thread(FIXTURE_NODE_HASH)
            .expect("stored failed thread");
        assert_eq!(stored.messages.len(), 1);
        assert!(stored.messages[0].failed);
        assert!(app
            .status
            .task
            .contains("message send failed: native LXMF send failed"));
        let diagnostics = app.active_lxmf_messaging_diagnostics();
        assert!(diagnostics
            .lines
            .iter()
            .any(|line| line.contains("failure reason: native LXMF send failed")));
    }

