    #[test]
    fn mouse_scroll_uses_target_browser_tab_width_and_keeps_other_tabs_stable() {
        let mut app = App::new(test_config("browser-tab-scroll-target"));
        let first = app.active_browser_tab().id;
        let long_line = "wrapped content ".repeat(20);
        let first_page = BrowserPage {
            url: "mock.node:/wide.mu".into(),
            title: "Wide".into(),
            markup: (0..8)
                .map(|index| format!("{index} {long_line}"))
                .collect::<Vec<_>>()
                .join("\n"),
            source: crate::browser::PageSource::Network,
            metadata: BTreeMap::new(),
            request_data: None,
        };
        app.active_browser_tab_mut()
            .session
            .apply_page(first_page, true);
        app.sync_browser_tab_from_session(app.workspace.active_browser, None);
        app.new_browser_tab();
        let second = app.active_browser_tab().id;
        let second_page = BrowserPage {
            url: "mock.node:/small.mu".into(),
            title: "Small".into(),
            markup: (0..40)
                .map(|index| format!("line {index}"))
                .collect::<Vec<_>>()
                .join("\n"),
            source: crate::browser::PageSource::Network,
            metadata: BTreeMap::new(),
            request_data: None,
        };
        app.active_browser_tab_mut()
            .session
            .apply_page(second_page, true);
        app.sync_browser_tab_from_session(app.workspace.active_browser, None);

        assert!(app.set_browser_tab_viewport(first, 32, 6));
        assert!(app.set_browser_tab_viewport(second, 90, 20));
        assert_eq!(app.scroll_browser_tab_lines(first, 7), Some(7));

        let first_tab = app
            .workspace
            .browser_tabs
            .iter()
            .find(|tab| tab.id == first)
            .expect("first tab");
        let second_tab = app
            .workspace
            .browser_tabs
            .iter()
            .find(|tab| tab.id == second)
            .expect("second tab");
        assert_eq!(first_tab.scroll.offset, 7);
        assert_eq!(
            (first_tab.viewport_width, first_tab.viewport_height),
            (32, 6)
        );
        assert_eq!(second_tab.scroll.offset, 0);
        assert_eq!(
            (second_tab.viewport_width, second_tab.viewport_height),
            (90, 20)
        );
    }

