    #[tokio::test]
    async fn field_forwarding_link_activation_uses_session_values() {
        let mut app = App::new(test_config("link-forwarding"));
        let page = BrowserPage {
            url: "mock.node:/form.mu".into(),
            title: "Form".into(),
            markup: "`<12|nickname`mesh>\n`[Submit`mock.node:/page/gallery.mu`nickname]".into(),
            source: crate::browser::PageSource::Network,
            metadata: BTreeMap::new(),
            request_data: None,
        };
        app.active_browser_tab_mut().session.apply_page(page, true);
        app.sync_browser_tab_from_session(app.workspace.active_browser, None);
        app.active_browser_tab_mut()
            .session
            .set_field_value("nickname", "mesh friend");
        let link = app.active_browser_tab().session.available_links()[0].clone();

        app.open_browser_link_at_index(app.workspace.active_browser, link);
        let preview = app
            .active_browser_tab()
            .request_preview
            .as_ref()
            .expect("request preview");
        assert_eq!(preview.status, BrowserRequestStatus::Pending);
        assert_eq!(
            preview
                .request_data
                .get("field_nickname")
                .map(String::as_str),
            Some("mesh friend")
        );
        assert!(app.status.task.contains("forwarded field"));

        assert!(app.wait_for_browser_task_result().await);

        let page = app
            .active_browser_tab()
            .current_page
            .as_ref()
            .expect("page");
        assert_eq!(
            page.request_data
                .as_ref()
                .and_then(|data| data.get("field_nickname"))
                .map(String::as_str),
            Some("mesh friend")
        );
        let preview = app
            .active_browser_tab()
            .request_preview
            .as_ref()
            .expect("completed request preview");
        assert_eq!(preview.status, BrowserRequestStatus::Completed);
        assert!(preview.detail.contains("gallery"));
    }

