    #[test]
    fn browser_status_overlay_summarizes_history_partials_and_task() {
        let mut app = App::new(test_config("browser-status-overlay"));
        let first = BrowserPage {
            url: "mock.node:/one.mu".into(),
            title: "One".into(),
            markup: "one".into(),
            source: crate::browser::PageSource::Network,
            metadata: BTreeMap::new(),
            request_data: None,
        };
        let second = BrowserPage {
            url: "mock.node:/two.mu".into(),
            title: "Two".into(),
            markup: "`{mock.node:/slot.mu`5`name|pid=slot}".into(),
            source: crate::browser::PageSource::Cache,
            metadata: BTreeMap::new(),
            request_data: None,
        };
        app.active_browser_tab_mut().session.apply_page(first, true);
        app.active_browser_tab_mut()
            .session
            .apply_page(second, true);
        app.sync_browser_tab_from_session(app.workspace.active_browser, None);
        let generation = app.active_browser_tab().session.generation;
        app.active_browser_tab_mut().partials.pending = 1;
        app.active_browser_tab_mut().loading = Some(LoadState {
            generation,
            target: "mock.node:/three.mu".into(),
            submitted_fields: false,
            cancel: CancellationToken::new(),
        });

        let overlay = app.browser_status_overlay();

        assert!(overlay
            .lines
            .iter()
            .any(|line| line.contains("current: mock.node:/two.mu")));
        assert!(overlay
            .lines
            .iter()
            .any(|line| line.contains("source/cache: Cache")));
        assert!(overlay
            .lines
            .iter()
            .any(|line| line.contains("history: 2 of 2")));
        assert!(overlay
            .lines
            .iter()
            .any(|line| line.contains("back: mock.node:/one.mu")));
        assert!(overlay
            .lines
            .iter()
            .any(|line| line.contains("partials: specs=1 pending=1")));
        assert!(overlay
            .lines
            .iter()
            .any(|line| line.contains("task: mock.node:/three.mu")));
    }

    #[test]
    fn browser_overlay_mode_cycles_and_expands() {
        let mut app = App::new(test_config("browser-overlay-mode"));

        assert_eq!(
            app.workspace.browser_overlay_mode,
            BrowserOverlayMode::Status
        );
        assert!(app.workspace.browser_overlay_mode.shows_status());
        assert!(!app.workspace.browser_overlay_mode.shows_focus());

        app.cycle_browser_overlay_mode();
        assert_eq!(app.workspace.browser_overlay_mode, BrowserOverlayMode::Both);
        assert!(app.workspace.browser_overlay_mode.shows_status());
        assert!(app.workspace.browser_overlay_mode.shows_focus());

        app.cycle_browser_overlay_mode();
        assert_eq!(
            app.workspace.browser_overlay_mode,
            BrowserOverlayMode::Hidden
        );
        assert!(!app.workspace.browser_overlay_mode.shows_status());
        assert!(!app.workspace.browser_overlay_mode.shows_focus());

        app.toggle_browser_overlay_expanded();
        assert_eq!(
            app.workspace.browser_overlay_mode,
            BrowserOverlayMode::Expanded
        );
        assert!(app.workspace.browser_overlay_mode.shows_status());
        assert!(app.workspace.browser_overlay_mode.shows_focus());

        app.toggle_browser_overlay_expanded();
        assert_eq!(
            app.workspace.browser_overlay_mode,
            BrowserOverlayMode::Status
        );
    }

